function parseName(data: Uint8Array, offset: number): { name: string; consumed: number } {
  let name: string = '';
  let i = offset;
  while (i < data.length) {
    const len = data[i];
    if (len === 0) {
      return { name, consumed: i + 1 };
    }
    if ((len & 0xC0) === 0xC0) {
      // Compression pointer
      const pointer = ((len & 0x3F) << 8) | data[i + 1];
      const { name: ptrName, consumed: ptrConsumed } = parseName(data, pointer);
      return { name: name + ptrName, consumed: i + 2 };
