async function queryDNS(name: string, qtype: number, port: number): Promise<{ rcode: number; answer: { name: string; ttl: number; type: number; rdata: Uint8Array }[] }> {
  const id = Math.floor(Math.random() * 0xFFFF);
  const query = buildQuery(id, name, qtype);
  const udpSocket = net.createSocket('udp4');
  const tcpSocket = net.createSocket('tcp4');
  const responses: { id: number; data: Uint8Array }[] = [];
  const responseData: Uint8Array[] = [];
  let udpReceived = false;

  udpSocket.on('message', (data) => {
    const header = parseHeader(data);
    if (header.id === id) {
      responses.push({ id, data });
      udpReceived = true;
    }
  });

  tcpSocket.on('data', (data) => {
    responseData.push(data);
  });

  try {
    udpSocket.send(query, 0, query.length, 'udp', `127.0.0.1:${port}`);

    if (udpReceived) {
      udpSocket.end();
    }

    for (let i = 0; i < responses.length; i++) {
      const res = responses[i];
      if (res.data.length < 12) continue;
      const header = parseHeader(res.data);
      if (header.id === id) {
        return { rcode: header.rcode, answer: [] };
      }
    }

    if (udpReceived) {
      udpSocket.end();
      udpSocket.destroy();
    }

    tcpSocket.connect(port, '127.0.0.1');
    tcpSocket.write(toBytes(query.length));
    tcpSocket.write(query);

    await new Promise((resolve) => {
      if (responseData.length > 0) {
        resolve(null);
      } else {
        tcpSocket.once('data', resolve);
      }
    });

    const combined = Buffer.concat(responseData);
    tcpSocket.end();

    if (combined.length < 12) return { rcode: 0, answer: [] };
    const header = parseHeader(combined);
    if (header.id !== id) {
      return { rcode: 1, answer: [] };
    }

    if ((header.flags >> 2) & 1) {
      return { rcode: 0, answer: [] };
    }

    const offset = 12;
    let currentOffset = offset;
    let consumed = 0;
    const answers: { name: string; ttl: number; type: number; rdata: Uint8Array }[] = [];

    while (consumed < header.ancount) {
      const { name, ttl, type, rdata, consumed: recConsumed } = parseRecord(combined, currentOffset, header.qdcount);
      answers.push({ name, ttl, type, rdata });
      currentOffset += recConsumed;
      consumed++;
    }

    return { rcode: header.rcode, answer: answers };
  } catch (err) {
    return { rcode: 0, answer: [] };
  }
}

