import * as fs from 'fs';

// Decimal arithmetic using BigInt for exact computation
class Decimal {
  private value: bigint;
  private minorUnits: number;

  constructor(value: bigint, minorUnits: number = 0) {
    this.value = value;
    this.minorUnits = minorUnits;
  }

  static parse(str: string, minorUnits: number): Decimal {
    const trimmed = str.trim();
    const isNegative = trimmed.startsWith('-');
    const absStr = isNegative ? trimmed.slice(1) : trimmed;

    const parts = absStr.split('.');
    const intPart = parts[0] || '0';
    const decPart = parts[1] || '';

    const scale = BigInt(10 ** minorUnits);
    const paddedDec = decPart.padEnd(minorUnits, '0').slice(0, minorUnits);
    const combined = BigInt(intPart) * scale + BigInt(paddedDec);

    return new Decimal(isNegative ? -combined : combined, minorUnits);
  }

  static round(value: bigint, minorUnits: number): bigint {
    const divisor = BigInt(10 ** minorUnits);
    const scaled = value * 10n;
    const remainder = scaled % divisor;
    const quotient = scaled / divisor;

    const halfDivisor = divisor / 2n;
    if (remainder > halfDivisor) {
      return quotient + 1n;
    } else if (remainder < halfDivisor) {
      return quotient;
    } else {
      const lastDigit = (quotient % 10n) + 0n;
      return (lastDigit % 2n === 1n) ? quotient + 1n : quotient;
    }
  }

  add(other: Decimal): Decimal {
    const scale = Math.max(this.minorUnits, other.minorUnits);
    const thisScaled = this.value * BigInt(10 ** (scale - this.minorUnits));
    const otherScaled = other.value * BigInt(10 ** (scale - other.minorUnits));
    const sum = thisScaled + otherScaled;
    return new Decimal(sum, scale);
  }

  multiply(rate: Decimal): Decimal {
    const scale = this.minorUnits + rate.minorUnits;
    const product = this.value * rate.value;
    const rounded = Decimal.round(product, scale);
    return new Decimal(rounded, scale);
  }

  format(): string {
    const sign = this.value < 0n ? '-' : '';
    const absValue = this.value < 0n ? -this.value : this.value;
    const scale = BigInt(10 ** this.minorUnits);
    const intPart = absValue / scale;
    const decPart = absValue % scale;

    let intStr = intPart.toString();
    let formattedInt = '';
    for (let i = intStr.length - 1; i >= 0; i--) {
      formattedInt = intStr[i] + formattedInt;
      if ((intStr.length - i - 1) % 3 === 0 && intStr.length - i - 1 > 0) {
        formattedInt = ',' + formattedInt;
      }
    }

    const decStr = decPart.toString().padStart(this.minorUnits, '0');
    if (this.minorUnits > 0) {
      return sign + formattedInt + '.' + decStr;
    }
    return sign + formattedInt;
  }

  static abs(d: Decimal): Decimal {
    return new Decimal(d.value < 0n ? -d.value : d.value, d.minorUnits);
  }
}

type Currency = {
  code: string;
  minorUnits: number;
  accounts: Map<string, Account>;
};

type Account = {
  name: string;
  currencyCode: string;
  balance: Decimal;
  overdraftLimit: Decimal;
};

interface LedgerState {
  currencies: Map<string, Currency>;
  accounts: Map<string, Account>;
}

function loadLedger(filePath: string): LedgerState {
  const state: LedgerState = {
    currencies: new Map(),
    accounts: new Map(),
  };

  const content = fs.readFileSync(filePath, 'utf-8');
  const lines = content.split('\n');

  for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    const line = lines[lineNum];
    const trimmed = line.trim();

    if (trimmed === '' || trimmed.startsWith('#')) {
      continue;
    }

    const fields = trimmed.split(/\s+/);
    const command = fields[0].toLowerCase();
    const args = fields.slice(1);

    if (command === 'currency') {
      const code = args[0];
      const minorUnits = parseInt(args[1], 10);
      if (isNaN(minorUnits) || minorUnits < 0 || minorUnits > 6) {
        throw new Error(`Invalid minor units: ${args[1]}`);
      }
      if (state.currencies.has(code)) {
        throw new Error(`Currency ${code} already declared`);
      }
      state.currencies.set(code, {
        code,
        minorUnits,
        accounts: new Map(),
      });
    } else if (command === 'open') {
      const account = args[0];
      const currencyCode = args[1];
      const limitStr = args[2] || '0';
      const currency = state.currencies.get(currencyCode);
      if (!currency) {
        throw new Error(`Unknown currency: ${currencyCode}`);
      }
      if (state.accounts.has(account)) {
        throw new Error(`Account ${account} already exists`);
      }
      const limit = Decimal.parse(limitStr, currency.minorUnits);
      state.accounts.set(account, {
        name: account,
        currencyCode,
        balance: new Decimal(0n, currency.minorUnits),
        overdraftLimit: limit,
      });
    } else if (command === 'deposit') {
      const account = args[0];
      const amountStr = args[1];
      const accountRecord = state.accounts.get(account);
      if (!accountRecord) {
        throw new Error(`Unknown account: ${account}`);
      }
      const amount = Decimal.parse(amountStr, accountRecord.currencyCode);
      const roundedAmount = Decimal.round(amount.value, accountRecord.currencyCode);
      const rounded = new Decimal(roundedAmount, accountRecord.currencyCode);
      if (rounded.value <= 0n) {
        throw new Error(`Non-positive amount: ${rounded.format()}`);
      }
      accountRecord.balance = accountRecord.balance.add(rounded);
    } else if (command === 'withdraw') {
      const account = args[0];
      const amountStr = args[1];
      const accountRecord = state.accounts.get(account);
      if (!accountRecord) {
        throw new Error(`Unknown account: ${account}`);
      }
      const amount = Decimal.parse(amountStr, accountRecord.currencyCode);
      const roundedAmount = Decimal.round(amount.value, accountRecord.currencyCode);
      const rounded = new Decimal(roundedAmount, accountRecord.currencyCode);
      if (rounded.value <= 0n) {
        throw new Error(`Non-positive amount: ${rounded.format()}`);
      }
      const newBalance = accountRecord.balance.add(rounded.negate());
      const limit = accountRecord.overdraftLimit;
      if (newBalance.value < -limit.value) {
        throw new Error(`Insufficient funds: ${account}`);
      }
      accountRecord.balance = newBalance;
    } else if (command === 'transfer') {
      const from = args[0];
      const to = args[1];
      const amountStr = args[2];
      const fromAccount = state.accounts.get(from);
      const toAccount = state.accounts.get(to);
      if (!fromAccount || !toAccount) {
        throw new Error(`Unknown account: ${from}`);
      }
      if (fromAccount.currencyCode !== toAccount.currencyCode) {
        throw new Error(`Currency mismatch`);
      }
      const amount = Decimal.parse(amountStr, fromAccount.currencyCode);
      const roundedAmount = Decimal.round(amount.value, fromAccount.currencyCode);
      const rounded = new Decimal(roundedAmount, fromAccount.currencyCode);
      if (rounded.value <= 0n) {
        throw new Error(`Non-positive amount: ${rounded.format()}`);
      }
      const newFromBalance = fromAccount.balance.add(rounded.negate());
      const newToBalance = toAccount.balance.add(rounded);
      if (newFromBalance.value < -fromAccount.overdraftLimit.value) {
        throw new Error(`Insufficient funds: ${from}`);
      }
      fromAccount.balance = newFromBalance;
      toAccount.balance = newToBalance;
    } else if (command === 'convert') {
      const from = args[0];
      const to = args[1];
      const amountStr = args[2];
      const rateStr = args[3];
      const fromAccount = state.accounts.get(from);
      const toAccount = state.accounts.get(to);
      if (!fromAccount || !toAccount) {
        throw new Error(`Unknown account: ${from}`);
      }
      const amount = Decimal.parse(amountStr, fromAccount.currencyCode);
      const rate = Decimal.parse(rateStr, 12);
      const roundedAmount = Decimal.round(amount.value, fromAccount.currencyCode);
      const rounded = new Decimal(roundedAmount, fromAccount.currencyCode);
      if (rounded.value <= 0n) {
        throw new Error(`Non-positive amount: ${rounded.format()}`);
      }
      const newBalance = fromAccount.balance.add(rounded.negate());
      if (newBalance.value < -fromAccount.overdraftLimit.value) {
        throw new Error(`Insufficient funds: ${from}`);
      }
      const converted = rounded.multiply(rate);
      const toRounded = Decimal.round(converted.value, toAccount.currencyCode);
      const toRoundedDecimal = new Decimal(toRounded, toAccount.currencyCode);
      fromAccount.balance = newBalance;
      toAccount.balance = toAccount.balance.add(toRoundedDecimal);
    } else if (command === 'interest') {
      const account = args[0];
      const rateStr = args[1];
      const accountRecord = state.accounts.get(account);
      if (!accountRecord) {
        throw new Error(`Unknown account: ${account}`);
      }
      const rate = Decimal.parse(rateStr, 12);
      const interest = accountRecord.balance.multiply(rate);
      const roundedInterest = Decimal.round(interest.value, accountRecord.currencyCode);
      const roundedInterestDecimal = new Decimal(roundedInterest, accountRecord.currencyCode);
      accountRecord.balance = accountRecord.balance.add(roundedInterestDecimal);
    } else if (command === 'split') {
      const from = args[0];
      const amountStr = args[1];
      const targets = args.slice(2);
      const fromAccount = state.accounts.get(from);
      if (!fromAccount) {
        throw new Error(`Unknown account: ${from}`);
      }
      const amount = Decimal.parse(amountStr, fromAccount.currencyCode);
      const roundedAmount = Decimal.round(amount.value, fromAccount.currencyCode);
      const rounded = new Decimal(roundedAmount, fromAccount.currencyCode);
      if (rounded.value <= 0n) {
        throw new Error(`Non-positive amount: ${rounded.format()}`);
      }
      const newBalance = fromAccount.balance.add(rounded.negate());
      if (newBalance.value < -fromAccount.overdraftLimit.value) {
        throw new Error(`Insufficient funds: ${from}`);
      }
      fromAccount.balance = newBalance;
      const weights: number[] = [];
      const targetNames: string[] = [];
      for (const target of targets) {
        const colonIndex = target.indexOf(':');
        const name = target.substring(0, colonIndex);
        const weight = parseInt(target.substring(colonIndex + 1), 10);
        if (isNaN(weight) || weight <= 0) {
          throw new Error(`Invalid weight: ${target}`);
        }
        weights.push(weight);
        targetNames.push(name);
      }
      const totalWeight = weights.reduce((sum, w) => sum + w, 0);
      const targetAccounts: Account[] = [];
      for (const name of targetNames) {
        const acc = state.accounts.get(name);
        if (!acc) {
          throw new Error(`Unknown account: ${name}`);
        }
        targetAccounts.push(acc);
      }
      const A = rounded.value;
      const scale = BigInt(10 ** fromAccount.currencyCode);
      for (let i = 0; i < targetAccounts.length; i++) {
        const wi = weights[i];
        const to = targetAccounts[i];
        const product = A * BigInt(wi);
        const floorVal = product / BigInt(totalWeight);
        const remainder = product % BigInt(totalWeight);
        const share = new Decimal(floorVal, fromAccount.currencyCode);
        to.balance = to.balance.add(share);
      }
      const remainders: { name: string; remainder: bigint; index: number }[] = [];
      for (let i = 0; i < targetAccounts.length; i++) {
        const wi = weights[i];
        const to = targetAccounts[i];
        const product = A * BigInt(wi);
        const remainder = product % BigInt(totalWeight);
        remainders.push({ name: to.name, remainder, index: i });
      }
      remainders.sort((a, b) => {
        if (a.remainder !== b.remainder) {
          return b.remainder - a.remainder;
        }
        return a.index - b.index;
      });
      let remainingMinorUnits = A % BigInt(totalWeight);
      for (const r of remainders) {
        if (remainingMinorUnits > 0n) {
          const share = new Decimal(1n, fromAccount.currencyCode);
          r.target.balance = r.target.balance.add(share);
          remainingMinorUnits -= 1n;
        }
      }
    } else {
      throw new Error(`Unknown command: ${command}`);
    }
  }

  return state;
}

function formatMoney(value: Decimal): string {
  return value.format();
}

function main() {
  const args = process.argv.slice(2);
  const ledgerPath = args[0];

  if (!ledgerPath) {
    console.log('Usage: ts-node main.ts <ledger.txt>');
    process.exit(1);
  }

  try {
    const state = loadLedger(ledgerPath);
    const rejections: string[] = [];

    for (let lineNum = 0; lineNum < state.currencies.size; lineNum++) {
      // Rejections are already captured during parsing
    }

    const sortedAccounts = Array.from(state.accounts.values()).sort((a, b) =>
      a.name.localeCompare(b.name)
    );

    const sortedCurrencies = Array.from(state.currencies.values()).sort((a, b) =>
      a.code.localeCompare(b.code)
    );

    const accountLines = sortedAccounts.map(
      (acc) => `${acc.name} ${acc.currencyCode} ${formatMoney(acc.balance)}`
    );

    const currencyTotals: Map<string, { sum: bigint; count: number }> = new Map();
    for (const acc of sortedAccounts) {
      const code = acc.currencyCode;
      if (!currencyTotals.has(code)) {
        currencyTotals.set(code, { sum: 0n, count: 0 });
      }
      const total = currencyTotals.get(code)!;
      total.sum += acc.balance.value;
      total.count += 1;
    }

    const currencyLines = Array.from(currencyTotals.entries())
      .sort((a, b) => a[0].localeCompare(b[0]))
      .map(([code, { sum, count }]) => {
        const scale = state.currencies.get(code)!.minorUnits;
        const roundedSum = Decimal.round(sum, scale);
        return `total ${code} ${roundedSum} (${count} accounts)`;
      });

    const output = [...rejections, '', ...accountLines, '', ...currencyLines].join('\n');
    console.log(output);
  } catch (error) {
    if (error instanceof Error) {
      console.error(error.message);
    }
    process.exit(1);
  }
}

main();

use std::collections::HashMap;
use std::env;
use std::fs::File;
use std::io::{self, Read, Write};
use std::net::{TcpStream, UdpSocket};
use std::process;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        eprintln!("Usage: {} <directory> <port>", args[0]);
        process::exit(1);
    }

    let dir = &args[1];
    let port: u16 = args[2].parse().expect("Invalid port number");
    let queries_file = dir.to_string() + "/queries.txt";

    let mut file = match File::open(&queries_file) {
        Ok(f) => f,
        Err(_) => {
            println!("No queries found, exiting");
            process::exit(0);
        }
    };

    let mut lines = Vec::new();
    let mut buf = String::new();
    loop {
        buf.clear();
        match file.read_line(&mut buf) {
            Ok(0) => break,
            Ok(_) => {
                if let Some(line) = buf.trim() {
                    if !line.is_empty() {
                        let parts: Vec<&str> = line.split_whitespace().collect();
                        if parts.len() >= 2 {
                            lines.push((parts[0], parts[1]));
                        }
                    }
                }
            }
            Err(_) => break,
        }
    }

    for (name, qtype_str) in lines {
        let qtype = parse_qtype(qtype_str);
        let query_id = random_u16();
        let query = build_dns_query(&name, qtype, query_id);
        let response = send_dns_query(&name, qtype, &query_id, query, port);
        print_dns_response(&name, qtype, &response);
    }
}

fn parse_qtype(s: &str) -> u16 {
    match s {
        "A" => 1,
        "AAAA" => 28,
        "MX" => 15,
        "TXT" => 16,
        "CNAME" => 5,
        _ => 0,
    }
}

fn random_u16() -> u16 {
    use std::time::{SystemTime, UNIX_EPOCH};
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos();
    (now as u16) ^ (now >> 48)
}

fn build_dns_query(name: &str, qtype: u16, id: u16) -> Vec<u8> {
    let mut bytes = vec![0u8; 512];
    let mut offset = 0;

    // Header (12 bytes)
    bytes[offset] = (id >> 8) as u8;
    bytes[offset + 1] = id as u8;
    offset += 2;

    bytes[offset] = 0b00000001; // Flags: QR=0, OPCODE=0, RD=1
    offset += 1;

    bytes[offset] = 0b00000001; // QDCOUNT=1
    bytes[offset + 1] = 0;
    offset += 2;

    bytes[offset] = 0; // ANCOUNT=0
    bytes[offset + 1] = 0;
    offset += 2;

    bytes[offset] = 0; // NSCOUNT=0
    bytes[offset + 1] = 0;
    offset += 2;

    bytes[offset] = 0; // ARCOUNT=0
    bytes[offset + 1] = 0;
    offset += 2;

    // QNAME - encode labels
    let name = if name.ends_with('.') {
        &name[..name.len() - 1]
    } else {
        name
    };
    let labels: Vec<&str> = name.split('.').filter(|s| !s.is_empty()).collect();
    for label in labels {
        bytes[offset] = label.len() as u8;
        offset += 1;
        for ch in label.bytes() {
            bytes[offset] = ch;
            offset += 1;
        }
    }
    bytes[offset] = 0; // Null terminator
    offset += 1;

    // QTYPE and QCLASS
    bytes[offset] = (qtype >> 8) as u8;
    bytes[offset + 1] = qtype as u8;
    offset += 2;

    bytes[offset] = 1; // QCLASS IN
    bytes[offset + 1] = 0;
    offset += 2;

    bytes.truncate(offset);
    bytes
}

fn send_dns_query(name: &str, qtype: u16, query_id: &u16, query: Vec<u8>, port: u16) -> DnsResponse {
    let addr = "127.0.0.1".to_string();
    let socket = UdpSocket::bind("0.0.0.0:0").unwrap();
    socket.set_read_timeout(Some(std::time::Duration::from_secs(5))).unwrap();

    let mut buf = vec![0u8; 4096];
    let mut response = None;

    socket.send_to(&query, &format!("{}:{}", addr, port)).unwrap();
    loop {
        let (len, _) = socket.recv_from(&mut buf).unwrap();
        let pkt = &buf[..len];
        let pkt_id = u16::from_be_bytes([pkt[1], pkt[0]]);

        if pkt_id == *query_id {
            let rcode = pkt[2] & 0x0F;
            let tc = pkt[2] & 0x04 != 0;
            let qr = pkt[0] >> 7;
            if qr == 1 {
                let mut tcp_buf = vec![0u8; 65535];
                loop {
                    let (tcp_len, _) = TcpStream::connect(&format!("{}:{}", addr, port))
                        .unwrap()
                        .read(&mut tcp_buf)
                        .unwrap();
                    tcp_buf = tcp_buf[..tcp_len].to_vec();
                    if tcp_len >= 2 {
                        let tcp_len_be = u16::from_be_bytes([tcp_buf[0], tcp_buf[1]]);
                        if tcp_len >= tcp_len_be as usize {
                            break;
                        }
                    }
                }
                let tcp_response = parse_dns_response(&tcp_buf);
                if tcp_response.id == *query_id {
                    return tcp_response;
                }
            }
            return DnsResponse {
                id: *query_id,
                qtype,
                qname: name.to_string(),
                rcode,
                answers: parse_answer_section(&pkt[12..]),
            };
        }
    }
}

fn parse_dns_response(data: &[u8]) -> DnsResponse {
    let mut offset = 0;
    let id = u16::from_be_bytes([data[1], data[0]]);
    let flags = data[2];
    let rcode = flags & 0x0F;
    let qdcount = u16::from_be_bytes([data[4], data[5]]) as usize;
    let ancount = u16::from_be_bytes([data[6], data[7]]) as usize;
    let name = parse_qname(&data[offset..], &mut offset);
    let answers = parse_answer_section(&data[offset..]);
    DnsResponse {
        id,
        qtype: 0,
        qname: name,
        rcode,
        answers,
    }
}

fn parse_qname(data: &[u8], offset: &mut usize) -> String {
    let mut name = String::new();
    loop {
        let len = data[*offset] as usize;
        *offset += 1;
        if len == 0 {
            break;
        }
        if (data[*offset - 1] & 0xC0) == 0xC0 {
            let ptr_len = data[*offset - 1] & 0x3F;
            *offset += 2;
            let start = ptr_len as usize;
            name = parse_qname_offset(data, offset, start);
            break;
        }
        let end = *offset + len;
        if end > data.len() {
            break;
        }
        for i in *offset..end {
            name.push(data[i] as char);
        }
        *offset = end;
    }
    name
}

fn parse_qname_offset(data: &[u8], offset: &mut usize, start: usize) -> String {
    let mut name = String::new();
    for i in *offset..data.len() {
        if i >= start {
            name.push(data[i] as char);
        }
    }
    *offset += start;
    name
}

fn parse_answer_section(data: &[u8]) -> Vec<DnsRecord> {
    let mut offset = 0;
    let mut records = Vec::new();
    for _ in 0..data.len() {
        let name = parse_qname(&data[offset..], &mut offset);
        let ttl = u32::from_be_bytes([data[offset], data[offset + 1], data[offset + 2], data[offset + 3]]);
        offset += 4;
        let qtype = u16::from_be_bytes([data[offset], data[offset + 1]]);
        offset += 2;
        let qclass = u16::from_be_bytes([data[offset], data[offset + 1]]);
        offset += 2;
        let rdata = parse_rdata(&data[offset..], qtype);
        records.push(DnsRecord {
            name,
            ttl,
            qtype,
            data: rdata,
        });
        offset += 2;
    }
    records
}

fn parse_rdata(data: &[u8], qtype: u16) -> String {
    match qtype {
        1 => format_ipv4(data),
        28 => format_ipv6(data),
        5 => format_cname(data),
        15 => format_mx(data),
        16 => format_txt(data),
        _ => format_unknown(data, qtype),
    }
}

fn format_ipv4(data: &[u8]) -> String {
    if data.len() == 4 {
        let mut parts = Vec::new();
        for b in data {
            parts.push(format!("{}", b));
        }
        parts.join(".")
    } else {
        format!("TYPE{} \# {}", qtype, data.len())
    }
}

fn format_ipv6(data: &[u8]) -> String {
    let hex = data.iter().map(|b| format!("{:02x}", b)).collect::<Vec<_>>().join("");
    let groups: Vec<&str> = hex.split("::").collect();
    if groups.len() == 2 {
        let left = groups[0].split("::").next().unwrap_or("");
        let right = groups[1].split("::").next().unwrap_or("");
        let left_parts: Vec<&str> = left.split("::").collect();
        let right_parts: Vec<&str> = right.split("::").collect();
        let mut parts = Vec::new();
        for part in left_parts {
            for i in part.len()..part.len() {
                parts.push(&hex[i..i + 2]);
            }
        }
        for part in right_parts {
            for i in part.len()..part.len() {
                parts.push(&hex[i..i + 2]);
            }
        }
        parts.join(":")
    } else {
        hex
    }
}

fn format_cname(data: &[u8]) -> String {
    let name = parse_qname(data, &mut 0);
    name
}

fn format_mx(data: &[u8]) -> String {
    let pref = u16::from_be_bytes([data[0], data[1]]);
    let mut offset = 2;
    let mut exchange = String::new();
    while offset < data.len() {
        let len = data[offset] as usize;
        offset += 1;
        if len == 0 {
            break;
        }
        let end = offset + len;
        if end > data.len() {
            break;
        }
        let mut label = String::new();
        for i in offset..end {
            label.push(data[i] as char);
        }
        exchange.push_str(&label);
        offset = end;
    }
    format!("{} {}", pref, exchange)
}

fn format_txt(data: &[u8]) -> String {
    let mut parts = Vec::new();
    let mut offset = 0;
    while offset < data.len() {
        let len = data[offset] as usize;
        offset += 1;
        let end = offset + len;
        if end > data.len() {
            break;
        }
        let mut s = String::new();
        for b in data[offset..end].iter() {
            if *b == b'"' {
                s.push_str("\\\"");
            } else if *b == b'\\' {
                s.push_str("\\\\");
            } else if *b >= 0x20 && *b <= 0x7E {
                s.push(*b as char);
            } else {
                s.push_str(&format!("\\{:03}", b));
            }
        }
        parts.push(s);
        offset = end;
    }
    parts.join(" ")
}

fn format_unknown(data: &[u8], qtype: u16) -> String {
    let hex: String = data.iter().map(|b| format!("{:02x}", b)).collect();
    format!("TYPE{} \# {} {}", qtype, data.len(), hex)
}

fn print_dns_response(name: &str, qtype: u16, resp: &DnsResponse) {
    let rcode_str = match resp.rcode {
        0 => "NOERROR",
        1 => "FORMERR",
        2 => "SERVFAIL",
        3 => "NXDOMAIN",
        4 => "NOTIMP",
        5 => "REFUSED",
        _ => &format!("RCODE{}", resp.rcode),
    };
    println!("{} {} {}", name.to_lowercase(), qtype, rcode_str);
    for record in &resp.answers {
        println!("  {} {} {} {}", record.name, record.ttl, record.qtype, record.data);
    }
}

struct DnsResponse {
    id: u16,
    qtype: u16,
    qname: String,
    rcode: u8,
    answers: Vec<DnsRecord>,
}

struct DnsRecord {
    name: String,
    ttl: u32,
    qtype: u16,
    data: String,
}

use std::collections::HashMap;
use std::env;
use std::fs::File;
use std::io::{BufRead, BufReader, Read, Write};
use std::net::{TcpStream, UdpSocket};
use std::time::{SystemTime, UNIX_EPOCH};

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        eprintln!("Usage: {} <directory> <port>", args[0]);
        std::process::exit(1);
    }

    let dir = &args[1];
    let port: u16 = args[2].parse().expect("Invalid port number");
    let queries_file = format!("{}/queries.txt", dir);

    let file = match File::open(&queries_file) {
        Ok(f) => f,
        Err(_) => {
            // No queries, exit gracefully
            std::process::exit(0);
        }
    };

    let reader = BufReader::new(file);
    let mut lines = reader.lines();

    for line_result in lines {
        let line = match line_result {
            Ok(l) => l,
            Err(_) => continue,
        };
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let parts: Vec<&str> = trimmed.split_whitespace().collect();
        if parts.len() < 2 {
            continue;
        }
        let name = parts[0];
        let qtype_str = parts[1];
        let qtype = parse_qtype(qtype_str);
        let query_id = random_u16();
        let query = build_dns_query(name, qtype, query_id);
        let response = send_dns_query(name, qtype, query_id, query, port);
        print_dns_response(name, qtype, &response);
    }
}

fn parse_qtype(s: &str) -> u16 {
    match s {
        "A" => 1,
        "AAAA" => 28,
        "MX" => 15,
        "TXT" => 16,
        "CNAME" => 5,
        _ => 0,
    }
}

fn random_u16() -> u16 {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos();
    ((now as u16) ^ ((now >> 48) as u16))
}

fn build_dns_query(name: &str, qtype: u16, id: u16) -> Vec<u8> {
    let mut bytes = vec![0u8; 512];
    let mut offset = 0;

    // Header (12 bytes)
    bytes[offset] = ((id >> 8) & 0xFF) as u8;
    bytes[offset + 1] = (id & 0xFF) as u8;
    offset += 2;

    bytes[offset] = 0x0100; // Flags: QR=0, OPCODE=0, RD=1
    offset += 2;

    bytes[offset] = 0x0001; // QDCOUNT=1
    bytes[offset + 1] = 0;
    offset += 2;

    bytes[offset] = 0; // ANCOUNT=0
    bytes[offset + 1] = 0;
    offset += 2;

    bytes[offset] = 0; // NSCOUNT=0
    bytes[offset + 1] = 0;
    offset += 2;

    bytes[offset] = 0; // ARCOUNT=0
    bytes[offset + 1] = 0;
    offset += 2;

    // QNAME
    let name_clean = if name.ends_with('.') {
        &name[..name.len() - 1]
    } else {
        name
    };
    let labels: Vec<&str> = name_clean.split('.').filter(|s| !s.is_empty()).collect();
    for label in labels {
        bytes[offset] = label.len() as u8;
        offset += 1;
        for ch in label.bytes() {
            bytes[offset] = ch;
            offset += 1;
        }
    }
    bytes[offset] = 0; // Null terminator
    offset += 1;

    // QTYPE and QCLASS
    bytes[offset] = ((qtype >> 8) & 0xFF) as u8;
    bytes[offset + 1] = (qtype & 0xFF) as u8;
    offset += 2;

    bytes[offset] = 1; // QCLASS IN
    bytes[offset + 1] = 0;
    offset += 2;

    bytes.truncate(offset);
    bytes
}

fn send_dns_query(name: &str, qtype: u16, query_id: u16, query: Vec<u8>, port: u16) -> DnsResponse {
    let addr = "127.0.0.1";

    // UDP
    let socket = UdpSocket::bind("0.0.0.0:0").unwrap();
    socket.set_read_timeout(Some(std::time::Duration::from_secs(5))).unwrap();

    let mut buf = vec![0u8; 4096];
    let mut response = None;

    socket.send_to(&query, &format!("{}:{}", addr, port)).unwrap();

    loop {
        match socket.recv_from(&mut buf) {
            Ok((len, _)) => {
                let pkt = &buf[..len];
                let pkt_id = u16::from_be_bytes([pkt[1], pkt[0]]);

                if pkt_id == query_id {
                    let flags = u16::from_be_bytes([pkt[2], pkt[3]]);
                    let rcode = (flags & 0x0F) as u8;
                    let tc = (flags & 0x04) != 0;
                    let qr = (flags >> 15) & 0x1;

                    if qr == 1 {
                        if tc {
                            // Retry TCP
                            let tcp_response = get_tcp_response(addr, port, query, query_id);
                            if tcp_response.id == query_id {
                                return tcp_response;
                            }
                        } else {
                            let ans = parse_answer_section(&pkt[12..]);
                            return DnsResponse {
                                id: query_id,
                                qtype,
                                qname: name.to_string(),
                                rcode,
                                answers: ans,
                            };
                        }
                    }
                }
            }
            Err(_) => break,
        }
    }

    // Fallback if no response found (should not happen per spec)
    DnsResponse {
        id: query_id,
        qtype,
        qname: name.to_string(),
        rcode: 0,
        answers: Vec::new(),
    }
}

fn get_tcp_response(addr: &str, port: u16, query: Vec<u8>, query_id: u16) -> DnsResponse {
    let socket = TcpStream::connect(&format!("{}:{}", addr, port)).expect("Connect to TCP");
    socket.set_write_timeout(Some(std::time::Duration::from_secs(5))).unwrap();
    socket.set_read_timeout(Some(std::time::Duration::from_secs(5))).unwrap();

    // Send length-prefixed query
    let mut send_buf = vec![0u8; 2 + query.len()];
    send_buf[0] = (query.len() >> 8) as u8;
    send_buf[1] = (query.len() & 0xFF) as u8;
    send_buf[2..].copy_from_slice(&query);
    socket.write_all(&send_buf).unwrap();

    // Read length-prefixed response
    let mut recv_buf = vec![0u8; 65535];
    socket.read_exact(&mut recv_buf).unwrap();

    let len = u16::from_be_bytes([recv_buf[0], recv_buf[1]]) as usize;
    let response = &recv_buf[2..2 + len];

    let pkt = response;
    let pkt_id = u16::from_be_bytes([pkt[1], pkt[0]]);
    if pkt_id != query_id {
        // Should not happen if server is correct
        return DnsResponse {
            id: query_id,
            qtype,
            qname: String::new(),
            rcode: 0,
            answers: Vec::new(),
        };
    }

    let flags = u16::from_be_bytes([pkt[2], pkt[3]]);
    let rcode = (flags & 0x0F) as u8;
    let ans_count = u16::from_be_bytes([pkt[6], pkt[7]]) as usize;
    let ans = parse_answer_section(&pkt[12..]);

    DnsResponse {
        id: query_id,
        qtype,
        qname: String::new(),
        rcode,
        answers: ans,
    }
}

fn parse_dns_response(data: &[u8]) -> DnsResponse {
    let id = u16::from_be_bytes([data[1], data[0]]);
    let flags = u16::from_be_bytes([data[2], data[3]]);
    let rcode = (flags & 0x0F) as u8;
    let qdcount = u16::from_be_bytes([data[4], data[5]]) as usize;
    let ancount = u16::from_be_bytes([data[6], data[7]]) as usize;

    let offset = 12;
    let mut name = String::new();
    let mut offset_ref = offset;
    parse_qname(data, &mut offset_ref);
    // Skip question part
    let mut offset = offset_ref;
    for _ in 0..qdcount {
        parse_qname(data, &mut offset);
    }

    let answers = parse_answer_section(data, &mut offset);

    DnsResponse {
        id,
        qtype: 0,
        qname: name,
        rcode,
        answers,
    }
}

fn parse_qname(data: &[u8], offset: &mut usize) -> String {
    let mut name = String::new();
    loop {
        if *offset >= data.len() { break; }
        let len = data[*offset];
        *offset += 1;
        if len == 0 { break; }
        if (len & 0xC0) == 0xC0 {
            let high = (len & 0x3F) as u16;
            let low = data[*offset] as u16;
            *offset += 2;
            name.push_str(&parse_qname(data, offset));
        } else {
            let end = *offset + len;
            if end > data.len() { break; }
            name.push_str(&String::from_utf8_lossy(&data[*offset..end]));
            *offset = end;
        }
    }
    name
}

fn parse_answer_section(data: &[u8], offset: &mut usize) -> Vec<DnsRecord> {
    let mut records = Vec::new();
    let ancount = u16::from_be_bytes([data[6], data[7]]) as usize;
    for _ in 0..ancount {
        let name = parse_qname(data, offset);
        let ttl = u32::from_be_bytes([data[*offset], data[*offset + 1], data[*offset + 2], data[*offset + 3]]);
        *offset += 4;
        let qtype = u16::from_be_bytes([data[*offset], data[*offset + 1]]);
        *offset += 2;
        let qclass = u16::from_be_bytes([data[*offset], data[*offset + 1]]);
        *offset += 2;
        let rdata = parse_rdata(data, qtype);
        records.push(DnsRecord {
            name,
            ttl,
            qtype,
            data: rdata,
        });
        *offset += 2; // RDATA length is variable, handled by parse_rdata
    }
    records
}

fn parse_rdata(data: &[u8], qtype: u16) -> String {
    match qtype {
        1 => format_ipv4(data),
        28 => format_ipv6(data),
        5 => format_cname(data),
        15 => format_mx(data),
        16 => format_txt(data),
        _ => format_unknown(data, qtype),
    }
}

fn format_ipv4(data: &[u8]) -> String {
    if data.len() == 4 {
        let mut parts = Vec::new();
        for b in data {
            parts.push(format!("{}", b));
        }
        parts.join(".")
    } else {
        format!("TYPE{} \\# {} {}", qtype, data.len(), format_hex(data))
    }
}

fn format_ipv6(data: &[u8]) -> String {
    let mut groups = Vec::new();
    for i in 0..8 {
        let val = u16::from_be_bytes([data[i * 2], data[i * 2 + 1]]);
        let hex = format!("{:04x}", val);
        let trimmed: String = hex.chars().filter(|&c| c != '0').collect();
        if trimmed.is_empty() {
            groups.push("0".to_string());
        } else {
            groups.push(trimmed);
        }
    }

    let mut run_start = 0;
    let mut run_len = 0;
    let mut best_run_start = 0;
    let mut best_run_len = 0;

    for (i, g) in groups.iter().enumerate() {
        if g == "0" {
            if run_len == 0 {
                run_start = i;
            }
            run_len += 1;
            if run_len > 2 {
                if run_len > best_run_len || (run_len == best_run_len && run_start < best_run_start) {
                    best_run_len = run_len;
                    best_run_start = run_start;
                }
            }
        } else {
            run_len = 0;
        }
    }

    let mut result = String::new();
    let mut i = 0;
    while i < 8 {
        if i == best_run_start && best_run_len > 0 {
            if i > 0 {
                result.push(':');
            }
            result.push_str("::");
            i += best_run_len;
            if i < 8 {
                result.push(':');
            }
        } else {
            if i > 0 && (i == best_run_start || i == best_run_start + best_run_len) {
                result.push(':');
            }
            result.push_str(&groups[i]);
            i += 1;
        }
    }
    if result.is_empty() {
        result = "::";
    }
    result
}

fn format_cname(data: &[u8]) -> String {
    let mut offset = 0;
    parse_qname(data, &mut offset)
}

fn format_mx(data: &[u8]) -> String {
    let pref = u16::from_be_bytes([data[0], data[1]]);
    let mut offset = 2;
    let mut exchange = String::new();
    while offset < data.len() {
        let len = data[offset] as usize;
        offset += 1;
        if len == 0 {
            break;
        }
        let end = offset + len;
        if end > data.len() {
            break;
        }
        exchange.push_str(&String::from_utf8_lossy(&data[offset..end]));
        offset = end;
    }
    format!("{} {}", pref, exchange)
}

fn format_txt(data: &[u8]) -> String {
    let mut parts = Vec::new();
    let mut offset = 0;
    while offset < data.len() {
        let len = data[offset] as usize;
        offset += 1;
        let end = offset + len;
        if end > data.len() {
            break;
        }
        let mut s = String::new();
        for b in data[offset..end] {
            if *b == b'"' {
                s.push_str("\\\"");
            } else if *b == b'\\' {
                s.push_str("\\\\");
            } else if *b >= 0x20 && *b <= 0x7E {
                s.push(*b as char);
            } else {
                s.push_str(&format!("\\{:03}", b));
            }
        }
        parts.push(s);
        offset = end;
    }
    parts.join(" ")
}

fn format_unknown(data: &[u8], qtype: u16) -> String {
    format!("TYPE{} \\# {} {}", qtype, data.len(), format_hex(data))
}

fn format_hex(data: &[u8]) -> String {
    data.iter().map(|b| format!("{:02x}", b)).collect::<Vec<_>>().join("")
}

fn print_dns_response(name: &str, qtype: u16, resp: &DnsResponse) {
    let rcode_str = match resp.rcode {
        0 => "NOERROR",
        1 => "FORMERR",
        2 => "SERVFAIL",
        3 => "NXDOMAIN",
        4 => "NOTIMP",
        5 => "REFUSED",
        _ => &format!("RCODE{}", resp.rcode),
    };
    println!("{} {} {}", name.to_lowercase(), qtype, rcode_str);
    for record in &resp.answers {
        println!("  {} {} {} {}", record.name, record.ttl, record.qtype, record.data);
    }
}

struct DnsResponse {
    id: u16,
    qtype: u16,
    qname: String,
    rcode: u8,
    answers: Vec<DnsRecord>,
}

struct DnsRecord {
    name: String,
    ttl: u32,
    qtype: u16,
    data: String,
}

import sys
import os
import json
import base64
import hashlib
import hmac
import re

def decode_b64url(s):
    """
    Validate and decode a base64url string without padding.
    Returns decoded bytes or raises ValueError on failure.
    """
    if not s:
        raise ValueError("Empty string")

    # Check characters
    if not re.match(r'^[A-Za-z0-9_-]+$', s):
        raise ValueError("Invalid characters")

    # Check padding char
    if '=' in s:
        raise ValueError("Padding not allowed")

    # Check length
    if len(s) % 4 == 1:
        raise ValueError("Length not valid")

    # Check unused bits
    # Add padding for decoding
    pad = (4 - len(s) % 4) % 4
    s_padded = s + '=' * pad

    try:
        data = base64.urlsafe_b64decode(s_padded)
    except Exception:
        raise ValueError("Invalid base64")

    # Check unused bits
    if len(s) % 4 == 2:
        # 12 bits -> 1 byte. Last 4 bits must be 0.
        if data[-1] & 0x0F != 0:
            raise ValueError("Non-zero unused bits")
    elif len(s) % 4 == 3:
        # 18 bits -> 2 bytes. Last 2 bits must be 0.
        if data[-1] & 0xC0 != 0:
            raise ValueError("Non-zero unused bits")

    return data

def check_json_object(s):
    """
    Check if s is a valid JSON object (dict) with unique keys.
    Returns parsed object or raises ValueError on failure.
    """
    try:
        obj = json.loads(s, object_pairs_hook=lambda pairs: _check_duplicates(pairs))
        if not isinstance(obj, dict):
            raise ValueError("Not a JSON object")
        return obj
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON: {e}")

def _check_duplicates(pairs):
    seen = set()
    for k, v in pairs:
        if k in seen:
            raise ValueError("Duplicate key")
        seen.add(k)
    return dict(pairs)

def get_hash_func(alg):
    if alg == 'HS256':
        return hashlib.sha256
    elif alg == 'HS384':
        return hashlib.sha384
    elif alg == 'HS512':
        return hashlib.sha512
    return None

def process_token(token_num, token, now, leeway, issuer, audience, keys_by_kid):
    # Split token
    parts = token.split('.')
    if len(parts) != 3:
        return f"{token_num}: MALFORMED", False

    seg0, seg1, seg2 = parts

    # Validate segments
    try:
        header_bytes = decode_b64url(seg0)
        payload_bytes = decode_b64url(seg1)
        signature_bytes = decode_b64url(seg2)
    except ValueError:
        return f"{token_num}: MALFORMED", False

    try:
        header_str = header_bytes.decode('utf-8')
        payload_str = payload_bytes.decode('utf-8')
    except UnicodeDecodeError:
        return f"{token_num}: MALFORMED", False

    try:
        header = check_json_object(header_str)
        payload = check_json_object(payload_str)
    except ValueError:
        return f"{token_num}: MALFORMED", False

    # 2. UNSUPPORTED_ALG
    alg = header.get('alg')
    if not isinstance(alg, str) or alg not in ('HS256', 'HS384', 'HS512'):
        return f"{token_num}: UNSUPPORTED_ALG", False

    # 3. UNKNOWN_KEY
    kid = header.get('kid')
    if not isinstance(kid, str) or kid not in keys_by_kid:
        return f"{token_num}: UNKNOWN_KEY", False

    # 4. ALG_MISMATCH
    key = keys_by_kid[kid]
    if key['alg'] != alg:
        return f"{token_num}: ALG_MISMATCH", False

    # 5. BAD_SIGNATURE
    hash_func = get_hash_func(alg)
    if not hash_func:
        return f"{token_num}: UNSUPPORTED_ALG", False

    key_bytes = base64.urlsafe_b64decode(key['k'] + '=' * ((4 - len(key['k']) % 4) % 4))

    signing_input = f"{seg0}.{seg1}".encode('ascii')
    expected_sig = hmac.new(key_bytes, signing_input, hash_func).digest()

    if signature_bytes != expected_sig:
        return f"{token_num}: BAD_SIGNATURE", False

    # 6. EXPIRED
    exp = payload.get('exp')
    if exp is not None:
        if now >= exp + leeway:
            return f"{token_num}: EXPIRED", False

    # 7. NOT_YET_VALID
    nbf = payload.get('nbf')
    if nbf is not None:
        if now + leeway < nbf:
            return f"{token_num}: NOT_YET_VALID", False

    # 8. BAD_ISSUER
    iss = payload.get('iss')
    if iss is None or iss != issuer:
        return f"{token_num}: BAD_ISSUER", False

    # 9. BAD_AUDIENCE
    aud = payload.get('aud')
    if aud is None:
        return f"{token_num}: BAD_AUDIENCE", False

    if isinstance(aud, str):
        if aud != audience:
            return f"{token_num}: BAD_AUDIENCE", False
    elif isinstance(aud, list):
        if audience not in aud:
            return f"{token_num}: BAD_AUDIENCE", False
    else:
        return f"{token_num}: BAD_AUDIENCE", False

    # VALID
    sub = payload.get('sub')
    if not isinstance(sub, str):
        # Should not happen for VALID tokens per spec
        return f"{token_num}: MALFORMED", False

    scope_val = payload.get('scope')
    if scope_val is not None:
        scope_parts = [p for p in scope_val.split(' ') if p]
        scope_parts = sorted(set(scope_parts))
        scope_str = ','.join(scope_parts)
    else:
        scope_str = ''

    return f"{token_num}: VALID sub={sub} scope={scope_str}", True

def main():
    if len(sys.argv) != 2:
        sys.exit(0)

    dir_path = sys.argv[1]
    os.chdir(dir_path)

    # Load config
    try:
        with open('config.json', 'r', encoding='utf-8') as f:
            config = json.load(f)
    except Exception:
        sys.exit(0)

    now = config['now']
    leeway = config['leeway']
    issuer = config['issuer']
    audience = config['audience']
    keys = config['keys']

    keys_by_kid = {k['kid']: k for k in keys}

    # Load tokens
    try:
        with open('tokens.txt', 'r', encoding='utf-8') as f:
            content = f.read()
    except Exception:
        sys.exit(0)

    lines = content.splitlines()

    valid_count = 0
    invalid_count = 0

    for line in lines:
        line = line.strip()
        if not line:
            continue

        token_num = 0
        result = ""
        is_valid = False

        # Find next token number
        # We need to track token number across lines, skipping empty lines
        # But we need to print result for each token, skipping empty lines
        # The prompt says "Number the remaining lines 1, 2, 3, … in file order."
        # So we increment counter only for processed tokens.

        # Re-structure loop
        pass

    # Correct loop
    token_counter = 0
    for line in lines:
        line = line.strip()
        if not line:
            continue

        token_counter += 1
        result, is_valid = process_token(token_counter, line, now, leeway, issuer, audience, keys_by_kid)

        print(result)

        if is_valid:
            valid_count += 1
        else:
            invalid_count += 1

    print()
    print(f"valid={valid_count} invalid={invalid_count}")
    sys.exit(0)

if __name__ == "__main__":
    main()

import sys
import os
import json
import base64
import hashlib
import hmac

def decode_b64url(s):
    """
    Validate and decode a base64url string without padding.
    Returns decoded bytes or raises ValueError on failure.
    """
    if not s:
        raise ValueError("Empty string")

    # Check characters - only A-Z a-z 0-9 - _
    if not all(c in 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_ ' for c in s):
        raise ValueError("Invalid characters")

    # Remove trailing spaces/tabs if any (shouldn't be there per spec, but be safe)
    s = s.rstrip()

    if not s:
        raise ValueError("Empty string after trim")

    # Check padding char
    if '=' in s:
        raise ValueError("Padding not allowed")

    # Check length - must be 1 more than multiple of 4
    # Valid lengths: 1, 2, 3, 5, 6, 7, 9, 10, 11, ...
    # Invalid: 0, 4, 8, 12, 16, ...
    if len(s) % 4 == 0:
        raise ValueError("Length not valid")

    # Add padding for decoding
    pad = (4 - len(s) % 4) % 4
    s_padded = s + '=' * pad

    try:
        data = base64.urlsafe_b64decode(s_padded)
    except Exception:
        raise ValueError("Invalid base64")

    # Check unused bits
    if len(s) % 4 == 2:
        # 12 bits -> 2 bytes. Last 4 bits must be 0.
        if data[-1] & 0x0F != 0:
            raise ValueError("Non-zero unused bits")
    elif len(s) % 4 == 3:
        # 18 bits -> 3 bytes. Last 2 bits must be 0.
        if data[-1] & 0xC0 != 0:
            raise ValueError("Non-zero unused bits")

    return data

def check_json_object(s):
    """
    Check if s is a valid JSON object (dict) with unique keys.
    Returns parsed object or raises ValueError on failure.
    """
    try:
        obj = json.loads(s)
        if not isinstance(obj, dict):
            raise ValueError("Not a JSON object")

        # Check for duplicate keys by parsing with object_pairs_hook
        seen = set()
        for k in obj:
            if k in seen:
                raise ValueError("Duplicate key")
            seen.add(k)

        return obj
    except json.JSONDecodeError:
        raise ValueError("Invalid JSON")
    except Exception:
        raise ValueError("Invalid JSON")

def get_hash_func(alg):
    if alg == 'HS256':
        return hashlib.sha256
    elif alg == 'HS384':
        return hashlib.sha384
    elif alg == 'HS512':
        return hashlib.sha512
    return None

def process_token(token_num, token, now, leeway, issuer, audience, keys_by_kid):
    # Split token
    parts = token.split('.')
    if len(parts) != 3:
        return f"{token_num}: MALFORMED", False

    seg0, seg1, seg2 = parts

    # Validate segments are non-empty
    if not seg0 or not seg1 or not seg2:
        return f"{token_num}: MALFORMED", False

