            if (parser.peek() == ',') parser.next();
        }
        parser.skip(); // skip ']'

        return config;
    }

    static ValidationResult validateToken(Config config, String tokenStr, int lineNum) {
        String[] segments = tokenStr.split("\\.");
        if (segments.length != 3) {
            return new ValidationResult(lineNum + ": MALFORMED", false);
        }
        if (segments[0].isEmpty() || segments[1].isEmpty() || segments[2].isEmpty()) {
            return new ValidationResult(lineNum + ": MALFORMED", false);
        }

        if (!isValidBase64url(segments[0]) || !isValidBase64url(segments[1]) || !isValidBase64url(segments[2])) {
            return new ValidationResult(lineNum + ": MALFORMED", false);
        }

        try {
            byte[] headerBytes = decodeBase64Url(segments[0]);
            byte[] payloadBytes = decodeBase64Url(segments[1]);
            byte[] signatureBytes = decodeBase64Url(segments[2]);

            Map<String, Object> header = parseJsonHeader(new String(headerBytes, StandardCharsets.UTF_8));
            Map<String, Object> payload = parseJsonPayload(new String(payloadBytes, StandardCharsets.UTF_8));

            if (!(header instanceof Map) || !(payload instanceof Map)) {
                return new ValidationResult(lineNum + ": MALFORMED", false);
            }

            // 2. UNSUPPORTED_ALG
            Object algObj = header.get("alg");
            if (algObj == null || !(algObj instanceof String)) {
                return new ValidationResult(lineNum + ": UNSUPPORTED_ALG", false);
            }
            String alg = (String) algObj;
            if (!"HS256".equals(alg) && !"HS384".equals(alg) && !"HS512".equals(alg)) {
                return new ValidationResult(lineNum + ": UNSUPPORTED_ALG", false);
            }

            // 3. UNKNOWN_KEY
            Object kidObj = header.get("kid");
            if (kidObj == null || !(kidObj instanceof String)) {
                return new ValidationResult(lineNum + ": UNKNOWN_KEY", false);
            }
            String kid = (String) kidObj;
            if (!config.keys.containsKey(kid)) {
                return new ValidationResult(lineNum + ": UNKNOWN_KEY", false);
            }

            // 4. ALG_MISMATCH
            Config.KeyInfo keyInfo = config.keys.get(kid);
            if (!keyInfo.alg.equals(alg)) {
                return new ValidationResult(lineNum + ": ALG_MISMATCH", false);
            }

            // 5. BAD_SIGNATURE
            String signingInput = segments[0] + "." + segments[1];
            byte[] inputBytes = signingInput.getBytes(StandardCharsets.US_ASCII);
            byte[] expectedSignature = computeHmac(alg, inputBytes, keyInfo.k);
            if (!Arrays.equals(expectedSignature, signatureBytes)) {
                return new ValidationResult(lineNum + ": BAD_SIGNATURE", false);
            }

            // 6. EXPIRED
            Double exp = getNumber(payload, "exp");
            if (exp != null) {
                double now = config.now;
                if (now >= exp + config.leeway) {
                    return new ValidationResult(lineNum + ": EXPIRED", false);
                }
            }

            // 7. NOT_YET_VALID
            Double nbf = getNumber(payload, "nbf");
            if (nbf != null) {
                double now = config.now;
                if (now + config.leeway < nbf) {
                    return new ValidationResult(lineNum + ": NOT_YET_VALID", false);
                }
            }

            // 8. BAD_ISSUER
            Object issObj = payload.get("iss");
            if (issObj == null || !(issObj instanceof String)) {
                return new ValidationResult(lineNum + ": BAD_ISSUER", false);
            }
            String iss = (String) issObj;
            if (!iss.equals(config.issuer)) {
                return new ValidationResult(lineNum + ": BAD_ISSUER", false);
            }

            // 9. BAD_AUDIENCE
            Object audObj = payload.get("aud");
            if (audObj == null) {
                return new ValidationResult(lineNum + ": BAD_AUDIENCE", false);
            }
            boolean audienceValid = false;
            if (audObj instanceof String) {
                String aud = (String) audObj;
                if (aud.equals(config.audience)) {
                    audienceValid = true;
                }
            } else if (audObj instanceof List) {
                List<?> audList = (List<?>) audObj;
                for (Object item : audList) {
                    if (item instanceof String && ((String) item).equals(config.audience)) {
                        audienceValid = true;
                        break;
                    }
                }
            }
            if (!audienceValid) {
                return new ValidationResult(lineNum + ": BAD_AUDIENCE", false);
            }

            // VALID
            String sub = (String) payload.get("sub");
            // Decode JSON escapes for sub
            if (sub != null) {
                sub = decodeJsonEscapes(sub);
            }

            String scopeStr = (String) payload.get("scope");
            String scopes = "";
            if (scopeStr != null) {
                scopes = processScope(scopeStr);
            }

            return new ValidationResult(lineNum + ": VALID sub=" + sub + " scope=" + scopes, true, sub, scopes);

        } catch (Exception e) {
            // If parsing fails, it's malformed
            return new ValidationResult(lineNum + ": MALFORMED", false);
        }
    }

    static boolean isValidBase64url(String segment) {
        if (segment.isEmpty()) return false;
        for (int i = 0; i < segment.length(); i++) {
            char c = segment.charAt(i);
            if (!Character.isLetterOrDigit(c) && c != '-' && c != '_') {
                return false;
            }
        }
        if (segment.contains("=")) return false;
        // Length check: not 1 more than a multiple of 4
        if (segment.length() % 4 == 1) return false;
        return true;
    }

    static byte[] decodeBase64Url(String segment) throws Exception {
        // Add padding if needed
        int padding = 4 - (segment.length() % 4);
        if (padding != 4) {
            segment += String.format("%0" + padding + "d", 0).substring(0, padding);
        }
        return java.util.Base64.getUrlDecoder().decode(segment);
    }

    static byte[] computeHmac(String alg, byte[] input, String secretBase64) throws Exception {
        byte[] key = decodeBase64Url(secretBase64);
        Mac mac = Mac.getInstance(alg);
        SecretKeySpec secretKeySpec = new SecretKeySpec(key, "HmacSHA256");
        // Need to use the correct algorithm name for the key
        if ("HS256".equals(alg)) {
            SecretKeySpec keySpec256 = new SecretKeySpec(key, "HmacSHA256");
            mac = Mac.getInstance("HmacSHA256");
            mac.init(keySpec256);
        } else if ("HS384".equals(alg)) {
            SecretKeySpec keySpec384 = new SecretKeySpec(key, "HmacSHA384");
            mac = Mac.getInstance("HmacSHA384");
            mac.init(keySpec384);
        } else if ("HS512".equals(alg)) {
            SecretKeySpec keySpec512 = new SecretKeySpec(key, "HmacSHA512");
            mac = Mac.getInstance("HmacSHA512");
            mac.init(keySpec512);
        }
        return mac.doFinal(input);
    }

    static Map<String, Object> parseJsonHeader(String json) throws Exception {
        return (Map<String, Object>) new JsonParser(json).parse();
    }

    static Map<String, Object> parseJsonPayload(String json) throws Exception {
        return (Map<String, Object>) new JsonParser(json).parse();
    }

    static Double getNumber(Map<String, Object> map, String key) {
        Object obj = map.get(key);
        if (obj instanceof Number) {
            return ((Number) obj).doubleValue();
        }
        return null;
    }

    static String decodeJsonEscapes(String s) {
        if (s == null) return "";
        StringBuilder sb = new StringBuilder();
        int i = 0;
        while (i < s.length()) {
            char c = s.charAt(i);
            if (c == '\\' && i + 1 < s.length()) {
                i++;
                char next = s.charAt(i);
                if (next == 'u') {
                    if (i + 4 < s.length()) {
                        String hex = s.substring(i + 1, i + 5);
                        sb.append((char) Integer.parseInt(hex, 16));
                        i += 4;
                    } else {
                        sb.append(c);
                        i++;
                    }
                } else {
                    sb.append(next);
                }
            } else {
                sb.append(c);
            }
            i++;
        }
        return sb.toString();
    }

    static String processScope(String s) {
        if (s == null || s.isEmpty()) return "";
        String[] parts = s.split(" ");
        List<String> unique = new ArrayList<>();
        for (String part : parts) {
            if (!part.isEmpty()) {
                if (!unique.contains(part)) {
                    unique.add(part);
                }
            }
        }
        unique.sort((a, b) -> a.compareTo(b));
        return String.join(",", unique);
    }

    static class JsonParser {
        private String input;
        private int pos;

        JsonParser(String input) {
            this.input = input;
            this.pos = 0;
        }

        void skip() throws Exception {
            while (pos < input.length() && Character.isWhitespace(input.charAt(pos))) {
                pos++;
            }
        }

        char peek() {
            skip();
            if (pos >= input.length()) throw new Exception("Unexpected end");
            return input.charAt(pos);
        }

        char next() throws Exception {
            skip();
            if (pos >= input.length()) throw new Exception("Unexpected end");
            return input.charAt(pos++);
        }

        Object parse() throws Exception {
            skip();
            char c = peek();
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (c == 't' || c == 'f') return parseBool();
            if (c == 'n') return parseNull();
            if (c == '-' || Character.isDigit(c)) return parseNumber();
            throw new Exception("Unexpected character: " + c);
        }

        String parseString() throws Exception {
            next(); // skip "
            StringBuilder sb = new StringBuilder();
            while (true) {
                char c = next();
                if (c == '"') break;
                if (c == '\\') {
                    char nextC = next();
                    if (nextC == 'u') {
                        String hex = new String(new char[]{input.charAt(pos - 2), input.charAt(pos - 1), input.charAt(pos), input.charAt(pos + 1)});
                        pos -= 4;
                        sb.append((char)Integer.parseInt(hex, 16));
                    } else {
                        sb.append(nextC);
                    }
                } else {
                    sb.append(c);
                }
            }
            return sb.toString();
        }

        Number parseNumber() throws Exception {
            skip();
            StringBuilder sb = new StringBuilder();
            if (peek() == '-') sb.append(next());
            while (peek() >= '0' && peek() <= '9') sb.append(next());
            if (peek() == '.') {
                sb.append(next());
                while (peek() >= '0' && peek() <= '9') sb.append(next());
            }
            if (peek() == 'e' || peek() == 'E') {
                sb.append(next());
                if (peek() == '-' || peek() == '+') sb.append(next());
                while (peek() >= '0' && peek() <= '9') sb.append(next());
            }
            return Double.parseDouble(sb.toString());
        }

        boolean parseBool() throws Exception {
            next(); // skip t/f
            if (input.startsWith("true", pos - 1)) {
                pos += 4;
                return true;
            } else {
                pos += 5;
                return false;
            }
        }

        Object parseNull() throws Exception {
            next(); // skip n
            pos += 3; // ull
            return null;
        }

        Object parseArray() throws Exception {
            next(); // skip [
            List<Object> list = new ArrayList<>();
            if (peek() != ']') {
                list.add(parse());
                while (peek() == ',') {
                    next();
                    list.add(parse());
                }
            }
            next(); // skip ]
            return list;
        }

        Object parseObject() throws Exception {
            next(); // skip {
            Map<String, Object> map = new LinkedHashMap<>();
            if (peek() != '}') {
                String key = parseString();
                next(); // skip :
                map.put(key, parse());
                while (peek() == ',') {
                    next();
                    key = parseString();
                    next(); // skip :
                    map.put(key, parse());
                }
            }
            next(); // skip }
            return map;
        }
    }
