                        result.append(new String(bytes, StandardCharsets.UTF_8));
                        i = eq + 2;
                        continue;
                    }
                }
                result.append(text.charAt(i++));
            }
            return result.toString();
        }

        private byte[] decodeEncodedWord(String charset, String enc, String encoded, boolean isBase64) {
            if (charset.equals("us-ascii")) return encoded.getBytes(StandardCharsets.US_ASCII);
            if (charset.equals("utf-8")) return encoded.getBytes(StandardCharsets.UTF_8);
            if (charset.equals("iso-8859-1")) return encoded.getBytes(StandardCharsets.ISO_8859_1);
            if (charset.equals("windows-1252")) return encoded.getBytes(StandardCharsets.ISO_8859_1); // Simplified
            // Windows-1252 specific mapping
            byte[] bytes = encoded.getBytes(StandardCharsets.ISO_8859_1);
            for (int i = 0; i < bytes.length; i++) {
                byte b = bytes[i];
                if (b >= 0x80 && b <= 0x9F) {
                    bytes[i] = windows1252Map[b];
                }
            }
            return bytes;
        }

        private static final byte[] windows1252Map = new byte[128];
        static {
            System.arraycopy(StandardCharsets.ISO_8859_1.newDecoder().decode("€").toByteArray(), 0, windows1252Map, 0, 1);
            // 0x80 -> €
