        private static String getCharset(String name) {
            if (name.equals("us-ascii")) return StandardCharsets.US_ASCII.name();
            if (name.equals("utf-8")) return StandardCharsets.UTF_8.name();
            if (name.equals("iso-8859-1")) return StandardCharsets.ISO_8859_1.name();
            if (name.equals("windows-1252")) return "windows-1252";
            return StandardCharsets.UTF_8.name();
        }

        private byte[] decodeTransfer(byte[] raw, String cte) throws Exception {
            if (cte.equals("7bit") || cte.equals("8bit") || cte.equals("binary")) {
                return raw;
            }
            if (cte.equals("base64")) {
                String str = new String(raw, StandardCharsets.UTF_8);
                int end = str.indexOf('=');
                if (end != -1) str = str.substring(0, end);
                return Base64.getDecoder().decode(str);
            }
            if (cte.equals("quoted-printable")) {
                String str = new String(raw, StandardCharsets.UTF_8);
                // Remove trailing spaces/tabs from each line
                StringBuilder sb = new StringBuilder();
                int i = 0;
                while (i < str.length()) {
                    int lineEnd = str.indexOf(lineSep, i);
                    if (lineEnd == -1) {
                        sb.append(str.substring(i));
                        break;
                    }
                    sb.append(str.substring(i, lineEnd));
                    // Remove trailing spaces/tabs
                    int end = sb.length() - 1;
                    while (end >= 0 && (sb.charAt(end) == ' ' || sb.charAt(end) == '\t')) end--;
                    sb.setLength(end + 1);
                    i = lineEnd + lineSep.length();
                }
                str = sb.toString();

                // Handle soft line breaks
                StringBuilder sb2 = new StringBuilder();
                i = 0;
                while (i < str.length()) {
                    int eq = str.indexOf('=', i);
                    if (eq != -1) {
                        int nextLine = str.indexOf(lineSep, eq + 1);
                        if (nextLine != -1 && nextLine == eq + 1) {
                            // Soft break
                            i = nextLine + lineSep.length();
                            continue;
                        } else {
                            // Not soft break, keep =
                            sb2.append(str.substring(i, eq + 1));
                            i = eq + 1;
                            continue;
                        }
                    }
                    sb2.append(str.substring(i));
                    break;
                }
                str = sb2.toString();

                // Decode
                byte[] bytes = new byte[str.length()];
                for (int i = 0; i < str.length(); i++) {
                    char c = str.charAt(i);
                    if (c == '=') {
                        if (i + 2 < str.length()) {
                            String hex = String.valueOf(str.charAt(i + 1)) + String.valueOf(str.charAt(i + 2));
                            try {
                                bytes[i] = (byte) Integer.parseInt(hex, 16);
                                i += 2;
                            } catch (NumberFormatException e) {
                                bytes[i] = (byte) '=';
                            }
                        } else {
                            bytes[i] = (byte) '=';
                        }
                    } else {
                        bytes[i] = (byte) c;
                    }
                }
                return bytes;
            }
            return raw;
        }

        private int decodedTransferSize(byte[] raw, String cte) throws Exception {
            byte[] decoded = decodeTransfer(raw, cte);
            return decoded.length;
        }

        private long calcCRC32(byte[] data) {
            CRC32 crc = new CRC32();
            crc.update(data);
            return crc.getValue();
        }

        private String normalizeLineBreaks(String text) {
            return text.replace("\r\n", "\n").replace("\r", "\n");
        }

        private String quotedString(String text) {
            StringBuilder sb = new StringBuilder();
            sb.append("\"");
            for (int i = 0; i < text.length(); i++) {
                char c = text.charAt(i);
                if (c == '\\' || c == '"') {
                    sb.append('\\').append(c);
                } else if (c == '\n') {
                    sb.append('\\').append('n');
                } else if (c == '\t') {
                    sb.append('\\').append('t');
                } else if (c < 0x20 || (c >= 0x7F && c <= 0x9F)) {
                    sb.append(String.format("\\u%04x", (int) c));
                } else {
                    sb.append(c);
                }
            }
            sb.append("\"");
            return sb.toString();
        }
    }

    static class Multipart extends Part {
        private String boundary;
        private byte[] rawBytes;
        private String lineSep;

        public Multipart(Map<String, String> headers, byte[] rawBytes, String lineSep, String type, String boundary, String disposition) {
            super(headers, rawBytes, lineSep, type, disposition);
            this.boundary = boundary;
            this.rawBytes = rawBytes;
            this.lineSep = lineSep;
            parseParts();
        }

        private void parseParts() {
            try {
                String content = new String(rawBytes, StandardCharsets.UTF_8);
                // Find boundary
                String delim = "--" + boundary + lineSep;
                int start = 0;

                // Preamble
                int delimIndex = content.indexOf(delim);
                if (delimIndex != -1) {
                    // Preamble
                    if (delimIndex > 0) {
                        String preamble = content.substring(0, delimIndex);
                        // Ignore preamble
                    }
                    start = delimIndex + delim.length();
                }

                // Find close delimiter
                String closeDelim = "--" + boundary + "--" + lineSep;
                int closeIndex = content.indexOf(closeDelim);

                // Loop for parts
                while (start < content.length()) {
                    int nextDelim = content.indexOf(delim, start);
                    int nextClose = content.indexOf(closeDelim, start);

                    if (nextClose != -1 && (nextDelim == -1 || nextClose < nextDelim)) {
                        // Epilogue
                        break;
                    }

                    if (nextDelim == -1) break;

                    String partContent = content.substring(start, nextDelim);

                    // Parse part header
                    String[] partLines = partContent.split(lineSep, -1);
                    Map<String, String> partHeaders = new HashMap<>();
                    for (String line : partLines) {
                        int colon = line.indexOf(':');
                        if (colon != -1) {
                            String name = line.substring(0, colon).trim().toLowerCase();
                            String value = line.substring(colon + 1).trim();
                            partHeaders.put(name, value);
                        }
                    }

                    // Skip empty line
                    int headerEnd = 0;
                    for (String line : partLines) {
                        if (line.trim().isEmpty()) {
                            headerEnd = headerEnd + line.length() + lineSep.length();
                            break;
                        }
                        headerEnd = headerEnd + line.length() + lineSep.length();
                    }

                    byte[] partBytes = partContent.getBytes(StandardCharsets.UTF_8);
                    String type = partHeaders.get("content-type");
                    String disposition = partHeaders.get("content-disposition");
                    if (disposition == null || disposition.trim().isEmpty()) disposition = "inline";
                    else disposition = disposition.trim().toLowerCase();

                    children.add(new Part(partHeaders, partBytes, lineSep, type, disposition));

                    start = nextDelim + delim.length();
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }
}

import java.io.*;
import java.nio.charset.*;
import java.nio.file.*;
import java.util.*;
import java.util.regex.*;
import java.util.zip.*;

public class Main {
    public static void main(String[] args) throws Exception {
        if (args.length != 1) {
            return;
        }
        Path dir = Paths.get(args[0]);
        if (!Files.exists(dir)) return;

        List<Path> files = new ArrayList<>();
        try (Stream<Path> stream = Files.list(dir)) {
            stream.filter(p -> Files.isRegularFile(p))
                  .filter(p -> p.toString().toLowerCase().endsWith(".eml"))
                  .forEach(files::add);
        }

        Collections.sort(files, (p1, p2) -> {
            byte[] b1 = p1.getFileName().toString().getBytes(StandardCharsets.UTF_8);
            byte[] b2 = p2.getFileName().toString().getBytes(StandardCharsets.UTF_8);
            return Arrays.compare(b1, b2);
        });

        for (int i = 0; i < files.size(); i++) {
            if (i > 0) System.out.println();
            processFile(files.get(i));
        }
    }

    private static void processFile(Path file) throws Exception {
        byte[] rawBytes = Files.readAllBytes(file);
        MimeMessage message = new MimeMessage(rawBytes);

        System.out.println("== " + file.getFileName());
        System.out.println("From: " + quotedString(message.getHeader("From")));
        System.out.println("Subject: " + quotedString(message.getHeader("Subject")));
        message.printTree();
    }

    static class MimeMessage {
        private byte[] rawBytes;
        private String lineSep;
        private Map<String, String> headers;
        private Part root;

        public MimeMessage(byte[] rawBytes) throws Exception {
            this.rawBytes = rawBytes;
            detectLineSep();
            parse();
        }

        private void detectLineSep() {
            int lastCRLF = -1;
            int lastLF = -1;
            for (int i = 0; i < rawBytes.length; i++) {
                if (rawBytes[i] == 0x0A) { // LF
                    lastLF = i;
                }
                if (rawBytes[i] == 0x0D && i + 1 < rawBytes.length && rawBytes[i + 1] == 0x0A) { // CRLF
                    lastCRLF = i;
                }
            }
            if (lastCRLF != -1) {
                lineSep = "\r\n";
            } else if (lastLF != -1) {
                lineSep = "\n";
            } else {
                lineSep = "\n";
            }
        }

        private void parse() throws Exception {
            String content = new String(rawBytes, StandardCharsets.UTF_8);
            String[] lines = content.split(lineSep, -1);

            StringBuilder headerBuilder = new StringBuilder();
            for (String line : lines) {
                headerBuilder.append(line).append(lineSep);
            }
            String headerContent = headerBuilder.toString();

            headers = new HashMap<>();
            int headerEnd = 0;
            while (headerEnd < headerContent.length()) {
                int nextLine = headerContent.indexOf(lineSep, headerEnd);
                if (nextLine == -1) break;
                String headerLine = headerContent.substring(headerEnd, nextLine);
                int colon = headerLine.indexOf(':');
                if (colon != -1) {
                    String name = headerLine.substring(0, colon).trim().toLowerCase();
                    String value = headerLine.substring(colon + 1).trim();
                    headers.put(name, value);
                }
                headerEnd = nextLine + lineSep.length();
            }
            // Skip empty line after headers
            if (headerEnd < headerContent.length()) {
                headerEnd += lineSep.length();
            }

            // Parse body
            if (headerEnd >= headerContent.length()) {
                this.root = new Part(headers, rawBytes, lineSep, "text/plain", "inline");
            } else {
                String body = headerContent.substring(headerEnd);
                String contentType = headers.get("content-type");
                if (contentType == null || contentType.trim().isEmpty()) {
                    this.root = new Part(headers, rawBytes, lineSep, "text/plain", "inline");
                } else {
                    this.root = parseBody(body, headers, "application/octet-stream", "attachment");
                }
            }
        }

        private Part parseBody(String body, Map<String, String> headers, String defaultType, String defaultDisp) {
            String contentType = headers.get("content-type");
            if (contentType == null || contentType.trim().isEmpty()) {
                return new Part(headers, rawBytes, lineSep, defaultType, defaultDisp);
            }
            String[] ctParts = contentType.split(";");
            String typeSubtype = ctParts[0].trim();
            String disposition = headers.get("content-disposition");
            if (disposition == null || disposition.trim().isEmpty()) {
                disposition = "inline";
            } else {
                disposition = disposition.trim().toLowerCase();
                String[] dispParts = disposition.split(";");
                if (dispParts.length > 0) disposition = dispParts[0].trim().toLowerCase();
            }

            if (typeSubtype.startsWith("multipart/")) {
                String boundary = null;
                for (String param : ctParts) {
                    if (param.trim().startsWith("boundary=")) {
                        boundary = param.trim().substring("boundary=".length());
                        break;
                    }
                }
                if (boundary == null) boundary = "boundary";
                return new Multipart(headers, rawBytes, lineSep, typeSubtype, boundary, disposition);
            }
            return new Part(headers, rawBytes, lineSep, typeSubtype, disposition);
        }

        public void printTree() {
            root.print(0);
        }

        public String getHeader(String name) {
            return headers.getOrDefault(name.toLowerCase(), null);
        }
    }

    static class Part {
        private Map<String, String> headers;
        private byte[] rawBytes;
        private String lineSep;
        private String type;
        private String subtype;
        private String disposition;
        private List<Part> children;

        public Part(Map<String, String> headers, byte[] rawBytes, String lineSep, String type, String disposition) {
            this.headers = headers;
            this.rawBytes = rawBytes;
            this.lineSep = lineSep;
            this.type = type;
            this.subtype = subtype;
            this.disposition = disposition;
            this.children = new ArrayList<>();
        }

        public void print(int indent) {
            String cte = headers.get("content-transfer-encoding");
            if (cte == null || cte.trim().isEmpty()) cte = "7bit";
            cte = cte.trim().toLowerCase();

            String disp = this.disposition;
            if (disp == null || disp.trim().isEmpty()) disp = "-";
            else disp = disp.trim().toLowerCase();

            String name = "-";
            byte[] nameBytes = null;
            String displayName = null;

            // Determine name
            String contentType = headers.get("content-type");
            String dispHeader = this.disposition;

            // RFC 2231 check for filename
            String nameParam = null;
            if (contentType != null && !contentType.trim().isEmpty()) {
                nameParam = getParam(contentType, "name");
            }
            if (nameParam == null && dispHeader != null && !dispHeader.trim().isEmpty()) {
                nameParam = getParam(dispHeader, "filename");
            }
            if (nameParam != null) {
                if (nameParam.endsWith("*")) {
                    nameBytes = decodeRFC2231(nameParam);
                    displayName = new String(nameBytes, StandardCharsets.UTF_8);
                } else {
                    displayName = decodeRFC2047(nameParam);
                }
            }

            if (children.isEmpty()) {
                // Single part
                if (type.startsWith("text/") && !dispHeader.equals("attachment")) {
                    String charset = headers.get("charset");
                    if (charset == null || charset.trim().isEmpty()) charset = "us-ascii";
                    charset = charset.trim().toLowerCase();

                    byte[] decodedBytes = decodeTransfer(rawBytes, cte);
                    String decodedStr = new String(decodedBytes, getCharset(charset));
                    decodedStr = normalizeLineBreaks(decodedStr);
                    int chars = decodedStr.codePointCount(0, decodedStr.length());

                    System.out.println("  ".repeat(indent) + "text/" + subtype + " charset=" + charset + " cte=" + cte + " chars=" + chars);
                    System.out.println("  ".repeat(indent + 1) + quotedString(decodedStr));
                } else {
                    // Other part
                    byte[] decodedBytes = decodeTransfer(rawBytes, cte);
                    int size = decodedBytes.length;
                    long crc = calcCRC32(decodedBytes);
                    System.out.println("  ".repeat(indent) + type + "/" + subtype + " cte=" + cte + " disposition=" + disp + " name=\"" + quotedString(displayName) + "\" size=" + size + " crc32=" + String.format("%08x", crc));
                }
            } else {
                // Multipart
                System.out.println("  ".repeat(indent) + "multipart/" + subtype + " parts=" + children.size());
                for (Part child : children) {
                    child.print(indent + 1);
                }
            }
        }

        private String getParam(String paramStr, String name) {
            if (!paramStr.startsWith(name + "=")) return null;
            String value = paramStr.substring(name.length() + 1);
            return value.trim();
        }

        private byte[] decodeRFC2231(String paramStr) {
            // RFC 2231: a*=charset'lang'value or a*0, a*1...
            String[] parts = paramStr.split("=");
            if (parts.length < 2) return new byte[0];

            String segName = parts[0].trim();
            if (!segName.endsWith("*")) {
                // Not RFC 2231 form, treat as RFC 2047
                return new String(decodeRFC2047(paramStr), StandardCharsets.UTF_8).getBytes(StandardCharsets.UTF_8);
            }

            // RFC 2231 form - parse segments
            List<String> segs = new ArrayList<>();
            for (String part : parts) {
                part = part.trim();
                if (part.startsWith("filename*") || part.startsWith("name*")) {
                    segs.add(part);
                }
            }
            // Sort segments by number
            segs.sort((a, b) -> {
                String na = a.replace("*", "").replace("filename", "").replace("name", "");
                String nb = b.replace("*", "").replace("filename", "").replace("name", "");
                int ia = -1, ib = -1;
                try {
                    ia = Integer.parseInt(na);
                } catch (Exception e) { ia = 0; }
                try {
                    ib = Integer.parseInt(nb);
                } catch (Exception e) { ib = 0; }
                return Integer.compare(ia, ib);
            });

            StringBuilder sb = new StringBuilder();
            String charset = "us-ascii";
            String lang = "";

            // Get charset from first segment if present
            if (!segs.isEmpty()) {
                String first = segs.get(0);
                if (first.contains("'")) {
                    int idx = first.indexOf("'");
                    if (idx != -1) {
                        String csPart = first.substring(0, idx);
                        int q = csPart.indexOf("'");
                        if (q != -1 && q > 0) {
                            charset = csPart.substring(0, q).trim().toLowerCase();
                            if (q + 1 < csPart.length()) {
                                lang = csPart.substring(q + 1, idx).trim();
                            }
                        }
                    }
                }
            }

            for (String s : segs) {
                if (s.endsWith("*")) {
                    // Percent encoded segment
                    int eq = s.indexOf('=');
                    if (eq != -1) {
                        String val = s.substring(eq + 1);
                        for (int i = 0; i < val.length(); i++) {
                            char c = val.charAt(i);
                            if (c == '%') {
                                if (i + 2 < val.length()) {
                                    String hex = val.substring(i + 1, i + 3);
                                    sb.append((byte) Integer.parseInt(hex, 16));
                                    i += 2;
                                }
                            } else {
                                sb.append(c);
                            }
                        }
                    }
                } else {
                    // Literal segment
                    int eq = s.indexOf('=');
                    if (eq != -1) {
                        sb.append(s.substring(eq + 1));
                    }
                }
            }
            return sb.toString().getBytes(getCharset(charset));
        }

        private String decodeRFC2047(String text) {
            StringBuilder result = new StringBuilder();
            int i = 0;
            while (i < text.length()) {
                if (i + 3 < text.length() && text.charAt(i) == '=' && 
                    text.charAt(i + 1) == '?' && text.charAt(i + 2) != '?') {
                    int end = text.indexOf('?', i + 3);
                    if (end != -1) {
                        int start = end + 1;
                        int eq = text.indexOf('?', start);
                        if (eq != -1 && eq < text.length()) {
                            String charset = text.substring(i + 2, end);
                            if (charset.endsWith("*")) charset = charset.substring(0, charset.indexOf("*")).trim().toLowerCase();
                            else charset = charset.toLowerCase();

                            String encoding = text.substring(i + 3, end - 1);
                            if (encoding.equals("B") || encoding.equals("b")) {
                                String encoded = text.substring(start, eq);
                                byte[] bytes = decodeEncodedWord(charset, "B", encoded, true);
                                result.append(new String(bytes, StandardCharsets.UTF_8));
                                i = eq + 2;
                                continue;
                            } else if (encoding.equals("Q") || encoding.equals("q")) {
                                String encoded = text.substring(start, eq);
                                byte[] bytes = decodeEncodedWord(charset, "Q", encoded, false);
                                result.append(new String(bytes, StandardCharsets.UTF_8));
                                i = eq + 2;
                                continue;
                            }
                        }
                    }
                }
                result.append(text.charAt(i++));
            }
            return result.toString();
        }

        private byte[] decodeEncodedWord(String charset, String enc, String encoded, boolean isBase64) {
            byte[] bytes;
            if (charset.equals("us-ascii")) {
                bytes = encoded.getBytes(StandardCharsets.US_ASCII);
            } else if (charset.equals("utf-8")) {
                bytes = encoded.getBytes(StandardCharsets.UTF_8);
            } else if (charset.equals("iso-8859-1")) {
                bytes = encoded.getBytes(StandardCharsets.ISO_8859_1);
            } else if (charset.equals("windows-1252")) {
                bytes = encoded.getBytes(StandardCharsets.ISO_8859_1);
                for (int j = 0; j < bytes.length; j++) {
                    byte b = bytes[j];
                    if (b >= 0x80 && b <= 0x9F) {
                        bytes[j] = windows1252Map[b];
                    }
                }
            } else {
                bytes = encoded.getBytes(StandardCharsets.UTF_8);
            }

            if (isBase64) {
                return Base64.getDecoder().decode(bytes);
            } else {
                return decodeQuotedPrintable(bytes);
            }
        }

        private static final byte[] windows1252Map = new byte[128];
        static {
            for (int i = 0; i < 128; i++) {
                windows1252Map[i] = (byte) i;
            }
            windows1252Map[0x80] = (byte) 0x20AC;  // €
            windows1252Map[0x81] = (byte) 0x81;   // U+0081
            windows1252Map[0x82] = (byte) 0x201A;  // ‚
            windows1252Map[0x83] = (byte) 0x0192;  // ƒ
            windows1252Map[0x84] = (byte) 0x201E;  // „
            windows1252Map[0x85] = (byte) 0x2026;  // …
            windows1252Map[0x86] = (byte) 0x2020;  // †
