// --- Types and Value Classes ---

type ValueType = 'int' | 'bool' | 'string' | 'list' | 'function' | 'nil';

class Value {
  type: ValueType;
  constructor(type: ValueType) {
    this.type = type;
  }
}

class IntValue extends Value {
  value: bigint;
  constructor(value: bigint) {
    super('int');
    this.value = value;
  }
}

class BoolValue extends Value {
  value: boolean;
  constructor(value: boolean) {
    super('bool');
    this.value = value;
  }
}

class StringValue extends Value {
  value: string;
  constructor(value: string) {
    super('string');
    this.value = value;
  }
}

class ListValue extends Value {
  value: ListValue[];
  constructor(value: ListValue[]) {
    super('list');
    this.value = value;
  }
}

class NilValue extends Value {
  constructor() {
    super('nil');
  }
}

class FunctionValue extends Value {
  // Function closure: body, params, scope, name
  body: Array<ASTNode>;
  params: string[];
  scope: Scope; // Captured scope
  name: string; // For display
  constructor(body: Array<ASTNode>, params: string[], scope: Scope, name: string) {
