    this.body = body;
    this.params = params;
    this.scope = scope;
    this.name = name;
  }
}

// --- AST Nodes ---

type ASTNode =
  | Program
  | Block
  | LetStmt
  | FnDecl
  | IfStmt
  | WhileStmt
  | ForStmt
  | ReturnStmt
  | BreakStmt
  | ContinueStmt
  | AssignStmt
  | IndexAssign
  | Expr
  | BinaryOp
  | UnaryOp
  | Call
  | ArrayLit
  | IndexExpr
  | Primary;

