}

class ReturnStmt extends ASTNodeBase {
  expr?: Expr;
  constructor(line: number, expr?: Expr) {
    super(line);
    this.expr = expr;
  }
}

class BreakStmt extends ASTNodeBase {
  constructor(line: number) {
    super(line);
  }
}

class ContinueStmt extends ASTNodeBase {
  constructor(line: number) {
    super(line);
  }
}

class AssignStmt extends ASTNodeBase {
  name: string;
  expr: Expr;
  constructor(line: number, name: string, expr: Expr) {
    super(line);
    this.name = name;
    this.expr = expr;
  }
}

class IndexAssign extends ASTNodeBase {
  obj: Expr;
  index: Expr;
  value: Expr;
  constructor(line: number, obj: Expr, index: Expr, value: Expr) {
    super(line);
    this.obj = obj;
    this.index = index;
    this.value = value;
  }
}

abstract class ExprBase extends ASTNodeBase {
  abstract eval(scope: Scope): Value;
}

class BinaryOp extends ExprBase {
  op: string;
  left: Expr;
  right: Expr;
  constructor(line: number, op: string, left: Expr, right: Expr) {
    super(line);
    this.op = op;
    this.left = left;
    this.right = right;
  }
}

class UnaryOp extends ExprBase {
  op: string;
  expr: Expr;
  constructor(line: number, op: string, expr: Expr) {
    super(line);
    this.op = op;
    this.expr = expr;
  }
}

class Call extends ExprBase {
  callee: Expr;
  args: Array<Expr>;
  constructor(line: number, callee: Expr, args: Array<Expr>) {
    super(line);
    this.callee = callee;
    this.args = args;
  }
}

class ArrayLit extends ExprBase {
  items: Array<Expr>;
  constructor(line: number, items: Array<Expr>) {
    super(line);
    this.items = items;
  }
}

class IndexExpr extends ExprBase {
  obj: Expr;
  index: Expr;
  constructor(line: number, obj: Expr, index: Expr) {
    super(line);
    this.obj = obj;
    this.index = index;
  }
}

class Primary extends ExprBase {
  type: 'int' | 'string' | 'bool' | 'nil' | 'ident' | 'array' | 'fn' | 'paren';
  // For literals
  value?: bigint | string | boolean;
  // For ident
  name?: string;
  // For fn
  params?: string[];
  block?: Block;
  // For array
  items?: Array<Expr>;
  constructor(line: number, type: string, value?: bigint | string | boolean, name?: string, params?: string[], block?: Block, items?: Array<Expr>) {
    super(line);
    this.type = type;
    this.value = value;
    this.name = name;
    this.params = params;
    this.block = block;
    this.items = items;
  }
}

// --- Lexer ---

interface Token {
  type: string;
  value: string | bigint;
  line: number;
}

const KEYWORDS = new Set([
  'let', 'fn', 'if', 'else', 'while', 'for', 'in', 'return', 'break', 'continue',
  'and', 'or', 'not', 'true', 'false', 'nil'
]);

const OPERATORS = [
  '==', '!=', '<=', '>=', '<', '>',
  '+', '-', '*', '/', '%',
  '=', '(', ')', '[', ']', '{', '}', ','
];

class Lexer {
  source: string;
  pos: number;
  line: number;
  currentLine: number;
  tokens: Token[];

  constructor(source: string) {
    this.source = source;
    this.pos = 0;
    this.line = 1;
    this.currentLine = 1;
    this.tokens = [];
  }

  peek(): string | null {
    if (this.pos >= this.source.length) return null;
    return this.source[this.pos];
  }

  advance(): string | null {
    const c = this.source[this.pos];
    this.pos++;
    if (c === '\n') this.line++;
    return c;
  }

  skipWhitespace() {
    while (this.peek() === ' ' || this.peek() === '\t' || this.peek() === '\r' || this.peek() === '\n') {
      this.advance();
    }
  }

  skipComment() {
    while (this.peek() !== null && this.peek() !== '\n') {
      this.advance();
    }
  }

  readToken() {
    this.skipWhitespace();
    const startLine = this.line;

    if (this.peek() === null) return null;

    // String
    if (this.peek() === '"') {
      this.advance(); // consume opening quote
      let val = '';
      while (true) {
        if (this.peek() === null) throw new Error('Unterminated string');
        if (this.peek() === '"') {
          this.advance();
          return { type: 'STRING', value: val, line: startLine };
        }
        if (this.peek() === '\\') {
          this.advance();
          const escape = this.advance();
          if (escape === 'n') val += '\n';
          else if (escape === 't') val += '\t';
          else if (escape === '"') val += '"';
          else if (escape === '\\') val += '\\';
          else throw new Error('Invalid escape');
        } else {
          val += this.advance();
        }
      }
    }

    // Number
    if (/^[0-9]/.test(this.peek())) {
      let val = '';
      while (this.peek() !== null && /^[0-9]/.test(this.peek())) {
        val += this.advance();
      }
      const num = BigInt(val);
      return { type: 'INT', value: num, line: startLine };
    }

    // Identifier / Keyword
    if (/[A-Za-z_]/.test(this.peek())) {
      let val = '';
      while (this.peek() !== null && /[A-Za-z0-9_]/.test(this.peek())) {
        val += this.advance();
      }
      const type = KEYWORDS.has(val) ? 'KEYWORD' : 'IDENT';
      return { type, value: val, line: startLine };
    }

    // Operators / Punctuation
    if (this.peek() === '#') {
      this.skipComment();
      return this.readToken();
    }

    const c = this.peek();
    if (c === '(' || c === ')' || c === '{' || c === '}' || c === '[' || c === ']' || c === ';' || c === ',') {
      this.advance();
      return { type: c, value: c, line: startLine };
    }

    // Multi-char operators
    const len = this.peek() === '=' && this.peek(1) === '=' ? 2 : 
                this.peek() === '=' ? 1 :
                this.peek() === '<' && this.peek(1) === '=' ? 2 :
                this.peek() === '<' ? 1 :
                this.peek() === '>' && this.peek(1) === '=' ? 2 :
                this.peek() === '>' ? 1 :
                this.peek() === '+' || this.peek() === '-' || this.peek() === '*' || this.peek() === '/' || this.peek() === '%' ? 1 :
                null;

    if (len) {
      const op = this.peek();
      if (len === 2) {
        this.advance(); this.advance();
      } else {
        this.advance();
      }
      return { type: op, value: op, line: startLine };
    }

    throw new Error(`Unexpected character: ${c}`);
  }

  peekChar(n: number = 0): string | null {
    const idx = this.pos + n;
    if (idx >= this.source.length) return null;
    return this.source[idx];
  }

  tokenize(): Token[] {
    while (true) {
      const tok = this.readToken();
      if (!tok) break;
      this.tokens.push(tok);
    }
    this.tokens.push({ type: 'EOF', value: '', line: this.line });
    return this.tokens;
  }
}

// --- Parser ---

class Parser {
  tokens: Token[];
  pos: number;

  constructor(tokens: Token[]) {
    this.tokens = tokens;
    this.pos = 0;
  }

  current(): Token { return this.tokens[this.pos]; }
  peek(n: number = 0): Token { return this.tokens[this.pos + n]; }

  consume(type: string, value?: string): Token {
    const t = this.current();
    if (t.type !== type || (value !== undefined && t.value !== value)) {
      throw new Error(`Expected ${type} or ${value}, got ${t.type}`);
    }
    this.pos++;
    return t;
  }

  expect(type: string, value?: string): Token {
    const t = this.current();
    if (t.type !== type || (value !== undefined && t.value !== value)) {
      throw new Error(`Expected ${type} or ${value}, got ${t.type}`);
    }
    this.pos++;
    return t;
  }

  parseProgram(): Program {
    const stmts: Array<ASTNode> = [];
    while (this.current().type !== 'EOF') {
      stmts.push(this.parseStmt());
    }
    return new Program(stmts[0].line, stmts);
  }

  parseStmt(): ASTNode {
    const line = this.current().line;
    const tok = this.current();

    if (tok.type === 'KEYWORD') {
      if (tok.value === 'let') return this.parseLet();
      if (tok.value === 'fn') return this.parseFn();
      if (tok.value === 'if') return this.parseIf();
      if (tok.value === 'while') return this.parseWhile();
      if (tok.value === 'for') return this.parseFor();
      if (tok.value === 'return') return this.parseReturn();
      if (tok.value === 'break') return this.parseBreak();
      if (tok.value === 'continue') return this.parseContinue();
    }

    if (tok.value === '{') return this.parseBlock();
    if (tok.type === 'IDENT') return this.parseAssign();
    if (tok.type === 'INT' || tok.type === 'STRING' || tok.type === 'KEYWORD' || tok.type === 'IDENT') {
      // Could be postfix expression
      return this.parsePostfix();
    }

    throw new Error(`Unexpected token: ${tok.type}`);
  }

  parseLet(): LetStmt {
    this.expect('KEYWORD', 'let');
    const name = this.expect('IDENT').value as string;
    this.expect('=');
    const expr = this.parseExpr();
    this.expect(';');
    return new LetStmt(this.current().line, name, expr);
  }

  parseFn(): FnDecl {
    this.expect('KEYWORD', 'fn');
    const name = this.expect('IDENT').value as string;
    this.expect('(');
    const params: string[] = [];
    if (this.current().type !== ')') {
      params.push(this.expect('IDENT').value as string);
      while (this.current().type === ',') {
        this.consume(',');
        params.push(this.expect('IDENT').value as string);
      }
    }
    this.expect(')');
    const block = this.parseBlock();
    return new FnDecl(this.current().line, name, params, block);
  }

  parseBlock(): Block {
    this.expect('{');
    const stmts: Array<ASTNode> = [];
    while (this.current().type !== '}') {
      stmts.push(this.parseStmt());
    }
    this.expect('}');
    return new Block(stmts[0].line, stmts);
  }

  parseIf(): IfStmt {
    this.expect('KEYWORD', 'if');
    const cond = this.parseExpr();
    const thenBlock = this.parseBlock();
    let elseBlock: Block | undefined;
    if (this.current().type === 'KEYWORD' && this.current().value === 'else') {
      this.consume('KEYWORD', 'else');
      elseBlock = this.parseIfOrBlock();
    }
    return new IfStmt(this.current().line, cond, thenBlock, elseBlock);
  }

  parseIfOrBlock(): Block | IfStmt {
    if (this.current().type === 'KEYWORD' && this.current().value === 'if') {
      return this.parseIf();
    }
    return this.parseBlock();
  }

  parseWhile(): WhileStmt {
    this.expect('KEYWORD', 'while');
    const cond = this.parseExpr();
    const block = this.parseBlock();
    return new WhileStmt(this.current().line, cond, block);
  }

  parseFor(): ForStmt {
    this.expect('KEYWORD', 'for');
    const name = this.expect('IDENT').value as string;
    this.expect('in');
    const expr = this.parseExpr();
    const block = this.parseBlock();
    return new ForStmt(this.current().line, name, expr, block);
  }

  parseReturn(): ReturnStmt {
    this.expect('KEYWORD', 'return');
    let expr: Expr | undefined;
    if (this.current().type !== ';') {
      expr = this.parseExpr();
    }
    this.expect(';');
    return new ReturnStmt(this.current().line, expr);
  }

  parseBreak(): BreakStmt {
    this.expect('KEYWORD', 'break');
    this.expect(';');
    return new BreakStmt(this.current().line);
  }

  parseContinue(): ContinueStmt {
    this.expect('KEYWORD', 'continue');
    this.expect(';');
    return new ContinueStmt(this.current().line);
  }

  parseAssign(): AssignStmt {
    const name = this.expect('IDENT').value as string;
    this.expect('=');
    const expr = this.parseExpr();
    this.expect(';');
    return new AssignStmt(this.current().line, name, expr);
  }

  parseIndexAssign(): IndexAssign {
    const obj = this.parseExpr();
    this.expect('[');
    const index = this.parseExpr();
    this.expect(']');
    this.expect('=');
    const value = this.parseExpr();
    this.expect(';');
    return new IndexAssign(this.current().line, obj, index, value);
  }

  parsePostfix(): ASTNode {
    const line = this.current().line;
    const tok = this.current();
    let primary: Primary;

    if (tok.type === 'INT') {
      primary = new Primary(line, 'int', tok.value as bigint);
    } else if (tok.type === 'STRING') {
      primary = new Primary(line, 'string', tok.value as string);
    } else if (tok.type === 'KEYWORD') {
      if (tok.value === 'true') primary = new Primary(line, 'bool', true);
      else if (tok.value === 'false') primary = new Primary(line, 'bool', false);
      else if (tok.value === 'nil') primary = new Primary(line, 'nil');
      else if (tok.value === 'fn') {
        // fn() { ... }
        primary = new Primary(line, 'fn', undefined, undefined, undefined, undefined);
        this.expect('(');
        this.expect(')');
        primary = new Primary(line, 'fn', undefined, undefined, undefined, undefined);
        const block = this.parseBlock();
        primary = new Primary(line, 'fn', undefined, undefined, undefined, block);
        return primary;
      } else {
        primary = new Primary(line, 'ident', undefined, tok.value as string);
      }
    } else if (tok.type === 'IDENT') {
      primary = new Primary(line, 'ident', undefined, tok.value as string);
    } else if (tok.type === '[') {
      this.expect('[');
      const items: Array<Expr> = [];
      if (this.current().type !== ']') {
        items.push(this.parseExpr());
        while (this.current().type === ',') {
          this.consume(',');
          items.push(this.parseExpr());
        }
      }
      this.expect(']');
      primary = new Primary(line, 'array', undefined, undefined, undefined, items);
    } else if (tok.type === '(') {
      this.expect('(');
      this.parseExpr(); // consume expression
      this.expect(')');
      primary = new Primary(line, 'paren');
    }

    while (this.current().type === 'IDENT' && 
           (this.current().value === '(' || this.current().value === '[')) {
      const callTok = this.current();
      const isCall = callTok.value === '(';
      if (isCall) {
        this.expect('(');
        const args: Array<Expr> = [];
        if (this.current().type !== ')') {
          args.push(this.parseExpr());
          while (this.current().type === ',') {
            this.consume(',');
            args.push(this.parseExpr());
          }
        }
        this.expect(')');
        if (primary.type === 'fn' && primary.block) {
           primary = new Primary(line, 'fn', undefined, undefined, undefined, primary.block);
        }
        // If primary was 'fn', we need to wrap it? No, primary is the function object.
        // Wait, if it was 'fn' declaration, we parsed it earlier.
        // Here, we are parsing postfix calls.
        // If primary is 'fn' literal (anonymous), we need to handle it.
        // But grammar says `primary := ... | "fn" "(" params? ")" block`.
        // So `fn` literal is parsed as Primary.
        // If it's `fn() { ... }`, it is a Primary.
        // Then we can call it.
        // But `fn` literal is not a function value yet, it's an AST node.
        // So `fn() { ... }` is parsed as a Primary.
        // When evaluating, we create the function object.
        // So `fn() { ... }` is a Primary node.
        // Then we can call it.
        // So `primary` is the callee.
      } else {
        this.expect('[');
        const index = this.parseExpr();
        this.expect(']');
      }
    }
    return primary;
  }

  parseExpr(): ExprBase {
    return this.parseOr();
  }

  parseOr(): ExprBase {
    let left = this.parseAnd();
    while (this.current().type === 'KEYWORD' && this.current().value === 'or') {
      this.consume('KEYWORD', 'or');
      const right = this.parseAnd();
      left = new BinaryOp(left.line, 'or', left, right);
    }
    return left;
  }

  parseAnd(): ExprBase {
    let left = this.parseNot();
    while (this.current().type === 'KEYWORD' && this.current().value === 'and') {
      this.consume('KEYWORD', 'and');
      const right = this.parseNot();
      left = new BinaryOp(left.line, 'and', left, right);
    }
    return left;
  }

  parseNot(): ExprBase {
    if (this.current().type === 'KEYWORD' && this.current().value === 'not') {
      this.consume('KEYWORD', 'not');
      const expr = this.parsePrefix();
      return new UnaryOp(expr.line, 'not', expr);
    }
    return this.parsePrefix();
  }

  parsePrefix(): ExprBase {
    if (this.current().type === 'KEYWORD' && this.current().value === 'not') {
      // Wait, `not` is handled in `parseNot`.
      // `parsePrefix` handles `-` and `not`?
      // Grammar: `not` is prefix. `-` is prefix.
      // But `not` is lower precedence than `and`/`or`.
      // My `parseNot` handles `not`.
      // `parsePrefix` handles `-`.
      // Let's restructure.
    }
    // Unary minus
    if (this.current().type === 'KEYWORD' && this.current().value === '-') {
      this.consume('KEYWORD', '-');
      const expr = this.parsePostfix();
      return new UnaryOp(expr.line, '-', expr);
    }
    return this.parsePostfix();
  }

  parsePostfix(): ExprBase {
    let left = this.parseComparison();
    while (this.current().type === 'IDENT' && 
           (this.current().value === '(' || this.current().value === '[')) {
      const callTok = this.current();
      const isCall = callTok.value === '(';
      if (isCall) {
        this.expect('(');
        const args: Array<Expr> = [];
        if (this.current().type !== ')') {
          args.push(this.parseExpr());
          while (this.current().type === ',') {
            this.consume(',');
            args.push(this.parseExpr());
          }
        }
        this.expect(')');
        left = new Call(left.line, left, args);
      } else {
        this.expect('[');
        const index = this.parseExpr();
        this.expect(']');
        left = new IndexExpr(left.line, left, index);
      }
    }
    return left;
  }

  parseComparison(): ExprBase {
    let left = this.parseAdd();
    while (this.current().type === 'KEYWORD' && 
           (this.current().value === '==' || this.current().value === '!=' || 
            this.current().value === '<' || this.current().value === '>' ||
            this.current().value === '<=' || this.current().value === '>=')) {
      const op = this.current().value;
      this.consume('KEYWORD', op);
      const right = this.parseAdd();
      left = new BinaryOp(left.line, op, left, right);
    }
    return left;
  }

  parseAdd(): ExprBase {
    let left = this.parseMult();
    while (this.current().type === 'KEYWORD' && 
           (this.current().value === '+' || this.current().value === '-')) {
      const op = this.current().value;
      this.consume('KEYWORD', op);
      const right = this.parseMult();
      left = new BinaryOp(left.line, op, left, right);
    }
    return left;
  }

  parseMult(): ExprBase {
    let left = this.parsePrimary();
    while (this.current().type === 'KEYWORD' && 
           (this.current().value === '*' || this.current().value === '/' || this.current().value === '%')) {
      const op = this.current().value;
      this.consume('KEYWORD', op);
      const right = this.parsePrimary();
      left = new BinaryOp(left.line, op, left, right);
    }
    return left;
  }

  parsePrimary(): ExprBase {
    const tok = this.current();
    if (tok.type === 'INT') return new Primary(tok.line, 'int', tok.value as bigint);
    if (tok.type === 'STRING') return new Primary(tok.line, 'string', tok.value as string);
    if (tok.type === 'KEYWORD') {
      if (tok.value === 'true') return new Primary(tok.line, 'bool', true);
      if (tok.value === 'false') return new Primary(tok.line, 'bool', false);
      if (tok.value === 'nil') return new Primary(tok.line, 'nil');
      if (tok.value === 'fn') {
        this.expect('(');
        const params: string[] = [];
        if (this.current().type !== ')') {
          params.push(this.expect('IDENT').value as string);
          while (this.current().type === ',') {
            this.consume(',');
            params.push(this.expect('IDENT').value as string);
          }
        }
        this.expect(')');
        const block = this.parseBlock();
        return new Primary(tok.line, 'fn', undefined, undefined, params, block);
      }
      // Ident
      return new Primary(tok.line, 'ident', undefined, tok.value as string);
    }
    if (tok.type === 'IDENT') {
      return new Primary(tok.line, 'ident', undefined, tok.value as string);
    }
    if (tok.type === '[') {
      this.expect('[');
      const items: Array<Expr> = [];
      if (this.current().type !== ']') {
        items.push(this.parseExpr());
        while (this.current().type === ',') {
          this.consume(',');
          items.push(this.parseExpr());
        }
      }
      this.expect(']');
      return new Primary(tok.line, 'array', undefined, undefined, undefined, items);
    }
    if (tok.type === '(') {
      this.expect('(');
      const expr = this.parseExpr();
      this.expect(')');
      return new Primary(tok.line, 'paren');
    }
    throw new Error(`Unexpected token: ${tok.type}`);
  }
}

// --- Interpreter ---

class RuntimeError extends Error {
  line: number;
  token: string;
  constructor(line: number, message: string, token: string) {
    super(message);
    this.line = line;
    this.token = token;
    this.name = 'RuntimeError';
  }
}

class Scope {
  bindings: Map<string, Value>;
  parent: Scope | null;
  constructor(parent: Scope | null, bindings?: Map<string, Value>) {
    this.parent = parent;
    this.bindings = bindings || new Map();
  }
}

const BUILTINS: Map<string, Function> = new Map();

function initBuiltins() {
  // print
  BUILTINS.set('print', (...args: any[]) => {
    // args are values
    let output = '';
    for (let i = 0; i < args.length; i++) {
      if (i > 0) output += ' ';
      output += display(args[i], false);
    }
    output += '\n';
    // In interpreter, we just return nil, but print goes to stdout
    // But we need to capture stdout? No, the spec says "output is your program's standard output".
    // So we print directly.
    // But wait, `print` returns nil.
    return new NilValue();
  });

  // str
  BUILTINS.set('str', (v: Value) => {
    return new StringValue(display(v, false));
  });

  // type
  BUILTINS.set('type', (v: Value) => {
    return new StringValue(v.type);
  });

  // len
  BUILTINS.set('len', (v: Value) => {
    if (v.type === 'string') return new IntValue(BigInt(v.value!.length));
    if (v.type === 'list') return new IntValue(BigInt(v.value!.length));
    throw new RuntimeError(0, `bad argument to len`, '(');
  });

  // push
  BUILTINS.set('push', (list: Value, v: Value) => {
    if (list.type !== 'list') throw new RuntimeError(0, `bad argument to push`, '(');
    list.value!.push(v);
    return new NilValue();
  });

  // pop
  BUILTINS.set('pop', (list: Value) => {
    if (list.type !== 'list') throw new RuntimeError(0, `bad argument to pop`, '(');
    if (list.value!.length === 0) throw new RuntimeError(0, `bad argument to pop`, '(');
    return list.value!.pop()!;
  });

  // range
  BUILTINS.set('range', (a: Value, b: Value) => {
    if (a.type !== 'int' || b.type !== 'int') throw new RuntimeError(0, `bad argument to range`, '(');
    const start = a.value as bigint;
    const end = b.value as bigint;
    const list: ListValue[] = [];
    if (start < end) {
      for (let i = start; i < end; i++) {
        list.push(new IntValue(i));
      }
    }
    return new ListValue(list);
  });

  // slice
  BUILTINS.set('slice', (x: Value, a: Value, b: Value) => {
    if (a.type !== 'int' || b.type !== 'int') throw new RuntimeError(0, `bad argument to slice`, '(');
    const start = Number(a.value as bigint);
    const end = Number(b.value as bigint);
    if (start < 0 || end > 1000000) throw new RuntimeError(0, `bad argument to slice`, '('); // Sanity check
    if (x.type === 'string') {
      return new StringValue(x.value!.substring(start, end));
    } else if (x.type === 'list') {
      const res: ListValue[] = [];
      for (let i = start; i < end; i++) {
        if (i < x.value!.length) res.push(x.value![i]);
      }
      return new ListValue(res);
    } else {
      throw new RuntimeError(0, `bad argument to slice`, '(');
    }
  });
}

function ternDiv(a: bigint, b: bigint): bigint {
  if (b === 0n) throw new RuntimeError(0, 'division by zero', '/');
  let q = a / b;
  let r = a % b;
  if (r !== 0n && ((a < 0n) !== (b < 0n))) {
    q = q + 1n;
  }
  return q;
}

function ternMod(a: bigint, b: bigint): bigint {
  const q = ternDiv(a, b);
  return a - q * b;
}

function display(v: Value, isListElement: boolean = false): string {
  if (v.type === 'int') {
    return v.value!.toString();
  }
  if (v.type === 'bool') {
    return v.value!.toString();
  }
  if (v.type === 'nil') {
    return 'nil';
  }
  if (v.type === 'function') {
    return '<fn>';
  }
  if (v.type === 'string') {
    if (isListElement) {
      let s = v.value!;
      s = s.replace(/\\/g, '\\\\');
      s = s.replace(/"/g, '\\"');
      s = s.replace(/\n/g, '\\n');
      s = s.replace(/\t/g, '\\t');
      return `"${s}"`;
    }
    return v.value!;
  }
  if (v.type === 'list') {
    const seen = new Set<Value>();
    return displayList(v, seen, false);
  }
  return '';
}

function displayList(v: ListValue, seen: Set<Value>, isListElement: boolean): string {
  if (seen.has(v)) {
    return '[...]';
  }
  seen.add(v);
  let res = '[';
  for (let i = 0; i < v.value.length; i++) {
    if (i > 0) res += ', ';
    res += display(v.value[i], true);
  }
  seen.delete(v);
  res += ']';
  return res;
}

function resolve(name: string, scope: Scope): Value {
  let s: Scope | null = scope;
  while (s) {
    if (s.bindings.has(name)) return s.bindings.get(name)!;
    s = s.parent;
  }
  throw new RuntimeError(scope.bindings.size, `undefined variable ${name}`, name);
}

function setVar(name: string, value: Value, scope: Scope): void {
  if (!scope.bindings.has(name)) {
    throw new RuntimeError(scope.bindings.size, `undefined variable ${name}`, name);
  }
  scope.bindings.set(name, value);
}

function execute(
  ast: ASTNode,
  scope: Scope,
  builtinScope: Map<string, Function>
): void | Value {
  if (ast instanceof Program) {
    for (const stmt of ast.stmts) {
      execute(stmt, scope, builtinScope);
    }
    return;
  }
  if (ast instanceof Block) {
    const newScope = new Scope(scope);
    for (const stmt of ast.stmts) {
      execute(stmt, newScope, builtinScope);
    }
    return;
  }

  if (ast instanceof LetStmt) {
    const val = ast.expr.eval(scope);
    setVar(ast.name, val, scope);
    return;
  }

  if (ast instanceof FnDecl) {
    const fn = new FunctionValue(ast.block.stmts, ast.params, scope, ast.name);
    setVar(ast.name, fn, scope);
    return;
  }

  if (ast instanceof IfStmt) {
    const cond = ast.cond.eval(scope);
    if (isTruthy(cond)) {
      execute(ast.thenBlock, scope, builtinScope);
    } else if (ast.elseBlock) {
      execute(ast.elseBlock, scope, builtinScope);
    }
    return;
  }

  if (ast instanceof WhileStmt) {
    let scopeForWhile = new Scope(scope);
    while (true) {
      const cond = ast.cond.eval(scopeForWhile);
      if (!isTruthy(cond)) break;
      execute(ast.block, scopeForWhile, builtinScope);
    }
    return;
  }

  if (ast instanceof ForStmt) {
    const loopScope = new Scope(scope);
    const eVal = ast.expr.eval(scope);
    if (eVal.type !== 'list') {
      throw new RuntimeError(ast.line, `cannot iterate ${eVal.type}`, 'for');
    }
    const list = eVal.value!;
    let i = 0n;
    while (true) {
      if (i >= BigInt(list.length)) break;
      const xVal = list[i];
      const bodyScope = new Scope(loopScope);
      bodyScope.bindings.set(ast.name, xVal);
      // Check for continue/break
      let skipIncrement = false;
      let breakLoop = false;
      try {
        for (const stmt of ast.block.stmts) {
          if (stmt instanceof ContinueStmt) {
            skipIncrement = true;
            break;
          }
          if (stmt instanceof BreakStmt) {
            breakLoop = true;
            break;
          }
          execute(stmt, bodyScope, builtinScope);
        }
      } catch (e) {
        if (e instanceof RuntimeError) throw e;
        if (e instanceof BreakLoop) breakLoop = true;
      }
      if (breakLoop) break;
      if (!skipIncrement) i = i + 1n;
    }
    return;
  }

  if (ast instanceof ReturnStmt) {
    if (ast.expr) {
      return ast.expr.eval(scope);
    }
    return new NilValue();
  }

  if (ast instanceof BreakStmt) {
    throw new BreakLoop();
  }

  if (ast instanceof ContinueStmt) {
    // Handled in ForStmt
    return;
  }

  if (ast instanceof AssignStmt) {
    const val = ast.expr.eval(scope);
    setVar(ast.name, val, scope);
    return;
  }

  if (ast instanceof IndexAssign) {
    const objVal = ast.obj.eval(scope);
    const idxVal = ast.index.eval(scope);
    const valVal = ast.value.eval(scope);
    if (objVal.type !== 'list') {
      throw new RuntimeError(ast.line, `cannot assign into ${objVal.type}`, '[');
    }
    if (idxVal.type !== 'int') {
      throw new RuntimeError(ast.line, `cannot index list with ${idxVal.type}`, '[');
    }
    const idx = idxVal.value as bigint;
    if (idx < 0n || idx >= BigInt(objVal.value.length)) {
      throw new RuntimeError(ast.line, `index ${idx} out of range for length ${objVal.value.length}`, '[');
    }
    objVal.value[idx] = valVal;
    return;
  }

  // Expressions
  if (ast instanceof BinaryOp) {
    const left = ast.left.eval(scope);
    const right = ast.right.eval(scope);
    return evalBinaryOp(ast.op, left, right, ast.line);
  }

  if (ast instanceof UnaryOp) {
    const val = ast.expr.eval(scope);
    if (ast.op === 'not') {
      return new BoolValue(!isTruthy(val));
    }
    if (ast.op === '-') {
      if (val.type !== 'int') throw new RuntimeError(ast.line, `cannot apply - to ${val.type}`, '-');
      const res = -val.value!;
      if (res < BigInt(-9223372036854775808) || res > BigInt(9223372036854775807)) {
        throw new RuntimeError(ast.line, 'integer overflow', '-');
      }
      return new IntValue(res);
    }
    throw new RuntimeError(ast.line, `cannot apply ${ast.op} to ${val.type}`, ast.op);
  }

  if (ast instanceof Call) {
    const calleeVal = ast.callee.eval(scope);
    if (calleeVal.type !== 'function') {
      throw new RuntimeError(ast.line, `cannot call ${calleeVal.type}`, '(');
    }
    const fn = calleeVal as FunctionValue;
    const args = ast.args.map(a => a.eval(scope));
    if (fn.params.length !== args.length) {
      throw new RuntimeError(ast.line, `expected ${fn.params.length} arguments, got ${args.length}`, '(');
    }
    // Check builtins
    if (fn.name === 'print') {
      // print is handled specially in interpreter loop or here?
      // Here we just return nil.
      return new NilValue();
    }
    // Execute function
    // Create new scope for function call
    const callScope = new Scope(fn.scope);
    for (let i = 0; i < fn.params.length; i++) {
      callScope.bindings.set(fn.params[i], args[i]);
    }
    // Execute body
    for (const stmt of fn.body) {
      const res = execute(stmt, callScope, builtinScope);
      if (res && stmt instanceof ReturnStmt) {
        return res;
      }
    }
    return new NilValue();
  }

  if (ast instanceof ArrayLit) {
    const items = ast.items.map(i => i.eval(scope));
    return new ListValue(items);
  }

  if (ast instanceof IndexExpr) {
    const objVal = ast.obj.eval(scope);
    const idxVal = ast.index.eval(scope);
    if (objVal.type !== 'list' && objVal.type !== 'string') {
      throw new RuntimeError(ast.line, `cannot index ${objVal.type} with ${idxVal.type}`, '[');
    }
    if (idxVal.type !== 'int') {
      throw new RuntimeError(ast.line, `cannot index list with ${idxVal.type}`, '[');
    }
    const idx = idxVal.value as bigint;
    if (idx < 0n) {
      throw new RuntimeError(ast.line, `index ${idx} out of range for length ${BigInt(objVal.type === 'list' ? objVal.value.length : objVal.value.length)}`, '[');
    }
    if (objVal.type === 'list') {
      if (idx >= BigInt(objVal.value.length)) {
        throw new RuntimeError(ast.line, `index ${idx} out of range for length ${objVal.value.length}`, '[');
      }
      return objVal.value[idx];
    } else {
      // String
      const len = BigInt(objVal.value.length);
      if (idx >= len) {
        throw new RuntimeError(ast.line, `index ${idx} out of range for length ${objVal.value.length}`, '[');
      }
      const char = objVal.value.toString()[Number(idx)];
      return new StringValue(char);
    }
  }

  if (ast instanceof Primary) {
    if (ast.type === 'int') return new IntValue(ast.value as bigint);
    if (ast.type === 'string') return new StringValue(ast.value as string);
    if (ast.type === 'bool') return new BoolValue(ast.value as boolean);
    if (ast.type === 'nil') return new NilValue();
    if (ast.type === 'ident') {
      return resolve(ast.name as string, scope);
    }
    if (ast.type === 'fn') {
      // Function literal
      const fn = new FunctionValue(ast.block!.stmts, ast.params!, scope, ast.name || '<fn>');
      return fn;
    }
    if (ast.type === 'array') {
      return new ListValue(ast.items!.map(i => i.eval(scope)));
    }
    if (ast.type === 'paren') {
      return ast.items![0].eval(scope);
    }
    throw new RuntimeError(ast.line, `unexpected primary type ${ast.type}`, ast.type);
  }

  throw new RuntimeError(ast.line, `unexpected node type ${ast.constructor.name}`, ast.constructor.name);
}

class BreakLoop extends Error {
  constructor() {
    super('BreakLoop');
  }
}

function isTruthy(v: Value): boolean {
  if (v.type === 'bool') return v.value!;
  if (v.type === 'nil') return false;
  if (v.type === 'int') return v.value! !== 0n;
  if (v.type === 'string') return v.value!.length > 0;
  if (v.type === 'list') return v.value!.length > 0;
  return true; // functions are truthy
}

function evalBinaryOp(op: string, left: Value, right: Value, line: number): Value {
  if (op === '==') {
    if (left.type !== right.type) return new BoolValue(false);
    if (left.type === 'int' && right.type === 'int') {
      return new BoolValue(left.value! === right.value!);
    }
    if (left.type === 'bool' && right.type === 'bool') {
      return new BoolValue(left.value! === right.value!);
    }
    if (left.type === 'string' && right.type === 'string') {
      return new BoolValue(left.value! === right.value!);
    }
    if (left.type === 'list' && right.type === 'list') {
      if (left.value!.length !== right.value!.length) return new BoolValue(false);
      for (let i = 0; i < left.value!.length; i++) {
        if (!evalBinaryOp('==', left.value![i], right.value![i], line)) return new BoolValue(false);
      }
      return new BoolValue(true);
    }
    if (left.type === 'function' && right.type === 'function') {
      return new BoolValue(left === right);
    }
    return new BoolValue(false);
  }
  if (op === '!=') {
    if (left.type !== right.type) return new BoolValue(true);
    if (left.type === 'int' && right.type === 'int') {
      return new BoolValue(left.value! !== right.value!);
    }
    if (left.type === 'bool' && right.type === 'bool') {
      return new BoolValue(left.value! !== right.value!);
    }
    if (left.type === 'string' && right.type === 'string') {
      return new BoolValue(left.value! !== right.value!);
    }
    if (left.type === 'list' && right.type === 'list') {
      if (left.value!.length !== right.value!.length) return new BoolValue(true);
      for (let i = 0; i < left.value!.length; i++) {
        if (evalBinaryOp('==', left.value![i], right.value![i], line)) return new BoolValue(true);
      }
      return new BoolValue(false);
    }
    if (left.type === 'function' && right.type === 'function') {
      return new BoolValue(left !== right);
    }
    return new BoolValue(false);
  }
  if (op === '<' || op === '<=' || op === '>' || op === '>=') {
    if (left.type !== right.type) throw new RuntimeError(line, `cannot apply ${op} to ${left.type} and ${right.type}`, op);
    if (left.type === 'int' && right.type === 'int') {
      const l = left.value as bigint;
      const r = right.value as bigint;
      if (op === '<') return new BoolValue(l < r);
      if (op === '<=') return new BoolValue(l <= r);
      if (op === '>') return new BoolValue(l > r);
      if (op === '>=') return new BoolValue(l >= r);
    }
    if (left.type === 'string' && right.type === 'string') {
      const l = left.value as string;
      const r = right.value as string;
      if (op === '<') return new BoolValue(l < r);
      if (op === '<=') return new BoolValue(l <= r);
      if (op === '>') return new BoolValue(l > r);
      if (op === '>=') return new BoolValue(l >= r);
    }
    throw new RuntimeError(line, `cannot apply ${op} to ${left.type} and ${right.type}`, op);
  }
  if (op === '+') {
    if (left.type === 'int' && right.type === 'int') {
      const l = left.value as bigint;
      const r = right.value as bigint;
      const res = l + r;
      if (res < BigInt(-9223372036854775808) || res > BigInt(9223372036854775807)) {
        throw new RuntimeError(line, 'integer overflow', '+');
      }
      return new IntValue(res);
    }
    if (left.type === 'string' && right.type === 'string') {
      return new StringValue((left.value as string) + (right.value as string));
    }
    if (left.type === 'list' && right.type === 'list') {
      const res: ListValue[] = [...left.value!, ...right.value!];
      return new ListValue(res);
    }
    throw new RuntimeError(line, `cannot apply + to ${left.type} and ${right.type}`, '+');
  }
  if (op === '-') {
    if (left.type !== 'int' || right.type !== 'int') {
      throw new RuntimeError(line, `cannot apply - to ${left.type} and ${right.type}`, '-');
    }
    const l = left.value as bigint;
    const r = right.value as bigint;
    const res = l - r;
    if (res < BigInt(-9223372036854775808) || res > BigInt(9223372036854775807)) {
      throw new RuntimeError(line, 'integer overflow', '-');
    }
    return new IntValue(res);
  }
  if (op === '*') {
    if (left.type !== 'int' || right.type !== 'int') {
      throw new RuntimeError(line, `cannot apply * to ${left.type} and ${right.type}`, '*');
    }
    const l = left.value as bigint;
    const r = right.value as bigint;
    const res = l * r;
    if (res < BigInt(-9223372036854775808) || res > BigInt(9223372036854775807)) {
      throw new RuntimeError(line, 'integer overflow', '*');
    }
    return new IntValue(res);
  }
  if (op === '/') {
    if (left.type !== 'int' || right.type !== 'int') {
      throw new RuntimeError(line, `cannot apply / to ${left.type} and ${right.type}`, '/');
    }
    const q = ternDiv(left.value as bigint, right.value as bigint);
    if (q < BigInt(-9223372036854775808) || q > BigInt(9223372036854775807)) {
      throw new RuntimeError(line, 'integer overflow', '/');
    }
    return new IntValue(q);
  }
  if (op === '%') {
    if (left.type !== 'int' || right.type !== 'int') {
      throw new RuntimeError(line, `cannot apply % to ${left.type} and ${right.type}`, '%');
    }
    const res = ternMod(left.value as bigint, right.value as bigint);
    if (res < BigInt(-9223372036854775808) || res > BigInt(9223372036854775807)) {
      throw new RuntimeError(line, 'integer overflow', '%');
    }
    return new IntValue(res);
  }
  if (op === 'and') {
    if (!isTruthy(left)) return left;
    return right;
  }
  if (op === 'or') {
    if (isTruthy(left)) return left;
    return right;
  }
  throw new RuntimeError(line, `unexpected operator ${op}`, op);
}

// --- Main ---

function main() {
  const args = process.argv.slice(2);
  if (args.length !== 1) {
    console.error('Usage: tsx main.ts <directory>');
    process.exit(1);
  }
  const dir = args[0];
  const filePath = path.join(dir, 'program.tern');
  const source = fs.readFileSync(filePath, 'utf-8');

  initBuiltins();

  try {
    const lexer = new Lexer(source);
    const tokens = lexer.tokenize();
    const parser = new Parser(tokens);
    const ast = parser.parseProgram();

    const globalScope = new Scope(null, new Map<string, Function>(BUILTINS));
    const result = execute(ast, globalScope, BUILTINS);
  } catch (e) {
    if (e instanceof RuntimeError) {
      console.error(`error at line ${e.line}: ${e.message}`);
    } else if (e instanceof BreakLoop) {
      // Ignore break
    } else {
      console.error(`error at line 1: ${e}`);
    }
    process.exit(0);
  }
  process.exit(0);
}

main();

import * as fs from 'fs';
import * as path from 'path';

// --- Types ---

type ValueType = 'int' | 'bool' | 'string' | 'list' | 'function' | 'nil';

class IntValue {
  value: bigint;
  constructor(value: bigint) {
    this.value = value;
  }
  type: ValueType = 'int';
}

class BoolValue {
  value: boolean;
  constructor(value: boolean) {
    this.value = value;
  }
  type: ValueType = 'bool';
}

class StringValue {
  value: string;
  constructor(value: string) {
    this.value = value;
  }
  type: ValueType = 'string';
}

class ListValue {
  value: Array<Value>;
  constructor(value: Array<Value>) {
    this.value = value;
  }
  type: ValueType = 'list';
}

class NilValue {
  type: ValueType = 'nil';
}

class FunctionValue {
  body: Array<ASTNode>;
  params: string[];
  scope: Scope;
  name: string;
  constructor(body: Array<ASTNode>, params: string[], scope: Scope, name: string) {
    this.body = body;
    this.params = params;
    this.scope = scope;
    this.name = name;
  }
  type: ValueType = 'function';
}

// --- AST Nodes ---

type ASTNode = Program | Block | LetStmt | FnDecl | IfStmt | WhileStmt | ForStmt | ReturnStmt | BreakStmt | ContinueStmt | AssignStmt | IndexAssign | Expr | BinaryOp | UnaryOp | Call | ArrayLit | IndexExpr | Primary;

abstract class ASTNodeBase {
  line: number;
  constructor(line: number) {
    this.line = line;
  }
}

class Program extends ASTNodeBase {
  stmts: Array<ASTNode>;
  constructor(line: number, stmts: Array<ASTNode>) {
    super(line);
    this.stmts = stmts;
  }
}

class Block extends ASTNodeBase {
  stmts: Array<ASTNode>;
  constructor(line: number, stmts: Array<ASTNode>) {
    super(line);
    this.stmts = stmts;
  }
}

class LetStmt extends ASTNodeBase {
  name: string;
  expr: Expr;
  constructor(line: number, name: string, expr: Expr) {
    super(line);
    this.name = name;
    this.expr = expr;
  }
}

class FnDecl extends ASTNodeBase {
  name: string;
  params: string[];
  block: Block;
  constructor(line: number, name: string, params: string[], block: Block) {
    super(line);
    this.name = name;
    this.params = params;
    this.block = block;
  }
}

class IfStmt extends ASTNodeBase {
  cond: Expr;
  thenBlock: Block;
  elseBlock?: Block;
  constructor(line: number, cond: Expr, thenBlock: Block, elseBlock?: Block) {
    super(line);
    this.cond = cond;
    this.thenBlock = thenBlock;
    this.elseBlock = elseBlock;
  }
}

class WhileStmt extends ASTNodeBase {
  cond: Expr;
  block: Block;
  constructor(line: number, cond: Expr, block: Block) {
    super(line);
    this.cond = cond;
    this.block = block;
  }
}

class ForStmt extends ASTNodeBase {
  name: string;
  expr: Expr;
  block: Block;
  constructor(line: number, name: string, expr: Expr, block: Block) {
    super(line);
    this.name = name;
    this.expr = expr;
    this.block = block;
  }
}

class ReturnStmt extends ASTNodeBase {
  expr?: Expr;
  constructor(line: number, expr?: Expr) {
    super(line);
    this.expr = expr;
  }
}

class BreakStmt extends ASTNodeBase {
  constructor(line: number) {
    super(line);
  }
}

class ContinueStmt extends ASTNodeBase {
  constructor(line: number) {
    super(line);
  }
}

class AssignStmt extends ASTNodeBase {
  name: string;
  expr: Expr;
  constructor(line: number, name: string, expr: Expr) {
    super(line);
    this.name = name;
    this.expr = expr;
  }
}

class IndexAssign extends ASTNodeBase {
  obj: Expr;
  index: Expr;
  value: Expr;
  constructor(line: number, obj: Expr, index: Expr, value: Expr) {
    super(line);
    this.obj = obj;
    this.index = index;
    this.value = value;
  }
}

abstract class ExprBase extends ASTNodeBase {
  abstract eval(scope: Scope): Value;
}

class BinaryOp extends ExprBase {
  op: string;
  left: Expr;
  right: Expr;
  constructor(line: number, op: string, left: Expr, right: Expr) {
    super(line);
    this.op = op;
    this.left = left;
    this.right = right;
  }
}

class UnaryOp extends ExprBase {
  op: string;
  expr: Expr;
  constructor(line: number, op: string, expr: Expr) {
    super(line);
    this.op = op;
    this.expr = expr;
  }
}

class Call extends ExprBase {
  callee: Expr;
  args: Array<Expr>;
  constructor(line: number, callee: Expr, args: Array<Expr>) {
    super(line);
    this.callee = callee;
    this.args = args;
  }
}

class ArrayLit extends ExprBase {
  items: Array<Expr>;
  constructor(line: number, items: Array<Expr>) {
    super(line);
    this.items = items;
  }
}

class IndexExpr extends ExprBase {
  obj: Expr;
  index: Expr;
  constructor(line: number, obj: Expr, index: Expr) {
    super(line);
    this.obj = obj;
    this.index = index;
  }
}

class Primary extends ExprBase {
  type: 'int' | 'string' | 'bool' | 'nil' | 'ident' | 'array' | 'fn' | 'paren';
  value?: bigint | string | boolean;
  name?: string;
  params?: string[];
  block?: Block;
  items?: Array<Expr>;
  constructor(line: number, type: string, value?: bigint | string | boolean, name?: string, params?: string[], block?: Block, items?: Array<Expr>) {
    super(line);
    this.type = type;
    this.value = value;
    this.name = name;
    this.params = params;
    this.block = block;
    this.items = items;
  }
}

// --- Lexer ---

interface Token {
  type: string;
  value: string | bigint;
  line: number;
}

const KEYWORDS = new Set([
  'let', 'fn', 'if', 'else', 'while', 'for', 'in', 'return', 'break', 'continue',
  'and', 'or', 'not', 'true', 'false', 'nil'
]);

class Lexer {
  source: string;
  pos: number;
  line: number;
  tokens: Token[];

  constructor(source: string) {
    this.source = source;
    this.pos = 0;
    this.line = 1;
    this.tokens = [];
  }

  peekChar(n: number = 0): string | null {
    const idx = this.pos + n;
    if (idx >= this.source.length) return null;
    return this.source[idx];
  }

  advanceChar(): string | null {
    const c = this.source[this.pos];
    this.pos++;
    if (c === '\n') this.line++;
    return c;
  }

  skipWhitespace() {
    while (this.peekChar() === ' ' || this.peekChar() === '\t' || this.peekChar() === '\r' || this.peekChar() === '\n') {
      this.advanceChar();
    }
  }

  skipComment() {
    while (this.peekChar() !== null && this.peekChar() !== '\n') {
      this.advanceChar();
    }
  }

  readToken(): Token | null {
    this.skipWhitespace();
    if (this.peekChar() === null) return null;

    const startLine = this.line;

    if (this.peekChar() === '#') {
      this.skipComment();
      return this.readToken();
    }

    // String literal
    if (this.peekChar() === '"') {
      this.advanceChar();
      let val = '';
      while (true) {
        if (this.peekChar() === null) throw new Error('Unterminated string');
        if (this.peekChar() === '"') {
          this.advanceChar();
          return { type: 'STRING', value: val, line: startLine };
        }
        if (this.peekChar() === '\\') {
          this.advanceChar();
          const escape = this.peekChar();
          if (escape === 'n') val += '\n';
          else if (escape === 't') val += '\t';
          else if (escape === '"') val += '"';
          else if (escape === '\\') val += '\\';
          else throw new Error('Invalid escape');
          this.advanceChar();
        } else {
          val += this.advanceChar();
        }
      }
    }

    // Integer literal
    if (this.peekChar() >= '0' && this.peekChar() <= '9') {
      let val = '';
      while (this.peekChar() >= '0' && this.peekChar() <= '9') {
        val += this.advanceChar();
      }
      const num = BigInt(val);
      return { type: 'INT', value: num, line: startLine };
    }

    // Identifier / Keyword
    if (this.peekChar() && (this.peekChar() >= 'A' && this.peekChar() <= 'Z' || this.peekChar() >= 'a' && this.peekChar() <= 'z' || this.peekChar() === '_')) {
      let val = '';
      while (this.peekChar() && (this.peekChar() >= 'A' && this.peekChar() <= 'Z' || this.peekChar() >= 'a' && this.peekChar() <= 'z' || this.peekChar() >= '0' && this.peekChar() <= '9' || this.peekChar() === '_')) {
        val += this.advanceChar();
      }
      const type = KEYWORDS.has(val) ? 'KEYWORD' : 'IDENT';
      return { type, value: val, line: startLine };
    }

    // Operators / Punctuation - longest match first
    if (this.peekChar() === '=' && this.peekChar(1) === '=') {
      this.advanceChar(); this.advanceChar();
      return { type: '==', value: '==', line: startLine };
    }
    if (this.peekChar() === '!' && this.peekChar(1) === '=') {
      this.advanceChar(); this.advanceChar();
      return { type: '!=', value: '!=', line: startLine };
    }
    if (this.peekChar() === '<' && this.peekChar(1) === '=') {
      this.advanceChar(); this.advanceChar();
      return { type: '<=', value: '<=', line: startLine };
    }
    if (this.peekChar() === '>' && this.peekChar(1) === '=') {
      this.advanceChar(); this.advanceChar();
      return { type: '>=', value: '>=', line: startLine };
    }
    if (this.peekChar() === '<') {
      this.advanceChar();
      return { type: '<', value: '<', line: startLine };
    }
    if (this.peekChar() === '>') {
      this.advanceChar();
      return { type: '>', value: '>', line: startLine };
    }
    if (this.peekChar() === '+') {
      this.advanceChar();
      return { type: '+', value: '+', line: startLine };
    }
    if (this.peekChar() === '-') {
      this.advanceChar();
      return { type: '-', value: '-', line: startLine };
    }
    if (this.peekChar() === '*') {
      this.advanceChar();
      return { type: '*', value: '*', line: startLine };
    }
    if (this.peekChar() === '/') {
      this.advanceChar();
      return { type: '/', value: '/', line: startLine };
    }
    if (this.peekChar() === '%') {
      this.advanceChar();
      return { type: '%', value: '%', line: startLine };
    }
    if (this.peekChar() === '(') {
      this.advanceChar();
      return { type: '(', value: '(', line: startLine };
    }
    if (this.peekChar() === ')') {
      this.advanceChar();
      return { type: ')', value: ')', line: startLine };
    }
    if (this.peekChar() === '[') {
      this.advanceChar();
      return { type: '[', value: '[', line: startLine };
    }
    if (this.peekChar() === ']') {
      this.advanceChar();
      return { type: ']', value: ']', line: startLine };
    }
    if (this.peekChar() === '{') {
      this.advanceChar();
      return { type: '{', value: '{', line: startLine };
    }
    if (this.peekChar() === '}') {
      this.advanceChar();
      return { type: '}', value: '}', line: startLine };
    }
    if (this.peekChar() === ',') {
      this.advanceChar();
      return { type: ',', value: ',', line: startLine };
    }
    if (this.peekChar() === ';') {
      this.advanceChar();
      return { type: ';', value: ';', line: startLine };
    }

    throw new Error(`Unexpected character: ${this.peekChar()}`);
  }

  tokenize(): Token[] {
    while (true) {
      const tok = this.readToken();
      if (!tok) break;
      this.tokens.push(tok);
    }
    this.tokens.push({ type: 'EOF', value: '', line: this.line });
    return this.tokens;
  }
}

// --- Parser ---

class Parser {
  tokens: Token[];
  pos: number;

  constructor(tokens: Token[]) {
    this.tokens = tokens;
    this.pos = 0;
  }

  current(): Token { return this.tokens[this.pos]; }
  peek(n: number = 0): Token { return this.tokens[this.pos + n]; }

  consume(type: string, value?: string): Token {
    const t = this.current();
    if (t.type !== type || (value !== undefined && t.value !== value)) {
      throw new Error(`Expected ${type} or ${value}, got ${t.type}`);
    }
    this.pos++;
    return t;
  }

  expect(type: string, value?: string): Token {
    const t = this.current();
    if (t.type !== type || (value !== undefined && t.value !== value)) {
      throw new Error(`Expected ${type} or ${value}, got ${t.type}`);
    }
    this.pos++;
    return t;
  }

  parseProgram(): Program {
    const stmts: Array<ASTNode> = [];
    while (this.current().type !== 'EOF') {
      stmts.push(this.parseStmt());
    }
    return new Program(stmts[0].line, stmts);
  }

  parseStmt(): ASTNode {
    const line = this.current().line;
    const tok = this.current();

    if (tok.type === 'KEYWORD') {
      if (tok.value === 'let') return this.parseLet();
      if (tok.value === 'fn') return this.parseFn();
      if (tok.value === 'if') return this.parseIf();
      if (tok.value === 'while') return this.parseWhile();
      if (tok.value === 'for') return this.parseFor();
      if (tok.value === 'return') return this.parseReturn();
      if (tok.value === 'break') return this.parseBreak();
      if (tok.value === 'continue') return this.parseContinue();
    }

    if (tok.value === '{') return this.parseBlock();
    if (tok.type === 'IDENT') return this.parseAssign();

    // Postfix expression start
    return this.parsePostfix();
  }

  parseLet(): LetStmt {
    this.expect('KEYWORD', 'let');
    const name = this.expect('IDENT').value as string;
    this.expect('=');
    const expr = this.parseExpr();
    this.expect(';');
    return new LetStmt(this.current().line, name, expr);
  }

  parseFn(): FnDecl {
    this.expect('KEYWORD', 'fn');
    const name = this.expect('IDENT').value as string;
    this.expect('(');
    const params: string[] = [];
    if (this.current().type !== ')') {
      params.push(this.expect('IDENT').value as string);
      while (this.current().type === ',') {
        this.consume(',');
        params.push(this.expect('IDENT').value as string);
      }
    }
    this.expect(')');
    const block = this.parseBlock();
    return new FnDecl(this.current().line, name, params, block);
  }

  parseBlock(): Block {
    this.expect('{');
    const stmts: Array<ASTNode> = [];
    while (this.current().type !== '}') {
      stmts.push(this.parseStmt());
    }
    this.expect('}');
    return new Block(stmts[0].line, stmts);
  }

  parseIf(): IfStmt {
    this.expect('KEYWORD', 'if');
    const cond = this.parseExpr();
    const thenBlock = this.parseBlock();
    let elseBlock: Block | undefined;
    if (this.current().type === 'KEYWORD' && this.current().value === 'else') {
      this.consume('KEYWORD', 'else');
      elseBlock = this.parseIfOrBlock();
    }
    return new IfStmt(this.current().line, cond, thenBlock, elseBlock);
  }

  parseIfOrBlock(): Block | IfStmt {
    if (this.current().type === 'KEYWORD' && this.current().value === 'if') {
      return this.parseIf();
    }
    return this.parseBlock();
  }

  parseWhile(): WhileStmt {
    this.expect('KEYWORD', 'while');
    const cond = this.parseExpr();
    const block = this.parseBlock();
    return new WhileStmt(this.current().line, cond, block);
  }

  parseFor(): ForStmt {
    this.expect('KEYWORD', 'for');
    const name = this.expect('IDENT').value as string;
    this.expect('in');
    const expr = this.parseExpr();
    const block = this.parseBlock();
    return new ForStmt(this.current().line, name, expr, block);
  }

  parseReturn(): ReturnStmt {
    this.expect('KEYWORD', 'return');
    let expr: Expr | undefined;
    if (this.current().type !== ';') {
      expr = this.parseExpr();
    }
    this.expect(';');
    return new ReturnStmt(this.current().line, expr);
  }

  parseBreak(): BreakStmt {
    this.expect('KEYWORD', 'break');
    this.expect(';');
    return new BreakStmt(this.current().line);
  }

  parseContinue(): ContinueStmt {
    this.expect('KEYWORD', 'continue');
    this.expect(';');
    return new ContinueStmt(this.current().line);
  }

  parseAssign(): AssignStmt {
    const name = this.expect('IDENT').value as string;
    this.expect('=');
    const expr = this.parseExpr();
    this.expect(';');
    return new AssignStmt(this.current().line, name, expr);
  }

  parseIndexAssign(): IndexAssign {
    const obj = this.parseExpr();
    this.expect('[');
    const index = this.parseExpr();
    this.expect(']');
    this.expect('=');
    const value = this.parseExpr();
    this.expect(';');
    return new IndexAssign(this.current().line, obj, index, value);
  }

  parsePostfix(): ASTNode {
    const line = this.current().line;
    let primary: Primary;

    if (this.current().type === 'INT') {
      primary = new Primary(line, 'int', this.current().value as bigint);
      this.consume('INT');
    } else if (this.current().type === 'STRING') {
      primary = new Primary(line, 'string', this.current().value as string);
      this.consume('STRING');
    } else if (this.current().type === 'KEYWORD') {
      if (this.current().value === 'true') {
        primary = new Primary(line, 'bool', true);
        this.consume('KEYWORD', 'true');
      } else if (this.current().value === 'false') {
        primary = new Primary(line, 'bool', false);
        this.consume('KEYWORD', 'false');
      } else if (this.current().value === 'nil') {
        primary = new Primary(line, 'nil');
        this.consume('KEYWORD', 'nil');
      } else if (this.current().value === 'fn') {
        this.consume('KEYWORD', 'fn');
        this.expect('(');
        const params: string[] = [];
        if (this.current().type !== ')') {
          params.push(this.expect('IDENT').value as string);
          while (this.current().type === ',') {
            this.consume(',');
            params.push(this.expect('IDENT').value as string);
          }
        }
        this.expect(')');
        const block = this.parseBlock();
        primary = new Primary(line, 'fn', undefined, undefined, params, block);
      } else {
        primary = new Primary(line, 'ident', undefined, this.current().value as string);
        this.consume('KEYWORD');
      }
    } else if (this.current().type === 'IDENT') {
      primary = new Primary(line, 'ident', undefined, this.current().value as string);
      this.consume('IDENT');
    } else if (this.current().type === '[') {
      this.consume('[');
      const items: Array<Expr> = [];
      if (this.current().type !== ']') {
        items.push(this.parseExpr());
        while (this.current().type === ',') {
          this.consume(',');
          items.push(this.parseExpr());
        }
      }
      this.consume(']');
      primary = new Primary(line, 'array', undefined, undefined, undefined, items);
    } else if (this.current().type === '(') {
      this.consume('(');
      this.parseExpr();
      this.consume(')');
      primary = new Primary(line, 'paren');
    } else {
      throw new Error(`Unexpected token in postfix: ${this.current().type}`);
    }

    // Handle postfix calls and indexing
    while (true) {
      const nextTok = this.current();
      if (nextTok.type === 'IDENT' && (nextTok.value === '(' || nextTok.value === '[')) {
        if (nextTok.value === '(') {
          this.consume('(', '(');
          const args: Array<Expr> = [];
          if (this.current().type !== ')') {
            args.push(this.parseExpr());
            while (this.current().type === ',') {
              this.consume(',');
              args.push(this.parseExpr());
            }
          }
          this.consume(')');
          primary = new Call(primary.line as number, primary as Expr, args);
        } else {
          this.consume('[');
          const index = this.parseExpr();
          this.consume(']');
          primary = new IndexExpr(primary.line as number, primary as Expr, index);
        }
      } else {
        break;
      }
    }

    return primary;
  }

  parseExpr(): ExprBase {
    return this.parseOr();
  }

  parseOr(): ExprBase {
    let left = this.parseAnd();
    while (this.current().type === 'KEYWORD' && this.current().value === 'or') {
      this.consume('KEYWORD', 'or');
      const right = this.parseAnd();
      left = new BinaryOp(left.line, 'or', left, right);
    }
    return left;
  }

  parseAnd(): ExprBase {
    let left = this.parseNot();
    while (this.current().type === 'KEYWORD' && this.current().value === 'and') {
      this.consume('KEYWORD', 'and');
      const right = this.parseNot();
      left = new BinaryOp(left.line, 'and', left, right);
    }
    return left;
  }

  parseNot(): ExprBase {
    if (this.current().type === 'KEYWORD' && this.current().value === 'not') {
      this.consume('KEYWORD', 'not');
      const expr = this.parsePrefix();
      return new UnaryOp(expr.line, 'not', expr);
    }
    return this.parsePrefix();
  }

  parsePrefix(): ExprBase {
    if (this.current().type === 'KEYWORD' && this.current().value === '-') {
      this.consume('KEYWORD', '-');
      const expr = this.parsePostfix();
      return new UnaryOp(expr.line, '-', expr);
    }
    return this.parsePostfix();
  }

  parsePostfix(): ExprBase {
    let left = this.parseComparison();
    while (true) {
      const nextTok = this.current();
      if (nextTok.type === 'IDENT' && (nextTok.value === '(' || nextTok.value === '[')) {
        if (nextTok.value === '(') {
          this.consume('(', '(');
          const args: Array<Expr> = [];
          if (this.current().type !== ')') {
            args.push(this.parseExpr());
            while (this.current().type === ',') {
              this.consume(',');
              args.push(this.parseExpr());
            }
          }
          this.consume(')');
          left = new Call(left.line, left, args);
        } else {
          this.consume('[');
          const index = this.parseExpr();
          this.consume(']');
          left = new IndexExpr(left.line, left, index);
        }
      } else {
        break;
      }
    }
    return left;
  }

  parseComparison(): ExprBase {
    let left = this.parseAdd();
    while (this.current().type === 'KEYWORD' && 
           (this.current().value === '==' || this.current().value === '!=' || 
            this.current().value === '<' || this.current().value === '>' ||
            this.current().value === '<=' || this.current().value === '>=')) {
      const op = this.current().value;
      this.consume('KEYWORD', op);
      const right = this.parseAdd();
      left = new BinaryOp(left.line, op, left, right);
    }
    return left;
  }

  parseAdd(): ExprBase {
    let left = this.parseMult();
    while (this.current().type === 'KEYWORD' && 
           (this.current().value === '+' || this.current().value === '-')) {
      const op = this.current().value;
      this.consume('KEYWORD', op);
      const right = this.parseMult();
      left = new BinaryOp(left.line, op, left, right);
    }
    return left;
  }

  parseMult(): ExprBase {
    let left = this.parsePrimary();
    while (this.current().type === 'KEYWORD' && 
           (this.current().value === '*' || this.current().value === '/' || this.current().value === '%')) {
      const op = this.current().value;
      this.consume('KEYWORD', op);
      const right = this.parsePrimary();
      left = new BinaryOp(left.line, op, left, right);
    }
    return left;
  }

  parsePrimary(): ExprBase {
    const tok = this.current();
    if (tok.type === 'INT') {
      const val = this.consume('INT').value as bigint;
      return new Primary(tok.line, 'int', val);
    }
    if (tok.type === 'STRING') {
      const val = this.consume('STRING').value as string;
      return new Primary(tok.line, 'string', val);
    }
    if (tok.type === 'KEYWORD') {
      if (tok.value === 'true') {
        this.consume('KEYWORD', 'true');
        return new Primary(tok.line, 'bool', true);
      }
      if (tok.value === 'false') {
        this.consume('KEYWORD', 'false');
        return new Primary(tok.line, 'bool', false);
      }
      if (tok.value === 'nil') {
        this.consume('KEYWORD', 'nil');
        return new Primary(tok.line, 'nil');
      }
      if (tok.value === 'fn') {
        this.consume('KEYWORD', 'fn');
        this.expect('(');
        const params: string[] = [];
        if (this.current().type !== ')') {
          params.push(this.expect('IDENT').value as string);
          while (this.current().type === ',') {
            this.consume(',');
            params.push(this.expect('IDENT').value as string);
          }
        }
        this.expect(')');
        const block = this.parseBlock();
        return new Primary(tok.line, 'fn', undefined, undefined, params, block);
      }
      // Ident
      const val = this.consume('KEYWORD').value as string;
      return new Primary(tok.line, 'ident', undefined, val);
    }
    if (tok.type === 'IDENT') {
      const val = this.consume('IDENT').value as string;
      return new Primary(tok.line, 'ident', undefined, val);
    }
    if (tok.type === '[') {
      this.consume('[');
      const items: Array<Expr> = [];
      if (this.current().type !== ']') {
        items.push(this.parseExpr());
        while (this.current().type === ',') {
          this.consume(',');
          items.push(this.parseExpr());
        }
      }
      this.consume(']');
      return new Primary(tok.line, 'array', undefined, undefined, undefined, items);
    }
    if (tok.type === '(') {
      this.consume('(');
      const expr = this.parseExpr();
      this.consume(')');
      return new Primary(tok.line, 'paren');
    }
    throw new Error(`Unexpected token: ${tok.type}`);
  }
}

// --- Interpreter ---

class RuntimeError extends Error {
  line: number;
  token: string;
  constructor(line: number, message: string, token: string) {
    super(message);
    this.line = line;
    this.token = token;
    this.name = 'RuntimeError';
  }
}

class Scope {
  bindings: Map<string, Value>;
  parent: Scope | null;
  constructor(parent: Scope | null, bindings?: Map<string, Value>) {
    this.parent = parent;
    this.bindings = bindings || new Map();
  }
}

const BUILTINS: Map<string, Function> = new Map();

function initBuiltins() {
  // print
  BUILTINS.set('print', (...args: any[]) => {
    let output = '';
    for (let i = 0; i < args.length; i++) {
      if (i > 0) output += ' ';
      output += display(args[i], false);
    }
    output += '\n';
    return new NilValue();
  });

  // str
  BUILTINS.set('str', (v: Value) => {
    return new StringValue(display(v, false));
  });

  // type
  BUILTINS.set('type', (v: Value) => {
    return new StringValue(v.type);
  });

  // len
  BUILTINS.set('len', (v: Value) => {
    if (v.type === 'string') return new IntValue(BigInt(v.value!.length));
    if (v.type === 'list') return new IntValue(BigInt(v.value!.length));
    throw new RuntimeError(0, `bad argument to len`, '(');
  });

  // push
  BUILTINS.set('push', (list: Value, v: Value) => {
    if (list.type !== 'list') throw new RuntimeError(0, `bad argument to push`, '(');
    list.value!.push(v);
    return new NilValue();
  });

  // pop
  BUILTINS.set('pop', (list: Value) => {
    if (list.type !== 'list') throw new RuntimeError(0, `bad argument to pop`, '(');
    if (list.value!.length === 0) throw new RuntimeError(0, `bad argument to pop`, '(');
    return list.value!.pop()!;
  });

  // range
  BUILTINS.set('range', (a: Value, b: Value) => {
    if (a.type !== 'int' || b.type !== 'int') throw new RuntimeError(0, `bad argument to range`, '(');
    const start = a.value as bigint;
    const end = b.value as bigint;
    const list: ListValue[] = [];
    if (start < end) {
      for (let i = start; i < end; i++) {
        list.push(new IntValue(i));
      }
    }
    return new ListValue(list);
  });

  // slice
  BUILTINS.set('slice', (x: Value, a: Value, b: Value) => {
    if (a.type !== 'int' || b.type !== 'int') throw new RuntimeError(0, `bad argument to slice`, '(');
    const start = Number(a.value as bigint);
    const end = Number(b.value as bigint);
    if (x.type === 'string') {
      return new StringValue(x.value!.substring(start, end));
    } else if (x.type === 'list') {
      const res: ListValue[] = [];
      for (let i = start; i < end; i++) {
        if (i < x.value!.length) res.push(x.value![i]);
      }
      return new ListValue(res);
    } else {
      throw new RuntimeError(0, `bad argument to slice`, '(');
    }
  });
}

function ternDiv(a: bigint, b: bigint): bigint {
  if (b === 0n) throw new RuntimeError(0, 'division by zero', '/');
  let q = a / b;
  let r = a % b;
  if (r !== 0n && ((a < 0n) !== (b < 0n))) {
    q = q + 1n;
  }
  return q;
}

function ternMod(a: bigint, b: bigint): bigint {
  const q = ternDiv(a, b);
  return a - q * b;
}

function display(v: Value, isListElement: boolean = false): string {
  if (v.type === 'int') {
    return v.value!.toString();
  }
  if (v.type === 'bool') {
    return v.value!.toString();
  }
  if (v.type === 'nil') {
    return 'nil';
  }
  if (v.type === 'function') {
    return '<fn>';
  }
  if (v.type === 'string') {
    if (isListElement) {
      let s = v.value!;
      s = s.replace(/\\/g, '\\\\');
      s = s.replace(/"/g, '\\"');
      s = s.replace(/\n/g, '\\n');
      s = s.replace(/\t/g, '\\t');
      return `"${s}"`;
    }
    return v.value!;
  }
  if (v.type === 'list') {
    return displayList(v, false);
  }
  return '';
}

function displayList(v: ListValue, seen: Set<ListValue> | null): string {
  if (seen === null) {
    return displayList(v, new Set());
  }
  if (seen.has(v)) {
    return '[...]';
  }
  seen.add(v);
  let res = '[';
  for (let i = 0; i < v.value.length; i++) {
    if (i > 0) res += ', ';
    res += display(v.value[i], true);
  }
  seen.delete(v);
  res += ']';
  return res;
}

function resolve(name: string, scope: Scope): Value {
  let s: Scope | null = scope;
  while (s) {
    if (s.bindings.has(name)) return s.bindings.get(name)!;
    s = s.parent;
  }
  throw new RuntimeError(scope.bindings.size, `undefined variable ${name}`, name);
}

function setVar(name: string, value: Value, scope: Scope): void {
  if (!scope.bindings.has(name)) {
    throw new RuntimeError(scope.bindings.size, `undefined variable ${name}`, name);
  }
  scope.bindings.set(name, value);
}

function isTruthy(v: Value): boolean {
  if (v.type === 'bool') return v.value!;
  if (v.type === 'nil') return false;
  if (v.type === 'int') return v.value! !== 0n;
  if (v.type === 'string') return v.value!.length > 0;
  if (v.type === 'list') return v.value!.length > 0;
  return true;
}

function execute(
  ast: ASTNode,
  scope: Scope,
  builtinScope: Map<string, Function>
): void | Value {
  if (ast instanceof Program) {
    for (const stmt of ast.stmts) {
      execute(stmt, scope, builtinScope);
    }
    return;
  }
  if (ast instanceof Block) {
    const newScope = new Scope(scope);
    for (const stmt of ast.stmts) {
      execute(stmt, newScope, builtinScope);
    }
    return;
  }

  if (ast instanceof LetStmt) {
    const val = ast.expr.eval(scope);
    setVar(ast.name, val, scope);
    return;
  }

  if (ast instanceof FnDecl) {
    const fn = new FunctionValue(ast.block.stmts, ast.params, scope, ast.name);
    setVar(ast.name, fn, scope);
    return;
  }

  if (ast instanceof IfStmt) {
    const cond = ast.cond.eval(scope);
    if (isTruthy(cond)) {
      execute(ast.thenBlock, scope, builtinScope);
    } else if (ast.elseBlock) {
      execute(ast.elseBlock, scope, builtinScope);
    }
    return;
  }

  if (ast instanceof WhileStmt) {
    let scopeForWhile = new Scope(scope);
    while (true) {
      const cond = ast.cond.eval(scopeForWhile);
      if (!isTruthy(cond)) break;
      execute(ast.block, scopeForWhile, builtinScope);
    }
    return;
  }

  if (ast instanceof ForStmt) {
    const loopScope = new Scope(scope);
    const eVal = ast.expr.eval(scope);
    if (eVal.type !== 'list') {
      throw new RuntimeError(ast.line, `cannot iterate ${eVal.type}`, 'for');
    }
    const list = eVal.value!;
    let i = 0n;
    while (true) {
      if (i >= BigInt(list.length)) break;
      const xVal = list[i];
      const bodyScope = new Scope(loopScope);
      bodyScope.bindings.set(ast.name, xVal);
      let skipIncrement = false;
      let breakLoop = false;
      try {
        for (const stmt of ast.block.stmts) {
          if (stmt instanceof ContinueStmt) {
            skipIncrement = true;
            break;
          }
          if (stmt instanceof BreakStmt) {
            breakLoop = true;
            break;
          }
          execute(stmt, bodyScope, builtinScope);
        }
      } catch (e) {
        if (e instanceof RuntimeError) throw e;
        if (e instanceof BreakLoop) breakLoop = true;
      }
      if (breakLoop) break;
      if (!skipIncrement) i = i + 1n;
    }
    return;
  }

  if (ast instanceof ReturnStmt) {
    if (ast.expr) {
      return ast.expr.eval(scope);
    }
    return new NilValue();
  }

  if (ast instanceof BreakStmt) {
    throw new BreakLoop();
  }

  if (ast instanceof ContinueStmt) {
    return;
  }

  if (ast instanceof AssignStmt) {
    const val = ast.expr.eval(scope);
    setVar(ast.name, val, scope);
    return;
  }

  if (ast instanceof IndexAssign) {
    const objVal = ast.obj.eval(scope);
    const idxVal = ast.index.eval(scope);
    const valVal = ast.value.eval(scope);
    if (objVal.type !== 'list') {
      throw new RuntimeError(ast.line, `cannot assign into ${objVal.type}`, '[');
    }
    if (idxVal.type !== 'int') {
      throw new RuntimeError(ast.line, `cannot index list with ${idxVal.type}`, '[');
    }
    const idx = idxVal.value as bigint;
    if (idx < 0n || idx >= BigInt(objVal.value.length)) {
      throw new RuntimeError(ast.line, `index ${idx} out of range for length ${objVal.value.length}`, '[');
    }
    objVal.value[idx] = valVal;
    return;
  }

  // Expressions
  if (ast instanceof BinaryOp) {
    const left = ast.left.eval(scope);
    const right = ast.right.eval(scope);
    return evalBinaryOp(ast.op, left, right, ast.line);
  }

  if (ast instanceof UnaryOp) {
    const val = ast.expr.eval(scope);
    if (ast.op === 'not') {
      return new BoolValue(!isTruthy(val));
    }
    if (ast.op === '-') {
      if (val.type !== 'int') throw new RuntimeError(ast.line, `cannot apply - to ${val.type}`, '-');
      const res = -val.value!;
      if (res < BigInt(-9223372036854775808) || res > BigInt(9223372036854775807)) {
        throw new RuntimeError(ast.line, 'integer overflow', '-');
      }
      return new IntValue(res);
    }
    throw new RuntimeError(ast.line, `cannot apply ${ast.op} to ${val.type}`, ast.op);
  }

  if (ast instanceof Call) {
    const calleeVal = ast.callee.eval(scope);
    if (calleeVal.type !== 'function') {
      throw new RuntimeError(ast.line, `cannot call ${calleeVal.type}`, '(');
    }
    const fn = calleeVal as FunctionValue;
    const args = ast.args.map(a => a.eval(scope));
    if (fn.params.length !== args.length) {
      throw new RuntimeError(ast.line, `expected ${fn.params.length} arguments, got ${args.length}`, '(');
    }
    const callScope = new Scope(fn.scope);
    for (let i = 0; i < fn.params.length; i++) {
      callScope.bindings.set(fn.params[i], args[i]);
    }
    let result: Value | undefined;
    for (const stmt of fn.body) {
      result = execute(stmt, callScope, builtinScope);
    }
    return result || new NilValue();
  }

  if (ast instanceof ArrayLit) {
    const items = ast.items.map(i => i.eval(scope));
    return new ListValue(items);
  }

  if (ast instanceof IndexExpr) {
    const objVal = ast.obj.eval(scope);
    const idxVal = ast.index.eval(scope);
    if (objVal.type !== 'list' && objVal.type !== 'string') {
      throw new RuntimeError(ast.line, `cannot index ${objVal.type} with ${idxVal.type}`, '[');
    }
    if (idxVal.type !== 'int') {
      throw new RuntimeError(ast.line, `cannot index list with ${idxVal.type}`, '[');
    }
    const idx = idxVal.value as bigint;
    if (idx < 0n) {
      throw new RuntimeError(ast.line, `index ${idx} out of range for length ${BigInt(objVal.type === 'list' ? objVal.value.length : objVal.value.length)}`, '[');
    }
    if (objVal.type === 'list') {
      if (idx >= BigInt(objVal.value.length)) {
        throw new RuntimeError(ast.line, `index ${idx} out of range for length ${objVal.value.length}`, '[');
      }
      return objVal.value[idx];
    } else {
      const len = BigInt(objVal.value.length);
      if (idx >= len) {
        throw new RuntimeError(ast.line, `index ${idx} out of range for length ${objVal.value.length}`, '[');
      }
      const char = objVal.value.toString()[Number(idx)];
      return new StringValue(char);
    }
  }

  if (ast instanceof Primary) {
    if (ast.type === 'int') return new IntValue(ast.value as bigint);
    if (ast.type === 'string') return new StringValue(ast.value as string);
    if (ast.type === 'bool') return new BoolValue(ast.value as boolean);
    if (ast.type === 'nil') return new NilValue();
    if (ast.type === 'ident') {
      return resolve(ast.name as string, scope);
    }
    if (ast.type === 'fn') {
      const fn = new FunctionValue(ast.block!.stmts, ast.params!, scope, ast.name || '<fn>');
      return fn;
    }
    if (ast.type === 'array') {
      return new ListValue(ast.items!.map(i => i.eval(scope)));
    }
    if (ast.type === 'paren') {
      return (ast.items![0] as Expr).eval(scope);
    }
    throw new RuntimeError(ast.line, `unexpected primary type ${ast.type}`, ast.type);
  }

  throw new RuntimeError(ast.line, `unexpected node type ${ast.constructor.name}`, ast.constructor.name);
}

class BreakLoop extends Error {
  constructor() {
    super('BreakLoop');
  }
}

function evalBinaryOp(op: string, left: Value, right: Value, line: number): Value {
  if (op === '==') {
    if (left.type !== right.type) return new BoolValue(false);
    if (left.type === 'int' && right.type === 'int') {
      return new BoolValue(left.value! === right.value!);
    }
    if (left.type === 'bool' && right.type === 'bool') {
      return new BoolValue(left.value! === right.value!);
    }
    if (left.type === 'string' && right.type === 'string') {
      return new BoolValue(left.value! === right.value!);
    }
    if (left.type === 'list' && right.type === 'list') {
      if (left.value!.length !== right.value!.length) return new BoolValue(false);
      for (let i = 0; i < left.value!.length; i++) {
        if (!evalBinaryOp('==', left.value![i], right.value![i], line)) return new BoolValue(false);
      }
      return new BoolValue(true);
    }
    if (left.type === 'function' && right.type === 'function') {
      return new BoolValue(left === right);
    }
    return new BoolValue(false);
  }
  if (op === '!=') {
    if (left.type !== right.type) return new BoolValue(true);
    if (left.type === 'int' && right.type === 'int') {
      return new BoolValue(left.value! !== right.value!);
    }
    if (left.type === 'bool' && right.type === 'bool') {
      return new BoolValue(left.value! !== right.value!);
    }
    if (left.type === 'string' && right.type === 'string') {
      return new BoolValue(left.value! !== right.value!);
    }
    if (left.type === 'list' && right.type === 'list') {
      if (left.value!.length !== right.value!.length) return new BoolValue(true);
      for (let i = 0; i < left.value!.length; i++) {
        if (evalBinaryOp('==', left.value![i], right.value![i], line)) return new BoolValue(true);
      }
      return new BoolValue(false);
    }
    if (left.type === 'function' && right.type === 'function') {
      return new BoolValue(left !== right);
    }
    return new BoolValue(false);
  }
  if (op === '<' || op === '<=' || op === '>' || op === '>=') {
    if (left.type !== right.type) throw new RuntimeError(line, `cannot apply ${op} to ${left.type} and ${right.type}`, op);
    if (left.type === 'int' && right.type === 'int') {
      const l = left.value as bigint;
      const r = right.value as bigint;
      if (op === '<') return new BoolValue(l < r);
      if (op === '<=') return new BoolValue(l <= r);
      if (op === '>') return new BoolValue(l > r);
      if (op === '>=') return new BoolValue(l >= r);
    }
    if (left.type === 'string' && right.type === 'string') {
      const l = left.value as string;
      const r = right.value as string;
      if (op === '<') return new BoolValue(l < r);
      if (op === '<=') return new BoolValue(l <= r);
      if (op === '>') return new BoolValue(l > r);
      if (op === '>=') return new BoolValue(l >= r);
    }
    throw new RuntimeError(line, `cannot apply ${op} to ${left.type} and ${right.type}`, op);
  }
  if (op === '+') {
    if (left.type === 'int' && right.type === 'int') {
      const l = left.value as bigint;
      const r = right.value as bigint;
      const res = l + r;
      if (res < BigInt(-9223372036854775808) || res > BigInt(9223372036854775807)) {
        throw new RuntimeError(line, 'integer overflow', '+');
      }
      return new IntValue(res);
    }
    if (left.type === 'string' && right.type === 'string') {
      return new StringValue((left.value as string) + (right.value as string));
    }
    if (left.type === 'list' && right.type === 'list') {
      const res: ListValue[] = [...left.value!, ...right.value!];
      return new ListValue(res);
    }
    throw new RuntimeError(line, `cannot apply + to ${left.type} and ${right.type}`, '+');
  }
  if (op === '-') {
    if (left.type !== 'int' || right.type !== 'int') {
      throw new RuntimeError(line, `cannot apply - to ${left.type} and ${right.type}`, '-');
    }
    const l = left.value as bigint;
    const r = right.value as bigint;
    const res = l - r;
    if (res < BigInt(-9223372036854775808) || res > BigInt(9223372036854775807)) {
      throw new RuntimeError(line, 'integer overflow', '-');
    }
    return new IntValue(res);
  }
  if (op === '*') {
    if (left.type !== 'int' || right.type !== 'int') {
      throw new RuntimeError(line, `cannot apply * to ${left.type} and ${right.type}`, '*');
    }
    const l = left.value as bigint;
    const r = right.value as bigint;
    const res = l * r;
    if (res < BigInt(-9223372036854775808) || res > BigInt(9223372036854775807)) {
      throw new RuntimeError(line, 'integer overflow', '*');
    }
    return new IntValue(res);
  }
  if (op === '/') {
    if (left.type !== 'int' || right.type !== 'int') {
      throw new RuntimeError(line, `cannot apply / to ${left.type} and ${right.type}`, '/');
    }
    const q = ternDiv(left.value as bigint, right.value as bigint);
    if (q < BigInt(-9223372036854775808) || q > BigInt(9223372036854775807)) {
      throw new RuntimeError(line, 'integer overflow', '/');
    }
    return new IntValue(q);
  }
  if (op === '%') {
    if (left.type !== 'int' || right.type !== 'int') {
      throw new RuntimeError(line, `cannot apply % to ${left.type} and ${right.type}`, '%');
    }
    const res = ternMod(left.value as bigint, right.value as bigint);
    if (res < BigInt(-9223372036854775808) || res > BigInt(9223372036854775807)) {
      throw new RuntimeError(line, 'integer overflow', '%');
    }
    return new IntValue(res);
  }
  if (op === 'and') {
    if (!isTruthy(left)) return left;
    return right;
  }
  if (op === 'or') {
    if (isTruthy(left)) return left;
    return right;
  }
  throw new RuntimeError(line, `unexpected operator ${op}`, op);
}

// --- Main ---

function main() {
  const args = process.argv.slice(2);
  if (args.length !== 1) {
    console.error('Usage: tsx main.ts <directory>');
    process.exit(1);
  }
  const dir = args[0];
  const filePath = path.join(dir, 'program.tern');
  const source = fs.readFileSync(filePath, 'utf-8');

  initBuiltins();

  try {
    const lexer = new Lexer(source);
    const tokens = lexer.tokenize();
    const parser = new Parser(tokens);
    const ast = parser.parseProgram();

    const globalScope = new Scope(null, new Map<string, Function>(BUILTINS));
    execute(ast, globalScope, BUILTINS);
  } catch (e) {
    if (e instanceof RuntimeError) {
      console.error(`error at line ${e.line}: ${e.message}`);
    } else if (e instanceof BreakLoop) {
      // Ignore break
    } else {
      console.error(`error at line 1: ${e}`);
    }
    process.exit(0);
  }
  process.exit(0);
}

main();

import java.io.*;
import java.util.*;
import java.util.zip.*;

public class Main {
    public static void main(String[] args) {
        if (args.length == 0) {
            System.exit(1);
        }
        File dir = new File(args[0]);
        File jsonFile = new File(dir, "scene.json");
        File outFile = new File(dir, "out.png");

        try {
            String json = new String(Files.readAllBytes(jsonFile.toPath()));
            Scene scene = parseScene(json);

            int width = scene.width;
            int height = scene.height;
            int[] background = scene.background;
            List<Shape> shapes = scene.shapes;

            // Initialize canvas
            // R, G, B interleaved
            byte[] canvas = new byte[width * height * 3];
            for (int i = 0; i < width * height; i++) {
                int r = background[0];
                int g = background[1];
                int b = background[2];
                canvas[i * 3] = (byte) r;
                canvas[i * 3 + 1] = (byte) g;
                canvas[i * 3 + 2] = (byte) b;
            }

            // Track distinct colors
            Set<Integer> distinctColors = new HashSet<>();

            // Render shapes
            for (int i = 0; i < shapes.size(); i++) {
                Shape shape = shapes.get(i);
                int covered = 0;
                int typeIndex = i + 1;
                String type = shape.type;

                if (type.equals("rect")) {
                    int rx = shape.x;
                    int ry = shape.y;
                    int w = shape.w;
                    int h = shape.h;
                    int[] color = shape.color;
                    int sR = color[0];
                    int sG = color[1];
                    int sB = color[2];
                    int A = (color.length > 3) ? color[3] : 255;

                    int startX = Math.max(0, rx);
                    int endX = Math.min(width, rx + w);
                    int startY = Math.max(0, ry);
                    int endY = Math.min(height, ry + h);

                    if (startX < endX && startY < endY) {
                        for (int x = startX; x < endX; x++) {
                            for (int y = startY; y < endY; y++) {
                                int idx = y * width + x;
                                if (x >= rx && x < rx + w && y >= ry && y < ry + h) {
                                    applyColor(canvas, idx, sR, sG, sB, A);
                                    covered++;
                                }
                            }
                        }
                    }
                } else if (type.equals("circle")) {
                    int cx = shape.cx;
                    int cy = shape.cy;
                    int r = shape.r;
                    int[] color = shape.color;
                    int sR = color[0];
                    int sG = color[1];
                    int sB = color[2];
                    int A = (color.length > 3) ? color[3] : 255;

                    int startX = Math.max(0, cx - r);
                    int endX = Math.min(width, cx + r);
                    int startY = Math.max(0, cy - r);
                    int endY = Math.min(height, cy + r);

                    if (startX < endX && startY < endY) {
                        for (int x = startX; x < endX; x++) {
                            for (int y = startY; y < endY; y++) {
                                if ((x - cx) * (x - cx) + (y - cy) * (y - cy) <= (long) r * r) {
                                    int idx = y * width + x;
                                    applyColor(canvas, idx, sR, sG, sB, A);
                                    covered++;
                                }
                            }
                        }
                    }
                } else if (type.equals("triangle")) {
                    int[][] points = shape.points;
                    int[] color = shape.color;
                    int sR = color[0];
                    int sG = color[1];
                    int sB = color[2];
                    int A = (color.length > 3) ? color[3] : 255;

                    int minX = Math.min(Math.min(points[0][0], points[1][0]), points[2][0]);
                    int maxX = Math.max(Math.max(points[0][0], points[1][0]), points[2][0]);
                    int minY = Math.min(Math.min(points[0][1], points[1][1]), points[2][1]);
                    int maxY = Math.max(Math.max(points[0][1], points[1][1]), points[2][1]);

                    int startX = Math.max(0, minX);
                    int endX = Math.min(width, maxX);
                    int startY = Math.max(0, minY);
                    int endY = Math.min(height, maxY);

                    if (startX < endX && startY < endY) {
                        for (int x = startX; x < endX; x++) {
                            for (int y = startY; y < endY; y++) {
                                if (isInsideTriangle(x, y, points)) {
                                    int idx = y * width + x;
                                    applyColor(canvas, idx, sR, sG, sB, A);
                                    covered++;
                                }
                            }
                        }
                    }
                } else if (type.equals("line")) {
                    int x1 = shape.x1;
                    int y1 = shape.y1;
                    int x2 = shape.x2;
                    int y2 = shape.y2;
                    int r = shape.r;
                    int[] color = shape.color;
                    int sR = color[0];
                    int sG = color[1];
                    int sB = color[2];
                    int A = (color.length > 3) ? color[3] : 255;

                    int minX = Math.min(x1, x2);
                    int maxX = Math.max(x1, x2);
                    int minY = Math.min(y1, y2);
                    int maxY = Math.max(y1, y2);

                    int startX = Math.max(0, minX);
                    int endX = Math.min(width, maxX);
                    int startY = Math.max(0, minY);
                    int endY = Math.min(height, maxY);

                    if (startX < endX && startY < endY) {
                        for (int x = startX; x < endX; x++) {
                            for (int y = startY; y < endY; y++) {
                                if (isInsideLine(x, y, x1, y1, x2, y2, r)) {
                                    int idx = y * width + x;
                                    applyColor(canvas, idx, sR, sG, sB, A);
                                    covered++;
                                }
                            }
                        }
                    }
                }

                System.out.println(typeIndex + " " + type + " " + covered);
            }

            // Count distinct colors
            for (int y = 0; y < height; y++) {
                for (int x = 0; x < width; x++) {
                    int idx = y * width + x;
                    int r = canvas[idx * 3] & 0xFF;
                    int g = canvas[idx * 3 + 1] & 0xFF;
                    int b = canvas[idx * 3 + 2] & 0xFF;
                    distinctColors.add(r * 65536 + g * 256 + b);
                }
            }
            System.out.println("colors " + distinctColors.size());

            // Write PNG
            writePng(width, height, canvas, outFile);

        } catch (Exception e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

    static void applyColor(byte[] canvas, int idx, int sR, int sG, int sB, int A) {
        if (A == 0) return;
        int r = canvas[idx * 3] & 0xFF;
        int g = canvas[idx * 3 + 1] & 0xFF;
        int b = canvas[idx * 3 + 2] & 0xFF;

        int newR = (sR * A + r * (255 - A) + 127) / 255;
        int newG = (sG * A + g * (255 - A) + 127) / 255;
        int newB = (sB * A + b * (255 - A) + 127) / 255;

        canvas[idx * 3] = (byte) newR;
        canvas[idx * 3 + 1] = (byte) newG;
        canvas[idx * 3 + 2] = (byte) newB;
    }

    static boolean isInsideTriangle(int x, int y, int[][] points) {
        long E0, E1, E2;
        int p0x = points[0][0];
        int p0y = points[0][1];
        int p1x = points[1][0];
        int p1y = points[1][1];
        int p2x = points[2][0];
        int p2y = points[2][1];

        // E0: P0 -> P1
        E0 = (long)(p1x - p0x) * (y - p0y) - (long)(p1y - p0y) * (x - p0x);
        // E1: P1 -> P2
        E1 = (long)(p2x - p1x) * (y - p1y) - (long)(p2y - p1y) * (x - p1x);
        // E2: P2 -> P0
        E2 = (long)(p0x - p2x) * (y - p2y) - (long)(p0y - p2y) * (x - p2x);

        boolean allPos = (E0 >= 0) && (E1 >= 0) && (E2 >= 0);
        boolean allNeg = (E0 <= 0) && (E1 <= 0) && (E2 <= 0);

        return allPos || allNeg;
    }

    static boolean isInsideLine(int x, int y, int x1, int y1, int x2, int y2, int r) {
        long dx = (long)x2 - x1;
        long dy = (long)y2 - y1;
        long L = dx * dx + dy * dy;
        long t = (long)(x - x1) * dx + (long)(y - y1) * dy;

        if (t <= 0) {
            return (long)(x - x1) * (x - x1) + (long)(y - y1) * (y - y1) <= (long)r * r;
        } else if (t >= L) {
            return (long)(x - x2) * (x - x2) + (long)(y - y2) * (y - y2) <= (long)r * r;
        } else {
            long c = (long)(x - x1) * dy - (long)(y - y1) * dx;
            return c * c <= (long)r * r * L;
        }
    }

