        List<Map<String, Object>> shapesMap = (List<Map<String, Object>>) map.get("shapes");

        List<Shape> shapes = new ArrayList<>();
        for (Map<String, Object> shapeMap : shapesMap) {
            String type = (String) shapeMap.get("type");
            int[] color = parseArray(shapeMap.get("color"), int.class);

            Shape shape = null;
            if (type.equals("rect")) {
                int x = (Integer) shapeMap.get("x");
