            } else if (type.equals("circle")) {
                int cx = (Integer) shapeMap.get("cx");
                int cy = (Integer) shapeMap.get("cy");
                int r = (Integer) shapeMap.get("r");
                shape = new Shape(type, cx, cy, r, color);
            } else if (type.equals("triangle")) {
                List<List<Integer>> pointsList = (List<List<Integer>>) shapeMap.get("points");
                int[][] points = new int[3][2];
                for (int i = 0; i < 3; i++) {
                    points[i][0] = pointsList.get(i).get(0);
                    points[i][1] = pointsList.get(i).get(1);
                }
                shape = new Shape(type, points, color);
