                int r = (Integer) shapeMap.get("r");
                shape = new Shape(type, x1, y1, x2, y2, r, color);
            }
            shapes.add(shape);
        }

        return new Scene(width, height, background, shapes);
    }

    static int[] parseArray(Object obj, Class<?> type) {
        List<Integer> list = (List<Integer>) obj;
