        }
        return arr;
    }

    static void writePng(int width, int height, byte[] canvas, File outFile) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();

        // Signature
        baos.write(new byte[]{0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A});

        // IHDR
        byte[] ihdrData = new byte[13];
        IHDR.write(ihdrData, width, height);
        CRC32 crc = new CRC32();
        crc.update(ihdrData);
        int ihdrCrc = (int) (crc.getValue() & 0xFFFFFFFFL);

        // IHDR chunk
        byte[] ihdrChunk = new byte[12 + ihdrData.length + 4];
        writeLength(ihdrChunk, 0, 13);
        System.arraycopy("IHDR".getBytes(), 0, ihdrChunk, 4, 4);
        System.arraycopy(ihdrData, 0, ihdrChunk, 8, 13);
        writeInt(ihdrChunk, 8 + 13, ihdrCrc);

        // IDAT
        byte[] idatData = compressImage(width, height, canvas);
        CRC32 crcIdat = new CRC32();
        crcIdat.update(idatData);
        int idatCrc = (int) (crcIdat.getValue() & 0xFFFFFFFFL);

        byte[] idatChunk = new byte[12 + idatData.length + 4];
        writeLength(idatChunk, 0, idatData.length);
        System.arraycopy("IDAT".getBytes(), 0, idatChunk, 4, 4);
        System.arraycopy(idatData, 0, idatChunk, 8, idatData.length);
        writeInt(idatChunk, 8 + idatData.length, idatCrc);

        // IEND
        byte[] iendData = new byte[0];
        CRC32 crcIend = new CRC32();
        crcIend.update(iendData);
        int iendCrc = (int) (crcIend.getValue() & 0xFFFFFFFFL);

        byte[] iendChunk = new byte[12 + 0 + 4];
        writeLength(iendChunk, 0, 0);
        System.arraycopy("IEND".getBytes(), 0, iendChunk, 4, 4);
        writeInt(iendChunk, 8, iendCrc);

        // Combine
        byte[] png = new byte[8 + 12 + 13 + 4 + 12 + idatData.length + 4 + 12 + 4];
        System.arraycopy(new byte[]{0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A}, 0, png, 0, 8);
        System.arraycopy(ihdrChunk, 0, png, 8, 12 + 13 + 4);
        System.arraycopy(idatChunk, 0, png, 8 + 12 + 13 + 4, 12 + idatData.length + 4);
        System.arraycopy(iendChunk, 0, png, 8 + 12 + 13 + 4 + 12 + idatData.length + 4, 12 + 4);

        Files.write(outFile.toPath(), png);
    }

    static byte[] compressImage(int width, int height, byte[] canvas) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        DeflaterOutputStream dos = new DeflaterOutputStream(baos, new Deflater(Deflater.DEFAULT_COMPRESSION, true));

        for (int y = 0; y < height; y++) {
            // Filter byte 0 (None)
            dos.write(new byte[]{0});
            for (int x = 0; x < width; x++) {
                int idx = y * width + x;
                dos.write(canvas[idx * 3]);
                dos.write(canvas[idx * 3 + 1]);
                dos.write(canvas[idx * 3 + 2]);
            }
        }

        dos.finish();
        dos.close();
        return baos.toByteArray();
    }

    static void writeLength(byte[] data, int offset, int length) {
        data[offset] = (byte) (length & 0xFF);
        data[offset + 1] = (byte) ((length >> 8) & 0xFF);
        data[offset + 2] = (byte) ((length >> 16) & 0xFF);
        data[offset + 3] = (byte) ((length >> 24) & 0xFF);
    }

    static void writeInt(byte[] data, int offset, int value) {
        data[offset] = (byte) (value & 0xFF);
        data[offset + 1] = (byte) ((value >> 8) & 0xFF);
        data[offset + 2] = (byte) ((value >> 16) & 0xFF);
        data[offset + 3] = (byte) ((value >> 24) & 0xFF);
    }

    static class IHDR {
        static void write(byte[] data, int width, int height) {
            System.arraycopy((int) width, 0, data, 0, 4);
            System.arraycopy((int) height, 0, data, 4, 4);
            data[8] = (byte) 8; // Bit depth
            data[9] = (byte) 2; // Color type
            data[10] = (byte) 0; // Compression
            data[11] = (byte) 0; // Filter
            data[12] = (byte) 0; // Interlace
        }
    }

    static class JsonParser {
        Scanner sc;

        JsonParser(String json) {
            sc = new Scanner(json).useDelimiter("\\A");
        }

        Object parse() {
            if (!sc.hasNext()) return null;
            String token = sc.next();
            if (token.equals("{")) {
                return parseObject();
            } else if (token.equals("[")) {
                return parseArray();
            } else if (token.equals("\"")) {
                return parseString();
            } else {
                return parseNumber();
            }
        }

        Object parseObject() {
            sc.next(); // skip {
            Map<String, Object> map = new HashMap<>();
            while (true) {
                String key = parseString();
                sc.next(); // skip :
                Object value = parse();
                map.put(key, value);
                String token = sc.next();
                if (token.equals("}")) {
                    break;
                } else if (token.equals(",")) {
                    continue;
                }
            }
            return map;
        }

        Object parseArray() {
            sc.next(); // skip [
            List<Object> list = new ArrayList<>();
            while (true) {
                Object value = parse();
                list.add(value);
                String token = sc.next();
                if (token.equals("]")) {
                    break;
                } else if (token.equals(",")) {
                    continue;
                }
            }
            return list;
        }

        String parseString() {
            sc.next(); // skip "
            StringBuilder sb = new StringBuilder();
            while (sc.hasNext()) {
                String token = sc.next();
                if (token.equals("\"")) {
                    break;
                }
                sb.append(token);
            }
            return sb.toString();
        }

        Integer parseNumber() {
            String token = sc.next();
            return Integer.parseInt(token);
        }
    }
}

import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;

public class Main {
    public static void main(String[] args) {
        if (args.length == 0) {
            System.exit(1);
        }
        File dir = new File(args[0]);
        File jsonFile = new File(dir, "scene.json");
        File outFile = new File(dir, "out.png");

        try {
            String json = new String(Files.readAllBytes(jsonFile.toPath()));
            Scene scene = parseScene(json);

            int width = scene.width;
            int height = scene.height;
            int[] background = scene.background;
            List<Shape> shapes = scene.shapes;

            // Initialize canvas
            // R, G, B interleaved
            byte[] canvas = new byte[width * height * 3];
            for (int i = 0; i < width * height; i++) {
                int r = background[0];
                int g = background[1];
                int b = background[2];
                canvas[i * 3] = (byte) r;
                canvas[i * 3 + 1] = (byte) g;
                canvas[i * 3 + 2] = (byte) b;
            }

            // Track distinct colors
            Set<Integer> distinctColors = new HashSet<>();

            // Render shapes
            for (int i = 0; i < shapes.size(); i++) {
                Shape shape = shapes.get(i);
                int covered = 0;
                int typeIndex = i + 1;
                String type = shape.type;

                if (type.equals("rect")) {
                    int rx = shape.x;
                    int ry = shape.y;
                    int w = shape.w;
                    int h = shape.h;
                    int[] color = shape.color;
                    int sR = color[0];
                    int sG = color[1];
                    int sB = color[2];
                    int A = (color.length > 3) ? color[3] : 255;

                    int startX = Math.max(0, rx);
                    int endX = Math.min(width, rx + w);
                    int startY = Math.max(0, ry);
                    int endY = Math.min(height, ry + h);

                    if (startX < endX && startY < endY) {
                        for (int x = startX; x < endX; x++) {
                            for (int y = startY; y < endY; y++) {
                                int idx = y * width + x;
                                if (x >= rx && x < rx + w && y >= ry && y < ry + h) {
                                    applyColor(canvas, idx, sR, sG, sB, A);
                                    covered++;
                                }
                            }
                        }
                    }
                } else if (type.equals("circle")) {
                    int cx = shape.cx;
                    int cy = shape.cy;
                    int r = shape.r;
                    int[] color = shape.color;
                    int sR = color[0];
                    int sG = color[1];
                    int sB = color[2];
                    int A = (color.length > 3) ? color[3] : 255;

                    int startX = Math.max(0, cx - r);
                    int endX = Math.min(width, cx + r);
                    int startY = Math.max(0, cy - r);
                    int endY = Math.min(height, cy + r);

                    if (startX < endX && startY < endY) {
                        for (int x = startX; x < endX; x++) {
                            for (int y = startY; y < endY; y++) {
                                if ((long)(x - cx) * (x - cx) + (long)(y - cy) * (y - cy) <= (long) r * r) {
                                    int idx = y * width + x;
                                    applyColor(canvas, idx, sR, sG, sB, A);
                                    covered++;
                                }
                            }
                        }
                    }
                } else if (type.equals("triangle")) {
                    int[][] points = shape.points;
                    int[] color = shape.color;
                    int sR = color[0];
                    int sG = color[1];
                    int sB = color[2];
                    int A = (color.length > 3) ? color[3] : 255;

                    int minX = Math.min(Math.min(points[0][0], points[1][0]), points[2][0]);
                    int maxX = Math.max(Math.max(points[0][0], points[1][0]), points[2][0]);
                    int minY = Math.min(Math.min(points[0][1], points[1][1]), points[2][1]);
                    int maxY = Math.max(Math.max(points[0][1], points[1][1]), points[2][1]);

                    int startX = Math.max(0, minX);
                    int endX = Math.min(width, maxX);
                    int startY = Math.max(0, minY);
                    int endY = Math.min(height, maxY);

                    if (startX < endX && startY < endY) {
                        for (int x = startX; x < endX; x++) {
                            for (int y = startY; y < endY; y++) {
                                if (isInsideTriangle(x, y, points)) {
                                    int idx = y * width + x;
                                    applyColor(canvas, idx, sR, sG, sB, A);
                                    covered++;
                                }
                            }
                        }
                    }
                } else if (type.equals("line")) {
                    int x1 = shape.x1;
                    int y1 = shape.y1;
                    int x2 = shape.x2;
                    int y2 = shape.y2;
                    int r = shape.r;
                    int[] color = shape.color;
                    int sR = color[0];
                    int sG = color[1];
                    int sB = color[2];
                    int A = (color.length > 3) ? color[3] : 255;

                    int minX = Math.min(x1, x2);
                    int maxX = Math.max(x1, x2);
                    int minY = Math.min(y1, y2);
                    int maxY = Math.max(y1, y2);

                    int startX = Math.max(0, minX);
                    int endX = Math.min(width, maxX);
                    int startY = Math.max(0, minY);
                    int endY = Math.min(height, maxY);

                    if (startX < endX && startY < endY) {
                        for (int x = startX; x < endX; x++) {
                            for (int y = startY; y < endY; y++) {
                                if (isInsideLine(x, y, x1, y1, x2, y2, r)) {
                                    int idx = y * width + x;
                                    applyColor(canvas, idx, sR, sG, sB, A);
                                    covered++;
                                }
                            }
                        }
                    }
                }

                System.out.println(typeIndex + " " + type + " " + covered);
            }

            // Count distinct colors
            for (int y = 0; y < height; y++) {
                for (int x = 0; x < width; x++) {
                    int idx = y * width + x;
                    int r = canvas[idx * 3] & 0xFF;
                    int g = canvas[idx * 3 + 1] & 0xFF;
                    int b = canvas[idx * 3 + 2] & 0xFF;
                    distinctColors.add(r * 65536 + g * 256 + b);
                }
            }
            System.out.println("colors " + distinctColors.size());

            // Write PNG
            writePng(width, height, canvas, outFile);

        } catch (Exception e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

    static void applyColor(byte[] canvas, int idx, int sR, int sG, int sB, int A) {
        if (A == 0) return;
        int r = canvas[idx * 3] & 0xFF;
        int g = canvas[idx * 3 + 1] & 0xFF;
        int b = canvas[idx * 3 + 2] & 0xFF;

        int newR = (sR * A + r * (255 - A) + 127) / 255;
        int newG = (sG * A + g * (255 - A) + 127) / 255;
        int newB = (sB * A + b * (255 - A) + 127) / 255;

        canvas[idx * 3] = (byte) newR;
        canvas[idx * 3 + 1] = (byte) newG;
        canvas[idx * 3 + 2] = (byte) newB;
    }

    static boolean isInsideTriangle(int x, int y, int[][] points) {
        long E0, E1, E2;
        int p0x = points[0][0];
        int p0y = points[0][1];
        int p1x = points[1][0];
        int p1y = points[1][1];
        int p2x = points[2][0];
        int p2y = points[2][1];

        // E0: P0 -> P1
        E0 = (long)(p1x - p0x) * (y - p0y) - (long)(p1y - p0y) * (x - p0x);
        // E1: P1 -> P2
        E1 = (long)(p2x - p1x) * (y - p1y) - (long)(p2y - p1y) * (x - p1x);
        // E2: P2 -> P0
        E2 = (long)(p0x - p2x) * (y - p2y) - (long)(p0y - p2y) * (x - p2x);

        boolean allPos = (E0 >= 0) && (E1 >= 0) && (E2 >= 0);
        boolean allNeg = (E0 <= 0) && (E1 <= 0) && (E2 <= 0);

        return allPos || allNeg;
    }

    static boolean isInsideLine(int x, int y, int x1, int y1, int x2, int y2, int r) {
        long dx = (long)x2 - x1;
        long dy = (long)y2 - y1;
        long L = dx * dx + dy * dy;
        long t = (long)(x - x1) * dx + (long)(y - y1) * dy;

        if (t <= 0) {
            return (long)(x - x1) * (x - x1) + (long)(y - y1) * (y - y1) <= (long)r * r;
        } else if (t >= L) {
            return (long)(x - x2) * (x - x2) + (long)(y - y2) * (y - y2) <= (long)r * r;
        } else {
            long c = (long)(x - x1) * dy - (long)(y - y1) * dx;
            return c * c <= (long)r * r * L;
        }
    }

