                int x2 = (Integer) shapeMap.get("x2");
                int y2 = (Integer) shapeMap.get("y2");
                int r = (Integer) shapeMap.get("r");
                shape = new Shape(type, x1, y1, x2, y2, r, color);
            }
            shapes.add(shape);
        }

        return new Scene(width, height, background, shapes);
    }

    static int[] parseArray(Object obj, Class<?> type) {
        List<Integer> list = (List<Integer>) obj;
        int[] arr = new int[list.size()];
        for (int i = 0; i < list.size(); i++) {
            arr[i] = list.get(i);
        }
        return arr;
    }

    static void writePng(int width, int height, byte[] canvas, File outFile) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();

        // Signature
        baos.write(new byte[]{0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A});

        // IHDR
        byte[] ihdrData = new byte[13];
        ihdrData[0] = (byte) (width & 0xFF);
        ihdrData[1] = (byte) ((width >> 8) & 0xFF);
        ihdrData[2] = (byte) ((width >> 16) & 0xFF);
        ihdrData[3] = (byte) ((width >> 24) & 0xFF);
        ihdrData[4] = (byte) (height & 0xFF);
        ihdrData[5] = (byte) ((height >> 8) & 0xFF);
        ihdrData[6] = (byte) ((height >> 16) & 0xFF);
        ihdrData[7] = (byte) ((height >> 24) & 0xFF);
        ihdrData[8] = (byte) 8; // Bit depth
        ihdrData[9] = (byte) 2; // Color type
        ihdrData[10] = (byte) 0; // Compression
        ihdrData[11] = (byte) 0; // Filter
        ihdrData[12] = (byte) 0; // Interlace

        CRC32 crc = new CRC32();
        crc.update(ihdrData);
        int ihdrCrc = (int) (crc.getValue() & 0xFFFFFFFFL);

        // IHDR chunk
        byte[] ihdrChunk = new byte[12 + ihdrData.length + 4];
        writeLength(ihdrChunk, 0, 13);
        ihdrChunk[4] = (byte) 'I';
        ihdrChunk[5] = (byte) 'H';
        ihdrChunk[6] = (byte) 'D';
        ihdrChunk[7] = (byte) 'R';
        System.arraycopy(ihdrData, 0, ihdrChunk, 8, 13);
        writeInt(ihdrChunk, 8 + 13, ihdrCrc);

        // IDAT
        byte[] idatData = compressImage(width, height, canvas);
        CRC32 crcIdat = new CRC32();
        crcIdat.update(idatData);
        int idatCrc = (int) (crcIdat.getValue() & 0xFFFFFFFFL);

        byte[] idatChunk = new byte[12 + idatData.length + 4];
        writeLength(idatChunk, 0, idatData.length);
        idatChunk[4] = (byte) 'I';
        idatChunk[5] = (byte) 'D';
        idatChunk[6] = (byte) 'A';
        idatChunk[7] = (byte) 'T';
        System.arraycopy(idatData, 0, idatChunk, 8, idatData.length);
        writeInt(idatChunk, 8 + idatData.length, idatCrc);

        // IEND
        byte[] iendData = new byte[0];
        CRC32 crcIend = new CRC32();
        crcIend.update(iendData);
        int iendCrc = (int) (crcIend.getValue() & 0xFFFFFFFFL);

        byte[] iendChunk = new byte[12 + 0 + 4];
        writeLength(iendChunk, 0, 0);
        iendChunk[4] = (byte) 'I';
        iendChunk[5] = (byte) 'E';
        iendChunk[6] = (byte) 'N';
        iendChunk[7] = (byte) 'D';
        writeInt(iendChunk, 8, iendCrc);

        // Combine
        byte[] png = new byte[8 + 12 + 13 + 4 + 12 + idatData.length + 4 + 12 + 4];
        System.arraycopy(new byte[]{0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A}, 0, png, 0, 8);
        System.arraycopy(ihdrChunk, 0, png, 8, 12 + 13 + 4);
        System.arraycopy(idatChunk, 0, png, 8 + 12 + 13 + 4, 12 + idatData.length + 4);
        System.arraycopy(iendChunk, 0, png, 8 + 12 + 13 + 4 + 12 + idatData.length + 4, 12 + 4);

        Files.write(outFile.toPath(), png);
    }

    static byte[] compressImage(int width, int height, byte[] canvas) throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        DeflaterOutputStream dos = new DeflaterOutputStream(baos, new Deflater(Deflater.DEFAULT_COMPRESSION, true));

        for (int y = 0; y < height; y++) {
            // Filter byte 0 (None)
            dos.write(new byte[]{0});
            for (int x = 0; x < width; x++) {
                int idx = y * width + x;
                dos.write(canvas[idx * 3]);
                dos.write(canvas[idx * 3 + 1]);
                dos.write(canvas[idx * 3 + 2]);
            }
        }

        dos.finish();
        dos.close();
        return baos.toByteArray();
    }

    static void writeLength(byte[] data, int offset, int length) {
        data[offset] = (byte) (length & 0xFF);
        data[offset + 1] = (byte) ((length >> 8) & 0xFF);
        data[offset + 2] = (byte) ((length >> 16) & 0xFF);
        data[offset + 3] = (byte) ((length >> 24) & 0xFF);
    }

    static void writeInt(byte[] data, int offset, int value) {
        data[offset] = (byte) (value & 0xFF);
        data[offset + 1] = (byte) ((value >> 8) & 0xFF);
        data[offset + 2] = (byte) ((value >> 16) & 0xFF);
        data[offset + 3] = (byte) ((value >> 24) & 0xFF);
    }

    static class JsonParser {
        Scanner sc;

        JsonParser(String json) {
            sc = new Scanner(json).useDelimiter("\\A");
        }

        Object parse() {
            if (!sc.hasNext()) return null;
            String token = sc.next();
            if (token.equals("{")) {
                return parseObject();
            } else if (token.equals("[")) {
                return parseArray();
            } else if (token.equals("\"")) {
                return parseString();
            } else {
                return parseNumber();
            }
        }

        Object parseObject() {
            sc.next(); // skip {
            Map<String, Object> map = new HashMap<>();
            while (true) {
                String key = parseString();
                sc.next(); // skip :
                Object value = parse();
                map.put(key, value);
                String token = sc.next();
                if (token.equals("}")) {
                    break;
                } else if (token.equals(",")) {
                    continue;
                }
            }
            return map;
        }

        Object parseArray() {
            sc.next(); // skip [
            List<Object> list = new ArrayList<>();
            while (true) {
                Object value = parse();
                list.add(value);
                String token = sc.next();
                if (token.equals("]")) {
                    break;
                } else if (token.equals(",")) {
                    continue;
                }
            }
            return list;
        }

        String parseString() {
            sc.next(); // skip "
            StringBuilder sb = new StringBuilder();
            while (sc.hasNext()) {
                String token = sc.next();
                if (token.equals("\"")) {
                    break;
                }
                sb.append(token);
            }
            return sb.toString();
        }

        Integer parseNumber() {
            String token = sc.next();
            return Integer.parseInt(token);
        }
    }
}

use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::Write;
use std::path::Path;

#[derive(Debug, Clone)]
struct Line {
    bytes: Vec<u8>,
    has_newline: bool,
}

impl Line {
    fn from_bytes(bytes: &[u8]) -> Self {
        let has_newline = bytes.last() == Some(&b'\n');
        Line {
            bytes: bytes.to_vec(),
            has_newline,
        }
    }
}

impl PartialEq for Line {
    fn eq(&self, other: &Self) -> bool {
        self.bytes == other.bytes && self.has_newline == other.has_newline
    }
}

#[derive(Debug, Clone)]
struct Hunk {
    old_lines: Vec<Line>,
    new_lines: Vec<Line>,
    header: String,
}

#[derive(Debug, Clone)]
enum FileKind {
    Create,
    Modify,
    Delete,
}

fn parse_diff_content(content: &[u8]) -> Vec<(String, FileKind, Vec<Hunk>)> {
    let mut sections = Vec::new();
    let mut lines: Vec<u8> = Vec::new();
    let mut current_section: Option<(String, FileKind, Vec<Hunk>)> = None;
    let mut in_hunk = false;
    let mut hunk_start = 0;
    let mut hunk_header = String::new();
    let mut hunk_old_lines = Vec::new();
    let mut hunk_new_lines = Vec::new();
    let mut hunk_header_old_count = 0;
    let mut hunk_header_new_count = 0;
    let mut hunk_header_valid = false;

    let mut line_start = 0;

    for (i, &byte) in content.iter().enumerate() {
        if byte == b'\n' {
            let line = &content[line_start..i];
            line_start = i + 1;
            lines.push(byte);

            if let Some(ref mut section) = current_section {
                match String::from_utf8(line.to_vec()).ok() {
                    Some(l) if l.starts_with("diff --git ") => {
                        // Save current section
                        if let Some((path, kind, hunks)) = section.take() {
                            sections.push((path, kind, hunks));
                        }
                        let path = l[9..].trim();
                        let mut kind = FileKind::Modify;
                        let mut hunks = Vec::new();
                        let mut hunk = None;

                        for j in i + 1..content.len() {
                            if content[j] == b'\n' {
                                let next_line = &content[j + 1..];
                                if next_line.starts_with(b"@@ ") || next_line.starts_with(b"diff --git ") {
                                    break;
                                }
                                if next_line.starts_with(b"new file mode ") || next_line.starts_with(b"deleted file mode ") {
                                    kind = if next_line.starts_with(b"new") { FileKind::Create } else { FileKind::Delete };
                                } else if next_line.starts_with(b"index ") {
                                    // ignore
                                } else if next_line.starts_with(b"--- ") && !next_line.starts_with(b"--- /dev/null") {
                                    // ignore
                                } else if next_line.starts_with(b"+++ ") && !next_line.starts_with(b"+++ /dev/null") {
                                    // ignore
                                } else if next_line.starts_with(b"@@ ") {
                                    if let Some(prev_hunk) = hunk {
                                        hunks.push(prev_hunk);
                                    }
                                    let header = String::from_utf8(next_line.to_vec()).unwrap_or_default();
                                    let mut old_lines = Vec::new();
                                    let mut new_lines = Vec::new();
                                    let mut header_parsed = false;
                                    let mut header_old_count = 0;
                                    let mut header_new_count = 0;

                                    for k in j + 1..content.len() {
                                        if content[k] == b'\n' {
                                            let l = &content[k + 1..];
                                            if l.starts_with(b"@@ ") || l.starts_with(b"diff --git ") {
                                                break;
                                            }
                                            let line = String::from_utf8(l.to_vec()).unwrap_or_default();
                                            if line.is_empty() {
                                                continue;
                                            }
                                            let first = line.chars().next().unwrap();
                                            match first {
                                                ' ' => {
                                                    old_lines.push(Line::from_bytes(l));
                                                    new_lines.push(Line::from_bytes(l));
                                                }
                                                '-' => {
                                                    old_lines.push(Line::from_bytes(l));
                                                }
                                                '+' => {
                                                    new_lines.push(Line::from_bytes(l));
                                                }
                                                '\\' => {
                                                    // \ No newline at end of file
                                                    if l.len() > 1 && l[1..].starts_with(b" No newline at end of file") {
                                                        old_lines.push(Line::from_bytes(&l[1..]));
                                                        new_lines.push(Line::from_bytes(&l[1..]));
                                                    } else {
                                                        old_lines.push(Line::from_bytes(l));
                                                        new_lines.push(Line::from_bytes(l));
                                                    }
                                                }
                                                _ => {}
                                            }
                                        }
                                    }

                                    hunk = Some(Hunk {
                                        old_lines,
                                        new_lines,
                                        header,
                                    });
                                }
                            }
                        }

                        if let Some(h) = hunk {
                            hunks.push(h);
                        }

                        section = Some((path, kind, hunks));
                        current_section = section.clone();
                    }
                    _ => {}
                }
            }
        }
    }

    if let Some((path, kind, hunks)) = current_section.take() {
        sections.push((path, kind, hunks));
    }

    sections
}

fn calculate_crc32(data: &[u8]) -> u32 {
    const POLY: u32 = 0xEDB88320;
    let mut crc = 0xFFFFFFFF;

    for &byte in data {
        crc = ((crc << 8) ^ crc_table[(crc >> 24) as usize ^ (byte as usize)]) ^ 0xFFFFFFFF;
    }

    crc
}

fn crc_table() -> [u32; 256] {
    let mut table = [0u32; 256];
    for i in 0..256 {
        let mut crc = i as u32;
        for _ in 0..8 {
            if crc & 1 == 1 {
                crc = (crc >> 1) ^ POLY;
            } else {
                crc >>= 1;
            }
        }
        table[i as usize] = crc;
    }
    table
}

fn apply_hunk(content: &[u8], old_lines: &[Line], new_lines: &[Line], header: &str) -> (Vec<u8>, bool) {
    let header_str = String::from_utf8(header.to_vec()).unwrap_or_default();
    let header_parts: Vec<&str> = header_str.split_whitespace().collect();

    if header_parts.len() < 2 {
        return (content.to_vec(), false);
    }

    let header_old_count: usize = if header_parts[0].starts_with('-') {
        header_parts[0][1..].split(',').next().unwrap_or("1").parse().unwrap_or(1)
    } else {
        1
    };

    let header_new_count: usize = if header_parts[1].starts_with('+') {
        header_parts[1][1..].split(',').next().unwrap_or("1").parse().unwrap_or(1)
    } else {
        1
    };

    if old_lines.len() != header_old_count || new_lines.len() != header_new_count {
        return (content.to_vec(), false);
    }

    let current_content = String::from_utf8_lossy(content).to_string();
    let mut lines: Vec<Line> = Vec::new();
    let mut current = String::new();
    let mut has_newline = true;

    for (i, ch) in current.chars().enumerate() {
        if ch == '\n' {
            lines.push(Line {
                bytes: current.as_bytes().to_vec(),
                has_newline: true,
            });
            current = String::new();
            has_newline = true;
        } else {
            current.push(ch);
            has_newline = false;
        }
    }

    if !current.is_empty() {
        lines.push(Line {
            bytes: current.as_bytes().to_vec(),
            has_newline: has_newline,
        });
    }

    let line_count = lines.len();
    let mut delta = 0;
    let mut expected_p = 1 + delta;

    let mut found = false;
    let mut p = expected_p;

    loop {
        if p < 1 || p as usize + header_old_count > line_count {
            p += 1;
            continue;
        }

        let mut match_found = true;
        for i in 0..header_old_count {
            if lines[p as usize + i] != old_lines[i] {
                match_found = false;
                break;
            }
        }

        if match_found {
            found = true;
            break;
        }

        p += 1;
        if p > expected_p + 100 {
            break;
        }
    }

    if !found {
        return (content.to_vec(), false);
    }

    let mut result = String::new();
    for i in 0..p as usize {
        result.push_str(&lines[i].bytes);
    }

    for (i, line) in new_lines.iter().enumerate() {
        result.push_str(&line.bytes);
    }

    for i in (p + header_old_count)..line_count {
        result.push_str(&lines[i].bytes);
    }

    (result.into_bytes(), true)
}

fn apply_patch(path: &str, kind: FileKind, hunks: &[Hunk], tree_dir: &str) -> FilePatchResult {
    let file_path = Path::new(tree_dir).join(path);
    let mut content: Option<Vec<u8>> = None;

    match kind {
        FileKind::Create => {
            if file_path.exists() {
                return FilePatchResult::Error("already exists".to_string());
            }
            content = Some(Vec::new());
        }
        FileKind::Modify | FileKind::Delete => {
            if !file_path.exists() {
                return FilePatchResult::Error("not found".to_string());
            }
            content = Some(fs::read(&file_path).unwrap_or_default());
        }
    }

    let mut result_content = content.unwrap_or_default();
    let mut hunk_results = Vec::new();

    for (i, hunk) in hunks.iter().enumerate() {
        let header = &hunk.header;
        let old_lines = &hunk.old_lines;
        let new_lines = &hunk.new_lines;

        let (new_content, applied) = apply_hunk(&result_content, old_lines, new_lines, header);
        result_content = new_content;

        let offset = if applied {
            let old_count = old_lines.len();
            let new_count = new_lines.len();
            let delta = new_count - old_count;
            delta
        } else {
            0
        };

        let applied_at = if applied {
            let expected_p = 1 + offset;
            expected_p
        } else {
            0
        };

        hunk_results.push(HunkResult {
            index: i + 1,
            applied,
            applied_at,
            offset,
        });
    }

    let final_content = if kind == FileKind::Delete {
        String::from_utf8_lossy(&result_content).to_string()
    } else {
        String::from_utf8_lossy(&result_content).to_string()
    };

    if kind == FileKind::Delete && final_content.is_empty() {
        FilePatchResult::Deleted
    } else if kind == FileKind::Delete {
        FilePatchResult::Error("not found".to_string())
    } else {
        let crc = calculate_crc32(&result_content);
        FilePatchResult::Result(result_content, crc)
    }
}

#[derive(Debug)]
struct HunkResult {
    index: usize,
    applied: bool,
    applied_at: usize,
    offset: isize,
}

#[derive(Debug)]
enum FilePatchResult {
    Result(Vec<u8>, u32),
    Error(String),
    Deleted,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        return;
    }

    let diff_dir = &args[1];
    let tree_dir = "tree";

    let diff_path = Path::new(diff_dir).join("changes.diff");
    let diff_content = fs::read(&diff_path).unwrap_or_default();

    let sections = parse_diff_content(&diff_content);

    let mut results = Vec::new();

    for (path, kind, hunks) in &sections {
        let result = apply_patch(path, kind, &hunks, tree_dir);
        results.push((path.clone(), kind.clone(), hunks.clone(), result));
    }

    results.sort_by(|a, b| a.0.cmp(&b.0));

    for (path, kind, hunks, result) in &results {
        let path_str = path.as_str();
        let kind_str = match kind {
            FileKind::Create => "create",
            FileKind::Modify => "modify",
            FileKind::Delete => "delete",
        };

        println!("{}: {}", path_str, kind_str);

        let hunks_vec: Vec<&Hunk> = hunks.iter().collect();
        for hunk in hunks_vec.iter() {
            let hunk_result = &hunk;
            let applied = hunk_result.applied;
            let applied_at = hunk_result.applied_at;
            let offset = hunk_result.offset;

            if applied {
                println!("  hunk {}: applied at {} (offset {})", hunk.index, applied_at, format_offset(offset));
            } else {
                println!("  hunk {}: rejected", hunk.index);
            }
        }

        match result {
            FilePatchResult::Result(content, crc) => {
                let line_count = content.len() / 2;
                println!("  result: {} lines, crc32 {}", line_count, crc_to_hex(crc));
            }
            FilePatchResult::Error(msg) => {
                println!("  error: {}", msg);
            }
            FilePatchResult::Deleted => {
                println!("  result: deleted");
            }
        }
    }
}

fn format_offset(offset: isize) -> String {
    if offset > 0 {
        format!("+{}", offset)
    } else if offset < 0 {
        format!("{}", offset)
    } else {
        "0".to_string()
    }
}

fn crc_to_hex(crc: u32) -> String {
    format!("{:08x}", crc)
}

import { existsSync, readFileSync } from 'fs';

// Character class helpers
function isDigit(c: string): boolean {
  return c >= '0' && c <= '9';
}

function isAlpha(c: string): boolean {
  return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z');
}

function isWordChar(c: string): boolean {
  return isAlpha(c) || isDigit(c) || c === '_';
}

function isSpaceChar(c: string): boolean {
  return c === ' ' || c === '\t' || c === '\n' || c === '\r' || c === '\f' || c === '\v';
}

function isWhitespace(c: string): boolean {
  return isSpaceChar(c);
}

function isPrintable(c: string): boolean {
  return c >= ' ' && c <= '~';
}

// Escape sequence handler
function parseEscapeChar(c: string): string {
  if (c === 'd') return '\d';
  if (c === 'w') return '\w';
  if (c === 's') return '\s';
  if (c === 'D') return '\D';
  if (c === 'W') return '\W';
  if (c === 'S') return '\S';
  if (c === '\\') return '\\';
  if (c === '.') return '.';
  if (c === '*') return '*';
  if (c === '+') return '+';
  if (c === '?') return '?';
  if (c === '|') return '|';
  if (c === '^') return '^';
  if (c === '$') return '$';
  if (c === '[') return '[';
  if (c === ']') return ']';
  if (c === '(') return '(';
  if (c === ')') return ')';
  if (c === '{') return '{';
  if (c === '}') return '}';
  if (c === ']') return ']';
  return c;
}

function isClassChar(c: string): boolean {
  return isDigit(c) || isAlpha(c) || c === '_' || c === ' ' || c === '\t' || c === '\n' || c === '\r' || c === '\f' || c === '\v' || c === '\\';
}

// Parse a character class
function parseClass(content: string): { matches: (char: string) => boolean } {
  const negate = content[0] === '[';
  let i = 1;
  const matches: Set<string> = new Set();

  while (i < content.length) {
    const c = content[i];
    if (c === ']') {
      if (negate) matches.add(']');
      break;
    }
    if (c === '\\') {
      if (i + 1 < content.length) {
        const esc = content[i + 1];
        matches.add(esc);
        i += 2;
        continue;
      }
    }
    if (c === '-' && i + 2 < content.length && content[i + 2] !== ']') {
      const start = content[i];
      const end = content[i + 2];
      let startCode = start.charCodeAt(0);
      let endCode = end.charCodeAt(0);
      if (start === '\\') {
        startCode = 1; // placeholder
        endCode = 1;
      }
      if (end === '\\') {
        endCode = 1;
      }
      for (let code = startCode; code <= endCode; code++) {
        matches.add(String.fromCharCode(code));
      }
      i += 3;
      continue;
    }
    matches.add(c);
    i++;
  }

  const matchesChar = (char: string): boolean => {
    if (negate) return !matches.has(char);
    return matches.has(char);
  };

  return { matchesChar };
}

// Parse pattern into an AST
type ASTNode = { type: string; value?: any; children?: ASTNode[] };

function parsePattern(pattern: string): ASTNode[] {
  let pos = 0;

  function parseBranch(): ASTNode[] {
    const pieces: ASTNode[] = [];
    while (pos < pattern.length) {
      const c = pattern[pos];
      if (c === '|') break;
      if (c === '(') {
        const start = pos;
        let depth = 1;
        pos++;
        while (pos < pattern.length && depth > 0) {
          if (pattern[pos] === '(') depth++;
          else if (pattern[pos] === ')') depth--;
          pos++;
        }
        const group = pattern.substring(start, pos);
        const child = parseBranch();
        pieces.push({ type: 'group', children: child });
        if (group[0] === '(' && group[group.length - 1] === ')') {
          // capturing group
        } else if (group[0] === '(?' && group[group.length - 2] === ')') {
          // non-capturing group
        }
      } else if (c === '.') {
        pieces.push({ type: 'literal', value: '.' });
        pos++;
      } else if (c === '^') {
        pieces.push({ type: 'anchor', value: '^' });
        pos++;
      } else if (c === '$') {
        pieces.push({ type: 'anchor', value: '$' });
        pos++;
      } else if (c === '[') {
        const end = pattern.indexOf(']', pos);
        if (end === -1) break;
        const classContent = pattern.substring(pos + 1, end);
        pieces.push({ type: 'class', value: parseClass(classContent) });
        pos = end + 1;
      } else if (c === '\\') {
        if (pos + 1 < pattern.length) {
          const esc = pattern[pos + 1];
          pieces.push({ type: 'literal', value: parseEscapeChar(esc) });
          pos += 2;
        } else {
          pieces.push({ type: 'literal', value: c });
          pos++;
        }
      } else {
        pieces.push({ type: 'literal', value: c });
        pos++;
      }
    }
    return pieces;
  }

  function parsePiece(): ASTNode | null {
    const c = pattern[pos];
    if (c === '(') {
      const start = pos;
      let depth = 1;
      pos++;
      while (pos < pattern.length && depth > 0) {
        if (pattern[pos] === '(') depth++;
        else if (pattern[pos] === ')') depth--;
        pos++;
      }
      const group = pattern.substring(start, pos);
      const child = parseBranch();
      return { type: 'group', children: child };
    } else if (c === '.') {
      pos++;
      return { type: 'literal', value: '.' };
    } else if (c === '^') {
      pos++;
      return { type: 'anchor', value: '^' };
    } else if (c === '$') {
      pos++;
      return { type: 'anchor', value: '$' };
    } else if (c === '[') {
      const end = pattern.indexOf(']', pos);
      if (end === -1) return null;
      const classContent = pattern.substring(pos + 1, end);
      pos = end + 1;
      return { type: 'class', value: parseClass(classContent) };
    } else if (c === '\\') {
      if (pos + 1 < pattern.length) {
        const esc = pattern[pos + 1];
        pos += 2;
        return { type: 'literal', value: parseEscapeChar(esc) };
      }
      pos++;
      return { type: 'literal', value: c };
    } else {
      pos++;
      return { type: 'literal', value: c };
    }
  }

  const pieces: ASTNode[] = [];
  while (pos < pattern.length) {
    const c = pattern[pos];
    if (c === '(') {
      const start = pos;
      let depth = 1;
      pos++;
      while (pos < pattern.length && depth > 0) {
        if (pattern[pos] === '(') depth++;
        else if (pattern[pos] === ')') depth--;
        pos++;
      }
      const group = pattern.substring(start, pos);
      const child = parseBranch();
      pieces.push({ type: 'group', children: child });
    } else if (c === '|') {
      break;
    } else {
      const piece = parsePiece();
      if (piece) {
        pieces.push(piece);
      }
    }
  }

  return pieces;
}

// Match AST against subject
type State = {
  pos: number;
  groups: Map<number, [number, number]>;
};

function matchAST(ast: ASTNode[], subject: string): { match: boolean; span: [number, number]; groups: Map<number, [number, number]> } | null {
  const memo = new Map<string, { match: boolean; span: [number, number]; groups: Map<number, [number, number]> } | null>();
  const key = (pos: number): string => pos.toString();

  function tryMatch(node: ASTNode, pos: number, groups: Map<number, [number, number]>): { match: boolean; span: [number, number]; groups: Map<number, [number, number]> } | null {
    const cacheKey = `${node.type}:${pos}`;
    if (memo.has(cacheKey)) return memo.get(cacheKey);

    if (node.type === 'anchor' && node.value === '^') {
      if (pos === 0) {
        const result = tryMatch(node.children?.[0] || { type: 'branch' }, pos, groups);
        if (result && result.match) {
          memo.set(cacheKey, result);
          return result;
        }
      }
      return null;
    }

    if (node.type === 'anchor' && node.value === '$') {
      if (pos === subject.length) {
        const result = tryMatch(node.children?.[0] || { type: 'branch' }, pos, groups);
        if (result && result.match) {
          memo.set(cacheKey, result);
          return result;
        }
      }
      return null;
    }

    if (node.type === 'literal' && node.value) {
      if (pos < subject.length && subject[pos] === node.value) {
        const newGroups = new Map(groups);
        const result = tryMatch(node.children?.[0] || { type: 'branch' }, pos + 1, newGroups);
        if (result && result.match) {
          memo.set(cacheKey, result);
          return result;
        }
      }
      return null;
    }

    if (node.type === 'class' && node.value?.matchesChar) {
      if (pos < subject.length && node.value.matchesChar(subject[pos])) {
        const newGroups = new Map(groups);
        const result = tryMatch(node.children?.[0] || { type: 'branch' }, pos + 1, newGroups);
        if (result && result.match) {
          memo.set(cacheKey, result);
          return result;
        }
      }
      return null;
    }

    if (node.type === 'group') {
      const child = node.children?.[0];
      if (child) {
        const newGroups = new Map(groups);
        const result = tryMatch(child, pos, newGroups);
        if (result && result.match) {
          memo.set(cacheKey, result);
          return result;
        }
      }
      return null;
    }

    if (node.type === 'branch') {
      for (const piece of node.children || []) {
        const newGroups = new Map(groups);
        const result = tryMatch(piece, pos, newGroups);
        if (result && result.match) {
          memo.set(cacheKey, result);
          return result;
        }
      }
      return null;
    }

    if (node.type === 'quantifier' || node.type === 'piece') {
      if (node.children) {
        const child = node.children[0];
        if (child) {
          const newGroups = new Map(groups);
          const result = tryMatch(child, pos, newGroups);
          if (result && result.match) {
            memo.set(cacheKey, result);
            return result;
          }
        }
      }
      return null;
    }

    memo.set(cacheKey, null);
    return null;
  }

  for (let pos = 0; pos <= subject.length; pos++) {
    const groups = new Map();
    const result = tryMatch(ast[0], pos, groups);
    if (result && result.match) {
      return { match: true, span: [pos, result.span[1]], groups: groups };
    }
  }

  return null;
}

function main() {
  const args = process.argv.slice(2);
  if (args.length < 1) {
    console.error('Usage: main.ts <directory>');
    process.exit(1);
  }

  const dir = args[0];
  const casesFile = `${dir}/cases.txt`;

  if (!existsSync(casesFile)) {
    console.error(`File not found: ${casesFile}`);
    process.exit(1);
  }

  const content = readFileSync(casesFile, 'utf8');
  const lines = content.split('\n');

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line === '') break;

    const tabIdx = line.indexOf('\t');
    if (tabIdx === -1) continue;

    const pattern = line.substring(0, tabIdx);
    const subject = line.substring(tabIdx + 1);

    const ast = parsePattern(pattern);
    const result = matchAST(ast, subject);

    if (result && result.match) {
      const groups: (string | '-').[] = [];
      groups.push(`${result.span[0]}-${result.span[1]}`);
      for (const [key, value] of result.groups) {
        groups.push(`${value[0]}-${value[1]}`);
      }
      console.log(`${i + 1}: ${groups.join(' ')}`);
    } else {
      console.log(`${i + 1}: no match`);
    }
  }
}

main();

#!/usr/bin/env python3
"""
Regular Expression Search Engine
Implements regex matching with capturing groups using an NFA-based approach with epsilon transitions.
"""

import sys
from typing import List, Tuple, Optional, Dict, Set, Any


class NFAState:
    """Represents a state in the NFA with epsilon transitions and character transitions."""
    def __init__(self, label: str = ""):
        self.label = label  # Character or epsilon
        self.epsilon: List['NFAState'] = []
        self.char_transitions: List['NFAState'] = []
        self.is_accepting = False


class RegexNode:
    """Abstract syntax tree node for regex patterns."""
    pass


class LiteralNode(RegexNode):
    def __init__(self, char: str):
        self.char = char


class DotNode(RegexNode):
    pass


class AnchorNode(RegexNode):
    def __init__(self, anchor: str):
        self.anchor = anchor  # '^' or '$'


class ClassNode(RegexNode):
    def __init__(self, negated: bool, items: List[Any]):
        self.negated = negated
        self.items = items  # List of (char, is_escaped)


class EscapeNode(RegexNode):
    def __init__(self, escape_type: str, char: Optional[str] = None):
        self.escape_type = escape_type  # 'd', 'w', 's', 'D', 'W', 'S'
        self.char = char  # For literal escape like \.


class GroupNode(RegexNode):
    def __init__(self, capturing: bool, content: RegexNode):
        self.capturing = capturing
        self.content = content


class QuantifierNode(RegexNode):
    def __init__(self, content: RegexNode, min_count: int, max_count: Optional[int], lazy: bool):
        self.content = content
        self.min_count = min_count
        self.max_count = max_count  # None means unbounded
        self.lazy = lazy


class AltNode(RegexNode):
    def __init__(self, branches: List[RegexNode]):
        self.branches = branches


def parse_regex(pattern: str) -> RegexNode:
    """Parse a regex pattern string into an AST."""
    pos = 0
    n = len(pattern)

    def peek() -> Optional[str]:
        if pos < n:
            return pattern[pos]
        return None

    def consume() -> Optional[str]:
        nonlocal pos
        if pos < n:
            ch = pattern[pos]
            pos += 1
            return ch
        return None

    def match_char(expected: str) -> bool:
        ch = consume()
        return ch == expected

    def parse_quantifier() -> Optional[QuantifierNode]:
        """Parse a quantifier after an atom."""
        ch = peek()
        if ch not in '*+?{':
            return None

        content = consume()
        if content == '*':
            return QuantifierNode(content, 0, 0, False)
        elif content == '+':
            return QuantifierNode(content, 1, 0, False)
        elif content == '?':
            return QuantifierNode(content, 0, 1, False)
        elif content == '{':
            # Parse {m}, {m,}, {m,n}
            start = pos
            while pos < n and pattern[pos] not in '},':
                pos += 1
            if pos >= n:
                raise ValueError(f"Unterminated quantifier at position {start}")
            s = pattern[start:pos]
            pos += 1  # Skip }
            parts = s.split(',')
            min_count = int(parts[0])
            max_count = None
            if len(parts) == 2:
                if parts[1] == '':
                    max_count = None
                else:
                    max_count = int(parts[1])
            return QuantifierNode(content, min_count, max_count, False)
        return None

    def parse_class() -> ClassNode:
        """Parse a character class [..] or [^..]."""
        pos += 1  # Skip [
        negated = pattern[pos - 1] == '['
        if negated:
            pos += 1  # Skip ^
        items = []
        while pos < n and pattern[pos] != ']':
            ch = consume()
            if ch == '\\' and pos < n:
                next_ch = consume()
                if next_ch == 'd':
                    items.append(('d', False))
                elif next_ch == 'w':
                    items.append(('w', False))
                elif next_ch == 's':
                    items.append(('s', False))
                elif next_ch == 'D':
                    items.append(('D', False))
                elif next_ch == 'W':
                    items.append(('W', False))
                elif next_ch == 'S':
                    items.append(('S', False))
                elif next_ch == ']:
                    items.append((']', True))
                elif next_ch == '[':
                    items.append(('[', True))
                elif next_ch == '-':
                    items.append(('-', True))
                else:
                    items.append((next_ch, True))
            elif ch == '-' and pos < n and pattern[pos] != ']':
                next_ch = consume()
                items.append((next_ch, False))
            else:
                items.append((ch, False))
        if pos < n and pattern[pos] == ']':
            pos += 1
        return ClassNode(negated, items)

    def parse_escape() -> EscapeNode:
        """Parse an escape sequence."""
        ch = consume()
        if ch != '\\':
            return EscapeNode('literal', ch)
        next_ch = consume()
        if not next_ch:
            return EscapeNode('literal', ch)
        if next_ch in 'dwsDW':
            return EscapeNode(next_ch, None)
        elif next_ch == 'D' or next_ch == 'W' or next_ch == 'S':
            return EscapeNode(next_ch, None)
        else:
            return EscapeNode('literal', next_ch)

    def parse_literal() -> RegexNode:
        """Parse a literal character (not special)."""
        ch = consume()
        if ch is None or ch in '.^$*+?|(){}[]\\':
            raise ValueError(f"Unexpected character at position {pos}: {ch}")
        return LiteralNode(ch)

    def parse_atom() -> RegexNode:
        """Parse an atom (group, literal, special, class, escape)."""
        ch = peek()
        if ch == '(':
            pos += 1  # Skip (
            if peek() == '?':
                pos += 1  # Skip ?
                if peek() == '(':
                    pos += 1  # Skip (
                    # Non-capturing group
                    content = parse_branch()
                    if not match_char(')'):
                        raise ValueError("Missing closing )")
                    return GroupNode(False, content)
            content = parse_branch()
            if not match_char(')'):
                raise ValueError("Missing closing )")
            return GroupNode(True, content)
        elif ch == '.':
            pos += 1
            return DotNode()
        elif ch == '^':
            pos += 1
            return AnchorNode('^')
        elif ch == '$':
            pos += 1
            return AnchorNode('$')
        elif ch == '[':
            return parse_class()
        elif ch == '\\':
            return parse_escape()
        else:
            return parse_literal()

    def parse_branch() -> RegexNode:
        """Parse a branch (sequence of pieces)."""
        pieces = []
        while peek() and peek() not in '|)':
            pieces.append(parse_piece())
        if not pieces:
            return AltNode([])
        return AltNode(pieces)

    def parse_piece() -> RegexNode:
        """Parse a piece (atom + optional quantifier)."""
        atom = parse_atom()
        quantifier = parse_quantifier()
        if quantifier:
            return QuantifierNode(atom, quantifier.min_count, quantifier.max_count, quantifier.lazy)
        return atom

    def parse_alternation() -> RegexNode:
        """Parse alternation (branch | branch | ...)."""
        branches = []
        while peek() and peek() != ')':
            branches.append(parse_branch())
            if peek() == '|':
                pos += 1
        if not branches:
            return AltNode([])
        return AltNode(branches)

    def parse_anchored() -> RegexNode:
        """Parse anchored pattern (with ^ or $)."""
        if peek() == '^':
            pos += 1
            return AnchorNode('^')
        elif peek() == '$':
            pos += 1
            return AnchorNode('$')
        return None

    # Main parsing
    content = parse_alternation()
    return content


class RegexMatcher:
    """NFA-based regex matcher with capturing group tracking."""

    def __init__(self, pattern: RegexNode):
        self.pattern = pattern
        self.groups: List[Optional[Tuple[int, int]]] = []

    def reset(self):
        self.groups = []

    def match(self, subject: str) -> Optional[Tuple[int, int, List[Tuple[int, int]]]]:
        """
        Match the pattern against the subject.
        Returns (start, end, captures) or None if no match.
        """
        n = len(subject)
        # For small inputs, we can use a backtracking approach with memoization
        # to avoid exponential time on pathological cases.
        return self._match_at(0, 0, subject, n)

    def _match_at(self, pos: int, group_idx: int, subject: str, n: int) -> Optional[Tuple[int, int, List[Tuple[int, int]]]]:
        """
        Try to match starting at position pos.
        Returns (start, end, captures) or None.
        """
        if group_idx >= len(self.groups):
            self.groups.append(None)

        # Try each branch in priority order
        branches = self.pattern.branches if isinstance(self.pattern, AltNode) else [self.pattern]

        for branch in branches:
            result = self._match_branch(branch, pos, 0, subject, n)
            if result:
                return result

        return None

    def _match_branch(self, node: RegexNode, pos: int, group_idx: int, subject: str, n: int) -> Optional[Tuple[int, int, List[Tuple[int, int]]]]:
        """Match a branch (sequence of pieces) starting at position pos."""
        if not isinstance(node, AltNode):
            # Single piece
            pieces = [node]
        else:
            pieces = node.branches

        # Try each piece in order
        for piece in pieces:
            result = self._match_piece(piece, pos, group_idx, subject, n)
            if result:
                return result

        return None

    def _match_piece(self, node: RegexNode, pos: int, group_idx: int, subject: str, n: int) -> Optional[Tuple[int, int, List[Tuple[int, int]]]]:
        """Match a single piece (atom + optional quantifier)."""
        if isinstance(node, QuantifierNode):
            return self._match_quantifier(node, pos, group_idx, subject, n)
        else:
            return self._match_atom(node, pos, group_idx, subject, n)

    def _match_atom(self, node: RegexNode, pos: int, group_idx: int, subject: str, n: int) -> Optional[Tuple[int, int, List[Tuple[int, int]]]]:
        """Match an atom."""
        if isinstance(node, LiteralNode):
            if pos < n and subject[pos] == node.char:
                return (pos, pos + 1, self._capture(node, pos, pos + 1))
            return None
        elif isinstance(node, DotNode):
            if pos < n:
                return (pos, pos + 1, self._capture(node, pos, pos + 1))
            return None
        elif isinstance(node, AnchorNode):
            if node.anchor == '^' and pos == 0:
                return (pos, pos, self._capture(node, pos, pos))
            elif node.anchor == '$' and pos == n:
                return (pos, pos, self._capture(node, pos, pos))
            return None
        elif isinstance(node, ClassNode):
            if pos < n:
                ch = subject[pos]
                if self._class_matches(node, ch):
                    return (pos, pos + 1, self._capture(node, pos, pos + 1))
            return None
        elif isinstance(node, EscapeNode):
            if isinstance(node.escape_type, str) and node.escape_type in 'dwsDW':
                if self._escape_matches(node.escape_type, subject[pos] if pos < n else None):
                    return (pos, pos + 1, self._capture(node, pos, pos + 1))
                return None
            else:
                # Literal escape
                if pos < n and subject[pos] == node.char if node.char else True:
                    return (pos, pos + 1, self._capture(node, pos, pos + 1))
                return None
        elif isinstance(node, GroupNode):
            # For capturing groups, we need to track them
            return self._match_group(node, pos, group_idx, subject, n)
        else:
            raise ValueError(f"Unknown node type: {type(node)}")

    def _class_matches(self, node: ClassNode, ch: str) -> bool:
        """Check if a character matches a class."""
        for item in node.items:
            item_type, item_char = item
            if item_type == 'd':
                if ch.isdigit():
                    return True
            elif item_type == 'w':
                if ch.isalnum() or ch == '_':
                    return True
            elif item_type == 's':
                if ch in ' \t\n\r\f\v':
                    return True
            elif item_type == 'D':
                if not ch.isdigit():
                    return True
            elif item_type == 'W':
                if not (ch.isalnum() or ch == '_'):
                    return True
            elif item_type == 'S':
                if not ch in ' \t\n\r\f\v':
                    return True
            elif item_type == 'literal':
                if item_char and ch == item_char:
                    return True
        return not node.negated

    def _escape_matches(self, escape_type: str, ch: Optional[str]) -> bool:
        """Check if a character matches an escape."""
        if escape_type == 'd':
            return ch is not None and ch.isdigit()
        elif escape_type == 'w':
            return ch is not None and (ch.isalnum() or ch == '_')
        elif escape_type == 's':
            return ch is not None and ch in ' \t\n\r\f\v'
        elif escape_type == 'D':
            return ch is not None and not ch.isdigit()
        elif escape_type == 'W':
            return ch is not None and not (ch.isalnum() or ch == '_')
        elif escape_type == 'S':
            return ch is not None and not ch in ' \t\n\r\f\v'
        return False

    def _capture(self, node: RegexNode, start: int, end: int) -> List[Tuple[int, int]]:
        """Record a capture for a group."""
        return [(start, end)]

    def _match_group(self, node: GroupNode, pos: int, group_idx: int, subject: str, n: int) -> Optional[Tuple[int, int, List[Tuple[int, int]]]]:
        """Match a capturing or non-capturing group."""
        self.groups[group_idx] = None
        result = self._match_alternation(node.content, pos, group_idx + 1, subject, n)
        if result:
            return result
        return None

    def _match_alternation(self, node: RegexNode, pos: int, group_idx: int, subject: str, n: int) -> Optional[Tuple[int, int, List[Tuple[int, int]]]]:
        """Match an alternation (branch | branch | ...)."""
        branches = node.branches if isinstance(node, AltNode) else [node]

        for branch in branches:
            result = self._match_branch(branch, pos, group_idx, subject, n)
            if result:
                return result

        return None

    def _match_quantifier(self, node: QuantifierNode, pos: int, group_idx: int, subject: str, n: int) -> Optional[Tuple[int, int, List[Tuple[int, int]]]]:
        """Match a quantified piece with backtracking."""
        content = node.content
        min_count = node.min_count
        max_count = node.max_count
        lazy = node.lazy

        # For greedy vs lazy matching
        greedy = not lazy

        # Try matching 0 to max_count times
        # For greedy: try max first, then backtrack
        # For lazy: try 0 first, then increment

        # We need to track captures for the group
        self.groups[group_idx] = None

        # Try different counts
        for count in range(min_count, max_count + 1 if max_count else min_count + 1):
            if greedy and count < max_count if max_count else True:
                # Greedy: try larger count first
                continue

            # Try matching 'count' times
            matched = True
            start_pos = pos
            last_match_start = None
            last_match_end = None

            for i in range(count):
                result = self._match_atom(content, pos, group_idx, subject, n)
                if result is None:
                    matched = False
                    break
                start, end, captures = result
                if i == count - 1:
                    last_match_start = start
                    last_match_end = end
                pos = end

            if matched:
                # Check if we can continue with more iterations (for greedy)
                if greedy and count < max_count if max_count else True:
                    # Try one more iteration
                    continue

                # Record the capture
                if last_match_start is not None:
                    self.groups[group_idx] = (last_match_start, last_match_end)
                return (start_pos, pos, self._capture(node, start_pos, pos))

        return None


def format_result(test_num: int, match: Optional[Tuple[int, int, List[Tuple[int, int]]]]) -> str:
    """Format the match result according to the specification."""
    if match is None:
        return f"{test_num}: no match"

    start, end, captures = match
    capture_strs = []
    for cap in captures:
        if cap is None:
            capture_strs.append("-")
        else:
            capture_strs.append(f"{cap[0]}-{cap[1]}")

    return f"{test_num}: {start}-{end} " + " ".join(capture_strs)


def main():
    if len(sys.argv) != 2:
        print("Usage: python3 main.py <directory>", file=sys.stderr)
        sys.exit(1)

    try:
        with open(sys.argv[1] + "/cases.txt", "r", encoding="utf-8") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print(f"Error: {sys.argv[1]}/cases.txt not found", file=sys.stderr)
        sys.exit(1)

    for i, line in enumerate(lines):
        line = line.rstrip('\n')
        if not line:
