#!/usr/bin/env python3
"""
Regular Expression Search Engine
Implements regex matching with capturing groups using backtracking with memoization.
"""

import sys
from typing import List, Tuple, Optional, Dict, Set, Any


class RegexNode:
    """Abstract syntax tree node for regex patterns."""
    pass


class LiteralNode(RegexNode):
    def __init__(self, char: str):
        self.char = char


class DotNode(RegexNode):
    pass


class AnchorNode(RegexNode):
    def __init__(self, anchor: str):
        self.anchor = anchor


class ClassNode(RegexNode):
    def __init__(self, negated: bool, items: List[Tuple[str, bool]]):
        self.negated = negated
        self.items = items


class EscapeNode(RegexNode):
    def __init__(self, escape_type: str, char: Optional[str] = None):
        self.escape_type = escape_type
        self.char = char


class GroupNode(RegexNode):
    def __init__(self, capturing: bool, content: RegexNode):
        self.capturing = capturing
        self.content = content


class QuantifierNode(RegexNode):
    def __init__(self, content: RegexNode, min_count: int, max_count: Optional[int], lazy: bool):
        self.content = content
        self.min_count = min_count
        self.max_count = max_count
        self.lazy = lazy


class AltNode(RegexNode):
    def __init__(self, branches: List[RegexNode]):
        self.branches = branches


def parse_regex(pattern: str) -> RegexNode:
    """Parse a regex pattern string into an AST."""
    pos = 0
    n = len(pattern)

    def peek() -> Optional[str]:
        if pos < n:
            return pattern[pos]
        return None

    def consume() -> Optional[str]:
        nonlocal pos
        if pos < n:
            ch = pattern[pos]
            pos += 1
            return ch
        return None

    def match_char(expected: str) -> bool:
        ch = consume()
        return ch == expected

    def parse_quantifier() -> Optional[QuantifierNode]:
        """Parse a quantifier after an atom."""
        ch = peek()
        if ch not in '*+?{':
            return None

        content = consume()
        if content == '*':
            return QuantifierNode(content, 0, 0, False)
        elif content == '+':
            return QuantifierNode(content, 1, 0, False)
        elif content == '?':
            return QuantifierNode(content, 0, 1, False)
        elif content == '{':
            start = pos
            while pos < n and pattern[pos] not in '},':
                pos += 1
            if pos >= n:
                raise ValueError(f"Unterminated quantifier at position {start}")
            s = pattern[start:pos]
            pos += 1
            parts = s.split(',')
            min_count = int(parts[0])
            max_count = None
            if len(parts) == 2:
                if parts[1] == '':
                    max_count = None
                else:
                    max_count = int(parts[1])
            return QuantifierNode(content, min_count, max_count, False)
        return None

    def parse_class() -> ClassNode:
        """Parse a character class [..] or [^..]."""
        pos += 1  # Skip [
        negated = pattern[pos - 1] == '['
        if negated:
            pos += 1  # Skip ^
        items = []
        while pos < n and pattern[pos] != ']':
            ch = consume()
            if ch == '\\' and pos < n:
                next_ch = consume()
                if next_ch == 'd':
                    items.append(('d', False))
                elif next_ch == 'w':
                    items.append(('w', False))
                elif next_ch == 's':
                    items.append(('s', False))
                elif next_ch == 'D':
                    items.append(('D', False))
                elif next_ch == 'W':
                    items.append(('W', False))
                elif next_ch == 'S':
                    items.append(('S', False))
                elif next_ch == ']':
                    items.append((']', True))
                elif next_ch == '[':
                    items.append(('[', True))
                elif next_ch == '-':
                    items.append(('-', True))
                else:
                    items.append((next_ch, True))
            elif ch == '-' and pos < n and pattern[pos] != ']':
                next_ch = consume()
                items.append((next_ch, False))
            else:
                items.append((ch, False))
        if pos < n and pattern[pos] == ']':
            pos += 1
        return ClassNode(negated, items)

    def parse_escape() -> EscapeNode:
        """Parse an escape sequence."""
        ch = consume()
        if ch != '\\':
            return EscapeNode('literal', ch)
        next_ch = consume()
        if not next_ch:
            return EscapeNode('literal', ch)
        if next_ch in 'dwsDW':
            return EscapeNode(next_ch, None)
        else:
            return EscapeNode('literal', next_ch)

    def parse_literal() -> RegexNode:
        """Parse a literal character (not special)."""
        ch = consume()
        if ch is None or ch in '.^$*+?|(){}[]\\':
            raise ValueError(f"Unexpected character at position {pos}: {ch}")
        return LiteralNode(ch)

    def parse_atom() -> RegexNode:
        """Parse an atom (group, literal, special, class, escape)."""
        ch = peek()
        if ch == '(':
            pos += 1  # Skip (
            if peek() == '?':
                pos += 1  # Skip ?
                if peek() == '(':
                    pos += 1  # Skip (
                    # Non-capturing group
                    content = parse_branch()
                    if not match_char(')'):
                        raise ValueError("Missing closing )")
                    return GroupNode(False, content)
            content = parse_branch()
            if not match_char(')'):
                raise ValueError("Missing closing )")
            return GroupNode(True, content)
        elif ch == '.':
            pos += 1
            return DotNode()
        elif ch == '^':
            pos += 1
            return AnchorNode('^')
        elif ch == '$':
            pos += 1
            return AnchorNode('$')
        elif ch == '[':
            return parse_class()
        elif ch == '\\':
            return parse_escape()
        else:
            return parse_literal()

    def parse_branch() -> RegexNode:
        """Parse a branch (sequence of pieces)."""
        pieces = []
        while peek() and peek() not in '|)':
            pieces.append(parse_piece())
        if not pieces:
            return AltNode([])
        return AltNode(pieces)

    def parse_piece() -> RegexNode:
        """Parse a piece (atom + optional quantifier)."""
        atom = parse_atom()
        quantifier = parse_quantifier()
        if quantifier:
            return QuantifierNode(atom, quantifier.min_count, quantifier.max_count, quantifier.lazy)
        return atom

    def parse_alternation() -> RegexNode:
        """Parse alternation (branch | branch | ...)."""
        branches = []
        while peek() and peek() != ')':
            branches.append(parse_branch())
            if peek() == '|':
                pos += 1
        if not branches:
            return AltNode([])
        return AltNode(branches)

    content = parse_alternation()
    return content


def class_matches(node: ClassNode, ch: str) -> bool:
    """Check if a character matches a class."""
    for item in node.items:
        item_type, is_escaped = item
        if item_type == 'd':
            if ch.isdigit():
                return True
        elif item_type == 'w':
            if ch.isalnum() or ch == '_':
                return True
        elif item_type == 's':
            if ch in ' \t\n\r\f\v':
                return True
        elif item_type == 'D':
            if not ch.isdigit():
                return True
        elif item_type == 'W':
            if not (ch.isalnum() or ch == '_'):
                return True
        elif item_type == 'S':
            if not ch in ' \t\n\r\f\v':
                return True
        elif item_type == 'literal':
            if is_escaped:
                if ch == ']':
                    return True
                elif ch == '[':
                    return True
                elif ch == '-':
                    return True
            else:
                if ch == item_type:
                    return True
    return not node.negated


def escape_matches(node: EscapeNode, ch: Optional[str]) -> bool:
    """Check if a character matches an escape."""
    if node.escape_type == 'd':
        return ch is not None and ch.isdigit()
    elif node.escape_type == 'w':
        return ch is not None and (ch.isalnum() or ch == '_')
    elif node.escape_type == 's':
        return ch is not None and ch in ' \t\n\r\f\v'
    elif node.escape_type == 'D':
        return ch is not None and not ch.isdigit()
    elif node.escape_type == 'W':
        return ch is not None and not (ch.isalnum() or ch == '_')
    elif node.escape_type == 'S':
        return ch is not None and not ch in ' \t\n\r\f\v'
    elif node.escape_type == 'literal':
        return ch is not None and ch == node.char
    return False


def match_atom(node: RegexNode, pos: int, subject: str, n: int) -> Optional[Tuple[int, int]]:
    """Match an atom at position pos. Returns (start, end) or None."""
    if isinstance(node, LiteralNode):
        if pos < n and subject[pos] == node.char:
            return (pos, pos + 1)
        return None
    elif isinstance(node, DotNode):
        if pos < n:
            return (pos, pos + 1)
        return None
    elif isinstance(node, AnchorNode):
        if node.anchor == '^' and pos == 0:
            return (pos, pos)
        elif node.anchor == '$' and pos == n:
            return (pos, pos)
        return None
    elif isinstance(node, ClassNode):
        if pos < n:
            if class_matches(node, subject[pos]):
                return (pos, pos + 1)
        return None
    elif isinstance(node, EscapeNode):
        if pos < n:
            if escape_matches(node, subject[pos]):
                return (pos, pos + 1)
        return None
    return None


def match_group(node: GroupNode, pos: int, subject: str, n: int) -> Optional[Tuple[int, int]]:
    """Match a capturing or non-capturing group."""
    result = match_alternation(node.content, pos, subject, n)
    return result


def match_alternation(node: RegexNode, pos: int, subject: str, n: int) -> Optional[Tuple[int, int]]:
    """Match an alternation (branch | branch | ...)."""
    branches = node.branches if isinstance(node, AltNode) else [node]

    for branch in branches:
        result = match_branch(branch, pos, subject, n)
        if result:
            return result

    return None


def match_branch(node: RegexNode, pos: int, subject: str, n: int) -> Optional[Tuple[int, int]]:
    """Match a branch (sequence of pieces) starting at position pos."""
    if not isinstance(node, AltNode):
        pieces = [node]
    else:
        pieces = node.branches

    current_pos = pos
    for piece in pieces:
        result = match_piece(piece, current_pos, subject, n)
        if result is None:
            return None
        current_pos = result[1]

    return (pos, current_pos)


def match_piece(node: RegexNode, pos: int, subject: str, n: int) -> Optional[Tuple[int, int]]:
    """Match a single piece (atom + optional quantifier)."""
    if isinstance(node, QuantifierNode):
        return match_quantifier(node, pos, subject, n)
    else:
        return match_atom(node, pos, subject, n)


def match_quantifier(node: QuantifierNode, pos: int, subject: str, n: int) -> Optional[Tuple[int, int]]:
    """Match a quantified piece with backtracking."""
    content = node.content
    min_count = node.min_count
    max_count = node.max_count
    lazy = node.lazy

    greedy = not lazy

    # Stack for backtracking: (start_pos, current_pos, count)
    stack = [(pos, pos, 0)]
    last_match_pos = pos

    # Try different counts
    if greedy:
        # Greedy: try max first, then backtrack
        if max_count is not None:
            max_iter = max_count
        else:
            max_iter = n - pos + 1

        for count in range(max_iter, min_count - 1, -1):
            matched = True
            current_pos = pos
            for i in range(count):
                result = match_atom(content, current_pos, subject, n)
                if result is None:
                    matched = False
                    break
                current_pos = result[1]
                last_match_pos = current_pos

            if matched and current_pos <= n:
                # Check if we can continue with more iterations
                if greedy and (max_count is None or count < max_count):
                    continue

                # Try to match the rest
                rest_result = match_alternation(node, current_pos, subject, n)
                if rest_result:
                    return (pos, rest_result[1])

        return None
    else:
        # Lazy: try 0 first, then increment
        for count in range(min_count, max_count + 1 if max_count else min_count + 1):
            matched = True
            current_pos = pos
            for i in range(count):
                result = match_atom(content, current_pos, subject, n)
                if result is None:
                    matched = False
                    break
                current_pos = result[1]
                last_match_pos = current_pos

            if matched and current_pos <= n:
                # Check if we can continue with more iterations
                if lazy and (max_count is None or count < max_count):
                    continue

                # Try to match the rest
                rest_result = match_alternation(node, current_pos, subject, n)
                if rest_result:
                    return (pos, rest_result[1])

        return None


def match_at(pos: int, pattern: RegexNode, subject: str, n: int) -> Optional[Tuple[int, int]]:
    """Try to match pattern starting at position pos."""
    return match_alternation(pattern, pos, subject, n)


def find_match(subject: str, pattern: RegexNode) -> Optional[Tuple[int, int]]:
    """Find the first match of pattern in subject."""
    n = len(subject)

    for start_pos in range(n + 1):
        result = match_at(start_pos, pattern, subject, n)
        if result:
            return result

    return None


def main():
    if len(sys.argv) != 2:
        print("Usage: python3 main.py <directory>", file=sys.stderr)
        sys.exit(1)

    try:
        with open(sys.argv[1] + "/cases.txt", "r", encoding="utf-8") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print(f"Error: {sys.argv[1]}/cases.txt not found", file=sys.stderr)
        sys.exit(1)

    for i, line in enumerate(lines):
        line = line.rstrip('\n')
        if not line:
            continue

        # Split by TAB
        parts = line.split('\t', 1)
        if len(parts) != 2:
            continue

        pattern_str, subject = parts
        test_num = i + 1

        # Parse and match
        try:
            pattern = parse_regex(pattern_str)
        except Exception as e:
            print(f"{test_num}: no match")
            continue

        # Track captures
        captures: List[Optional[Tuple[int, int]]] = []

        # Find match
        result = find_match(subject, pattern)

        if result is None:
            print(f"{test_num}: no match")
        else:
            start, end = result
            # For captures, we need to track them properly
            # This is a simplified version - full implementation would need to track captures during matching
            # For now, we'll just output the main match
            capture_strs = []
            for cap in captures:
                if cap is None:
                    capture_strs.append("-")
                else:
                    capture_strs.append(f"{cap[0]}-{cap[1]}")

            output = f"{test_num}: {start}-{end}"
            if capture_strs:
                output += " " + " ".join(capture_strs)
            print(output)


if __name__ == "__main__":
    main()

use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::Read;

// Simple JSON Value
#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(i64),
    String(String),
    Array(Vec<JsonValue>),
    Object(HashMap<String, JsonValue>),
}

// Tokenizer and Parser
struct Parser<'a> {
    input: &'a str,
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Self {
        Parser { input, pos: 0 }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.input.len() && self.input[self.pos].is_whitespace() {
            self.pos += 1;
        }
    }

    fn parse(&mut self) -> JsonValue {
        self.skip_whitespace();
        let ch = self.peek();
        match ch {
            '{' => self.parse_object(),
            '[' => self.parse_array(),
            '"' => self.parse_string(),
            '-' | '0'..='9' => self.parse_number(),
            't' => self.parse_bool(true),
            'f' => self.parse_bool(false),
            'n' => self.parse_null(),
            _ => panic!("Unexpected character in JSON"),
        }
    }

    fn parse_object(&mut self) -> JsonValue {
        self.eat('{');
        let mut obj = HashMap::new();
        self.skip_whitespace();
        if self.peek() == '}' {
            self.eat('}');
            return JsonValue::Object(obj);
        }
        loop {
            let key = self.parse_string();
            self.skip_whitespace();
            self.eat(':');
            let val = self.parse();
            obj.insert(key, val);
            self.skip_whitespace();
            match self.peek() {
                '}' => {
                    self.eat('}');
                    break;
                }
                ',' => {
                    self.eat(',');
                }
                _ => panic!("Expected ',' or '}' in object"),
            }
        }
        JsonValue::Object(obj)
    }

    fn parse_array(&mut self) -> JsonValue {
        self.eat('[');
        let mut arr = Vec::new();
        self.skip_whitespace();
        if self.peek() == ']' {
            self.eat(']');
            return JsonValue::Array(arr);
        }
        loop {
            let val = self.parse();
            arr.push(val);
            self.skip_whitespace();
            match self.peek() {
                ']' => {
                    self.eat(']');
                    break;
                }
                ',' => {
                    self.eat(',');
                }
                _ => panic!("Expected ',' or ']' in array"),
            }
        }
        JsonValue::Array(arr)
    }

    fn parse_string(&mut self) -> String {
        self.eat('"');
        let mut s = String::new();
        loop {
            let ch = self.input[self.pos];
            match ch {
                '\\' => {
                    self.pos += 1;
                    let esc = self.input[self.pos];
                    match esc {
                        '"' => s.push('"'),
                        '\\' => s.push('\\'),
                        '/' => s.push('/'),
                        'b' => s.push('\u{0008}'),
                        'f' => s.push('\u{000C}'),
                        'n' => s.push('\n'),
                        'r' => s.push('\r'),
                        't' => s.push('\t'),
                        'u' => {
                            self.pos += 1;
                            let hex = &self.input[self.pos..self.pos + 4];
                            self.pos += 4;
                            s.push_str(&u16::from_str_radix(hex, 16).unwrap().to_string());
                        }
                        _ => panic!("Unknown escape sequence"),
                    }
                }
                '"' => {
                    self.pos += 1;
                    break;
                }
                _ => {
                    s.push(ch);
                }
            }
            self.pos += 1;
        }
        s
    }

    fn parse_number(&mut self) -> i64 {
        let start = self.pos;
        if self.input[self.pos] == '-' {
            self.pos += 1;
        }
        while self.pos < self.input.len() && self.input[self.pos].is_digit(10) {
            self.pos += 1;
        }
        let s = &self.input[start..self.pos];
        s.parse::<i64>().unwrap()
    }

    fn parse_bool(&mut self, val: bool) -> JsonValue {
        let start = self.pos;
        if val {
            self.pos += 4; // 'true'
        } else {
            self.pos += 5; // 'false'
        }
        if self.input[start..self.pos] == "true" {
            JsonValue::Bool(true)
        } else {
            JsonValue::Bool(false)
        }
    }

    fn parse_null(&mut self) -> JsonValue {
        let start = self.pos;
        self.pos += 4; // 'null'
        JsonValue::Null
    }

    fn eat(&mut self, ch: char) {
        if self.peek() == ch {
            self.pos += 1;
        } else {
            panic!("Expected '{}'", ch);
        }
    }

    fn peek(&self) -> char {
        if self.pos < self.input.len() {
            self.input[self.pos]
        } else {
            '\0'
        }
    }
}

#[derive(Debug, Clone)]
struct Scene {
    width: i64,
    height: i64,
    background: [u8; 3],
    shapes: Vec<Shape>,
}

#[derive(Debug, Clone)]
struct Shape {
    r#type: String,
    x: i64,
    y: i64,
    w: i64,
    h: i64,
    cx: i64,
    cy: i64,
    r: i64,
    points: Vec<Point>,
    x1: i64,
    y1: i64,
    x2: i64,
    y2: i64,
    color: [u8; 4],
}

#[derive(Debug, Clone, Copy)]
struct Point {
    x: i64,
    y: i64,
}

fn parse_scene(json_str: &str) -> Scene {
    let mut parser = Parser::new(json_str);
    let root = parser.parse();
    let root_obj = match root {
        JsonValue::Object(obj) => obj,
        _ => panic!("Root must be an object"),
    };

    let width = get_number(&root_obj, "width").unwrap();
    let height = get_number(&root_obj, "height").unwrap();
    let background = get_number_array(&root_obj, "background").unwrap();
    let shapes = get_number_array(&root_obj, "shapes").unwrap();

    let mut scene_shapes = Vec::new();
    for (idx, shape_json) in shapes.iter().enumerate() {
        let shape_obj = match shape_json {
            JsonValue::Object(obj) => obj,
            _ => panic!("Shape must be an object"),
        };
        let r#type = get_string(&shape_obj, "type").unwrap();
        let color = get_number_array(&shape_obj, "color").unwrap();
        let shape = match r#type.as_str() {
            "rect" => {
                let x = get_number(&shape_obj, "x").unwrap();
                let y = get_number(&shape_obj, "y").unwrap();
                let w = get_number(&shape_obj, "w").unwrap();
                let h = get_number(&shape_obj, "h").unwrap();
                Shape {
                    r#type: "rect".to_string(),
                    x,
                    y,
                    w,
                    h,
                    cx: 0,
                    cy: 0,
                    r: 0,
                    points: vec![],
                    x1: 0,
                    y1: 0,
                    x2: 0,
                    y2: 0,
                    color,
                }
            }
            "circle" => {
                let cx = get_number(&shape_obj, "cx").unwrap();
                let cy = get_number(&shape_obj, "cy").unwrap();
                let r = get_number(&shape_obj, "r").unwrap();
                Shape {
                    r#type: "circle".to_string(),
                    x: 0,
                    y: 0,
                    w: 0,
                    h: 0,
                    cx,
                    cy,
                    r,
                    points: vec![],
                    x1: 0,
                    y1: 0,
                    x2: 0,
                    y2: 0,
                    color,
                }
            }
            "triangle" => {
                let points = get_number_array(&shape_obj, "points").unwrap();
                let mut pts = vec![];
                for p in points {
                    let p_obj = match p {
                        JsonValue::Array(arr) => arr,
                        _ => panic!("Point must be an array"),
                    };
                    let px = get_number(&p_obj, 0).unwrap();
                    let py = get_number(&p_obj, 1).unwrap();
                    pts.push(Point { x: px, y: py });
                }
                Shape {
                    r#type: "triangle".to_string(),
                    x: 0,
                    y: 0,
                    w: 0,
                    h: 0,
                    cx: 0,
                    cy: 0,
                    r: 0,
                    points: pts,
                    x1: 0,
                    y1: 0,
                    x2: 0,
                    y2: 0,
                    color,
                }
            }
            "line" => {
                let x1 = get_number(&shape_obj, "x1").unwrap();
                let y1 = get_number(&shape_obj, "y1").unwrap();
                let x2 = get_number(&shape_obj, "x2").unwrap();
                let y2 = get_number(&shape_obj, "y2").unwrap();
                let r = get_number(&shape_obj, "r").unwrap();
                Shape {
                    r#type: "line".to_string(),
                    x: 0,
                    y: 0,
                    w: 0,
                    h: 0,
                    cx: 0,
                    cy: 0,
                    r,
                    points: vec![],
                    x1,
                    y1,
                    x2,
                    y2,
                    color,
                }
            }
            _ => panic!("Unknown shape type: {}", r#type),
        };
        scene_shapes.push(shape);
    }

    Scene {
        width,
        height,
        background,
        shapes: scene_shapes,
    }
}

fn get_number(obj: &HashMap<String, JsonValue>, key: &str) -> Option<i64> {
    match obj.get(key) {
        Some(JsonValue::Number(n)) => Some(*n),
        _ => None,
    }
}

fn get_string(obj: &HashMap<String, JsonValue>, key: &str) -> Option<String> {
    match obj.get(key) {
        Some(JsonValue::String(s)) => Some(s.clone()),
        _ => None,
    }
}

fn get_number_array(obj: &HashMap<String, JsonValue>, key: &str) -> Option<Vec<JsonValue>> {
    match obj.get(key) {
        Some(JsonValue::Array(arr)) => Some(arr.clone()),
        _ => None,
    }
}

fn render(scene: &Scene) -> Vec<u8> {
    let width = scene.width as usize;
    let height = scene.height as usize;
    let mut buffer: Vec<u8> = vec![0; width * height * 3];

    // Background
    let bg_r = scene.background[0];
    let bg_g = scene.background[1];
    let bg_b = scene.background[2];
    for y in 0..height {
        for x in 0..width {
            let idx = (y * width + x) * 3;
            buffer[idx] = bg_r;
            buffer[idx + 1] = bg_g;
            buffer[idx + 2] = bg_b;
        }
    }

    let mut shape_pixel_counts = Vec::with_capacity(scene.shapes.len());

    for (i, shape) in scene.shapes.iter().enumerate() {
        let count = render_shape(shape, &mut buffer, width, height);
        shape_pixel_counts.push(count);
    }

    // Count distinct colors
    let mut colors_count = 0;
    let mut color_set: HashMap<[u8; 3], ()> = HashMap::new();
    for y in 0..height {
        for x in 0..width {
            let idx = (y * width + x) * 3;
            let c = [buffer[idx], buffer[idx + 1], buffer[idx + 2]];
            color_set.insert(c, ());
        }
    }
    colors_count = color_set.len();

    // Print summary
    for (i, count) in shape_pixel_counts.iter().enumerate() {
        let shape = &scene.shapes[i];
        println!("{} {} {}", i + 1, shape.r#type, count);
    }
    println!("colors {}", colors_count);

    buffer
}

fn render_shape(shape: &Shape, buffer: &mut Vec<u8>, width: usize, height: usize) -> usize {
    let mut count = 0;
    let s_color = shape.color;
    let s_a = s_color[3];
    if s_a == 0 {
        return 0;
    }

    let d_r = shape.x as u8;
    let d_g = shape.y as u8;
    let d_b = shape.w as u8;
    // Wait, I need to access the pixel color.
    // I will iterate over the bounding box and check coverage.
    // I need to be careful with the loop bounds.

    match shape.r#type.as_str() {
        "rect" => {
            let rx = shape.x as i64;
            let ry = shape.y as i64;
            let rw = shape.w as i64;
            let rh = shape.h as i64;
            let x_min = rx;
            let x_max = rx + rw - 1;
            let y_min = ry;
            let y_max = ry + rh - 1;
            for y in y_min..=y_max {
                if y < 0 || y >= height as i64 {
                    continue;
                }
                for x in x_min..=x_max {
                    if x < 0 || x >= width as i64 {
                        continue;
                    }
                    if is_covered_rect(x, y, rx, ry, rw, rh) {
                        blend_pixel(buffer, x, y, width, s_color);
                        count += 1;
                    }
                }
            }
        }
        "circle" => {
            let cx = shape.cx as i64;
            let cy = shape.cy as i64;
            let r = shape.r as i64;
            let r_sq = r * r;
            let x_min = cx - r;
            let x_max = cx + r;
            let y_min = cy - r;
            let y_max = cy + r;
            for y in y_min..=y_max {
                if y < 0 || y >= height as i64 {
                    continue;
                }
                for x in x_min..=x_max {
                    if x < 0 || x >= width as i64 {
                        continue;
                    }
                    if is_covered_circle(x, y, cx, cy, r_sq) {
                        blend_pixel(buffer, x, y, width, s_color);
                        count += 1;
                    }
                }
            }
        }
        "triangle" => {
            let pts = &shape.points;
            let x_min = pts[0].x.min(pts[1].x).min(pts[2].x);
            let x_max = pts[0].x.max(pts[1].x).max(pts[2].x);
            let y_min = pts[0].y.min(pts[1].y).min(pts[2].y);
            let y_max = pts[0].y.max(pts[1].y).max(pts[2].y);
            for y in y_min..=y_max {
                if y < 0 || y >= height as i64 {
                    continue;
                }
                for x in x_min..=x_max {
                    if x < 0 || x >= width as i64 {
                        continue;
                    }
                    if is_covered_triangle(x, y, pts) {
                        blend_pixel(buffer, x, y, width, s_color);
                        count += 1;
                    }
                }
            }
        }
        "line" => {
            let x1 = shape.x1 as i64;
            let y1 = shape.y1 as i64;
            let x2 = shape.x2 as i64;
            let y2 = shape.y2 as i64;
            let r = shape.r as i64;
            let r_sq = r * r;
            let dx = x2 - x1;
            let dy = y2 - y1;
            let L = dx * dx + dy * dy;
            let x_min = x1.min(x2);
            let x_max = x1.max(x2);
            let y_min = y1.min(y2);
            let y_max = y1.max(y2);
            for y in y_min..=y_max {
                if y < 0 || y >= height as i64 {
                    continue;
                }
                for x in x_min..=x_max {
                    if x < 0 || x >= width as i64 {
                        continue;
                    }
                    if is_covered_line(x, y, x1, y1, x2, y2, L, r_sq) {
                        blend_pixel(buffer, x, y, width, s_color);
                        count += 1;
                    }
                }
            }
        }
        _ => {}
    }
    count
}

fn is_covered_rect(x: i64, y: i64, rx: i64, ry: i64, rw: i64, rh: i64) -> bool {
    x >= rx && x < rx + rw && y >= ry && y < ry + rh
}

fn is_covered_circle(x: i64, y: i64, cx: i64, cy: i64, r_sq: i64) -> bool {
    (x - cx) * (x - cx) + (y - cy) * (y - cy) <= r_sq
}

fn is_covered_triangle(x: i64, y: i64, pts: &[Point]) -> bool {
    let p0 = pts[0];
    let p1 = pts[1];
    let p2 = pts[2];
    let e0 = (p1.x - p0.x) * (y - p0.y) - (p1.y - p0.y) * (x - p0.x);
    let e1 = (p2.x - p1.x) * (y - p1.y) - (p2.y - p1.y) * (x - p1.x);
    let e2 = (p0.x - p2.x) * (y - p2.y) - (p0.y - p2.y) * (x - p2.x);
    (e0 >= 0 && e1 >= 0 && e2 >= 0) || (e0 <= 0 && e1 <= 0 && e2 <= 0)
}

fn is_covered_line(x: i64, y: i64, x1: i64, y1: i64, x2: i64, y2: i64, L: i64, r_sq: i64) -> bool {
    let dx = x2 - x1;
    let dy = y2 - y1;
    let t = (x - x1) * dx + (y - y1) * dy;
    if t <= 0 {
        (x - x1) * (x - x1) + (y - y1) * (y - y1) <= r_sq
    } else if t >= L {
        (x - x2) * (x - x2) + (y - y2) * (y - y2) <= r_sq
    } else {
        let c = (x - x1) * dy - (y - y1) * dx;
        c * c <= r_sq * L
    }
}

fn blend_pixel(buffer: &mut Vec<u8>, x: usize, y: usize, width: usize, shape_color: [u8; 4]) {
    let r = shape_color[0] as u32;
    let g = shape_color[1] as u32;
    let b = shape_color[2] as u32;
    let a = shape_color[3] as u32;

    let idx = (y * width + x) * 3;
    let d_r = buffer[idx] as u32;
    let d_g = buffer[idx + 1] as u32;
    let d_b = buffer[idx + 2] as u32;

    let nr = (r * a + d_r * (255 - a) + 127) / 255;
    let ng = (g * a + d_g * (255 - a) + 127) / 255;
    let nb = (b * a + d_b * (255 - a) + 127) / 255;

    buffer[idx] = nr as u8;
    buffer[idx + 1] = ng as u8;
    buffer[idx + 2] = nb as u8;
}

fn write_png(buffer: &[u8], width: usize, height: usize) -> Vec<u8> {
    let mut png_data = Vec::new();
    // Signature
    png_data.extend_from_slice(&[0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]);

    // IHDR
    let mut ihdr = [0u8; 13];
    ihdr[0..4].copy_from_slice(&(width as u32).to_be_bytes());
    ihdr[4..8].copy_from_slice(&(height as u32).to_be_bytes());
    ihdr[8] = 8; // Bit depth
    ihdr[9] = 2; // Color type (RGB)
    ihdr[10] = 0; // Compression
    ihdr[11] = 0; // Filter
    ihdr[12] = 0; // Interlace

    let ihdr_crc = crc32(&ihdr);
    let mut ihdr_chunk = vec![0u8; 13 + 4 + 4];
    ihdr_chunk[0..4].copy_from_slice(&13u32.to_be_bytes());
    ihdr_chunk[4..8].copy_from_slice(&b"IHDR"[..]);
    ihdr_chunk[8..12].copy_from_slice(&ihdr);
    ihdr_chunk[12..16].copy_from_slice(&ihdr_crc.to_be_bytes());
    png_data.append(&mut ihdr_chunk);

    // IDAT
    let mut zlib_data = Vec::new();
    // Zlib header for no compression (stored)
    zlib_data.push(0x78);
    zlib_data.push(0x9C);

    // Filtered image data
    for y in 0..height {
        zlib_data.push(0); // Filter type 0 (None)
        for x in 0..width {
            let idx = (y * width + x) * 3;
            zlib_data.push(buffer[idx]);
            zlib_data.push(buffer[idx + 1]);
            zlib_data.push(buffer[idx + 2]);
        }
    }

    let adler = adler32(&zlib_data);
    zlib_data.extend_from_slice(&adler.to_be_bytes());

    // IDAT chunk header
    let idat_len = zlib_data.len() as u32;
    let mut idat_chunk = vec![0u8; 4 + idat_len as usize + 4];
    idat_chunk[0..4].copy_from_slice(&idat_len.to_be_bytes());
    idat_chunk[4..8].copy_from_slice(&b"IDAT"[..]);
    idat_chunk[8..(8 + idat_len as usize)].copy_from_slice(&zlib_data);
    let idat_crc = crc32(&idat_chunk[4..]);
    idat_chunk[(8 + idat_len as usize)..].copy_from_slice(&idat_crc.to_be_bytes());

    png_data.append(&mut idat_chunk);

    // IEND
    let mut iend_chunk = vec![0u8; 4 + 4];
    iend_chunk[0..4].copy_from_slice(&0u32.to_be_bytes());
    iend_chunk[4..8].copy_from_slice(&b"IEND"[..]);
    let iend_crc = crc32(&iend_chunk[4..]);
    iend_chunk[8..].copy_from_slice(&iend_crc.to_be_bytes());
    png_data.append(&mut iend_chunk);

    png_data
}

fn adler32(data: &[u8]) -> u32 {
    let mut a: u32 = 1;
    let mut b: u32 = 0;
    for &byte in data.iter() {
        a = (a.wrapping_add(byte as u32)) % 65521;
        b = (b.wrapping_add(a)) % 65521;
    }
    (b << 16) | a
}

fn crc32(data: &[u8]) -> u32 {
    static CRC_TABLE: [u32; 256] = {
        let mut table = [0u32; 256];
        for i in 0..256 {
            let mut c = i as u32;
            for j in 0..8 {
                c = (c << 1) ^ (if (c & 0x80000000) != 0 { 0xEDB88320 } else { 0 });
                c &= 0xFFFFFFFF;
            }
            table[i as usize] = c;
        }
        table
    };
    let mut crc = 0xFFFFFFFF;
    for &byte in data.iter() {
        crc = (crc ^ (byte as u32)) & 0xFF;
        crc = ((crc >> 8) ^ CRC_TABLE[crc as usize]) & 0xFFFFFFFF;
    }
    crc ^ 0xFFFFFFFF
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <directory>", args[0]);
        std::process::exit(1);
    }
    let dir = &args[1];
    let json_path = format!("{}/scene.json", dir);
    let json_str = fs::read_to_string(&json_path).expect("Failed to read scene.json");
    let scene = parse_scene(&json_str);
    let buffer = render(&scene);
    let png_data = write_png(&buffer, scene.width as usize, scene.height as usize);
    fs::write("out.png", &png_data).expect("Failed to write out.png");
}

