typedef enum {
    SHAPE_NONE,
    SHAPE_RECT,
    SHAPE_CIRCLE,
    SHAPE_TRIANGLE,
    SHAPE_LINE
} ShapeType;

typedef struct {
    int x, y;
} Point;

typedef struct {
    ShapeType type;
