static char json_buffer[MAX_JSON_SIZE];
static int json_pos = 0;

void skip_whitespace(void) {
    while (json_pos < strlen(json_buffer) && json_buffer[json_pos] <= ' ') {
        json_pos++;
    }
}

int parse_int(void) {
    int sign = 1;
    if (json_buffer[json_pos] == '-') {
        sign = -1;
        json_pos++;
    }
    int val = 0;
    while (json_pos < strlen(json_buffer) && json_buffer[json_pos] >= '0' && json_buffer[json_pos] <= '9') {
        val = val * 10 + (json_buffer[json_pos] - '0');
        json_pos++;
    }
    return sign * val;
}

char* parse_string(void) {
    if (json_buffer[json_pos] != '"') return NULL;
    json_pos++;
    char* start = json_buffer + json_pos;
    while (json_pos < strlen(json_buffer) && json_buffer[json_pos] != '"') {
        json_pos++;
    }
    json_pos++;
    int len = json_pos - (start - json_buffer);
    char* s = malloc(len + 1);
    memcpy(s, start, len);
    s[len] = 0;
    return s;
}

void parse_array_int(int count, int* out) {
    if (json_buffer[json_pos] != '[') return;
    json_pos++;
    for (int i = 0; i < count; i++) {
        skip_whitespace();
        out[i] = parse_int();
    }
    skip_whitespace();
    if (json_buffer[json_pos] == ']') json_pos++;
}

void parse_points_array(Point* out) {
    if (json_buffer[json_pos] != '[') return;
    json_pos++;
    for (int i = 0; i < 3; i++) {
