        // I need to implement this manually.
        // Skip [
        if (json_buffer[json_pos] == '[') json_pos++;
        out[i].x = parse_int();
        skip_whitespace();
        if (json_buffer[json_pos] == ',') json_pos++;
        out[i].y = parse_int();
        skip_whitespace();
        if (json_buffer[json_pos] == ']') json_pos++;
    }
}

