void parse_shape(Shape* s) {
    skip_whitespace();
    if (json_buffer[json_pos] != '{') return;
    json_pos++;

    s->type = SHAPE_NONE;
    s->x = s->y = s->w = s->h = 0;
    s->cx = s->cy = s->r = 0;
    s->color[0] = s->color[1] = s->color[2] = s->color[3] = 0;
    s->color_a = 0;

    while (1) {
        skip_whitespace();
        if (json_buffer[json_pos] == '}') {
            json_pos++;
            break;
        }

        // Search for keys
        // Keys: type, color, x, y, w, h, r, cx, cy, points, x1, y1, x2, y2
        // I will search for "key":

        const char* keys[] = {"type", "color", "x", "y", "w", "h", "r", "cx", "cy", "points", "x1", "y1", "x2", "y2"};
        const int key_lens[] = {4, 5, 1, 1, 1, 1, 1, 2, 2, 6, 2, 2, 2, 2};

        int found = 0;
        for (int i = 0; i < 14; i++) {
            int key_len = key_lens[i];
            const char* key = keys[i];
            int key_start = json_pos;

            // Find key
            int found_idx = 0;
            while (json_pos < strlen(json_buffer)) {
                if (json_buffer[json_pos] == '"') {
                    json_pos++;
                    int k = 0;
                    while (json_pos < strlen(json_buffer) && json_buffer[json_pos] != '"') {
                        if (json_buffer[json_pos] == key[k]) k++;
                        json_pos++;
                    }
                    if (k == key_len) {
                        // Check for colon
                        skip_whitespace();
                        if (json_pos < strlen(json_buffer) && json_buffer[json_pos] == ':') {
                            found = 1;
                            json_pos++; // Skip colon
                            break;
                        }
                        // Not a match
                        json_pos = key_start; // Backtrack
                        break;
                    }
                }
                json_pos++;
            }
            if (found) break;
        }

        if (!found) continue;

        // Now parse value based on key
        if (strcmp(keys[0], "type") == 0) {
            s->type = SHAPE_NONE;
            char* type_str = parse_string();
            if (type_str) {
                if (strcmp(type_str, "rect") == 0) s->type = SHAPE_RECT;
                else if (strcmp(type_str, "circle") == 0) s->type = SHAPE_CIRCLE;
                else if (strcmp(type_str, "triangle") == 0) s->type = SHAPE_TRIANGLE;
                else if (strcmp(type_str, "line") == 0) s->type = SHAPE_LINE;
                free(type_str);
            }
        } else if (strcmp(keys[1], "color") == 0) {
            parse_color(s->color);
            s->color_a = s->color[3];
            s->color[3] = 0; // Store alpha separately for rendering logic
        } else if (strcmp(keys[2], "points") == 0) {
            parse_points(s->points);
        } else if (strcmp(keys[3], "x") == 0) {
            s->x = parse_int();
        } else if (strcmp(keys[4], "y") == 0) {
            s->y = parse_int();
        } else if (strcmp(keys[5], "w") == 0) {
            s->w = parse_int();
        } else if (strcmp(keys[6], "h") == 0) {
            s->h = parse_int();
        } else if (strcmp(keys[7], "r") == 0) {
            s->r = parse_int();
        } else if (strcmp(keys[8], "cx") == 0) {
            s->cx = parse_int();
        } else if (strcmp(keys[9], "cy") == 0) {
            s->cy = parse_int();
        } else if (strcmp(keys[10], "x1") == 0) {
            s->x = parse_int(); // x1 -> x, y1 -> y
            // Need to handle line separately
        } else if (strcmp(keys[11], "y1") == 0) {
            s->y = parse_int(); // y1 -> y
        } else if (strcmp(keys[12], "x2") == 0) {
            s->x2 = parse_int(); // x2
        } else if (strcmp(keys[13], "y2") == 0) {
            s->y2 = parse_int(); // y2
        }
    }
}

