        const int key_lens[] = {4, 5, 1, 1, 1, 1, 1, 2, 2, 6, 2, 2, 2, 2};

        int found = 0;
        int key_idx = -1;

        for (int i = 0; i < 14; i++) {
            int klen = key_lens[i];
            const char* k = keys[i];
            int start = json_pos;
            // Search for "key":
            if (strstr(json_buffer + start, "\"") != NULL) {
                // Check if "key" exists
                int found_k = 0;
                int j = 0;
                while (json_buffer[start + j] != '"') {
                    if (json_buffer[start + j] == '"' && j == klen) {
                        found_k = 1;
                        break;
                    }
                    j++;
                }
                if (found_k) {
                    // Check for colon
                    json_pos = start + klen;
                    skip_whitespace();
                    if (json_pos < strlen(json_buffer) && json_buffer[json_pos] == ':') {
                        found = 1;
                        key_idx = i;
                        json_pos++; // Skip colon
                        break;
                    }
                }
            }
        }

        if (!found) continue;

        int klen = key_lens[key_idx];
