use std::env;
use std::fs;

// AST for regex patterns
#[derive(Debug, Clone)]
struct Regex {
    branches: Vec<Branch>,
    groups: Vec<Group>,
}

#[derive(Debug, Clone)]
struct Group {
    captures: Vec<Option<(usize, usize)>>,
}

#[derive(Debug, Clone)]
struct Branch {
    pieces: Vec<Piece>,
}

#[derive(Debug, Clone)]
struct Piece {
    atom: Atom,
    quantifier: Option<Quantifier>,
}

#[derive(Debug, Clone)]
enum Atom {
    Literal(char),
    Dot,
    Caret,
    Dollar,
    Class(Class),
    Escape(Escape),
    Group(Box<Regex>),
    NonCaretGroup(Box<Regex>),
}

#[derive(Debug, Clone)]
enum Quantifier {
    Star,
    Plus,
    Question,
    Count(Bound),
    Lazy(Bound),
}

#[derive(Debug, Clone)]
enum Bound {
    Exact(usize),
    Min(usize),
    MinMax(usize, usize),
}

#[derive(Debug, Clone)]
enum Escape {
    Digit,
    Word,
    Space,
    NotDigit,
    NotWord,
    NotSpace,
    Literal(char),
}

#[derive(Debug, Clone)]
struct Class {
    negated: bool,
    items: Vec<ClassItem>,
}

#[derive(Debug, Clone)]
enum ClassItem {
    Char(char),
    Range(char, char),
    Escape(Escape),
}

// Input parsing
fn parse_input(content: &str) -> Vec<(usize, String, String)> {
    let mut results = Vec::new();
    let mut line_num = 0;
    for (line_idx, line) in content.lines().enumerate() {
        if line.is_empty() { continue; }
        let tab_pos = line.find('\t').unwrap_or(line.len());
        let pattern = line[..tab_pos].to_string();
        let subject = line[tab_pos + 1..].to_string();
        results.push((line_idx + 1, pattern, subject));
        line_num += 1;
    }
    results
}

// Tokenizer
fn tokenize(pattern: &str) -> Vec<Token> {
    let mut tokens = Vec::new();
    let mut i = 0;
    while i < pattern.len() {
        let c = pattern.as_bytes()[i];
        if c == b'\\' {
            if i + 1 < pattern.len() {
                let next = pattern.as_bytes()[i + 1];
                match next {
                    b'd' => tokens.push(Token::Escape(Escape::Digit)),
                    b'w' => tokens.push(Token::Escape(Escape::Word)),
                    b's' => tokens.push(Token::Escape(Escape::Space)),
                    b'D' => tokens.push(Token::Escape(Escape::NotDigit)),
                    b'W' => tokens.push(Token::Escape(Escape::NotWord)),
                    b'S' => tokens.push(Token::Escape(Escape::NotSpace)),
                    _ => tokens.push(Token::Literal(pattern[i + 1])),
                }
                i += 2;
            } else {
                i += 1;
            }
        } else if c == b'.' {
            tokens.push(Token::Dot);
            i += 1;
        } else if c == b'^' {
            tokens.push(Token::Caret);
            i += 1;
        } else if c == b'$' {
            tokens.push(Token::Dollar);
            i += 1;
        } else if c == b'[' {
            if i + 1 < pattern.len() && pattern.as_bytes()[i + 1] == b'^' {
                let start = i + 2;
                let end = pattern[start..].find(']').unwrap_or(pattern.len());
                let inner = &pattern[start..start + end];
                tokens.push(Token::Class(Class::parse(inner)));
                i += end + 1;
            } else {
                let start = i + 1;
                let end = pattern[start..].find(']').unwrap_or(pattern.len());
                let inner = &pattern[start..start + end];
                tokens.push(Token::Class(Class::parse(inner)));
                i += end + 1;
            }
        } else if c == b'(' {
            if i + 1 < pattern.len() && pattern.as_bytes()[i + 1] == b'?' {
                tokens.push(Token::NonCaretGroup);
                i += 2;
            } else {
                tokens.push(Token::Group);
                i += 1;
            }
        } else if c == b'|' {
            tokens.push(Token::Alt);
            i += 1;
        } else if c == b'*' || c == b'+' || c == b'?' {
            tokens.push(Token::Quantifier(Quantifier::parse(&pattern[i..])));
            i += pattern[i..].match_quantifier().len();
        } else if c >= b'0' && c <= b'9' {
            let start = i;
            while i < pattern.len() && pattern.as_bytes()[i] >= b'0' && pattern.as_bytes()[i] <= b'9' {
                i += 1;
            }
            let num = u32::from_str_radix(&pattern[start..i], 10).unwrap();
            tokens.push(Token::Number(num));
        } else {
            tokens.push(Token::Literal(pattern[i]));
            i += 1;
        }
    }
    tokens
}

fn Token::parse_quantifier(s: &str) -> Option<Quantifier> {
    let mut i = 0;
    let mut quant = Quantifier::Star;
    if s.len() >= 2 && s.as_bytes()[0] == b'{' {
        let start = 1;
        let end = s[start..].find('}').unwrap_or(s.len());
        let inner = &s[start..start + end];
        if inner.contains(',') {
            let parts: Vec<&str> = inner.split(',').map(|s| s.trim()).collect();
            let (min, max) = if parts.len() == 1 {
                (parts[0].parse().unwrap(), parts[0].parse().unwrap())
            } else {
                (parts[0].parse().unwrap(), parts[1].parse().unwrap())
            };
            quant = Quantifier::Count(Bound::MinMax(min, max));
        } else {
            quant = Quantifier::Count(Bound::Exact(inner.parse().unwrap()));
        }
        i += end + 1;
    } else {
        quant = Quantifier::parse_simple(s.as_bytes()[0]);
        i += 1;
    }
    if i < s.len() && s.as_bytes()[i] == b'?' {
        return Some(Quantifier::Lazy(quant.clone()));
    }
    Some(quant)
}

fn Quantifier::parse_simple(byte: u8) -> Quantifier {
    match byte {
        b'*' => Quantifier::Star,
        b'+' => Quantifier::Plus,
        b'?' => Quantifier::Question,
        _ => Quantifier::Star,
    }
}

fn Class::parse(s: &str) -> Self {
    let mut negated = false;
    if s.as_bytes()[0] == b'^' {
        negated = true;
        let items = parse_class_items(&s[1..]);
        return Class { negated, items };
    }
    let items = parse_class_items(s);
    Class { negated, items }
}

fn parse_class_items(s: &str) -> Vec<ClassItem> {
    let mut items = Vec::new();
    let mut i = 0;
    while i < s.len() {
        let c = s.as_bytes()[i];
        if c == b'\\' {
            if i + 1 < s.len() {
                let next = s.as_bytes()[i + 1];
                match next {
                    b'\\' => items.push(ClassItem::Escape(Escape::Literal('\\'))),
                    b'[' => items.push(ClassItem::Escape(Escape::Literal('['))),
                    b']' => items.push(ClassItem::Escape(Escape::Literal(']'))),
                    b'-' => items.push(ClassItem::Escape(Escape::Literal('-'))),
                    b'0'..=b'9' => items.push(ClassItem::Escape(Escape::Digit)),
                    b'A'..=b'Z' => items.push(ClassItem::Escape(Escape::Word)),
                    b'a'..=b'z' => items.push(ClassItem::Escape(Escape::Word)),
                    b' ' => items.push(ClassItem::Escape(Escape::Space)),
                    _ => items.push(ClassItem::Char(s[i + 1])),
                }
                i += 2;
            } else {
                i += 1;
            }
        } else if c == b'-' && i + 1 < s.len() && s.as_bytes()[i + 1] != b'[' && s.as_bytes()[i + 1] != b'\\' {
            let end = s[i + 1..].find('-').unwrap_or(s.len());
            if end > 0 {
                items.push(ClassItem::Range(s[i], s[i + 1 + end]));
                i += 2 + end;
            } else {
                items.push(ClassItem::Char(s[i]));
                i += 1;
            }
        } else {
            items.push(ClassItem::Char(s[i]));
            i += 1;
        }
    }
    items
}

fn Token::match_quantifier(s: &str) -> usize {
    let mut i = 0;
    if s.len() >= 2 && s.as_bytes()[0] == b'{' {
        let start = 1;
        let end = s[start..].find('}').unwrap_or(s.len());
        i += end + 1;
        if i < s.len() && s.as_bytes()[i] == b'?' {
            i += 1;
        }
        i
    } else {
        i += 1;
    }
}

// Parser
fn parse(tokens: Vec<Token>) -> Regex {
    let mut branches = Vec::new();
    let mut current_branch = Vec::new();
    let mut group_count = 0;
    let mut group_stack: Vec<(usize, usize)> = Vec::new();

    for token in tokens {
        match token {
            Token::Alt => {
                if !current_branch.is_empty() {
                    branches.push(Branch { pieces: current_branch });
                    current_branch.clear();
                }
            }
            Token::Group => {
                group_count += 1;
                let idx = group_count - 1;
                group_stack.push((idx, group_count));
            }
            Token::NonCaretGroup => {
                group_count += 1;
                let idx = group_count - 1;
                group_stack.push((idx, group_count));
            }
            Token::Literal(c) => {
                current_branch.push(Piece { atom: Atom::Literal(c), quantifier: None });
            }
            Token::Dot => {
                current_branch.push(Piece { atom: Atom::Dot, quantifier: None });
            }
            Token::Caret => {
                current_branch.push(Piece { atom: Atom::Caret, quantifier: None });
            }
            Token::Dollar => {
                current_branch.push(Piece { atom: Atom::Dollar, quantifier: None });
            }
            Token::Class(class) => {
                current_branch.push(Piece { atom: Atom::Class(class.clone()), quantifier: None });
            }
            Token::Escape(escape) => {
                current_branch.push(Piece { atom: Atom::Escape(escape), quantifier: None });
            }
            Token::Number(_) => {
                // Handled in quantifier parsing
            }
            _ => {}
        }
    }
    if !current_branch.is_empty() {
        branches.push(Branch { pieces: current_branch });
    }
    Regex { branches, groups: Vec::new() }
}

// Matcher
fn match_regex(regex: &Regex, subject: &str, start: usize) -> Option<(usize, usize, Vec<Option<(usize, usize)>>)> {
    let len = subject.len();
    if start >= len {
        return None;
    }
    for branch in &regex.branches {
        if let Some((end, captures)) = match_branch(branch, subject, start, len) {
            return Some((end, end - start, captures));
        }
    }
    None
}

fn match_branch(branch: &Branch, subject: &str, start: usize, len: usize) -> Option<(usize, Vec<Option<(usize, usize)>>)> {
    let mut captures = Vec::new();
    let mut pos = start;
    for piece in &branch.pieces {
        let atom = &piece.atom;
        let quant = piece.quantifier.as_ref();
        if let Some((end, cap)) = match_atom(atom, subject, pos, len) {
            if let Some(quant) = quant {
                let count = match quant {
                    Quantifier::Star => {
                        while let Some((end, _)) = match_atom(atom, subject, end, len) {
                            end += 1;
                        }
                        0
                    }
                    Quantifier::Plus => {
                        let mut count = 1;
                        while let Some((end, _)) = match_atom(atom, subject, end, len) {
                            end += 1;
                            count += 1;
                        }
                        count
                    }
                    Quantifier::Question => {
                        if let Some((end, _)) = match_atom(atom, subject, end, len) {
                            end += 1;
                        }
                        1
                    }
                    Quantifier::Count(bound) => {
                        let mut count = 0;
                        while let Some((end, _)) = match_atom(atom, subject, end, len) {
                            end += 1;
                            count += 1;
                            if !bound.fits(count) { break; }
                        }
                        count
                    }
                    Quantifier::Lazy(bound) => {
                        let mut count = 0;
                        while let Some((end, _)) = match_atom(atom, subject, end, len) {
                            end += 1;
                            count += 1;
                            if !bound.fits(count) { break; }
                        }
                        count
                    }
                };
                pos = end;
            } else {
                pos = end;
            }
        } else {
            return None;
        }
    }
    Some((pos, captures))
}

fn match_atom(atom: &Atom, subject: &str, start: usize, len: usize) -> Option<(usize, Option<(usize, usize)>)> {
    match atom {
        Atom::Literal(c) => {
            if start < len && subject.as_bytes()[start] == *c {
                Some((start + 1, Some((start, start + 1))))
            } else {
                None
            }
        }
        Atom::Dot => {
            if start < len {
                Some((start + 1, Some((start, start + 1))))
            } else {
                None
            }
        }
        Atom::Caret => {
            if start == 0 {
                Some((start, None))
            } else {
                None
            }
        }
        Atom::Dollar => {
            if start == len {
                Some((start, None))
            } else {
                None
            }
        }
        Atom::Class(class) => {
            if start < len {
                let c = subject.as_bytes()[start];
                if class.matches(c) {
                    Some((start + 1, Some((start, start + 1))))
                } else {
                    None
                }
            } else {
                None
            }
        }
        Atom::Escape(escape) => {
            if start < len {
                let c = subject.as_bytes()[start];
                if escape.matches(c) {
                    Some((start + 1, Some((start, start + 1))))
                } else {
                    None
                }
            } else {
                None
            }
        }
        Atom::Group(ref regex) => {
            if let Some((end, captures)) = match_regex(regex, subject, start, len) {
                Some((end, captures.first().cloned()))
            } else {
                None
            }
        }
        Atom::NonCaretGroup(ref regex) => {
            if let Some((end, captures)) = match_regex(regex, subject, start, len) {
                Some((end, captures.first().cloned()))
            } else {
                None
            }
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let dir = args.get(1).map(|s| s.as_str()).unwrap_or(".");
    let path = format!("{}/cases.txt", dir);
    let content = fs::read_to_string(&path).expect("Failed to read cases.txt");
    let tests = parse_input(&content);

    for (line_num, pattern, subject) in tests {
        let tokens = tokenize(&pattern);
        let regex = parse(tokens);
        let mut best_match = None;
