                sb.append(new String(chunk, 0, read, StandardCharsets.UTF_8));
                br.readLine(); // Skip CRLF
            }
            body = sb.toString();
        } else {
            // Read until EOF
            byte[] data = new byte[1024];
            int total = 0;
            while (is.read(data, total, 1024 - total) > 0) {
                total += 1024;
            }
            body = new String(data, 0, total, StandardCharsets.UTF_8);
        }
        return new HttpResponse(status, body, headers);
    }
}

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import java.util.regex.*;

public class Main {
    static class Config {
        String clientId;
        String clientSecret;
        String scope;
        int pageSize;

        void load(String path) throws IOException {
            try (BufferedReader br = new BufferedReader(new FileReader(path))) {
                StringBuilder sb = new StringBuilder();
                String line;
                while ((line = br.readLine()) != null) {
                    sb.append(line);
                }
                String json = sb.toString();
                clientId = extractString(json, "client_id");
                clientSecret = extractString(json, "client_secret");
                scope = extractString(json, "scope");
                pageSize = extractInt(json, "page_size");
            }
        }

        private String extractString(String json, String key) {
            String regex = "\"" + key + "\"\\s*:\\s*\"([^\"]*)\"";
            Matcher m = Pattern.compile(regex).matcher(json);
            if (m.find()) return m.group(1);
            return null;
        }

        private int extractInt(String json, String key) {
            String regex = "\"" + key + "\"\\s*:\\s*(\\d+)";
            Matcher m = Pattern.compile(regex).matcher(json);
            if (m.find()) return Integer.parseInt(m.group(1));
            return 0;
        }
    }

    static class JsonParser {
        private String data;
        private int pos;

        JsonParser(String data) {
            this.data = data;
            this.pos = 0;
        }

        String parseString() throws IOException {
            skipWhitespace();
            if (pos >= data.length() || data.charAt(pos) != '"') throw new IOException("Expected string");
            pos++;
            StringBuilder sb = new StringBuilder();
            while (pos < data.length()) {
                char c = data.charAt(pos);
                if (c == '"') {
                    pos++;
                    return sb.toString();
                } else if (c == '\\') {
                    pos++;
                    if (pos >= data.length()) throw new IOException("Unterminated escape");
                    char nc = data.charAt(pos);
                    switch (nc) {
                        case '"': sb.append('"'); break;
                        case '\\': sb.append('\\'); break;
                        case '/': sb.append('/'); break;
                        case 'b': sb.append('\b'); break;
                        case 'f': sb.append('\f'); break;
                        case 'n': sb.append('\n'); break;
                        case 'r': sb.append('\r'); break;
                        case 't': sb.append('\t'); break;
                        case 'u':
                            pos += 4;
                            if (pos > data.length()) throw new IOException("Unterminated unicode");
                            String hex = data.substring(pos - 4, pos);
                            char ch = (char) Integer.parseInt(hex, 16);
                            sb.append(ch);
                            break;
                        default: sb.append(nc); break;
                    }
                    pos++;
                } else {
                    sb.append(c);
                    pos++;
                }
            }
            throw new IOException("Unterminated string");
        }

        long parseNumber() throws IOException {
            skipWhitespace();
            if (pos >= data.length()) throw new IOException("Expected number");
            int start = pos;
            if (data.charAt(pos) == '-') pos++;
            while (pos < data.length() && Character.isDigit(data.charAt(pos))) pos++;
            if (pos == start) throw new IOException("Expected number");
            String s = data.substring(start, pos);
            if (s.contains(".")) {
                String[] parts = s.split("\\.");
                long intPart = Long.parseLong(parts[0]);
                long fracPart = Long.parseLong(parts[1]);
                int len = parts[1].length();
                long cents = intPart * 100 + fracPart * (len == 1 ? 10 : 1);
                return cents;
            }
            return Long.parseLong(s);
        }

        Object parseValue() throws IOException {
            skipWhitespace();
            if (pos >= data.length()) throw new IOException("Unexpected end");
            char c = data.charAt(pos);
            if (c == '"') return parseString();
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == 't') return true;
            if (c == 'f') return false;
            if (c == 'n') return null;
            return parseNumber();
        }

        Object parseObject() throws IOException {
            skipWhitespace();
            if (pos >= data.length() || data.charAt(pos) != '{') throw new IOException("Expected object");
            pos++;
            skipWhitespace();
            if (pos < data.length() && data.charAt(pos) == '}') { pos++; return new HashMap<>(); }
            Map<String, Object> obj = new HashMap<>();
            while (pos < data.length()) {
                skipWhitespace();
                if (pos >= data.length() || data.charAt(pos) != '"') break;
                String key = parseString();
                skipWhitespace();
                if (pos >= data.length() || data.charAt(pos) != ':') throw new IOException("Expected :");
                pos++;
                Object val = parseValue();
                obj.put(key, val);
                skipWhitespace();
                if (pos >= data.length() || data.charAt(pos) == '}') { pos++; return obj; }
                if (pos >= data.length() || data.charAt(pos) != ',') break;
                pos++;
            }
            return obj;
        }

        List<Object> parseArray() throws IOException {
            skipWhitespace();
            if (pos >= data.length() || data.charAt(pos) != '[') throw new IOException("Expected array");
            pos++;
            skipWhitespace();
            List<Object> list = new ArrayList<>();
            while (pos < data.length()) {
                skipWhitespace();
                if (pos >= data.length() || data.charAt(pos) == ']') { pos++; return list; }
                Object val = parseValue();
                list.add(val);
                skipWhitespace();
                if (pos >= data.length() || data.charAt(pos) != ',') break;
                pos++;
            }
            return list;
        }

        void skipWhitespace() {
            while (pos < data.length() && data.charAt(pos) <= ' ') pos++;
        }
    }

    static String formEncode(String s) {
        StringBuilder sb = new StringBuilder();
        for (byte b : s.getBytes(StandardCharsets.UTF_8)) {
            if ((b >= 'A' && b <= 'Z') || (b >= 'a' && b <= 'z') ||
                (b >= '0' && b <= '9') || b == '-' || b == '.' || b == '_' || b == '*') {
                sb.append((char) b);
            } else if (b == ' ') {
                sb.append('+');
            } else {
                sb.append(String.format("%02X", b));
            }
        }
        return sb.toString();
    }

    static String encodeCursor(String cursor) {
        StringBuilder sb = new StringBuilder();
        for (char c : cursor.toCharArray()) {
            if (c == '+') sb.append("%2B");
            else if (c == '/') sb.append("%2F");
            else if (c == '=') sb.append("%3D");
            else if (c == '%') sb.append("%25");
            else sb.append(c);
        }
        return sb.toString();
    }

    static String getHost(String baseUrl) {
        try {
            URI uri = new URI(baseUrl);
            String host = uri.getHost();
            int port = uri.getPort();
            if (port == -1) port = 80;
            if (port == 80) return host;
            return host + ":" + port;
        } catch (Exception e) {
            return "localhost";
        }
    }

    static int getPort(String baseUrl) {
        try {
            URI uri = new URI(baseUrl);
            int port = uri.getPort();
            if (port == -1) port = 80;
            return port;
        } catch (Exception e) {
            return 80;
        }
    }

    static class HttpResponse {
        int status;
        String body;
        Map<String, String> headers;

        HttpResponse(int status, String body, Map<String, String> headers) {
            this.status = status;
            this.body = body;
            this.headers = headers;
        }
    }

    static HttpResponse readResponse(Socket socket) throws IOException {
        InputStream is = socket.getInputStream();
        BufferedReader br = new BufferedReader(new InputStreamReader(is, StandardCharsets.UTF_8));
        String line;
        Map<String, String> headers = new HashMap<>();
        int status = 0;
        boolean contentLength = false;
        boolean chunked = false;
        long contentLengthVal = 0;

        while ((line = br.readLine()) != null) {
            if (line.isEmpty()) break;
            int colon = line.indexOf(':');
            if (colon > 0) {
                String key = line.substring(0, colon).toLowerCase();
                String val = line.substring(colon + 1).trim();
                headers.put(key, val);
                if ("content-length".equals(key)) {
                    contentLength = true;
                    try {
                        contentLengthVal = Long.parseLong(val);
                    } catch (NumberFormatException e) {
                        contentLength = false;
                    }
                } else if ("transfer-encoding".equals(key) && "chunked".equalsIgnoreCase(val)) {
                    chunked = true;
                }
            } else if (line.startsWith("HTTP/")) {
                String[] parts = line.split(" ");
                if (parts.length >= 2) {
                    status = Integer.parseInt(parts[1]);
                }
            }
        }
        if (status == 0) throw new IOException("No status line");

        String body = "";
        if (contentLength) {
            byte[] data = new byte[(int) contentLengthVal];
            int read = 0;
            while (read < data.length) {
                int len = is.read(data, read, data.length - read);
                if (len == -1) break;
                read += len;
            }
            body = new String(data, 0, read, StandardCharsets.UTF_8);
        } else if (chunked) {
            StringBuilder sb = new StringBuilder();
            while (true) {
                line = br.readLine();
                if (line == null) break;
                line = line.trim();
                if (line.isEmpty()) continue;
                if (line.equals("0")) break;
                int chunkSize = Integer.parseInt(line, 16);
                byte[] chunk = new byte[chunkSize];
                int read = 0;
                while (read < chunkSize) {
                    int len = is.read(chunk, read, chunkSize - read);
                    if (len == -1) break;
                    read += len;
                }
                sb.append(new String(chunk, 0, read, StandardCharsets.UTF_8));
                br.readLine(); // Skip CRLF
            }
            body = sb.toString();
        } else {
            // Read until EOF
            byte[] data = new byte[1024];
            int total = 0;
            while (is.read(data, total, 1024 - total) > 0) {
                total += 1024;
            }
            body = new String(data, 0, total, StandardCharsets.UTF_8);
        }
        return new HttpResponse(status, body, headers);
    }

    static void sleepSeconds(int seconds) throws InterruptedException {
        Thread.sleep(seconds * 1000);
    }

    static void sleepMax1Second() throws InterruptedException {
        Thread.sleep(1000);
    }

    static String buildRequest(String baseUrl, String path, Map<String, String> headers, String body, String method) {
        StringBuilder sb = new StringBuilder();
        sb.append(method).append(" ").append(path).append(" HTTP/1.1\r\n");
        String host = getHost(baseUrl);
        sb.append("Host: ").append(host).append("\r\n");
        for (Map.Entry<String, String> e : headers.entrySet()) {
            sb.append(e.getKey()).append(": ").append(e.getValue()).append("\r\n");
        }
        if (body != null) {
            sb.append("\r\n");
            sb.append(body);
        } else {
            sb.append("\r\n");
        }
        return sb.toString();
    }

    static HttpResponse makeRequest(String baseUrl, String path, Map<String, String> headers, String body, String method) {
        try {
            String host = getHost(baseUrl);
            int port = getPort(baseUrl);
            Socket socket = new Socket(host, port);
            socket.getOutputStream().write(buildRequest(baseUrl, path, headers, body, method).getBytes(StandardCharsets.UTF_8));
            HttpResponse resp = readResponse(socket);
            return resp;
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    static long parseAmount(String amountStr) {
        if (amountStr == null) return 0;
        try {
            String s = amountStr.trim();
            if (s.isEmpty()) return 0;
            int sign = 1;
            if (s.startsWith("-")) {
                sign = -1;
                s = s.substring(1);
            }
            String[] parts = s.split("\\.");
            long intPart = Long.parseLong(parts[0]);
            long fracPart = 0;
            if (parts.length > 1) {
                fracPart = Long.parseLong(parts[1]);
                if (parts[1].length() == 1) fracPart *= 10;
            }
            return sign * (intPart * 100 + fracPart);
        } catch (Exception e) {
            return 0;
        }
    }

    static String getAccessToken(String baseUrl, String clientId, String clientSecret, String scope) {
        try {
            String host = getHost(baseUrl);
            int port = getPort(baseUrl);
            Socket socket = new Socket(host, port);
            Map<String, String> headers = new HashMap<>();
            headers.put("Content-Type", "application/x-www-form-urlencoded");
            headers.put("Authorization", "Basic " + formEncode(clientId) + ":" + formEncode(clientSecret));
            String body = "grant_type=client_credentials&scope=" + formEncode(scope);
            String request = buildRequest(baseUrl, "/oauth/token", headers, body, "POST");
            socket.getOutputStream().write(request.getBytes(StandardCharsets.UTF_8));
            HttpResponse resp = readResponse(socket);
            if (resp.status != 200) {
                return null;
            }
            JsonParser jp = new JsonParser(resp.body);
            Object root = jp.parseValue();
            return (String) ((Map<?, ?>) root).get("access_token");
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    public static void main(String[] args) {
        if (args.length < 2) {
            return;
        }
        String dataDir = args[0];
        String baseUrl = args[1];
        Config config = new Config();
        try {
            config.load(dataDir + "/client.json");
        } catch (Exception e) {
            System.out.println("ERROR 500 " + e.getMessage());
            System.exit(0);
            return;
        }

        String accessToken = null;
        int reauth = 0;
        int pages = 0;
        int retries = 0;
        int orders = 0;
        Map<String, Long> totals = new HashMap<>();
        Map<String, Integer> statusCounts = new HashMap<>();

        try {
            accessToken = getAccessToken(baseUrl, config.clientId, config.clientSecret, config.scope);
            String cursor = null;
            while (true) {
                String url = baseUrl + "/orders";
                Map<String, String> headers = new HashMap<>();
                headers.put("Authorization", "Bearer " + accessToken);
                StringBuilder sb = new StringBuilder();
                sb.append("limit=").append(config.pageSize);
                if (cursor != null) sb.append("&cursor=").append(encodeCursor(cursor));
                String path = "?" + sb.toString();
                HttpResponse resp = makeRequest(baseUrl, path, headers, null, "GET");
                int status = resp.status;
                String responseBody = resp.body;
                Map<String, String> respHeaders = resp.headers;

                if (status == 200) {
                    pages++;
                    try {
                        JsonParser jp = new JsonParser(responseBody);
                        Object dataObj = jp.parseValue();
                        Map<?, ?> root = (Map<?, ?>) dataObj;
                        List<?> list = (List<?>) ((Map<?, ?>) root).get("data");
                        Object nextCursorObj = ((Map<?, ?>) root).get("next_cursor");
                        String nextCursor = nextCursorObj == null ? null : (String) nextCursorObj;
                        if (nextCursor != null) cursor = nextCursor;
                        else cursor = null;

                        for (Object order : list) {
                            Map<?, ?> orderMap = (Map<?, ?>) order;
                            Map<?, ?> customerMap = (Map<?, ?>) orderMap.get("customer");
                            String name = (String) ((Map<?, ?>) customerMap).get("name");
                            String currency = (String) orderMap.get("currency");
                            String amountStr = (String) orderMap.get("amount");
                            String statusStr = (String) orderMap.get("status");
                            if (statusStr == null) continue;
                            statusCounts.put(statusStr, statusCounts.getOrDefault(statusStr, 0) + 1);
                            if (!"cancelled".equals(statusStr)) {
                                long cents = parseAmount(amountStr);
                                totals.put(name + "|" + currency, totals.getOrDefault(name + "|" + currency, 0L) + cents);
                            }
                            orders++;
                        }
                    } catch (Exception e) {
                        System.out.println("ERROR 200 " + responseBody);
                        System.exit(0);
                        return;
                    }
                } else if (status == 429) {
                    retries++;
                    String retryAfter = respHeaders.get("Retry-After");
                    if (retryAfter != null) {
                        try {
                            sleepSeconds(Integer.parseInt(retryAfter));
                        } catch (InterruptedException e) {
                            break;
                        }
                    } else {
                        sleepSeconds(1);
                    }
                    continue;
                } else if (status == 503) {
                    retries++;
                    sleepMax1Second();
                    continue;
                } else if (status == 401) {
                    if (cursor == null && "Bearer " + accessToken.equals(headers.get("Authorization"))) {
                        // This is the first /orders request with a newly obtained token
                        System.out.println("ERROR 401 " + responseBody);
                        System.exit(0);
                        return;
                    }
                    // Refresh token and retry
                    accessToken = getAccessToken(baseUrl, config.clientId, config.clientSecret, config.scope);
                    reauth++;
                    continue;
                } else {
                    System.out.println("ERROR " + status + " " + responseBody);
                    System.exit(0);
                    return;
                }
            }
        } catch (Exception e) {
            System.out.println("ERROR 500 " + e.getMessage());
            System.exit(0);
            return;
        }

        // Print report
        List<String> totalLines = new ArrayList<>();
        for (Map.Entry<String, Long> e : totals.entrySet()) {
            String[] parts = e.getKey().split("\\|");
            String name = parts[0];
            String currency = parts[1];
            long cents = e.getValue();
            double amount = cents / 100.0;
            String amountStr = String.format("%.2f", amount);
            totalLines.add(name + "|" + currency + "|" + amountStr);
        }
        totalLines.sort((a, b) -> {
            String[] pa = a.split("\\|");
            String[] pb = b.split("\\|");
            int cmp = pa[0].compareTo(pb[0]);
            if (cmp != 0) return cmp;
            return pa[1].compareTo(pb[1]);
        });
        for (String line : totalLines) {
            String[] parts = line.split("\\|");
            System.out.println("total " + parts[1] + " " + parts[2] + " " + parts[0]);
        }
        // Re-sort for status
        List<String> statusLines = new ArrayList<>();
        for (Map.Entry<String, Integer> e : statusCounts.entrySet()) {
            statusLines.add(e.getKey() + "|" + e.getValue());
        }
        statusLines.sort((a, b) -> a.compareTo(b));
        for (String line : statusLines) {
            String[] parts = line.split("\\|");
            System.out.println("status " + parts[0] + " " + parts[1]);
        }
        System.out.println("orders " + orders + " pages " + pages + " retries " + retries + " reauth " + reauth);
    }
}

import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.regex.*;
import java.util.stream.*;

public class Main {

    public static void main(String[] args) throws Exception {
        if (args.length < 2) {
            System.exit(1);
        }

        String dataDir = args[0];
        String baseUrl = args[1];

        // Load request.json
        Map<String, Object> requestConfig = parseJsonFile(new File(dataDir, "request.json"));

        String apiKey = (String) requestConfig.get("api_key");
        String model = (String) requestConfig.get("model");
        int maxTokens = (Integer) requestConfig.get("max_tokens");
        int thinkingBudget = (Integer) requestConfig.get("thinking_budget");
        String system = (String) requestConfig.get("system");
        Object toolsObj = requestConfig.get("tools");

        List<Map<String, Object>> tools = (List<Map<String, Object>>) toolsObj;

        // Process request 1
        List<String> outputLines = new ArrayList<>();
        outputLines.add("request 1");

        String response1 = makeRequest(
            baseUrl, apiKey, model, maxTokens, thinkingBudget, system, tools,
            Arrays.asList(Map.of("role", "user", "content", system))
        );

        // Parse response 1 content blocks
        List<ContentBlock> blocks1 = parseContentBlocks(response1);

        // Print blocks
        for (ContentBlock block : blocks1) {
            printBlock(block, outputLines);
        }

        // Print stop reason
        outputLines.add("stop_reason " + response1.get("stop_reason"));

        // Process tool results
        List<ToolResult> toolResults = new ArrayList<>();
        for (ContentBlock block : blocks1) {
            if (block.getType().equals("tool_use")) {
                String result = executeTool(block.getId(), block.getName(), block.getInput());
                toolResults.add(new ToolResult(block.getId(), result, result.contains("error")));
            }
        }

        // Print tool results
        for (ToolResult tr : toolResults) {
            if (tr.error) {
                outputLines.add("error " + tr.id + " " + tr.result);
            } else {
                outputLines.add("result " + tr.id + " " + tr.result);
            }
        }

        // Process request 2
        outputLines.add("request 2");

        List<Object> messages2 = new ArrayList<>();
        messages2.add(Map.of("role", "user", "content", system));

        // Add assistant message with all content blocks
        List<Object> assistantContent = new ArrayList<>();
        for (ContentBlock block : blocks1) {
            assistantContent.add(convertBlockToContent(block));
        }
        messages2.add(Map.of("role", "assistant", "content", assistantContent));

        // Add user message with tool results
        List<Object> userContent2 = new ArrayList<>();
        for (ToolResult tr : toolResults) {
            userContent2.add(Map.of("type", "tool_result", "tool_use_id", tr.id, "content", tr.result));
        }
        messages2.add(Map.of("role", "user", "content", userContent2));

        String response2 = makeRequest(
            baseUrl, apiKey, model, maxTokens, thinkingBudget, system, tools, messages2
        );

        // Parse response 2 content blocks
        List<ContentBlock> blocks2 = parseContentBlocks(response2);

        // Print blocks
        for (ContentBlock block : blocks2) {
            printBlock(block, outputLines);
        }

        // Print stop reason
        outputLines.add("stop_reason " + response2.get("stop_reason"));

        // Print usage
        Integer inputTokens = (Integer) response1.get("input_tokens");
        Integer outputTokens = (Integer) response2.get("output_tokens");
        Integer cacheReadTokens = (Integer) response1.get("cache_read_input_tokens");
        outputLines.add("usage input=" + inputTokens + " output=" + outputTokens + " cache_read=" + cacheReadTokens);

        // Print all output
        for (String line : outputLines) {
            System.out.println(escapeString(line));
        }
    }

    static Map<String, Object> parseJsonFile(File file) throws Exception {
        String content = new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8);
        return parseJson(content);
    }

    static Map<String, Object> parseJson(String json) {
        Map<String, Object> result = new LinkedHashMap<>();
        int i = 0;
        while (i < json.length()) {
            char c = json.charAt(i);
            if (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
                i++;
                continue;
            }
            if (c == '{') {
                i++;
                result = parseJsonObj(json, i);
            } else if (c == '[') {
                i++;
                result = parseJsonArray(json, i);
            } else {
                throw new RuntimeException("Unexpected character at " + i);
            }
            while (i < json.length() && (json.charAt(i) == ' ' || json.charAt(i) == '\n' || json.charAt(i) == '\r' || json.charAt(i) == '\t')) {
                i++;
            }
            break;
        }
        return result;
    }

    static Map<String, Object> parseJsonObj(String json, int start) {
        Map<String, Object> obj = new LinkedHashMap<>();
        int i = start;
        if (json.charAt(i) != '{') {
            throw new RuntimeException("Expected object");
        }
        i++;
        while (i < json.length()) {
            if (json.charAt(i) == '}') {
                i++;
                break;
            }
            if (json.charAt(i) == ' ' || json.charAt(i) == '\n' || json.charAt(i) == '\r' || json.charAt(i) == '\t') {
                i++;
                continue;
            }
            if (json.charAt(i) != '"') {
                throw new RuntimeException("Expected string key");
            }
            int keyStart = i;
            while (i < json.length() && json.charAt(i) != '"') {
                if (json.charAt(i) == '\\') {
                    i += 2;
                } else {
                    i++;
                }
            }
            String key = json.substring(keyStart + 1, i);
            i++; // skip closing quote
            while (i < json.length() && (json.charAt(i) == ' ' || json.charAt(i) == '\n' || json.charAt(i) == '\r' || json.charAt(i) == '\t')) {
                i++;
            }
            if (json.charAt(i) != ':') {
                throw new RuntimeException("Expected colon");
            }
            i++;
            while (i < json.length() && (json.charAt(i) == ' ' || json.charAt(i) == '\n' || json.charAt(i) == '\r' || json.charAt(i) == '\t')) {
                i++;
            }
            if (json.charAt(i) == '"') {
                int valStart = i + 1;
                while (i < json.length() && json.charAt(i) != '"') {
                    if (json.charAt(i) == '\\') {
                        i += 2;
                    } else {
                        i++;
                    }
                }
                String val = json.substring(valStart, i);
                i++;
                obj.put(key, val);
            } else if (json.charAt(i) == '{') {
                obj.put(key, parseJsonObj(json, i));
                while (i < json.length() && (json.charAt(i) == ' ' || json.charAt(i) == '\n' || json.charAt(i) == '\r' || json.charAt(i) == '\t')) {
                    i++;
                }
            } else if (json.charAt(i) == '[') {
                obj.put(key, parseJsonArray(json, i));
                while (i < json.length() && (json.charAt(i) == ' ' || json.charAt(i) == '\n' || json.charAt(i) == '\r' || json.charAt(i) == '\t')) {
                    i++;
                }
            } else if (json.charAt(i) == 't' || json.charAt(i) == 'f' || json.charAt(i) == 'n' || json.charAt(i) == 'u' || json.charAt(i) == 'T' || json.charAt(i) == 'F' || json.charAt(i) == 'N') {
                int valStart = i;
                while (i < json.length() && (json.charAt(i) != ',' && json.charAt(i) != '}' && json.charAt(i) != ' ' && json.charAt(i) != '\n' && json.charAt(i) != '\r' && json.charAt(i) != '\t')) {
                    i++;
                }
                String val = json.substring(valStart, i);
                if (val.equals("true")) {
                    obj.put(key, true);
                } else if (val.equals("false")) {
                    obj.put(key, false);
                } else if (val.equals("null")) {
                    obj.put(key, null);
                } else {
                    throw new RuntimeException("Unknown literal: " + val);
                }
            } else if (Character.isDigit(json.charAt(i)) || json.charAt(i) == '-') {
                int valStart = i;
                while (i < json.length() && (Character.isDigit(json.charAt(i)) || json.charAt(i) == '-' || json.charAt(i) == '.' || json.charAt(i) == 'e' || json.charAt(i) == 'E' || json.charAt(i) == '+' || json.charAt(i) == ' ' || json.charAt(i) == '\n' || json.charAt(i) == '\r' || json.charAt(i) == '\t')) {
                    i++;
                }
                String val = json.substring(valStart, i);
                try {
                    if (val.contains(".") || val.contains("e") || val.contains("E")) {
                        obj.put(key, Double.parseDouble(val));
                    } else {
                        obj.put(key, Integer.parseInt(val));
                    }
                } catch (NumberFormatException e) {
                    obj.put(key, val);
                }
            } else {
                throw new RuntimeException("Unexpected character after value: " + json.charAt(i));
            }
            while (i < json.length() && (json.charAt(i) == ' ' || json.charAt(i) == '\n' || json.charAt(i) == '\r' || json.charAt(i) == '\t')) {
                i++;
            }
            if (i < json.length() && json.charAt(i) == ',') {
                i++;
            }
        }
        return obj;
    }

    static List<Object> parseJsonArray(String json, int start) {
        List<Object> arr = new ArrayList<>();
        int i = start;
        if (json.charAt(i) != '[') {
            throw new RuntimeException("Expected array");
        }
        i++;
        while (i < json.length()) {
            if (json.charAt(i) == ']') {
                i++;
                break;
            }
            if (json.charAt(i) == ' ' || json.charAt(i) == '\n' || json.charAt(i) == '\r' || json.charAt(i) == '\t') {
                i++;
                continue;
            }
            if (json.charAt(i) == '"') {
                int valStart = i + 1;
                while (i < json.length() && json.charAt(i) != '"') {
                    if (json.charAt(i) == '\\') {
                        i += 2;
                    } else {
                        i++;
                    }
                }
                String val = json.substring(valStart, i);
                i++;
                arr.add(val);
            } else if (json.charAt(i) == '{') {
                arr.add(parseJsonObj(json, i));
                while (i < json.length() && (json.charAt(i) == ' ' || json.charAt(i) == '\n' || json.charAt(i) == '\r' || json.charAt(i) == '\t')) {
                    i++;
                }
            } else if (json.charAt(i) == '[') {
                arr.add(parseJsonArray(json, i));
                while (i < json.length() && (json.charAt(i) == ' ' || json.charAt(i) == '\n' || json.charAt(i) == '\r' || json.charAt(i) == '\t')) {
                    i++;
                }
            } else if (Character.isDigit(json.charAt(i)) || json.charAt(i) == '-' || json.charAt(i) == 't' || json.charAt(i) == 'f' || json.charAt(i) == 'n' || json.charAt(i) == 'u' || json.charAt(i) == 'T' || json.charAt(i) == 'F' || json.charAt(i) == 'N') {
                int valStart = i;
                while (i < json.length() && (Character.isDigit(json.charAt(i)) || json.charAt(i) == '-' || json.charAt(i) == '.' || json.charAt(i) == 'e' || json.charAt(i) == 'E' || json.charAt(i) == '+' || json.charAt(i) == ' ' || json.charAt(i) == '\n' || json.charAt(i) == '\r' || json.charAt(i) == '\t')) {
                    i++;
                }
                String val = json.substring(valStart, i);
                if (val.equals("true")) {
                    arr.add(true);
                } else if (val.equals("false")) {
                    arr.add(false);
                } else if (val.equals("null")) {
                    arr.add(null);
                } else {
                    try {
                        if (val.contains(".") || val.contains("e") || val.contains("E")) {
                            arr.add(Double.parseDouble(val));
                        } else {
                            arr.add(Integer.parseInt(val));
                        }
                    } catch (NumberFormatException e) {
                        arr.add(val);
                    }
                }
            } else {
                throw new RuntimeException("Unexpected character in array: " + json.charAt(i));
            }
            while (i < json.length() && (json.charAt(i) == ' ' || json.charAt(i) == '\n' || json.charAt(i) == '\r' || json.charAt(i) == '\t')) {
                i++;
            }
            if (i < json.length() && json.charAt(i) == ',') {
                i++;
            }
        }
        return arr;
    }

    static String escapeString(String s) {
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            switch (c) {
                case '\\':
                    sb.append("\\\\");
                    break;
                case '\n':
                    sb.append("\\n");
                    break;
                case '\r':
                    sb.append("\\r");
                    break;
                case '\t':
                    sb.append("\\t");
                    break;
                default:
                    sb.append(c);
            }
        }
        return sb.toString();
    }

    static String makeRequest(String baseUrl, String apiKey, String model, int maxTokens, int thinkingBudget, String system, List<Map<String, Object>> tools, List<Object> messages) throws Exception {
        String endpoint = baseUrl + "/v1/messages";
        StringBuilder body = new StringBuilder();
        body.append("{\"model\":\"").append(escapeJsonString(model)).append("\",\"max_tokens\":").append(maxTokens).append(",\"stream\":true,");
        body.append("\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":").append(thinkingBudget).append("},");
        body.append("\"system\":\"").append(escapeJsonString(system)).append("\",");
        body.append("\"tools\":").append(toJson(tools)).append(",");
        body.append("\"messages\":").append(toJson(messages)).append("}");

        URL url = new URL(endpoint);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("POST");
        conn.setRequestProperty("Host", url.getHost());
        conn.setRequestProperty("Content-Length", String.valueOf(body.length()));
        conn.setRequestProperty("x-api-key", apiKey);
        conn.setRequestProperty("anthropic-version", "2023-06-01");
        conn.setRequestProperty("content-type", "application/json");
        conn.setDoOutput(true);

        try (OutputStream os = conn.getOutputStream()) {
            byte[] input = body.toString().getBytes(StandardCharsets.UTF_8);
            os.write(input, 0, input.length);
        }

        int status = conn.getResponseCode();

        if (status == 200) {
            return parseSseResponse(conn.getInputStream());
        } else {
            StringBuilder errorBody = new StringBuilder();
            try (InputStream is = conn.getErrorStream()) {
                if (is != null) {
                    byte[] buf = new byte[4096];
                    int len;
                    while ((len = is.read(buf)) != -1) {
                        errorBody.append(new String(buf, 0, len, StandardCharsets.UTF_8));
                    }
                }
            }
            System.out.println(errorBody.toString());
            System.out.println("ERROR " + status + " error: " + errorBody.toString());
            System.exit(0);
        }
    }

    static String parseSseResponse(InputStream is) throws Exception {
        StringBuilder output = new StringBuilder();
        int token;
        boolean inData = false;
        StringBuilder currentData = new StringBuilder();
        String currentEvent = null;
        int dataCount = 0;

        while ((token = is.read()) != -1) {
            char c = (char) token;
            if (inData) {
                currentData.append(c);
                if (c == '\n') {
                    // End of data line
                    if (currentData.length() > 0) {
                        try {
                            Object data = parseJson(currentData.toString());
                            processSseEvent(currentEvent, data);
                        } catch (Exception e) {
                            // Ignore parsing errors
                        }
                    }
                    inData = false;
                    currentData = new StringBuilder();
                }
            } else {
                if (c == '\n' || c == '\r') {
                    if (currentData.length() > 0) {
                        // Empty line, end of event
                        if (currentEvent != null && dataCount > 0) {
                            // Process event
                        }
                    }
                    currentEvent = null;
                    dataCount = 0;
                    currentData = new StringBuilder();
                } else if (c == ':') {
                    // End of event name
                    currentEvent = currentData.toString().trim();
                    inData = true;
                } else if (c == 'd' || c == 'e' || c == 's' || c == 't' || c == 'p' || c == 'i' || c == 'm' || c == 'o' || c == 'n' || c == 'u') {
                    // Likely data: line
                    // Check if it's a data line
                    if (currentData.length() > 0 && (currentData.toString().startsWith(":") || currentData.toString().startsWith("d"))) {
                        inData = true;
                    }
                }
            }
        }

        return output.toString();
    }

    static void processSseEvent(String eventName, Object data) {
        if (eventName == null || eventName.equals("ping")) {
            return;
        }

        if (eventName.equals("message_start")) {
            Map<String, Object> msg = (Map<String, Object>) data;
            Map<String, Object> usage = (Map<String, Object>) msg.get("usage");
            if (usage != null) {
                Integer inputTokens = (Integer) usage.get("input_tokens");
                Integer cacheReadInputTokens = (Integer) usage.get("cache_read_input_tokens");
                System.out.println("input_tokens: " + inputTokens);
                System.out.println("cache_read_input_tokens: " + cacheReadInputTokens);
            }
        } else if (eventName.equals("content_block_start")) {
            Map<String, Object> block = (Map<String, Object>) data;
            Integer index = (Integer) block.get("index");
            Map<String, Object> content = (Map<String, Object>) block.get("content_block");
            String type = (String) content.get("type");
            System.out.println("content_block_start index: " + index + " type: " + type);
        } else if (eventName.equals("content_block_delta")) {
            Map<String, Object> delta = (Map<String, Object>) data;
            Integer index = (Integer) delta.get("index");
            Map<String, Object> d = (Map<String, Object>) delta.get("delta");
            String dType = (String) d.get("type");
            if (dType.equals("thinking_delta")) {
                String thinking = (String) d.get("thinking");
                System.out.println("thinking_delta index: " + index + " thinking: " + thinking);
            } else if (dType.equals("signature_delta")) {
                String signature = (String) d.get("signature");
                System.out.println("signature_delta index: " + index + " signature: " + signature);
            } else if (dType.equals("text_delta")) {
                String text = (String) d.get("text");
                System.out.println("text_delta index: " + index + " text: " + text);
            } else if (dType.equals("input_json_delta")) {
                String partialJson = (String) d.get("partial_json");
                System.out.println("input_json_delta index: " + index + " partial_json: " + partialJson);
            }
        } else if (eventName.equals("content_block_stop")) {
            Map<String, Object> block = (Map<String, Object>) data;
            Integer index = (Integer) block.get("index");
            System.out.println("content_block_stop index: " + index);
        } else if (eventName.equals("message_delta")) {
            Map<String, Object> msg = (Map<String, Object>) data;
            Map<String, Object> delta = (Map<String, Object>) msg.get("delta");
            String stopReason = (String) delta.get("stop_reason");
            System.out.println("message_delta stop_reason: " + stopReason);
            Map<String, Object> usage = (Map<String, Object>) msg.get("usage");
            if (usage != null) {
                Integer outputTokens = (Integer) usage.get("output_tokens");
                System.out.println("output_tokens: " + outputTokens);
            }
        } else if (eventName.equals("message_stop")) {
            System.out.println("message_stop");
        }
    }

    static String toJson(Object obj) {
        if (obj == null) {
            return "null";
        } else if (obj instanceof String) {
            return "\"" + escapeJsonString((String) obj) + "\"";
        } else if (obj instanceof Integer) {
            return String.valueOf((Integer) obj);
        } else if (obj instanceof Long) {
            return String.valueOf((Long) obj);
        } else if (obj instanceof Double) {
            return String.valueOf((Double) obj);
        } else if (obj instanceof Boolean) {
            return (Boolean) obj ? "true" : "false";
        } else if (obj instanceof List) {
            StringBuilder sb = new StringBuilder("[");
            boolean first = true;
            for (Object item : (List<?>) obj) {
                if (!first) {
                    sb.append(",");
                }
                sb.append(toJson(item));
                first = false;
            }
            sb.append("]");
            return sb.toString();
        } else if (obj instanceof Map) {
            StringBuilder sb = new StringBuilder("{");
            boolean first = true;
            for (Map.Entry<?, ?> entry : ((Map<?, ?>) obj).entrySet()) {
                if (!first) {
                    sb.append(",");
                }
                sb.append("\"").append(escapeJsonString(String.valueOf(entry.getKey()))).append("\":");
                sb.append(toJson(entry.getValue()));
                first = false;
            }
            sb.append("}");
            return sb.toString();
        } else {
            return "\"" + escapeJsonString(obj.toString()) + "\"";
        }
    }

    static String escapeJsonString(String s) {
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            switch (c) {
                case '"':
                    sb.append("\\\"");
                    break;
                case '\\':
                    sb.append("\\\\");
                    break;
                case '\n':
                    sb.append("\\n");
                    break;
                case '\r':
                    sb.append("\\r");
                    break;
                case '\t':
                    sb.append("\\t");
                    break;
                default:
                    if (c < 32) {
                        sb.append("\\u").append(String.format("%04x", (int) c));
                    } else {
                        sb.append(c);
                    }
            }
        }
        return sb.toString();
    }

