    static String executeTool(String id, String name, String inputJson) {
        Map<String, Object> input = parseJson(inputJson);

        if (name.equals("measure")) {
            Object textObj = input.get("text");
            Object unitObj = input.get("unit");
            if (textObj == null || unitObj == null) {
                return "measure error: missing fields";
            }
            String text = textObj.toString();
            String unit = unitObj.toString();

            int result;
            switch (unit) {
                case "code_points":
                    result = text.length();
                    break;
                case "utf8_bytes":
                    result = text.getBytes(StandardCharsets.UTF_8).length;
                    break;
                case "utf16_units":
                    result = countUtf16Units(text);
                    break;
                default:
                    return "unsupported unit: " + unit;
            }

            return String.valueOf(result);
        } else if (name.equals("reverse")) {
            String text = input.get("text").toString();
            return reverseCodePoints(text);
        } else {
            return "unknown tool: " + name;
        }
    }

    static int countUtf16Units(String text) {
        int count = 0;
        for (char c : text.toCharArray()) {
            count++;
            if (c > 0xFFFF) {
                count++;
            }
        }
        return count;
    }

    static String reverseCodePoints(String text) {
        StringBuilder sb = new StringBuilder();
        for (int i = text.length() - 1; i >= 0; i--) {
            char c = text.charAt(i);
            if (c > 0xFFFF) {
                // Surrogate pair
                sb.append(text.charAt(i + 1));
                sb.append(text.charAt(i));
                i--;
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }

    static List<ContentBlock> parseContentBlocks(String response) {
        List<ContentBlock> blocks = new ArrayList<>();
        int index = 0;
        StringBuilder thinking = new StringBuilder();
        StringBuilder signature = new StringBuilder();
        StringBuilder text = new StringBuilder();
        StringBuilder inputJson = new StringBuilder();
        boolean isThinking = false;
        boolean isSignature = false;
        boolean isText = false;
        boolean isInputJson = false;
        boolean isToolUse = false;

        String[] lines = response.split("\n");
        for (String line : lines) {
            if (line.trim().startsWith("data:")) {
                String data = line.trim().substring(5);
                if (data.startsWith("\"")) {
                    try {
                        Map<String, Object> dataObj = parseJson(data);
                        String type = (String) dataObj.get("type");

                        if (type.equals("thinking")) {
                            thinking.append(dataObj.get("thinking").toString());
                            isThinking = true;
                            isSignature = false;
                            isText = false;
                            isInputJson = false;
                            isToolUse = false;
                        } else if (type.equals("signature")) {
                            signature.append(dataObj.get("signature").toString());
                            isThinking = false;
                            isSignature = true;
                            isText = false;
                            isInputJson = false;
                            isToolUse = false;
                        } else if (type.equals("text")) {
                            text.append(dataObj.get("text").toString());
                            isThinking = false;
                            isSignature = false;
                            isText = true;
                            isInputJson = false;
                            isToolUse = false;
                        } else if (type.equals("input_json_delta")) {
                            inputJson.append(dataObj.get("partial_json").toString());
                            isThinking = false;
                            isSignature = false;
                            isText = false;
                            isInputJson = true;
                            isToolUse = false;
                        } else if (type.equals("tool_use")) {
                            String id = (String) dataObj.get("id");
                            String name = (String) dataObj.get("name");
                            isThinking = false;
                            isSignature = false;
                            isText = false;
                            isInputJson = false;
                            isToolUse = true;
                            blocks.add(new ContentBlock(index++, "tool_use", thinking.toString(), signature.toString(), text.toString(), id, name, inputJson.toString()));
                            thinking = new StringBuilder();
                            signature = new StringBuilder();
                            text = new StringBuilder();
                            inputJson = new StringBuilder();
                        }
                    } catch (Exception e) {
                        // Ignore parsing errors
                    }
                }
            }
        }

        // Add last block if it's a tool_use
        if (isToolUse) {
            blocks.add(new ContentBlock(index, "tool_use", thinking.toString(), signature.toString(), text.toString(), null, null, inputJson.toString()));
        }

        return blocks;
    }

    static Object convertBlockToContent(ContentBlock block) {
        if (block.type.equals("thinking")) {
            return Map.of("type", "thinking", "thinking", block.thinking, "signature", block.signature);
        } else if (block.type.equals("text")) {
            return Map.of("type", "text", "text", block.text);
        } else if (block.type.equals("tool_use")) {
            return Map.of("type", "tool_use", "id", block.id, "name", block.name, "input", parseJson(block.inputJson));
        }
        return null;
    }

    static void printBlock(ContentBlock block, List<String> outputLines) {
        if (block.type.equals("thinking")) {
            outputLines.add("thinking " + block.thinking);
            outputLines.add("signature " + block.signature);
        } else if (block.type.equals("text")) {
            outputLines.add("text " + block.text);
        } else if (block.type.equals("tool_use")) {
            outputLines.add("tool_use " + block.id + " " + block.name + " " + escapeString(block.inputJson));
        }
    }
}

