    static String makeRequest(String baseUrl, String apiKey, String model, int maxTokens, int thinkingBudget, String system, List<Map<String, Object>> tools, List<Object> messages) throws Exception {
        String endpoint = baseUrl + "/v1/messages";
        StringBuilder body = new StringBuilder();
        body.append("{\"model\":\"").append(escapeJsonString(model)).append("\",\"max_tokens\":").append(maxTokens).append(",\"stream\":true,");
        body.append("\"thinking\":{\"type\":\"enabled\",\"budget_tokens\":").append(thinkingBudget).append("},");
        body.append("\"system\":\"").append(escapeJsonString(system)).append("\",");
        body.append("\"tools\":").append(toJson(tools)).append(",");
        body.append("\"messages\":").append(toJson(messages)).append("}");

        URL url = new URL(endpoint);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("POST");
        conn.setRequestProperty("Host", url.getHost());
        conn.setRequestProperty("Content-Length", String.valueOf(body.length()));
        conn.setRequestProperty("x-api-key", apiKey);
        conn.setRequestProperty("anthropic-version", "2023-06-01");
        conn.setRequestProperty("content-type", "application/json");
        conn.setDoOutput(true);

        try (OutputStream os = conn.getOutputStream()) {
            byte[] input = body.toString().getBytes(StandardCharsets.UTF_8);
            os.write(input, 0, input.length);
        }

        int status = conn.getResponseCode();

        if (status == 200) {
            return new String(conn.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
        } else {
            StringBuilder errorBody = new StringBuilder();
            try (InputStream is = conn.getErrorStream()) {
                if (is != null) {
                    byte[] buf = new byte[4096];
                    int len;
                    while ((len = is.read(buf)) != -1) {
                        errorBody.append(new String(buf, 0, len, StandardCharsets.UTF_8));
                    }
                }
            }
            System.out.println(errorBody.toString());
            System.out.println("ERROR " + status + " error: " + errorBody.toString());
            System.exit(0);
        }
    }

    static void parseSseResponse(String response, Usage usage, List<ContentBlock> blocks, String stopReason) {
        int lineStart = 0;
        while ((lineStart = response.indexOf('\n', lineStart)) >= 0) {
            int lineEnd = lineStart + 1;
            if (lineEnd < response.length() && response.charAt(lineEnd) == '\r') {
                lineEnd++;
            }
            String line = response.substring(lineStart + 1, lineEnd);
            if (line.trim().startsWith("data:")) {
                String data = line.trim().substring(5);
                if (data.startsWith("\"")) {
                    try {
                        Object dataObj = parseJson(data);
                        processSseEvent(dataObj, usage, blocks, stopReason);
                    } catch (Exception e) {
                        // Ignore parsing errors
                    }
                }
            }
            lineStart = lineEnd;
        }
    }

    static void processSseEvent(Object data, Usage usage, List<ContentBlock> blocks, String stopReason) {
        Map<String, Object> dataMap = (Map<String, Object>) data;
        String type = (String) dataMap.get("type");
        String eventName = (String) dataMap.get("event");

        if (eventName == null || eventName.equals("ping")) {
            return;
        }

        if (eventName.equals("message_start")) {
            Map<String, Object> usageMap = (Map<String, Object>) dataMap.get("usage");
            if (usageMap != null) {
                Integer inputTokens = (Integer) usageMap.get("input_tokens");
                Integer cacheReadInputTokens = (Integer) usageMap.get("cache_read_input_tokens");
                if (inputTokens != null) {
                    usage.inputTokens += inputTokens;
                }
                if (cacheReadInputTokens != null) {
                    usage.cacheReadInputTokens += cacheReadInputTokens;
                }
            }
        } else if (eventName.equals("content_block_start")) {
            Map<String, Object> block = (Map<String, Object>) dataMap.get("content_block");
            Integer index = (Integer) dataMap.get("index");
            String blockType = (String) block.get("type");
            if (blockType.equals("thinking")) {
                blocks.add(new ContentBlock(index, "thinking", "", "", "", null, null, null));
            } else if (blockType.equals("text")) {
                blocks.add(new ContentBlock(index, "text", "", "", "", null, null, null));
            } else if (blockType.equals("tool_use")) {
                String id = (String) block.get("id");
                String name = (String) block.get("name");
                blocks.add(new ContentBlock(index, "tool_use", "", "", "", id, name, null));
            }
        } else if (eventName.equals("content_block_delta")) {
            Map<String, Object> delta = (Map<String, Object>) dataMap.get("delta");
            String dType = (String) delta.get("type");
            Integer index = (Integer) dataMap.get("index");
            if (dType.equals("thinking_delta")) {
                String thinking = (String) delta.get("thinking");
                for (ContentBlock block : blocks) {
                    if (block.getType().equals("thinking")) {
                        block.thinking += thinking;
                    }
                }
            } else if (dType.equals("signature_delta")) {
                String signature = (String) delta.get("signature");
                for (ContentBlock block : blocks) {
                    if (block.getType().equals("thinking")) {
                        block.signature += signature;
                    }
                }
            } else if (dType.equals("text_delta")) {
                String text = (String) delta.get("text");
                for (ContentBlock block : blocks) {
                    if (block.getType().equals("text")) {
                        block.text += text;
                    }
                }
            } else if (dType.equals("input_json_delta")) {
                String partialJson = (String) delta.get("partial_json");
                for (ContentBlock block : blocks) {
                    if (block.getType().equals("tool_use")) {
                        block.inputJson += partialJson;
                    }
                }
            }
        } else if (eventName.equals("content_block_stop")) {
            // Block completed
        } else if (eventName.equals("message_delta")) {
            Map<String, Object> delta = (Map<String, Object>) dataMap.get("delta");
            String stopReasonStr = (String) delta.get("stop_reason");
            stopReason = stopReasonStr;
            Map<String, Object> usageMap = (Map<String, Object>) dataMap.get("usage");
            if (usageMap != null) {
                Integer outputTokens = (Integer) usageMap.get("output_tokens");
                if (outputTokens != null) {
                    usage.outputTokens += outputTokens;
                }
            }
        } else if (eventName.equals("message_stop")) {
            // End of message
        }
    }

    static String toJson(Object obj) {
        if (obj == null) {
            return "null";
        } else if (obj instanceof String) {
            return "\"" + escapeJsonString((String) obj) + "\"";
        } else if (obj instanceof Integer) {
            return String.valueOf((Integer) obj);
        } else if (obj instanceof Long) {
            return String.valueOf((Long) obj);
        } else if (obj instanceof Double) {
            return String.valueOf((Double) obj);
        } else if (obj instanceof Boolean) {
            return (Boolean) obj ? "true" : "false";
        } else if (obj instanceof List) {
            StringBuilder sb = new StringBuilder("[");
            boolean first = true;
            for (Object item : (List<?>) obj) {
                if (!first) {
                    sb.append(",");
                }
                sb.append(toJson(item));
                first = false;
            }
            sb.append("]");
            return sb.toString();
        } else if (obj instanceof Map) {
            StringBuilder sb = new StringBuilder("{");
            boolean first = true;
            for (Map.Entry<?, ?> entry : ((Map<?, ?>) obj).entrySet()) {
                if (!first) {
                    sb.append(",");
                }
                sb.append("\"").append(escapeJsonString(String.valueOf(entry.getKey()))).append("\":");
                sb.append(toJson(entry.getValue()));
                first = false;
            }
            sb.append("}");
            return sb.toString();
        } else {
            return "\"" + escapeJsonString(obj.toString()) + "\"";
        }
    }

    static String escapeJsonString(String s) {
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            switch (c) {
                case '"':
                    sb.append("\\\"");
                    break;
                case '\\':
                    sb.append("\\\\");
                    break;
                case '\n':
                    sb.append("\\n");
                    break;
                case '\r':
                    sb.append("\\r");
                    break;
                case '\t':
                    sb.append("\\t");
                    break;
                default:
                    if (c < 32) {
                        sb.append("\\u").append(String.format("%04x", (int) c));
                    } else {
                        sb.append(c);
                    }
            }
        }
        return sb.toString();
    }

    static void printBlock(ContentBlock block) {
        if (block.getType().equals("thinking")) {
            outputLines.add("thinking " + escapeString(block.thinking));
            outputLines.add("signature " + escapeString(block.signature));
        } else if (block.getType().equals("text")) {
            outputLines.add("text " + escapeString(block.text));
        } else if (block.getType().equals("tool_use")) {
            outputLines.add("tool_use " + block.id + " " + block.name + " " + escapeString(block.inputJson));
        }
    }

    static String executeTool(String id, String name, String inputJson) {
        Map<String, Object> input = parseJson(inputJson);

        if (name.equals("measure")) {
            Object textObj = input.get("text");
            Object unitObj = input.get("unit");
            if (textObj == null || unitObj == null) {
                return "measure error: missing fields";
            }
            String text = textObj.toString();
            String unit = unitObj.toString();

            int result;
            switch (unit) {
                case "code_points":
                    result = text.length();
                    break;
                case "utf8_bytes":
                    result = text.getBytes(StandardCharsets.UTF_8).length;
                    break;
                case "utf16_units":
                    result = countUtf16Units(text);
                    break;
                default:
                    return "unsupported unit: " + unit;
            }

            return String.valueOf(result);
        } else if (name.equals("reverse")) {
            String text = input.get("text").toString();
            return reverseCodePoints(text);
        } else {
            return "unknown tool: " + name;
        }
    }

    static int countUtf16Units(String text) {
        int count = 0;
        int i = 0;
        while (i < text.length()) {
            int charCode = text.codePointAt(i);
            count++;
            if (charCode > 0xFFFF) {
                count++;
                i++;
            }
            i += Character.charCount(charCode);
        }
        return count;
    }

    static String reverseCodePoints(String text) {
        int[] codePoints = new int[text.length()];
        int cpCount = 0;
        int i = 0;
        while (i < text.length()) {
            codePoints[cpCount++] = text.codePointAt(i);
            i += Character.charCount(codePoints[cpCount - 1]);
        }
        int j = cpCount - 1;
        StringBuilder sb = new StringBuilder();
        while (j >= 0) {
            int cp = codePoints[j--];
            if (cp > 0xFFFF) {
                sb.appendCodePoint(cp);
            } else {
                sb.append((char) cp);
            }
        }
        return sb.toString();
    }

    static Object convertBlockToContent(ContentBlock block) {
        if (block.getType().equals("thinking")) {
            return Map.of("type", "thinking", "thinking", block.thinking, "signature", block.signature);
        } else if (block.getType().equals("text")) {
            return Map.of("type", "text", "text", block.text);
        } else if (block.getType().equals("tool_use")) {
            return Map.of("type", "tool_use", "id", block.id, "name", block.name, "input", parseJson(block.inputJson));
        }
        return null;
    }
