    int start;
    int end;
} Span;

typedef struct {
    int start;
    int end;
} GroupSpan;

typedef struct {
    int min;
    int max;
    int is_lazy;
} Quantifier;

typedef struct {
    char type; // 'c' for char, 'd' for digit, 'w' for word, 's' for space, 'C' for class, 'g' for group, 'n' for non-capturing, 'p' for literal
    int start_pos; // for classes
    int char_val;
    int min;
    int max;
    int is_lazy;
    int group_id;
    Span span;
} Atom;

typedef struct {
    Atom *atoms;
    int num_atoms;
    int num_groups;
} Pattern;

typedef struct {
    int start;
    int end;
} Match;

static Pattern *parse_pattern(const char *pattern, int *num_atoms);
static int match_nfa(const char *subject, int subject_len, const Pattern *pat, Match *match, GroupSpan *groups, int num_groups);
static int match_atom(const char *subject, int subject_len, const Atom *atom, int pos, int *new_pos, Span *span, int *group_match);
static void reset_match(Match *match, GroupSpan *groups, int num_groups);

int main(int argc, char *argv[]) {
    if (argc < 2) {
        return 1;
    }

    const char *dir = argv[1];
    FILE *f = fopen((char *)dir, "r");
    if (!f) {
        return 1;
    }

    int line_num = 0;
    char line[200];
    char *line_copy = NULL;
    size_t line_cap = 0;

    while (fgets(line, sizeof(line), f)) {
        line_num++;
        size_t len = strlen(line);
        if (len > 0 && line[len-1] == '\n') {
            line[len-1] = '\0';
            len--;
        }

        if (len == 0) continue;

        // Find TAB separator
        char *tab = strchr(line, '\t');
        if (!tab) {
            fprintf(stderr, "Line %d: missing TAB separator\n", line_num);
            fclose(f);
            return 1;
        }

        *tab = '\0';
        const char *pattern = line;
        const char *subject = tab + 1;

        Pattern *pat = parse_pattern(pattern, NULL);

        Match match;
        GroupSpan *groups = NULL;

        if (match_nfa(subject, strlen(subject), pat, &match, &groups, MAX_GROUPS)) {
            printf("%d: %d-%d", line_num, match.start, match.end);
            if (groups) {
                for (int i = 0; i < MAX_GROUPS; i++) {
                    if (groups[i].start >= 0) {
                        printf(" %d-%d", groups[i].start, groups[i].end);
                    } else {
                        printf(" -");
                    }
                }
            }
            printf("\n");
        } else {
            printf("%d: no match\n", line_num);
        }

        if (pat) free(pat);
        if (groups) free(groups);
    }

    fclose(f);
    return 0;
}

static int match_atom(const char *subject, int subject_len, const Atom *atom, int pos, int *new_pos, Span *span, int *group_match) {
    int match_len = 0;
    int start = pos;

    switch (atom->type) {
        case 'c': // literal char
            if (pos >= subject_len || subject[pos] != atom->char_val) return 0;
            match_len = 1;
            break;
        case 'd': // digit
            if (pos >= subject_len || !isdigit((unsigned char)subject[pos])) return 0;
            match_len = 1;
            break;
        case 'w': // word char
            if (pos >= subject_len || !isalnum((unsigned char)subject[pos]) && subject[pos] != '_') return 0;
            match_len = 1;
            break;
        case 's': // space (whitespace)
            if (pos >= subject_len || !isspace((unsigned char)subject[pos])) return 0;
            match_len = 1;
            break;
        case 'C': // class
            if (pos >= subject_len) return 0;
            char c = subject[pos];
            int in_class = 0;
            int neg = atom->char_val == 0; // 0 means negated class
            int i = 0;
            // Check if first char is escaped
            if (c == '\\') {
                c = subject[++pos];
                if (c == 'd') { in_class = 1; }
                else if (c == 'w') { in_class = 1; }
                else if (c == 's') { in_class = 1; }
                else if (c == 'D') { in_class = 1; neg = 1; }
                else if (c == 'W') { in_class = 1; neg = 1; }
                else if (c == 'S') { in_class = 1; neg = 1; }
                else {
                    // literal escaped char
                    if (neg) { in_class = 0; }
                    else { in_class = 1; }
                }
            } else {
                if (neg) { in_class = 0; }
                else { in_class = 1; }
            }
            if (!in_class) {
                *new_pos = pos + 1;
                span->start = pos;
                span->end = pos + 1;
                return 1;
            }
            // Check if it's negated class
            int is_neg = 0;
            if (atom->char_val == 0 && subject[start] == '[') {
                is_neg = 1;
            }
            if (is_neg) {
                for (i = 0; i < atom->num_ranges; i++) {
                    if (subject[pos] >= atom->range_start[i] && subject[pos] <= atom->range_end[i]) {
                        *new_pos = pos + 1;
                        span->start = pos;
                        span->end = pos + 1;
                        return 1;
                    }
                }
                *new_pos = pos + 1;
                span->start = pos;
                span->end = pos + 1;
                return 1;
            }
            // Positive class
            for (i = 0; i < atom->num_ranges; i++) {
                if (subject[pos] >= atom->range_start[i] && subject[pos] <= atom->range_end[i]) {
                    *new_pos = pos + 1;
                    span->start = pos;
                    span->end = pos + 1;
                    return 1;
                }
            }
            *new_pos = pos + 1;
            span->start = pos;
            span->end = pos + 1;
            return 1;
        case 'g': // group
            if (pos >= subject_len) return 0;
            *new_pos = pos + 1;
            span->start = pos;
            span->end = pos + 1;
            return 1;
        case 'n': // non-capturing
            if (pos >= subject_len) return 0;
            *new_pos = pos + 1;
            span->start = pos;
            span->end = pos + 1;
            return 1;
        case 'p': // literal (escaped)
            if (pos >= subject_len || subject[pos] != atom->char_val) return 0;
            match_len = 1;
            break;
        case '.': // any char
            if (pos >= subject_len) return 0;
            match_len = 1;
            break;
        case '^': // start anchor
            if (pos != 0) return 0;
            match_len = 0;
            break;
        case '$': // end anchor
            if (pos != subject_len) return 0;
            match_len = 0;
            break;
    }

    if (match_len == 0) {
        *new_pos = pos;
        span->start = -1;
        span->end = -1;
        return 1; // anchor
    }

    *new_pos = pos + match_len;
    span->start = start;
    span->end = start + match_len;
    return 1;
}

static int match_piece(const char *subject, int subject_len, const Atom *piece, int pos, int *new_pos, Span *span, GroupSpan *groups, int num_groups) {
    int count = 0;
    int min_count = piece->min;
    int max_count = piece->max;
    int is_lazy = piece->is_lazy;

    int current_pos = pos;
    Span current_span;
    current_span.start = -1;
    current_span.end = -1;

    int matched_group = -1;

    while (count < max_count) {
        int next_pos;
        Span temp_span;
        int group_result;

        if (!match_atom(subject, subject_len, piece, current_pos, &next_pos, &temp_span, &group_result)) {
            break;
        }

        if (!is_lazy) {
            // Greedy: try to match more
            count++;
            current_pos = next_pos;
            current_span = temp_span;
            if (group_result >= 0) matched_group = group_result;
        } else {
            // Lazy: stop if we've matched minimum
            if (count >= min_count) {
                break;
            }
            count++;
            current_pos = next_pos;
            current_span = temp_span;
            if (group_result >= 0) matched_group = group_result;
        }
    }

    if (is_lazy && count < max_count && count >= min_count) {
        // Lazy quantifier with optional iterations
        if (min_count > 0) {
            // If we matched minimum, we're done
            // But if we could have matched more, we should try
        }
    }

    *new_pos = current_pos;
    span->start = current_span.start;
    span->end = current_span.end;

    if (matched_group >= 0) {
        groups[matched_group].start = current_span.start;
        groups[matched_group].end = current_span.end;
    }

    return 1;
}

static int match_branch(const char *subject, int subject_len, Atom *pieces, int num_pieces, int pos, int *new_pos, Span *span, GroupSpan *groups, int num_groups) {
    int current_pos = pos;
    int start_pos = pos;
    Span start_span;
    start_span.start = -1;
    start_span.end = -1;

    int i = 0;
    while (i < num_pieces) {
        Atom *piece = &pieces[i];
        int next_pos;
        Span temp_span;
        int group_result;

        if (!match_atom(subject, subject_len, piece, current_pos, &next_pos, &temp_span, &group_result)) {
            break;
        }

        current_pos = next_pos;
        start_span.start = start_pos;
        start_span.end = current_pos;

        if (piece->group_id >= 0) {
            groups[piece->group_id].start = temp_span.start;
            groups[piece->group_id].end = temp_span.end;
        }

        i++;
    }

    *new_pos = current_pos;
    span->start = start_span.start;
    span->end = start_span.end;

    return i == num_pieces;
}

static int match_branch_or(const char *subject, int subject_len, Atom *pieces_a, int num_a, int pos, int *new_pos, Span *span, GroupSpan *groups, int num_groups) {
    int current_pos = pos;

    // Try first branch
    int next_pos;
    Span temp_span;
    int group_result;

    if (match_branch(subject, subject_len, pieces_a, num_a, current_pos, &next_pos, &temp_span, groups, num_groups)) {
        *new_pos = next_pos;
        span->start = temp_span.start;
        span->end = temp_span.end;
        return 1;
    }

    // Try second branch
    if (match_branch(subject, subject_len, pieces_a + num_a, num_a, current_pos, &next_pos, &temp_span, groups, num_groups)) {
        *new_pos = next_pos;
        span->start = temp_span.start;
        span->end = temp_span.end;
        return 1;
    }

    return 0;
}

static int match_nfa(const char *subject, int subject_len, const Pattern *pat, Match *match, GroupSpan *groups, int num_groups) {
    int total_pos = subject_len + 1;

    for (int start = 0; start <= subject_len; start++) {
        reset_match(match, groups, num_groups);

        int current_pos = start;
        Span current_span;
        current_span.start = start;
        current_span.end = start;

        const Atom *piece = pat->atoms;
        int num_atoms = pat->num_atoms;

        int matched = 0;
        for (int i = 0; i < num_atoms; i++) {
            int next_pos;
            Span temp_span;
            int group_result;

            if (!match_atom(subject, subject_len, &piece[i], current_pos, &next_pos, &temp_span, &group_result)) {
                break;
            }

            current_pos = next_pos;
            current_span.start = temp_span.start;
            current_span.end = temp_span.end;

            if (piece[i].group_id >= 0) {
                groups[piece[i].group_id].start = temp_span.start;
                groups[piece[i].group_id].end = temp_span.end;
            }

            if (piece[i].type == 'c' || piece[i].type == 'p' || piece[i].type == 'd' || piece[i].type == 'w' || piece[i].type == 's' || piece[i].type == 'C') {
                // Consuming atom
            } else if (piece[i].type == '^') {
                if (start != 0) {
                    break;
                }
            } else if (piece[i].type == '$') {
                if (current_pos != subject_len) {
                    break;
                }
            } else if (piece[i].type == '.') {
                if (current_pos >= subject_len) {
                    break;
                }
            }
        }

        if (current_pos > start) {
            matched = 1;
        }

        if (matched) {
            match->start = start;
            match->end = current_pos;
            return 1;
        }
    }

    return 0;
}

static void reset_match(Match *match, GroupSpan *groups, int num_groups) {
    match->start = -1;
    match->end = -1;
    for (int i = 0; i < num_groups; i++) {
        groups[i].start = -1;
        groups[i].end = -1;
    }
}

