#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_PATTERN_LEN 60
#define MAX_SUBJECT_LEN 80
#define MAX_GROUPS 30
#define MAX_NODES 2000

typedef struct {
    int min;
    int max;
    int is_lazy;
} Quantifier;

typedef struct {
    int type; // 0: BRANCH, 1: PIECE, 2: ATOM, 3: GROUP
    int next; // Next node index
    int children[4]; // For BRANCH (indices of PIECE nodes)
    int atom_idx; // For PIECE (index of ATOM node)
    Quantifier quant; // For PIECE
    int atom_type; // For ATOM
    char atom_val; // For ATOM
    int group_id; // For ATOM (capturing group)
    int id; // Unique ID for memoization
} Node;

typedef struct {
    int start;
    int end;
} Span;

typedef struct {
    Span span[MAX_GROUPS];
} Captures;

Node nodes[MAX_NODES];
int node_count = 0;
int node_id_counter = 0;

// For memoization: visited[node_id][subject_pos] = 1 if failed
int visited[MAX_NODES][MAX_SUBJECT_LEN + 1];

void add_node(int type, int next) {
    int idx = node_count++;
    Node *n = &nodes[idx];
    n->type = type;
    n->next = next;
    n->id = node_id_counter++;
    n->children[0] = -1;
    n->children[1] = -1;
    n->children[2] = -1;
    n->children[3] = -1;
    n->atom_idx = -1;
    n->atom_type = -1;
    n->atom_val = 0;
    n->group_id = -1;
    n->quant.min = 0;
    n->quant.max = 1;
    n->quant.is_lazy = 0;
    return idx;
}

void add_branch(int next) {
    int idx = add_node(0, next);
    // children initialized in add_node
    return idx;
}

void add_piece(int atom_idx, Quantifier q, int next) {
    int idx = add_node(1, next);
    nodes[idx].atom_idx = atom_idx;
    nodes[idx].quant = q;
    return idx;
}

void add_atom(int type, char val, int group_id, int next) {
    int idx = add_node(2, next);
    nodes[idx].atom_type = type;
    nodes[idx].atom_val = val;
    nodes[idx].group_id = group_id;
    return idx;
}

void add_group(int next) {
    int idx = add_node(3, next);
    return idx;
}

