function crc32(data: Uint8Array): number {
    const table = new Uint32Array(256);
    for (let i = 0; i < 256; i++) {
        let c = i ^ 0xFFFFFFFF;
        for (let j = 0; j < 8; j++) {
            c = (c & 1) === 1 ? (c >>> 1) ^ 0xEDB88320 : c >>> 1;
