// Format a TEXT value for output
function formatText(value: string): string {
    if (value.length <= 100) {
        let result = '';
        for (const char of value) {
            const code = char.charCodeAt(0);
            if (code === 0x5C) {
                result += '\\\\';
            } else if (code === 0x22) {
                result += '\\\"';
            } else if (code === 0x0A) {
                result += '\\n';
            } else if (code === 0x0D) {
                result += '\\r';
            } else if (code === 0x09) {
                result += '\\t';
            } else if (code < 0x20 || code >= 0x7F) {
                result += '\\x' + code.toString(16).toUpperCase().padStart(2, '0');
            } else {
                result += char;
            }
        }
        return '"' + result + '"';
    } else {
        const crc = crc32(Buffer.from(value, 'utf8'));
        return '<TEXT len=' + value.length + ' crc32=' + crc.toString(16).toUpperCase().padStart(8, '0') + '>';
    }
}

// Format a BLOB value for output
function formatBlob(value: Uint8Array): string {
    if (value.length <= 100) {
        let result = 'X\'';
        for (const byte of value) {
            result += byte.toString(16).toUpperCase().padStart(2, '0');
        }
        result += '\'';
        return result;
    } else {
        const crc = crc32(value);
        return '<BLOB len=' + value.length + ' crc32=' + crc.toString(16).toUpperCase().padStart(8, '0') + '>';
    }
}

// Main function
async function main(): Promise<void> {
    const args = process.argv.slice(2);
