import * as fs from 'fs';
import * as path from 'path';

// CRC32 calculation (zlib/PNG style)
function crc32(data: Uint8Array): number {
    const table = new Uint32Array(256);
    for (let i = 0; i < 256; i++) {
        let c = i ^ 0xFFFFFFFF;
        for (let j = 0; j < 8; j++) {
            c = (c & 1) === 1 ? (c >>> 1) ^ 0xEDB88320 : c >>> 1;
        }
        table[i] = c ^ 0xFFFFFFFF;
    }

    let crc = 0xFFFFFFFF;
    for (let i = 0; i < data.length; i++) {
        crc = table[(crc ^ data[i]) & 0xFF] ^ (crc >>> 8);
    }
    return crc ^ 0xFFFFFFFF;
}

// Read a big-endian 24-bit integer from buffer
function readUint24(buffer: Uint8Array, offset: number): number {
    return (buffer[offset] << 16) | (buffer[offset + 1] << 8) | buffer[offset + 2];
}

// Read a big-endian 32-bit integer from buffer
function readUint32(buffer: Uint8Array, offset: number): number {
    return (buffer[offset] << 24) | (buffer[offset + 1] << 16) | (buffer[offset + 2] << 8) | buffer[offset + 3];
}

// Read a signed 64-bit integer from buffer
function readInt64(buffer: Uint8Array, offset: number): bigint {
    const low = readUint32(buffer, offset);
    const high = readUint32(buffer, offset + 4);
    const result = (BigInt(high) << 32n) | BigInt(low);
    if (high & 0x80000000) {
        return result - 0x10000000000000000n;
    }
    return result;
}

// Read a big-endian 64-bit float from buffer
function readDouble(buffer: Uint8Array, offset: number): number {
    const bytes = buffer.slice(offset, offset + 8);
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    return view.getFloat64(0, false);
}

// Read a big-endian 32-bit float from buffer
function readFloat32(buffer: Uint8Array, offset: number): number {
    const bytes = buffer.slice(offset, offset + 4);
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    return view.getFloat32(0, false);
}

// Read a big-endian 16-bit integer from buffer
function readUint16(buffer: Uint8Array, offset: number): number {
    return (buffer[offset] << 8) | buffer[offset + 1];
}

// Read a 64-bit float for output - must be exact decimal
function formatDouble(value: number): string {
    if (Number.isNaN(value)) {
        return 'NaN';
    }
    if (value === Infinity) {
        return 'Infinity';
    }
    if (value === -Infinity) {
        return '-Infinity';
    }
    if (value === 0.0) {
        return '0.0';
    }

    const intPart = Math.trunc(value);
    const fracPart = value - intPart;

    if (fracPart === 0) {
        let str = intPart.toString();
        str += '.0';
        return str;
    } else {
        // Use a high-precision approach to avoid floating point issues
        let str = intPart.toString() + '.';
        let frac = Math.abs(fracPart);
        let fracStr = '';
        for (let i = 0; i < 20; i++) {
            frac *= 10;
            const digit = Math.floor(frac);
            fracStr += digit.toString();
            frac -= digit;
            if (frac === 0) break;
        }
        str += fracStr;
        const lastDot = str.lastIndexOf('.');
        str = str.substring(0, lastDot);
        return str;
    }
}

// Read a cell from buffer
function readCell(buffer: Uint8Array, pageOffset: number, pageSize: number, cellOffset: number): { 
    type: number, 
    payload: Uint8Array, 
    overflowPages: number[] 
} {
    // Cell header: 1 byte header size, 1 byte payload size, 1 byte serial type
    const headerSize = buffer[cellOffset];
    const payloadSize = buffer[cellOffset + 1];
    const serialType = buffer[cellOffset + 2];

    // Payload starts after header
    const payloadOffset = cellOffset + headerSize;

    // Check if payload spills to overflow pages
    const overflowPages: number[] = [];

    if (headerSize > 3) {
        // First 3 bytes are header size, payload size, serial type
        // Remaining bytes in header are overflow page info
        const overflowSize = readUint24(buffer, cellOffset + 3);
        if (overflowSize > 0) {
            // Overflow page follows
            overflowPages.push(payloadOffset + 4);
        }
    }

    // Read payload
    const payload = buffer.slice(payloadOffset, payloadOffset + payloadSize);

    return {
        type: serialType,
        payload: payload,
        overflowPages: overflowPages
    };
}

// Read a table b-tree
function readTableBTree(buffer: Uint8Array, rootPage: number, pageSize: number): { 
    cells: Array<{ 
        type: number, 
        payload: Uint8Array, 
        rowid: bigint, 
        overflowPages: number[] 
    }> 
} {
    const cells: Array<{ 
        type: number, 
        payload: Uint8Array, 
        rowid: bigint, 
        overflowPages: number[] 
    }> = [];

    function readPage(pageNum: number): void {
        const pageOffset = (pageNum - 1) * pageSize;
        const page = buffer.slice(pageOffset, pageOffset + pageSize);
        const pageType = page[0];

        if (pageType === 0x0D) {
            // Leaf table page
            const numCells = readUint16(page, 1);
            const cellPtrs = page.slice(3, 3 + numCells * 2);

            for (let i = 0; i < numCells; i++) {
                const cellOffset = cellPtrs[i * 2];
                const { type, payload, overflowPages } = readCell(buffer, pageOffset, pageSize, cellOffset);

                // Rowid is stored in the payload for leaf pages
                const rowid = readInt64(buffer, pageOffset + 4);

                cells.push({
                    type,
                    payload,
                    rowid,
                    overflowPages
                });
            }
        } else if (pageType === 0x05) {
            // Interior table page
            const numCells = readUint16(page, 1);
            const cellPtrs = page.slice(3, 3 + numCells * 2);

            for (let i = 0; i < numCells; i++) {
                const cellOffset = cellPtrs[i * 2];
                const { type, payload, overflowPages } = readCell(buffer, pageOffset, pageSize, cellOffset);

                // Interior pages don't store rowids in cells, they point to child pages
                // But we need to read the rowid from the payload for the actual data
                const rowid = readInt64(buffer, pageOffset + 4);

                cells.push({
                    type,
                    payload,
                    rowid,
                    overflowPages
                });
            }

            // Recursively read child pages
            const rightPageNum = readUint24(page, 3 + numCells * 2);
            if (rightPageNum > 0) {
                readPage(rightPageNum);
            }
        }
    }

    readPage(rootPage);

    return { cells };
}

// Parse CREATE TABLE statement to extract column info
function parseCreateTable(sql: string): { columns: string[], isRowidAlias: boolean[] } {
    const match = sql.match(/CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?["']?([^"']+)["']?\s*\((.*)\)/i);
    if (!match) return { columns: [], isRowidAlias: [] };

    const defs = match[2];

    // Parse column definitions
    const columns: string[] = [];
    const isRowidAlias: boolean[] = [];

    // Simple tokenizer to handle commas outside parentheses
    const tokens: string[] = [];
    let depth = 0;
    let current = '';

    for (const char of defs) {
        if (char === '(') {
            depth++;
            current += char;
        } else if (char === ')') {
            depth--;
            current += char;
        } else if (char === ',' && depth === 0) {
            if (current.trim()) {
                tokens.push(current.trim());
            }
            current = '';
        } else {
            current += char;
        }
    }
    if (current.trim()) {
        tokens.push(current.trim());
    }

    for (const token of tokens) {
        // Extract column name
        const nameMatch = token.match(/^["']?([^"']+)["']?\s*(.*)$/);
        if (nameMatch) {
            const colName = nameMatch[1];
            const rest = nameMatch[2];

            columns.push(colName);

            // Check if this is a rowid alias
            // Must be INTEGER (case insensitive) and PRIMARY KEY
            const typeMatch = rest.match(/^\s*(INTEGER|INT|BIGINT|SMALLINT|TINYINT)\s*(.*)/i);
            const isPkMatch = rest.includes('PRIMARY KEY');
            const isRowid = typeMatch && typeMatch[1].toUpperCase() === 'INTEGER' && isPkMatch;

            isRowidAlias.push(isRowid);
        }
    }

    return { columns, isRowidAlias };
}

// Read the schema table
function readSchemaTable(buffer: Uint8Array, pageSize: number): Array<{ type: string, name: string, tbl_name: string, rootpage: number, sql: string }> {
    const cells: Array<{ type: number, payload: Uint8Array, rowid: bigint, overflowPages: number[] }> = [];

    function readPage(pageNum: number): void {
        const pageOffset = (pageNum - 1) * pageSize;
        const page = buffer.slice(pageOffset, pageOffset + pageSize);
        const pageType = page[0];

        if (pageType === 0x0D) {
            // Leaf table page
            const numCells = readUint16(page, 1);
            const cellPtrs = page.slice(3, 3 + numCells * 2);

            for (let i = 0; i < numCells; i++) {
                const cellOffset = cellPtrs[i * 2];
                const { type, payload, overflowPages } = readCell(buffer, pageOffset, pageSize, cellOffset);

                const rowid = readInt64(buffer, pageOffset + 4);

                cells.push({
                    type,
                    payload,
                    rowid,
                    overflowPages
                });
            }
        } else if (pageType === 0x05) {
            // Interior table page
            const numCells = readUint16(page, 1);
            const cellPtrs = page.slice(3, 3 + numCells * 2);

            for (let i = 0; i < numCells; i++) {
                const cellOffset = cellPtrs[i * 2];
                const { type, payload, overflowPages } = readCell(buffer, pageOffset, pageSize, cellOffset);

                const rowid = readInt64(buffer, pageOffset + 4);

                cells.push({
                    type,
                    payload,
                    rowid,
                    overflowPages
                });
            }

            const rightPageNum = readUint24(page, 3 + numCells * 2);
            if (rightPageNum > 0) {
                readPage(rightPageNum);
            }
        }
    }

    readPage(1);

    const schema: Array<{ type: string, name: string, tbl_name: string, rootpage: number, sql: string }> = [];

    for (const cell of cells) {
        const payloadSize = cell.payload.length;
        if (payloadSize === 0) continue;

        const header = cell.payload;
        const payloadOffset = payloadSize;
        const payload = buffer.slice(payloadOffset, payloadOffset + payloadSize);

        const type = header[0];
        const nameLen = readUint24(header, 1);
        const name = header.slice(1, 1 + nameLen).toString('utf8');
        const tblNameLen = readUint24(header, 1 + nameLen);
        const tblName = header.slice(1 + nameLen, 1 + nameLen + tblNameLen).toString('utf8');
        const rootpage = readUint32(header, 1 + nameLen + tblNameLen);
        const sqlLen = readUint32(header, 1 + nameLen + tblNameLen + 4);
        const sql = header.slice(1 + nameLen + tblNameLen + 4, 1 + nameLen + tblNameLen + 4 + sqlLen).toString('utf8');

        schema.push({ type, name, tbl_name: tblName, rootpage, sql });
    }

    return schema;
}

// Format a TEXT value for output
function formatText(value: string): string {
    if (value.length <= 100) {
        let result = '';
        for (const char of value) {
            const code = char.charCodeAt(0);
            if (code === 0x5C) {
                result += '\\\\';
            } else if (code === 0x22) {
                result += '\\\"';
            } else if (code === 0x0A) {
                result += '\\n';
            } else if (code === 0x0D) {
                result += '\\r';
            } else if (code === 0x09) {
                result += '\\t';
            } else if (code < 0x20 || code >= 0x7F) {
                result += '\\x' + code.toString(16).toUpperCase().padStart(2, '0');
            } else {
                result += char;
            }
        }
        return '"' + result + '"';
    } else {
        const crc = crc32(Buffer.from(value, 'utf8'));
        return '<TEXT len=' + value.length + ' crc32=' + crc.toString(16).toUpperCase().padStart(8, '0') + '>';
    }
}

// Format a BLOB value for output
function formatBlob(value: Uint8Array): string {
    if (value.length <= 100) {
        let result = 'X\'';
        for (const byte of value) {
            result += byte.toString(16).toUpperCase().padStart(2, '0');
        }
        result += '\'';
        return result;
    } else {
        const crc = crc32(value);
        return '<BLOB len=' + value.length + ' crc32=' + crc.toString(16).toUpperCase().padStart(8, '0') + '>';
    }
}

// Format a value for output
function formatValue(value: string | number | bigint | Uint8Array | null, type: number): string {
    if (value === null) {
        return 'NULL';
    }

    if (type === 0) {
        // NULL
        return 'NULL';
    } else if (type === 1) {
        // 8-bit signed integer
        return value.toString();
    } else if (type === 2) {
        // 16-bit signed integer
        return value.toString();
    } else if (type === 3) {
        // 24-bit signed integer
        return value.toString();
    } else if (type === 4) {
        // 32-bit signed integer
        return value.toString();
    } else if (type === 5) {
        // 48-bit signed integer
        return value.toString();
    } else if (type === 6) {
        // 64-bit signed integer
        return value.toString();
    } else if (type === 7) {
        // IEEE 754 64-bit float
        const num = readDouble(value as Uint8Array, 0);
        return formatDouble(num);
    } else if (type === 8) {
        // 0 or 1
        return (value as number) === 0 ? '0' : '1';
    } else if (type === 9) {
        // 32-bit IEEE 754 float
        const num = readFloat32(value as Uint8Array, 0);
        const intPart = Math.trunc(num);
        const fracPart = num - intPart;
        if (fracPart === 0) {
            return intPart.toString();
        }
        let str = intPart.toString() + '.';
        let frac = Math.abs(fracPart);
        let fracStr = '';
        for (let i = 0; i < 20; i++) {
            frac *= 10;
            const digit = Math.floor(frac);
            fracStr += digit.toString();
            frac -= digit;
            if (frac === 0) break;
        }
        str += fracStr;
        const lastDot = str.lastIndexOf('.');
        str = str.substring(0, lastDot);
        return str;
    } else if (type === 10) {
        // 64-bit IEEE 754 float
        const num = readDouble(value as Uint8Array, 0);
        return formatDouble(num);
    } else if (type === 11) {
        // 128-bit IEEE 754 float
        const num = readDouble(value as Uint8Array, 0);
        return formatDouble(num);
    } else if (type >= 12) {
        // Unsigned integers
        const num = value as number;
        if (type >= 12 && type <= 16) {
            return num.toString();
        } else if (type >= 17) {
            // 128-bit unsigned integer - need to handle as BigInt
            const high = readUint32(value as Uint8Array, 0);
            const low = readUint32(value as Uint8Array, 4);
            const result = (BigInt(high) << 32n) | BigInt(low);
            return result.toString();
        }
        return 'NULL';
    }

    return 'NULL';
}

