import http from 'http';
import https from 'https';
import fs from 'fs';

function escape(str: string): string {
    let res = '';
    for (const c of str) {
        if (c === '\\') res += '\\\\';
        else if (c === '\n') res += '\\n';
        else if (c === '\r') res += '\\r';
        else if (c === '\t') res += '\\t';
        else res += c;
    }
    return res;
}

function measure(text: string, unit: string): string {
    if (unit === 'code_points') {
        return String(text.length);
    } else if (unit === 'utf8_bytes') {
        return String(Buffer.from(text, 'utf8').length);
    } else if (unit === 'utf16_units') {
        return String(text.length);
    } else {
        return `unsupported unit: ${unit}`;
    }
}

function reverse(text: string): string {
    return [...text].reverse().join('');
}

interface ContentBlock {
    type: 'thinking' | 'text' | 'tool_use';
    thinking?: string;
    signature?: string;
    text?: string;
    id?: string;
    name?: string;
    input?: any;
}

interface ToolResult {
    id: string;
    result: string;
    isError: boolean;
}

function run(dataDir: string, baseUrl: string): void {
    let outputLines: string[] = [];
    let usageInput: number = 0;
    let usageOutput: number = 0;
    let usageCacheRead: number = 0;

    const output = (line: string) => {
        outputLines.push(line);
    };

    const printOutput = () => {
        output(outputLines.join('\n'));
    };

    const readRequestJson = () => {
        const json = fs.readFileSync(`${dataDir}/request.json`, 'utf8');
        return JSON.parse(json);
    };

    const parseSSE = (bodyBuffer: Buffer): { events: { type: string; data: string[] }[] } => {
        let events: { type: string; data: string[] }[] = [];
        let currentEvent: { type: string; data: string[] } | null = null;
        let pendingLine = '';

        const processLine = (line: string) => {
            if (line.startsWith(':')) {
                // comment
                return;
            }
            if (line.startsWith('event:')) {
                currentEvent = { type: line.slice(6).trim(), data: [] };
            } else if (line.startsWith('data:')) {
                let data = line.slice(5).trim();
                if (data === '') {
                    // empty data line, ignore
                } else if (currentEvent && currentEvent.type) {
                    currentEvent.data.push(data);
                }
            } else if (line === '') {
                if (currentEvent && currentEvent.type) {
                    events.push({ type: currentEvent.type, data: currentEvent.data.join('\n') });
                    currentEvent = null;
                }
            }
        };

        let buffer = '';
        const str = bodyBuffer.toString('utf8');
        // Split by \n
        let parts = str.split('\n');

        for (let i = 0; i < parts.length; i++) {
            let line = parts[i];
            // Remove trailing \r
            if (line.endsWith('\r')) {
                line = line.slice(0, -1);
            }
            processLine(line);
        }

        return events;
    };

    const sendRequest = async (
        messages: any[],
        isSecondRequest: boolean
    ): Promise<{ blocks: ContentBlock[]; results: ToolResult[] }> => {
        const reqData = readRequestJson();
        const api_key = reqData.api_key;
        const model = reqData.model;
        const max_tokens = reqData.max_tokens;
        const thinking_budget = reqData.thinking_budget;
        const system = reqData.system;
        const tools = reqData.tools;

        let body: any = {
            model: model,
            max_tokens: max_tokens,
            stream: true,
            thinking: { type: 'enabled', budget_tokens: thinking_budget },
            system: system,
            tools: tools,
            messages: messages
        };

        const bodyStr = JSON.stringify(body);
        const contentLength = bodyStr.length;

        const url = new URL(baseUrl + '/v1/messages');
        const options: any = {
            hostname: url.hostname,
            port: url.port || (url.protocol === 'https:' ? 443 : 80),
            path: url.pathname + url.search,
            method: 'POST',
            headers: {
                'Host': url.host,
                'Content-Length': contentLength,
                'x-api-key': api_key,
                'anthropic-version': '2023-06-01',
                'content-type': 'application/json'
            }
        };

        return new Promise((resolve, reject) => {
            const client = url.protocol === 'https:' ? https : http;
            const req = client.request(options, (res) => {
                let bodyBuffer = Buffer.alloc(0);
                let errorData: any = null;
                let status = res.statusCode;

                res.on('data', (chunk) => {
                    bodyBuffer = Buffer.concat([bodyBuffer, chunk]);
                });

                res.on('end', () => {
                    if (status !== 200) {
                        // Error response
                        const errorBody = bodyBuffer.toString('utf8');
                        try {
                            const error = JSON.parse(errorBody);
                            printOutput();
                            output(`ERROR ${status} ${error.error.type}: ${error.error.message}`);
                            process.exit(0);
                        } catch (e) {
                            printOutput();
                            output(`ERROR ${status} error: ${errorBody}`);
                            process.exit(0);
                        }
                        return;
                    }

                    // Success response
                    const events = parseSSE(bodyBuffer);
                    let blocks: ContentBlock[] = [];
                    let results: ToolResult[] = [];
                    let currentBlock: ContentBlock | null = null;
                    let currentBlockIndex: number = -1;
                    let currentBlockType: string = '';
                    let currentBlockThinking: string = '';
                    let currentBlockSignature: string = '';
                    let currentBlockText: string = '';
                    let currentBlockInput: string = '';

