function escape(str: string): string {
    let res = '';
    for (const c of str) {
        if (c === '\\') res += '\\\\';
        else if (c === '\n') res += '\\n';
        else if (c === '\r') res += '\\r';
        else if (c === '\t') res += '\\t';
        else res += c;
    }
    return res;
}

function measure(text: string, unit: string): string {
    if (unit === 'code_points') {
        return String(text.length);
    } else if (unit === 'utf8_bytes') {
        return String(Buffer.from(text, 'utf8').length);
    } else if (unit === 'utf16_units') {
        return String(text.length);
    } else {
        return `unsupported unit: ${unit}`;
    }
}

function reverse(text: string): string {
    return [...text].reverse().join('');
}

interface ContentBlock {
    type: 'thinking' | 'text' | 'tool_use';
    thinking?: string;
    signature?: string;
    text?: string;
    id?: string;
    name?: string;
    input?: any;
}

interface ToolResult {
    id: string;
    result: string;
    isError: boolean;
}

async function run(dataDir: string, baseUrl: string): Promise<void> {
    let outputLines: string[] = [];
    let usageInput: number = 0;
    let usageOutput: number = 0;
    let usageCacheRead: number = 0;

    const output = (line: string) => {
        outputLines.push(line);
    };

    const printOutput = () => {
        console.log(outputLines.join('\n'));
        outputLines = [];
    };

    const readRequestJson = (): any => {
        const json = fs.readFileSync(`${dataDir}/request.json`, 'utf8');
        return JSON.parse(json);
    };

    const parseSSE = (bodyBuffer: Buffer): { type: string; data: string }[] => {
        let events: { type: string; data: string }[] = [];
        let currentEvent: { type: string; data: string[] } | null = null;

        const processLine = (line: string) => {
            if (line.startsWith(':')) {
                return;
            }
            if (line.startsWith('event:')) {
                currentEvent = { type: line.slice(6).trim(), data: [] };
            } else if (line.startsWith('data:')) {
                let data = line.slice(5).trim();
                if (currentEvent && currentEvent.type) {
                    currentEvent.data.push(data);
                }
            } else if (line === '') {
                if (currentEvent && currentEvent.type) {
                    events.push({ type: currentEvent.type, data: currentEvent.data.join('\n') });
                    currentEvent = null;
                }
            }
        };

        const str = bodyBuffer.toString('utf8');
        const lines = str.split('\n');

        for (let i = 0; i < lines.length; i++) {
            let line = lines[i];
            if (line.endsWith('\r')) {
                line = line.slice(0, -1);
            }
            processLine(line);
        }

        return events;
    };

    const sendRequest = async (
        messages: any[],
        isSecondRequest: boolean
    ): Promise<{ blocks: ContentBlock[]; results: ToolResult[]; stopReason: string }> => {
        const reqData = readRequestJson();
        const api_key = reqData.api_key;
        const model = reqData.model;
        const max_tokens = reqData.max_tokens;
        const thinking_budget = reqData.thinking_budget;
        const system = reqData.system;
        const tools = reqData.tools;

        let body: any = {
            model: model,
            max_tokens: max_tokens,
            stream: true,
            thinking: { type: 'enabled', budget_tokens: thinking_budget },
            system: system,
            tools: tools,
            messages: messages
        };

        const bodyStr = JSON.stringify(body);
        const contentLength = bodyStr.length;

        const url = new URL(baseUrl + '/v1/messages');
        const options: any = {
            hostname: url.hostname,
            port: url.port || (url.protocol === 'https:' ? 443 : 80),
            path: url.pathname + url.search,
            method: 'POST',
            headers: {
                'Host': url.host,
                'Content-Length': contentLength,
                'x-api-key': api_key,
                'anthropic-version': '2023-06-01',
                'content-type': 'application/json'
            }
        };

        return new Promise((resolve, reject) => {
            const client = url.protocol === 'https:' ? https : http;
            const req = client.request(options, (res) => {
                let bodyBuffer = Buffer.alloc(0);
                let errorData: any = null;
                let status = res.statusCode;

                res.on('data', (chunk) => {
                    bodyBuffer = Buffer.concat([bodyBuffer, chunk]);
                });

                res.on('end', () => {
                    if (status !== 200) {
                        const errorBody = bodyBuffer.toString('utf8');
                        try {
                            const error = JSON.parse(errorBody);
                            printOutput();
                            output(`ERROR ${status} ${error.error.type}: ${error.error.message}`);
                            process.exit(0);
                        } catch (e) {
                            printOutput();
                            output(`ERROR ${status} error: ${errorBody}`);
                            process.exit(0);
                        }
                        return;
                    }

                    const events = parseSSE(bodyBuffer);
                    let blocks: ContentBlock[] = [];
                    let results: ToolResult[] = [];
                    let currentBlock: ContentBlock | null = null;
                    let currentBlockIndex: number = -1;
                    let currentBlockType: string = '';
                    let currentBlockThinking: string = '';
                    let currentBlockSignature: string = '';
                    let currentBlockText: string = '';
                    let currentBlockInput: string = '';
                    let stopReason: string = 'end_turn';

                    for (const event of events) {
                        const type = event.type;
                        const data = event.data;

                        if (type === 'message_start') {
                            const usage = JSON.parse(data);
                            usageInput += (usage.usage.input_tokens || 0);
                            usageCacheRead += (usage.usage.cache_read_input_tokens || 0);
                        } else if (type === 'content_block_start') {
                            const block = JSON.parse(data);
                            currentBlockIndex = block.index;
                            currentBlockType = block.content_block.type;
                            currentBlock = { type: currentBlockType };
                            if (currentBlockType === 'thinking') {
                                currentBlock.thinking = '';
                                currentBlock.signature = '';
                            } else if (currentBlockType === 'text') {
                                currentBlock.text = '';
                            } else if (currentBlockType === 'tool_use') {
                                currentBlock.id = block.content_block.id;
                                currentBlock.name = block.content_block.name;
                                currentBlock.input = '';
                            }
                            blocks.push(currentBlock);
                        } else if (type === 'content_block_delta') {
                            const delta = JSON.parse(data);
                            const index = delta.index;
                            if (index === currentBlockIndex && currentBlock) {
                                if (delta.type === 'thinking_delta') {
                                    currentBlock.thinking = (currentBlock.thinking || '') + delta.delta.thinking;
                                } else if (delta.type === 'signature_delta') {
                                    currentBlock.signature = (currentBlock.signature || '') + delta.delta.signature;
                                } else if (delta.type === 'text_delta') {
                                    currentBlock.text = (currentBlock.text || '') + delta.delta.text;
                                } else if (delta.type === 'input_json_delta') {
                                    currentBlock.input = (currentBlock.input || '') + delta.delta.partial_json;
                                }
                            }
                        } else if (type === 'content_block_stop') {
                            if (currentBlockIndex === currentBlockIndex && currentBlock) {
                                if (currentBlockType === 'tool_use') {
                                    try {
                                        currentBlock.input = JSON.parse(currentBlock.input);
                                    } catch (e) {
                                        // Ignore
                                    }
                                }
                                if (currentBlockType === 'tool_use' && currentBlock.input) {
                                    const toolName = currentBlock.name;
                                    const toolInput = currentBlock.input;
                                    let toolResult: string;
                                    if (toolName === 'measure') {
                                        if (toolInput.text && toolInput.unit) {
                                            toolResult = measure(toolInput.text, toolInput.unit);
                                        } else {
                                            toolResult = 'invalid tool input';
                                        }
                                    } else if (toolName === 'reverse') {
                                        if (toolInput.text) {
                                            toolResult = reverse(toolInput.text);
                                        } else {
                                            toolResult = 'invalid tool input';
                                        }
                                    } else {
                                        toolResult = `unknown tool: ${toolName}`;
                                    }
                                    results.push({
                                        id: currentBlock.id!,
                                        result: toolResult,
                                        isError: toolResult.startsWith('unsupported') || toolResult.startsWith('unknown')
                                    });
                                }
                            }
                            currentBlock = null;
                        } else if (type === 'message_delta') {
                            const delta = JSON.parse(data);
                            if (delta.delta.stop_reason) {
                                stopReason = delta.delta.stop_reason;
                                usageOutput += (delta.usage.output_tokens || 0);
                            }
                        } else if (type === 'message_stop') {
                            // End of message
                        } else if (type === 'ping') {
                            // Ignore
                        } else {
                            // Ignore other events
                        }
                    }

                    resolve({ blocks, results, stopReason });
                });

                req.on('error', (err) => {
                    reject(err);
                });

                req.write(bodyStr);
                req.end();
            });

            req.on('error', (err) => {
                reject(err);
            });
        });
    };

    const reqData = readRequestJson();
    const api_key = reqData.api_key;
    const model = reqData.model;
    const max_tokens = reqData.max_tokens;
    const thinking_budget = reqData.thinking_budget;
    const system = reqData.system;
    const tools = reqData.tools;
    const prompt = reqData.prompt;

    // Request 1
    output('request 1');
    const messages1 = [{ role: 'user', content: prompt }];
    const { blocks: blocks1, results: results1, stopReason: stopReason1 } = await sendRequest(messages1, false);

    for (const block of blocks1) {
        if (block.type === 'thinking') {
            output(`thinking ${escape(block.thinking!)}`);
            output(`signature ${escape(block.signature!)}`);
        } else if (block.type === 'text') {
            output(`text ${escape(block.text!)}`);
        } else if (block.type === 'tool_use') {
            output(`tool_use ${block.id} ${block.name} ${escape(JSON.stringify(block.input))}`);
        }
    }
    output(`stop_reason ${stopReason1}`);

    for (const result of results1) {
        if (result.isError) {
            output(`error ${result.id} ${result.result}`);
        } else {
            output(`result ${result.id} ${result.result}`);
        }
    }

    // Request 2
    output('request 2');
    const messages2 = [
        { role: 'user', content: prompt },
        {
            role: 'assistant',
            content: blocks1.map(b => {
                if (b.type === 'thinking') {
                    return { type: 'thinking', thinking: b.thinking!, signature: b.signature! };
                } else if (b.type === 'text') {
                    return { type: 'text', text: b.text! };
                } else if (b.type === 'tool_use') {
                    return { type: 'tool_use', id: b.id!, name: b.name!, input: b.input };
                }
                return b;
            })
        },
        {
            role: 'user',
            content: results1.map(r => ({
                type: 'tool_result',
                tool_use_id: r.id,
                content: r.result,
                is_error: r.isError
            }))
        }
    ];

    const { blocks: blocks2, results: results2, stopReason: stopReason2 } = await sendRequest(messages2, true);

    for (const block of blocks2) {
        if (block.type === 'thinking') {
            output(`thinking ${escape(block.thinking!)}`);
            output(`signature ${escape(block.signature!)}`);
        } else if (block.type === 'text') {
            output(`text ${escape(block.text!)}`);
        } else if (block.type === 'tool_use') {
            output(`tool_use ${block.id} ${block.name} ${escape(JSON.stringify(block.input))}`);
        }
    }
    output(`stop_reason ${stopReason2}`);

    for (const result of results2) {
        if (result.isError) {
            output(`error ${result.id} ${result.result}`);
        } else {
            output(`result ${result.id} ${result.result}`);
        }
    }

    output(`usage input=${usageInput} output=${usageOutput} cache_read=${usageCacheRead}`);
};

