static char *get_json_string(const char *json, const char *key) {
    char search[256];
    snprintf(search, sizeof(search), "\"%s\":", key);
    const char *p = strstr(json, search);
    if (!p) return NULL;
    p += strlen(search);
    while (*p == ' ' || *p == '\t') p++;
    if (*p != '"') return NULL;
    p++;
    char *start = p;
    char *end = p;
    while (*end) {
        if (*end == '\\' && end[1]) {
            end += 2;
        } else if (*end == '"') {
            break;
        } else {
            end++;
        }
    }
    int len = end - start;
    char *result = malloc(len + 1);
    if (!result) return NULL;
    char *out = result;
    const char *in = start;
    while (in < end) {
        if (*in == '\\' && in[1]) {
            in++;
            if (*in == 'u') {
                if (in + 4 <= end) {
                    int cp = 0;
                    for (int i = 0; i < 4; i++) cp = cp * 16 + (*++in - '0');
                    if (cp >= 0xD800 && cp <= 0xDBFF) {
                        if (in < end && *in == '\\' && in[1] == 'u') {
                            in += 2;
                            cp = cp * 0x10000;
                            for (int i = 0; i < 4; i++) cp = cp + (*++in - '0') * 0x1000;
                        }
                    }
                    if (cp < 0x110000) {
                        if (cp < 0x80) *out++ = cp;
                        else if (cp < 0x800) { *out++ = 0xC0 | (cp >> 6); *out++ = 0x80 | (cp & 0x3F); }
                        else { *out++ = 0xE0 | (cp >> 12); *out++ = 0x80 | ((cp >> 6) & 0x3F); *out++ = 0x80 | (cp & 0x3F); }
                        else { *out++ = 0xF0 | (cp >> 18); *out++ = 0x80 | ((cp >> 12) & 0x3F); *out++ = 0x80 | ((cp >> 6) & 0x3F); *out++ = 0x80 | (cp & 0x3F); }
                    }
                }
            } else if (*in == 'n') { *out++ = '\n'; }
            else if (*in == 't') { *out++ = '\t'; }
            else if (*in == 'r') { *out++ = '\r'; }
            else if (*in == 'b') { *out++ = '\b'; }
            else if (*in == 'f') { *out++ = '\f'; }
            else if (*in == '"') { *out++ = '"'; }
            else if (*in == '/') { *out++ = '/'; }
            else if (*in == '\\') { *out++ = '\\'; }
            else { *out++ = *in; }
            in++;
        } else {
            *out++ = *in++;
        }
    }
    *out = '\0';
    return result;
}

static int get_json_int(const char *json, const char *key) {
    char search[256];
    snprintf(search, sizeof(search), "\"%s\":", key);
    const char *p = strstr(json, search);
    if (!p) return 0;
    p += strlen(search);
    while (*p == ' ' || *p == '\t') p++;
    if (*p == '"') return 0;
    char *endptr;
    long val = strtol(p, &endptr, 10);
    if (endptr == p) return 0;
    return (int)val;
}

static int url_encode(char *out, size_t out_size, const char *in) {
    size_t i = 0;
    while (*in && i + 3 < out_size) {
        unsigned char c = (unsigned char)*in;
        if (isalnum(c) || c == '-' || c == '.' || c == '_' || c == '*') {
            out[i++] = c;
        } else if (c == ' ') {
            out[i++] = '+';
        } else {
            out[i++] = '%';
            out[i++] = "0123456789ABCDEF"[c / 16];
            out[i++] = "0123456789ABCDEF"[c % 16];
        }
        in++;
    }
    out[i] = '\0';
    return i;
}

static int b64_encode(const unsigned char *src, int len, char *out, int out_size) {
    static const char b64[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    int i = 0;
    while (i < len) {
        int a = src[i] & 0xFF;
        int b = (i + 1 < len) ? (src[i + 1] & 0xFF) : 0;
        int c = (i + 2 < len) ? (src[i + 2] & 0xFF) : 0;
        int val1 = (a << 2) | (b >> 4);
        int val2 = ((b & 0xF) << 4) | (c >> 2);
        int val3 = ((c & 0x3) << 6);
        out[i++] = b64[val1 & 0x3F];
        if (i < out_size) out[i++] = b64[(val2 >> 2) & 0x3F];
        if (i < out_size && (i + 1 < len || len > 2)) {
            if (i + 2 < len) out[i++] = b64[(val3 >> 4) & 0x3F];
            else out[i++] = '=';
        } else out[i++] = '=';
        if (i >= out_size) return 0;
    }
    out[i] = '\0';
    return i;
}

static int http_get_token(const char *base_url, const char *client_id, const char *client_secret, const char *scope, char *access_token_out) {
    char host[MAX_PATH];
    char port[MAX_PATH];
    char *host_port = strstr(base_url, "://") + 3;
    char *path_start = strstr(base_url, "/");
    if (!path_start) path_start = strstr(base_url, "://");
    if (host_port && path_start) {
        int len = path_start - host_port;
        if (len >= (int)sizeof(host)) len = sizeof(host) - 1;
        memcpy(host, host_port, len);
        host[len] = '\0';
        if (path_start > host_port && path_start != host_port + len) {
            // Check if port is in host
            if (strstr(host, ":")) {
                char *colon = strchr(host, ':');
                int port_len = sizeof(port);
                memcpy(port, colon + 1, port_len);
                port[port_len] = '\0';
            }
        }
    } else {
        strcpy(host, "127.0.0.1");
        strcpy(port, "50123");
    }

    char host_header[MAX_PATH];
    if (host_port && path_start) {
        int len = path_start - host_port;
        if (len >= (int)sizeof(host_header)) len = sizeof(host_header) - 1;
        memcpy(host_header, host_port, len);
        host_header[len] = '\0';
    } else {
        strcpy(host_header, "127.0.0.1:50123");
    }

    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = IPPROTO_TCP;

    char port_str[MAX_PATH];
    if (strstr(host, ":")) {
        char *colon = strchr(host, ':');
        *colon = '\0';
        strcpy(port_str, colon + 1);
    } else {
        strcpy(port_str, "50123");
    }

    if (getaddrinfo(host, port_str, &hints, &res) != 0) return 0;

    int sock = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
    if (sock < 0) { freeaddrinfo(res); return 0; }
    if (connect(sock, res->ai_addr, res->ai_addrlen) < 0) { close(sock); freeaddrinfo(res); return 0; }
    freeaddrinfo(res);

    char encoded_id[MAX_PATH * 2];
    url_encode(encoded_id, sizeof(encoded_id), client_id);
    char encoded_secret[MAX_PATH * 2];
    url_encode(encoded_secret, sizeof(encoded_secret), client_secret);
    char auth_str[256];
    snprintf(auth_str, sizeof(auth_str), "%s:%s", encoded_id, encoded_secret);
    char b64_auth[MAX_PATH * 2];
    unsigned char auth_bytes[256];
    int auth_len = strlen(auth_str);
    for (int i = 0; i < auth_len; i++) auth_bytes[i] = auth_str[i];
    b64_encode(auth_bytes, auth_len, b64_auth, sizeof(b64_auth));

    char *body = malloc(256);
    snprintf(body, 256, "grant_type=client_credentials&scope=%s", scope);

    char *request = malloc(1024);
    snprintf(request, 1024, "POST %s/oauth/token HTTP/1.1\r\nHost: %s\r\nAuthorization: Basic %s\r\nContent-Type: application/x-www-form-urlencoded\r\nContent-Length: %zu\r\n\r\n%s", 
             base_url, host_header, b64_auth, strlen(body), body);

    send(sock, request, strlen(request), 0);

    char line[MAX_LINE];
    int status = 0;
    char response_body[MAX_PATH * 2];
    int body_len = 0;
    int content_length = 0;
    int chunked = 0;
    int chunk_size = 0;
    int chunk_pos = 0;

    while (recv(sock, line, sizeof(line), 0) > 0) {
        if (strstr(line, "HTTP/1.") && strstr(line, " 200")) {
            status = 200;
        }
        if (strstr(line, "Content-Length:")) {
            content_length = atoi(line + strlen("Content-Length:"));
        }
        if (strstr(line, "Transfer-Encoding:")) {
            if (strstr(line, "chunked")) chunked = 1;
        }
        if (strstr(line, "\r\n\r\n")) break;
    }

    if (status != 200) {
        close(sock);
        return 0;
    }

    if (content_length > 0) {
        char buf[4096];
        int total = 0;
        while (total < content_length && recv(sock, buf, sizeof(buf), 0) > 0) {
            int n = recv(sock, buf, sizeof(buf), 0);
            if (n <= 0) break;
            memcpy(response_body + body_len, buf, n);
            body_len += n;
            total += n;
        }
    } else if (chunked) {
        while (1) {
            char *chunk_line = malloc(1024);
            recv(sock, chunk_line, 1024, 0);
            if (strstr(chunk_line, "0\r\n")) {
                break;
            }
            char *end = strchr(chunk_line, '\r');
            if (end) *end = '\0';
            char *end2 = strchr(chunk_line, '\n');
            if (end2) *end2 = '\0';
            if (chunk_line[0] == '0') break;

            int len = atoi(chunk_line);
            char chunk[4096];
            recv(sock, chunk, len + 2, 0);
            memcpy(response_body + body_len, chunk, len);
            body_len += len;
        }
    }

    access_token_out[0] = '\0';
    char *token = get_json_string(response_body, "access_token");
    if (token) {
        strcpy(access_token_out, token);
        free(token);
    } else {
        close(sock);
        return 0;
    }

    close(sock);
    free(body);
    free(request);
    return 1;
}

