static long long parse_amount(const char *str) {
    long long cents = 0;
    int negative = 0;
    int i = 0;
    while (str[i] == ' ') i++;
    if (str[i] == '-') {
        negative = 1;
        i++;
    }
    while (str[i] >= '0' && str[i] <= '9') {
        cents = cents * 10 + (str[i] - '0');
        i++;
    }
    if (str[i] == '.') {
        i++;
        int decimals = 0;
        while (str[i] >= '0' && str[i] <= '9') {
            cents = cents * 10 + (str[i] - '0');
            decimals++;
            i++;
        }
    }
    if (negative) cents = -cents;
    return cents;
}

static void sleep_ms(int ms) {
    struct timespec ts;
    ts.tv_sec = ms / 1000;
    ts.tv_nsec = (ms % 1000) * 1000000;
    nanosleep(&ts, NULL);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s <data_dir> <base_url>\n", argv[0]);
        return 0;
    }

    char data_dir[MAX_PATH];
    char base_url[MAX_PATH];
    strcpy(data_dir, argv[1]);
    strcpy(base_url, argv[2]);

    char config_path[MAX_PATH];
    snprintf(config_path, sizeof(config_path), "%s/client.json", data_dir);

    FILE *f = fopen(config_path, "r");
    if (!f) {
        printf("ERROR 1 file not found\n");
        return 0;
    }

    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);

    char *json = malloc(size + 1);
    fread(json, 1, size, f);
    json[size] = '\0';
    fclose(f);

    char client_id[MAX_PATH];
    char client_secret[MAX_PATH];
    char scope[MAX_PATH];
    int page_size = 0;

    char *client_id_str = get_json_string(json, "client_id");
    if (client_id_str) strcpy(client_id, client_id_str);
    char *client_secret_str = get_json_string(json, "client_secret");
    if (client_secret_str) strcpy(client_secret, client_secret_str);
    char *scope_str = get_json_string(json, "scope");
    if (scope_str) strcpy(scope, scope_str);
    page_size = get_json_int(json, "page_size");

    free(client_id_str);
    free(client_secret_str);
    free(scope_str);
    free(json);

    char access_token[MAX_PATH];
    if (!http_get_token(base_url, client_id, client_secret, scope, access_token)) {
        printf("ERROR 1 token fetch failed\n");
        return 0;
    }

    char *cursor = NULL;
    char response_body[MAX_PATH * 2];
    char *body = response_body;

    while (1) {
        int status = 0;
        memset(response_body, 0, sizeof(response_body));
        int len = http_get_orders(base_url, cursor, access_token, response_body);
        if (!len) {
            printf("ERROR %d %s\n", 0, response_body);
            return 0;
        }

        int start = 0;
        char *p = strstr(response_body, "HTTP/1.");
        if (p) start = p - response_body;
        p = strstr(response_body + start, "\r\n\r\n");
        if (p) start += p - response_body + 4;
        else break;

        char *json_body = response_body + start;

        char *next_cursor = get_json_string(json_body, "next_cursor");
        if (next_cursor) {
            if (strcmp(next_cursor, "null") == 0) {
                cursor = NULL;
            } else {
                cursor = next_cursor;
            }
            free(next_cursor);
        }

        char *data = get_json_string(json_body, "data");
        if (!data) {
            printf("ERROR %d %s\n", 0, json_body);
            return 0;
        }

        char *p_order = data;
        while (p_order) {
            char *p_end = strchr(p_order, '}');
            if (p_end) {
                *p_end = '\0';
                p_order++;
            } else {
                break;
            }

            char *id = get_json_string(p_order, "id");
            char *name = get_json_string(p_order, "name");
            char *currency = get_json_string(p_order, "currency");
            char *status = get_json_string(p_order, "status");
            char *amount = get_json_string(p_order, "amount");

            if (name && currency && status && amount) {
                total_orders++;
                if (strcmp(status, "cancelled") != 0) {
                    CustomerTotal *ct = malloc(sizeof(CustomerTotal));
                    strcpy(ct->name, name);
                    strcpy(ct->currency, currency);
                    ct->total_cents += parse_amount(amount);
                    // Add to list
                    // ...
                }
                StatusCount *sc = malloc(sizeof(StatusCount));
                strcpy(sc->status, status);
                sc->count++;
                // Add to list
                // ...
            }

            p_order = strstr(p_order, "{");
            if (p_order) p_order++;
        }

        total_pages++;
        free(data);

        if (cursor == NULL) break;

        // Check for 429/503/401
        // Status code is in response_body
        char *status_line = strstr(response_body, "HTTP/1.");
        if (status_line) {
            char *status_str = status_line + 9;
            while (*status_str == ' ') status_str++;
            int status_code = atoi(status_str);

            if (status_code == 429) {
                char *retry_after = strstr(response_body, "Retry-After:");
                if (retry_after) {
                    char *val = retry_after + 12;
                    while (*val == ' ') val++;
                    int wait = atoi(val);
                    sleep(wait);
                    total_retries++;
                    continue;
                }
            } else if (status_code == 503) {
                sleep(1);
                total_retries++;
                continue;
            } else if (status_code == 401) {
                total_reauth++;
                if (!http_get_token(base_url, client_id, client_secret, scope, access_token)) {
                    printf("ERROR %d %s\n", 0, response_body);
                    return 0;
                }
                continue;
            } else {
                printf("ERROR %d %s\n", status_code, response_body);
                return 0;
            }
        }
    }

    // Output
    CustomerTotal *customers = malloc(10000 * sizeof(CustomerTotal));
    int customer_count = 0;
    StatusCount *statuses = malloc(10000 * sizeof(StatusCount));
    int status_count = 0;

    char *data = strstr(response_body, "\"data\":[");
    if (data) {
        // Process orders
        // ...
    }

    // Sort customers
    qsort(customers, customer_count, sizeof(CustomerTotal), compare_customers);
    // Sort statuses
    qsort(statuses, status_count, sizeof(StatusCount), compare_statuses);

    for (int i = 0; i < customer_count; i++) {
        if (customers[i].total_cents < 0) printf("total %s %lld.%02lld %s\n", customers[i].currency, abs(customers[i].total_cents) / 100, abs(customers[i].total_cents) % 100, customers[i].name);
        else printf("total %s %lld.%02lld %s\n", customers[i].currency, abs(customers[i].total_cents) / 100, abs(customers[i].total_cents) % 100, customers[i].name);
    }

    for (int i = 0; i < status_count; i++) {
        printf("status %s %d\n", statuses[i].status, statuses[i].count);
    }

    printf("orders %lld pages %d retries %d reauth %d\n", total_orders, total_pages, total_retries, total_reauth);

    return 0;
}

