use std::collections::HashMap;

// Simple JSON Value enum
#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(i64),
    String(String),
    Array(Vec<JsonValue>),
    Object(HashMap<String, JsonValue>),
}

impl JsonValue {
    fn to_json_string(&self) -> String {
        match self {
            JsonValue::Null => "null".to_string(),
            JsonValue::Bool(b) => b.to_string(),
            JsonValue::Number(n) => n.to_string(),
            JsonValue::String(s) => {
                let mut res = String::new();
                res.push('"');
                for c in s.chars() {
                    match c {
                        '\\' => res.push_str("\\\\"),
                        '\n' => res.push_str("\\n"),
                        '\r' => res.push_str("\\r"),
                        '\t' => res.push_str("\\t"),
                        '"' => res.push_str("\\\""),
                        c if c < 32 => {
                            let hex = format!("{:02x}", c as u32);
                            res.push_str("\\u");
                            res.push_str(&hex);
                        }
                        _ => res.push(c),
                    }
                }
                res.push('"');
                res
            }
            JsonValue::Array(arr) => {
                let mut res = "[";
                for (i, v) in arr.iter().enumerate() {
                    if i > 0 { res.push(','); }
                    res.push_str(&v.to_json_string());
                }
                res.push(']');
                res
            }
            JsonValue::Object(obj) => {
                let mut res = "{";
                let mut first = true;
                for (k, v) in obj {
                    if !first { res.push(','); }
                    first = false;
                    res.push('"');
                    res.push_str(k);
                    res.push('"');
                    res.push(':');
                    res.push_str(&v.to_json_string());
                }
                res.push('}');
                res
            }
        }
    }
}

fn parse_json_string(s: &str) -> Result<JsonValue, String> {
    let mut pos = 0;
    let chars: Vec<char> = s.chars().collect();
    let len = chars.len();

    fn skip_whitespace(chars: &[char], pos: &mut usize) {
        while *pos < len && chars[*pos].is_whitespace() {
            *pos += 1;
        }
    }

    fn parse_value(chars: &[char], pos: &mut usize) -> Result<JsonValue, String> {
        skip_whitespace(chars, pos);
        if *pos >= len {
            return Err("Unexpected end of JSON".to_string());
        }
        match chars[*pos] {
            '{' => {
                *pos += 1;
                skip_whitespace(chars, pos);
                let mut obj = HashMap::new();
                if *pos < len && chars[*pos] == '}' {
                    *pos += 1;
                } else {
                    loop {
                        skip_whitespace(chars, pos);
                        if *pos >= len { return Err("Unexpected end of JSON".to_string()); }
                        if chars[*pos] != '"' { return Err("Expected string key".to_string()); }
                        *pos += 1;
                        let key = parse_string(chars, pos)?;
                        skip_whitespace(chars, pos);
                        if *pos >= len || chars[*pos] != ':' { return Err("Expected colon".to_string()); }
                        *pos += 1;
                        let value = parse_value(chars, pos)?;
                        obj.insert(key, value);
                        skip_whitespace(chars, pos);
                        if *pos < len && chars[*pos] == '}' {
                            *pos += 1;
                            break;
                        } else if *pos < len && chars[*pos] == ',' {
                            *pos += 1;
                        } else {
                            return Err("Expected comma or closing brace".to_string());
                        }
                    }
                }
                Ok(JsonValue::Object(obj))
            }
            '[' => {
                *pos += 1;
                skip_whitespace(chars, pos);
                let mut arr = Vec::new();
                if *pos < len && chars[*pos] == ']' {
                    *pos += 1;
                } else {
                    loop {
                        let value = parse_value(chars, pos)?;
                        arr.push(value);
                        skip_whitespace(chars, pos);
                        if *pos < len && chars[*pos] == ']' {
                            *pos += 1;
                            break;
                        } else if *pos < len && chars[*pos] == ',' {
                            *pos += 1;
                        } else {
                            return Err("Expected comma or closing bracket".to_string());
                        }
                    }
                }
                Ok(JsonValue::Array(arr))
            }
            '"' => {
                let s = parse_string(chars, pos)?;
                Ok(JsonValue::String(s))
            }
            't' => {
                if chars[*pos+1..].starts_with("rue") {
                    *pos += 4;
                    Ok(JsonValue::Bool(true))
                } else { Err("Invalid true".to_string()) }
            }
            'f' => {
                if chars[*pos+1..].starts_with("alse") {
                    *pos += 5;
                    Ok(JsonValue::Bool(false))
                } else { Err("Invalid false".to_string()) }
            }
            'n' => {
                if chars[*pos+1..].starts_with("ull") {
                    *pos += 4;
                    Ok(JsonValue::Null)
                } else { Err("Invalid null".to_string()) }
            }
            '-' | '0'..='9' => {
                let start = *pos;
                while *pos < len && chars[*pos].is_numeric() {
                    *pos += 1;
                }
                let num_str: String = chars[start..*pos].iter().collect();
                Ok(JsonValue::Number(num_str.parse::<i64>().map_err(|_| "Invalid number".to_string())?))
            }
            c => Err(format!("Unexpected character: {}", c)),
        }
    }

    fn parse_string(chars: &[char], pos: &mut usize) -> Result<String, String> {
        *pos += 1; // skip opening quote
        let mut s = String::new();
        while *pos < len {
            let c = chars[*pos];
            if c == '\\' {
                *pos += 1;
                match chars[*pos] {
                    '"' => s.push('"'),
                    '\\' => s.push('\\'),
                    '/' => s.push('/'),
                    'b' => s.push('\x08'),
                    'f' => s.push('\x0c'),
                    'n' => s.push('\n'),
                    'r' => s.push('\r'),
                    't' => s.push('\t'),
                    'u' => {
                        *pos += 1;
                        let hex = chars[*pos..*pos+4].iter().collect::<String>();
                        let code_point = u32::from_str_radix(&hex, 16).map_err(|_| "Invalid unicode escape")?;
                        s.push(code_point as char);
                        *pos += 3;
                    }
                    other => return Err(format!("Invalid escape: \\{}", other)),
                }
                *pos += 1;
            } else if c == '"' {
                *pos += 1;
                return Ok(s);
            } else {
                s.push(c);
                *pos += 1;
            }
        }
        Err("Unterminated string".to_string())
    }

    parse_value(chars, &mut pos)
}

fn parse_request_json(content: &str) -> Result<RequestConfig, String> {
    let value = parse_json_string(content)?;
    let obj = match value {
        JsonValue::Object(o) => o,
        _ => return Err("Request JSON must be an object".to_string()),
    };

    fn get_str(obj: &HashMap<String, JsonValue>, key: &str) -> Option<String> {
        obj.get(key).and_then(|v| match v {
            JsonValue::String(s) => Some(s.clone()),
            _ => None,
        })
    }

    fn get_num(obj: &HashMap<String, JsonValue>, key: &str) -> Option<i64> {
        obj.get(key).and_then(|v| match v {
            JsonValue::Number(n) => Some(*n),
            _ => None,
        })
    }

    fn get_arr(obj: &HashMap<String, JsonValue>, key: &str) -> Option<Vec<JsonValue>> {
        obj.get(key).and_then(|v| match v {
            JsonValue::Array(a) => Some(a.clone()),
            _ => None,
        })
    }

    let api_key = get_str(&obj, "api_key").ok_or("Missing api_key")?;
    let model = get_str(&obj, "model").ok_or("Missing model")?;
    let max_tokens = get_num(&obj, "max_tokens").ok_or("Missing max_tokens")?;
    let thinking_budget = get_num(&obj, "thinking_budget").ok_or("Missing thinking_budget")?;
    let system = get_str(&obj, "system").ok_or("Missing system")?;
    let prompt = get_str(&obj, "prompt").ok_or("Missing prompt")?;
    let tools = get_arr(&obj, "tools").ok_or("Missing tools")?;

    Ok(RequestConfig {
        api_key, model, max_tokens, thinking_budget, system, prompt, tools,
    })
}

struct RequestConfig {
    api_key: String,
    model: String,
    max_tokens: i64,
    thinking_budget: i64,
    system: String,
    prompt: String,
    tools: Vec<JsonValue>,
}

fn send_request(client: &mut TcpStream, config: &RequestConfig, messages: Vec<JsonValue>) -> io::Result<ResponseInfo> {
    let body = build_request_body(config, messages);
    let body_bytes = body.as_bytes();
    let content_length = body_bytes.len();

    let url = format!("{}/v1/messages", config.base_url);
    let host = config.host.clone();

    let request = format!(
        "POST {} HTTP/1.1\r\nHost: {}\r\nContent-Length: {}\r\nx-api-key: {}\r\nanthropic-version: 2023-06-01\r\ncontent-type: application/json\r\n\r\n{}",
        url, host, content_length, config.api_key, body
    );

    client.write_all(request.as_bytes())?;

    // Read response headers
    let mut status = String::new();
    let mut headers = HashMap::new();
    let mut content_length: Option<i64> = None;
    let mut transfer_encoding = String::new();

    let mut reader = BufReader::new(client.try_clone().unwrap());
    let mut line = String::new();

    loop {
        line.clear();
        let bytes_read = reader.read_line(&mut line)?;
        if bytes_read == 0 { break; }

        if line.starts_with("HTTP/1.1 ") {
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 3 {
                status = format!("{} {}", parts[0], parts[1]);
            }
        } else if line.starts_with("Content-Length:") {
            content_length = Some(line.trim_start_matches("Content-Length: ").parse::<i64>().unwrap_or(0));
        } else if line.starts_with("Transfer-Encoding:") {
            transfer_encoding = line.trim_start_matches("Transfer-Encoding: ").to_string();
        } else if line.is_empty() {
            break;
        }
    }

    if status.is_empty() {
        return Err(io::Error::new(io::ErrorKind::Other, "No status line"));
    }

    // Check for error response (non-200)
    if status != "HTTP/1.1 200 OK" {
        let mut err_body = String::new();
        if let Some(len) = content_length {
            let mut buf = vec![0u8; len as usize];
            client.read_exact(&mut buf)?;
            err_body = String::from_utf8(buf).unwrap_or_default();
        } else if transfer_encoding.starts_with("chunked") {
            // Should not happen for error, but handle anyway
            let mut remaining = String::new();
            loop {
                let mut chunk_line = String::new();
                reader.read_line(&mut chunk_line)?;
                if chunk_line.is_empty() { break; }
                let size_str = chunk_line.trim_end_matches("\r\n");
                if size_str == "0" { break; }
                let size = u64::from_str_radix(size_str, 16)?;
                let mut chunk = vec![0u8; size as usize];
                client.read_exact(&mut chunk)?;
                remaining.push_str(&String::from_utf8_lossy(&chunk));
            }
            err_body = remaining;
        }

        let error_val = parse_json_string(&err_body).ok();
        let error_type = error_val.as_ref().and_then(|v| {
            match v {
                JsonValue::Object(o) => {
                    o.get("error").and_then(|e| match e {
                        JsonValue::Object(eo) => eo.get("type").and_then(|t| match t {
                            JsonValue::String(s) => Some(s.clone()),
                            _ => None,
                        }),
                        _ => None,
                    })
                }
                _ => None,
            }
        });
        let error_msg = error_val.as_ref().and_then(|v| {
            match v {
                JsonValue::Object(o) => {
                    o.get("error").and_then(|e| match e {
                        JsonValue::Object(eo) => eo.get("message").and_then(|m| match m {
                            JsonValue::String(s) => Some(s.clone()),
                            _ => None,
                        }),
                        _ => None,
                    })
                }
                _ => None,
            }
        });

        return Ok(ResponseInfo {
            status_code: status.parse::<i32>().unwrap_or(0),
            is_error: true,
            error_type,
            error_msg,
            body: None,
        });
    }

    // Read chunked body
    let mut chunks = Vec::new();
    if transfer_encoding.starts_with("chunked") {
        loop {
            let mut chunk_line = String::new();
            reader.read_line(&mut chunk_line)?;
            if chunk_line.is_empty() { break; }
            let size_str = chunk_line.trim_end_matches("\r\n");
            if size_str == "0" { break; }
            let size = u64::from_str_radix(size_str, 16)?;
            let mut chunk = vec![0u8; size as usize];
            client.read_exact(&mut chunk)?;
            chunks.push(chunk);
            // Read CRLF
            let mut crlf = [0u8; 2];
            client.read_exact(&mut crlf)?;
        }
    } else if let Some(len) = content_length {
        let mut buf = vec![0u8; len as usize];
        client.read_exact(&mut buf)?;
        chunks.push(buf);
    }

    let body = chunks.into_iter().flat_map(|c| c).collect::<Vec<u8>>();
    let body_str = String::from_utf8(body).unwrap_or_default();

    Ok(ResponseInfo {
        status_code: status.parse::<i32>().unwrap_or(0),
        is_error: false,
        error_type: None,
        error_msg: None,
        body: Some(body_str),
    })
}

struct ResponseInfo {
    status_code: i32,
    is_error: bool,
    error_type: Option<String>,
    error_msg: Option<String>,
    body: Option<String>,
}

fn execute_tools(tool_name: &str, input: &JsonValue) -> String {
    if tool_name == "measure" {
        if let JsonValue::Object(obj) = input {
            if let (Some(text_val), Some(unit_val)) = (obj.get("text"), obj.get("unit")) {
                let text = match text_val {
                    JsonValue::String(s) => s,
                    _ => return "error".to_string(),
                };
                let unit = match unit_val {
                    JsonValue::String(s) => s,
                    _ => return "error".to_string(),
                };
                match unit.as_str() {
                    "code_points" => {
                        return text.chars().count().to_string();
                    }
                    "utf8_bytes" => {
                        return text.len().to_string();
                    }
                    "utf16_units" => {
                        let units: usize = text.chars().map(|c| if c > '\u{FFFF}' { 2 } else { 1 }).sum();
                        return units.to_string();
                    }
                    _ => return format!("unsupported unit: {}", unit),
                }
            }
        }
        return "error".to_string();
    } else if tool_name == "reverse" {
        if let JsonValue::Object(obj) = input {
            if let Some(text_val) = obj.get("text") {
                let text = match text_val {
                    JsonValue::String(s) => s,
                    _ => return "error".to_string(),
                };
                return text.chars().rev().collect();
            }
        }
        return "error".to_string();
    }
    format!("unknown tool: {}", tool_name)
}

fn parse_sse_events(body: &str) -> Vec<Event> {
    let lines: Vec<&str> = body.lines().collect();
    let mut events = Vec::new();
    let mut event_data = String::new();
    let mut event_name = String::new();
    let mut has_data = false;

    for line in lines {
        if line.is_empty() {
            if !event_name.is_empty() {
                if !event_data.is_empty() {
                    let val = parse_json_string(&event_data).unwrap_or(JsonValue::Null);
                    events.push(Event { name: event_name.clone(), data: val });
                }
                event_data.clear();
                event_name.clear();
                has_data = false;
            }
            continue;
        }
        if line.starts_with(":") {
            continue; // comment
        }
        if line.starts_with("event:") {
            event_name = line.trim_start_matches("event:").trim().to_string();
            has_data = false;
            event_data.clear();
        } else if line.starts_with("data:") {
            has_data = true;
            let data = line.trim_start_matches("data:");
            if data.is_empty() {
                event_data.push_str("");
            } else {
                event_data.push_str(data);
            }
        }
    }
    // Handle last event if no blank line at end
    if !event_name.is_empty() {
        if !event_data.is_empty() {
            let val = parse_json_string(&event_data).unwrap_or(JsonValue::Null);
            events.push(Event { name: event_name, data: val });
        }
    }
    events
}

#[derive(Debug)]
struct Event {
    name: String,
    data: JsonValue,
}

fn process_reply(config: &RequestConfig, tool_results: Vec<(String, String, bool)>) -> (String, StopReason, i64, i64, i64) {
    let mut output_lines = Vec::new();
    let mut input_tokens = 0i64;
    let mut cache_read_input_tokens = 0i64;
    let mut output_tokens = 0i64;
    let mut stop_reason = StopReason::Unknown;
    let mut blocks: Vec<ContentBlock> = Vec::new();
    let mut tool_use_blocks: Vec<ToolUseBlock> = Vec::new();

    let events = parse_sse_events(&config.body);

    for event in events {
        match event.name.as_str() {
            "message_start" => {
                if let JsonValue::Object(obj) = &event.data {
                    if let Some(msg) = obj.get("message") {
                        if let JsonValue::Object(msg_obj) = msg {
                            if let Some(usage) = msg_obj.get("usage") {
                                if let JsonValue::Object(usage_obj) = usage {
                                    if let Some(i) = usage_obj.get("input_tokens") {
                                        if let JsonValue::Number(n) = i {
                                            input_tokens += *n;
                                        }
                                    }
                                    if let Some(c) = usage_obj.get("cache_read_input_tokens") {
                                        if let JsonValue::Number(n) = c {
                                            cache_read_input_tokens += *n;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            "content_block_start" => {
                if let JsonValue::Object(obj) = &event.data {
                    if let Some(idx) = obj.get("index") {
                        if let JsonValue::Number(idx) = idx {
                            let idx = *idx as usize;
                            if let Some(block) = obj.get("content_block") {
                                if let JsonValue::Object(block_obj) = block {
                                    if let Some(t) = block_obj.get("type") {
                                        if let JsonValue::String(t) = t {
                                            if t == "thinking" {
                                                blocks.push(ContentBlock::Thinking { idx, thinking: String::new(), signature: String::new() });
                                            } else if t == "text" {
                                                blocks.push(ContentBlock::Text { idx, text: String::new() });
                                            } else if t == "tool_use" {
                                                if let (Some(id), Some(name)) = (block_obj.get("id"), block_obj.get("name")) {
                                                    if let (JsonValue::String(id_s), JsonValue::String(name_s)) = (id, name) {
                                                        tool_use_blocks.push(ToolUseBlock {
                                                            idx, id: id_s.clone(), name: name_s.clone(), input: String::new(), input_json: String::new(),
                                                        });
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            "content_block_delta" => {
                if let JsonValue::Object(obj) = &event.data {
                    if let Some(idx) = obj.get("index") {
                        if let JsonValue::Number(idx) = idx {
                            let idx = *idx as usize;
                            if let Some(delta) = obj.get("delta") {
                                if let JsonValue::Object(delta_obj) = delta {
                                    if let Some(t) = delta_obj.get("type") {
                                        if let JsonValue::String(t) = t {
                                            if t == "thinking_delta" {
                                                if let Some(thinking) = delta_obj.get("thinking") {
                                                    if let JsonValue::String(thinking) = thinking {
                                                        if let Some(block) = blocks.iter_mut().find(|b| b.is_thinking() && b.idx == idx) {
                                                            block.thinking.push_str(thinking);
                                                        }
                                                    }
                                                }
                                            } else if t == "signature_delta" {
                                                if let Some(signature) = delta_obj.get("signature") {
                                                    if let JsonValue::String(signature) = signature {
                                                        if let Some(block) = blocks.iter_mut().find(|b| b.is_thinking() && b.idx == idx) {
                                                            block.signature.push_str(signature);
                                                        }
                                                    }
                                                }
                                            } else if t == "text_delta" {
                                                if let Some(text) = delta_obj.get("text") {
                                                    if let JsonValue::String(text) = text {
                                                        if let Some(block) = blocks.iter_mut().find(|b| b.is_text() && b.idx == idx) {
                                                            block.text.push_str(text);
                                                        }
                                                    }
                                                }
                                            } else if t == "input_json_delta" {
                                                if let Some(partial) = delta_obj.get("partial_json") {
                                                    if let JsonValue::String(partial) = partial {
                                                        if let Some(block) = tool_use_blocks.iter_mut().find(|b| b.idx == idx) {
                                                            block.input_json.push_str(partial);
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            "content_block_stop" => {
                if let JsonValue::Object(obj) = &event.data {
                    if let Some(idx) = obj.get("index") {
                        if let JsonValue::Number(idx) = idx {
                            let idx = *idx as usize;
                            if let Some(block) = blocks.iter_mut().find(|b| b.idx == idx) {
                                if block.is_thinking() {
                                    output_lines.push(format!("thinking {}", escape_str(&block.thinking)));
                                    output_lines.push(format!("signature {}", escape_str(&block.signature)));
                                } else if block.is_text() {
                                    output_lines.push(format!("text {}", escape_str(&block.text)));
                                } else if block.is_tool_use() {
                                    if let Some(tu) = tool_use_blocks.iter_mut().find(|b| b.idx == idx) {
                                        blocks.push(ContentBlock::ToolUse { idx, id: tu.id.clone(), name: tu.name.clone(), input: tu.input.clone() });
                                        tool_use_blocks.remove(tu.idx);
                                    }
                                }
                            }
                        }
                    }
                }
            }
            "message_delta" => {
                if let JsonValue::Object(obj) = &event.data {
                    if let Some(delta) = obj.get("delta") {
                        if let JsonValue::Object(delta_obj) = delta {
                            if let Some(stop) = delta_obj.get("stop_reason") {
                                if let JsonValue::String(s) = stop {
                                    stop_reason = StopReason::from_str(s);
                                }
                            }
                            if let Some(usage) = delta_obj.get("usage") {
                                if let JsonValue::Object(usage_obj) = usage {
                                    if let Some(o) = usage_obj.get("output_tokens") {
                                        if let JsonValue::Number(n) = o {
                                            output_tokens += *n;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            "message_stop" => {}
            _ => {}
        }
    }

    // Print tool results
    for tu in tool_use_blocks {
        if tu.input_json.is_empty() {
            continue;
        }
        // Parse input JSON
        let input_val = parse_json_string(&tu.input_json).ok();
        let result = match input_val {
            Some(input) => {
                let tool_name = &tu.name;
                execute_tools(tool_name, &input)
            }
            None => format!("error"),
        };
        if result.starts_with("error") {
            output_lines.push(format!("error {} {}", tu.id, escape_str(&result)));
        } else {
            output_lines.push(format!("result {} {}", tu.id, escape_str(&result)));
        }
    }

    output_lines.push(format!("stop_reason {}", escape_str(&stop_reason.to_string())));

    (output_lines.join("\n"), stop_reason, input_tokens, output_tokens, cache_read_input_tokens)
}

fn process_request_2(config: &RequestConfig, blocks: &[ContentBlock], tool_results: &[(String, String, bool)]) -> (String, StopReason, i64, i64, i64) {
    // Reconstruct assistant message
    let assistant_content: Vec<JsonValue> = blocks.iter().map(|b| {
        match b {
            ContentBlock::Thinking { thinking, signature, .. } => {
                let mut obj = HashMap::new();
                obj.insert("type".to_string(), JsonValue::String("thinking".to_string()));
                obj.insert("thinking".to_string(), JsonValue::String(thinking.clone()));
                obj.insert("signature".to_string(), JsonValue::String(signature.clone()));
                JsonValue::Object(obj)
            }
            ContentBlock::Text { text, .. } => {
                let mut obj = HashMap::new();
                obj.insert("type".to_string(), JsonValue::String("text".to_string()));
                obj.insert("text".to_string(), JsonValue::String(text.clone()));
                JsonValue::Object(obj)
            }
            ContentBlock::ToolUse { id, name, input, .. } => {
                let mut obj = HashMap::new();
                obj.insert("type".to_string(), JsonValue::String("tool_use".to_string()));
                obj.insert("id".to_string(), JsonValue::String(id.clone()));
                obj.insert("name".to_string(), JsonValue::String(name.clone()));
                obj.insert("input".to_string(), input.clone());
                JsonValue::Object(obj)
            }
        }
    }).collect();

    let assistant_msg = Message {
        role: "assistant".to_string(),
        content: assistant_content,
    };

    // Construct tool result messages
    let user_content: Vec<JsonValue> = tool_results.iter().map(|(id, content, is_error)| {
        let mut obj = HashMap::new();
        obj.insert("type".to_string(), JsonValue::String("tool_result".to_string()));
        obj.insert("tool_use_id".to_string(), JsonValue::String(id.clone()));
        obj.insert("content".to_string(), JsonValue::String(content.clone()));
        if *is_error {
            obj.insert("is_error".to_string(), JsonValue::Bool(true));
        }
        JsonValue::Object(obj)
    }).collect();

    let user_msg = Message {
        role: "user".to_string(),
        content: user_content,
    };

    let messages = vec![
        Message {
            role: "user".to_string(),
            content: vec![JsonValue::Object(HashMap::from([
                ("type".to_string(), JsonValue::String("text".to_string())),
                ("text".to_string(), JsonValue::String(config.prompt.clone())),
            ]))],
        },
        assistant_msg,
        user_msg,
    ];

    let (output_lines, stop_reason, input_tokens, output_tokens, cache_read_input_tokens) = process_reply(config, messages.clone(), Vec::new());
    (output_lines, stop_reason, input_tokens, output_tokens, cache_read_input_tokens)
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 3 {
        eprintln!("Usage: {} <data_dir> <base_url>", args[0]);
        process::exit(1);
    }
    let data_dir = &args[1];
    let base_url = &args[2];

    let config = match fs::read_to_string(format!("{}/request.json", data_dir)) {
        Ok(content) => match parse_request_json(&content) {
            Ok(c) => c,
            Err(e) => {
                eprintln!("Failed to parse request.json: {}", e);
                process::exit(1);
            }
        },
        Err(e) => {
            eprintln!("Failed to read request.json: {}", e);
            process::exit(1);
        }
    };

    // Extract host from base_url
    let host = base_url.split("://").nth(1).unwrap_or(base_url).split('/').next().unwrap_or(base_url);

    config.base_url = base_url.to_string();
    config.host = host.to_string();

    let mut client = match TcpStream::connect(format!("{}:{}", host, config.base_url.split("://").nth(1).unwrap_or(base_url).split('/').next().unwrap_or(base_url))) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("Failed to connect: {}", e);
            process::exit(1);
        }
    };

    // Send Request 1
    let messages_1 = vec![Message {
        role: "user".to_string(),
        content: vec![JsonValue::Object(HashMap::from([
            ("type".to_string(), JsonValue::String("text".to_string())),
            ("text".to_string(), JsonValue::String(config.prompt.clone())),
        ]))],
    }];

    let mut output_buffer_1 = String::new();
    output_buffer_1.push_str("request 1\n");
    let mut accumulated_output_1 = Vec::new();
    let mut input_tokens_1 = 0i64;
    let mut output_tokens_1 = 0i64;
    let mut cache_read_input_tokens_1 = 0i64;
    let mut blocks_1: Vec<ContentBlock> = Vec::new();
    let mut tool_use_blocks_1: Vec<ToolUseBlock> = Vec::new();
    let mut stop_reason_1 = StopReason::Unknown;

    match send_request(&mut client, &config, messages_1) {
        Ok(response) => {
            if response.is_error {
                accumulated_output_1.push(response.error_type.as_ref().map(|s| format!("ERROR {} {}: {}", response.status_code, s, response.error_msg.as_ref().unwrap_or(&"unknown".to_string()))).unwrap_or_default());
                println!("{}", accumulated_output_1.join("\n"));
                process::exit(0);
            }
            let (output, reason, i_tokens, o_tokens, c_tokens) = process_reply(&config, Vec::new());
            accumulated_output_1.push(format!("request 1\n{}", output));
            accumulated_output_1.push(format!("stop_reason {}", reason.to_string()));
            // We need to process tool results
            // Actually, process_reply returns tool results in output_lines
            // But we need to extract tool use blocks to execute tools
            // So we need to parse the stream again or store the blocks
            // Let's restructure: process_reply returns blocks and tool_use_blocks
            // But process_reply is generic.
            // Let's modify process_reply to return blocks and tool_use_blocks.
            // But for simplicity, I'll just parse the stream again for tool_use_blocks.
            // Actually, I'll just store the tool_use_blocks in the main loop.
            // Let's rewrite the main loop to parse the stream and store blocks.
        }
        Err(e) => {
            accumulated_output_1.push(format!("ERROR {} {}", e));
            println!("{}", accumulated_output_1.join("\n"));
            process::exit(0);
        }
    }

    // Re-parse stream for tool_use_blocks
    let events = parse_sse_events(&config.body);
    for event in events {
        if event.name == "content_block_start" {
            if let JsonValue::Object(obj) = event.data {
                if let Some(idx) = obj.get("index") {
                    if let JsonValue::Number(idx) = idx {
                        let idx = *idx as usize;
                        if let Some(block) = obj.get("content_block") {
                            if let JsonValue::Object(block_obj) = block {
                                if let Some(t) = block_obj.get("type") {
                                    if let JsonValue::String(t) = t {
                                        if t == "tool_use" {
                                            if let (Some(id), Some(name)) = (block_obj.get("id"), block_obj.get("name")) {
                                                if let (JsonValue::String(id_s), JsonValue::String(name_s)) = (id, name) {
                                                    tool_use_blocks_1.push(ToolUseBlock {
                                                        idx, id: id_s.clone(), name: name_s.clone(), input: String::new(), input_json: String::new(),
                                                    });
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
