        "POST {} HTTP/1.1\r\nHost: {}\r\nContent-Length: {}\r\nx-api-key: {}\r\nanthropic-version: 2023-06-01\r\ncontent-type: application/json\r\n\r\n{}",
        "/v1/messages", host, request_body_2.len(), config.api_key, request_body_2
    );

    if let Err(e) = client.write_all(request_2.as_bytes()) {
        eprintln!("Failed to send request: {}", e);
        process::exit(1);
    }

    let response_2 = match send_request(&mut client, &config, messages_2) {
        Ok(r) => r,
        Err(e) => {
            eprintln!("Failed to send request: {}", e);
            process::exit(1);
        }
