        println!("{}", error_line);
        process::exit(0);
    }

    let (output_lines_2, stop_reason_2, input_tokens_2, output_tokens_2, cache_read_input_tokens_2) = process_reply(&config, tool_results_1.clone());
    println!("request 2");
    println!("{}", output_lines_2);
    println!("stop_reason {}", escape_str(&stop_reason_2.to_string()));

    println!("usage input={} output={} cache_read={}", input_tokens_1 + input_tokens_2, output_tokens_1 + output_tokens_2, cache_read_input_tokens_1 + cache_read_input_tokens_2);
}

use std::fs;
use std::io::{self, BufRead, Read, Write};
use std::net::TcpStream;
use std::collections::HashMap;
use std::process;

#[derive(Debug, Clone)]
enum JsonVal {
    Null,
    Bool(bool),
    Number(i64),
    String(String),
    Array(Vec<JsonVal>),
    Object(HashMap<String, JsonVal>),
}

struct Parser<'a> {
    input: &'a str,
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Self {
        Parser { input, pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.input[self.pos..].chars().next()
    }

    fn next(&mut self) -> Option<char> {
        let ch = self.peek()?;
        self.pos += ch.len_utf8();
        Some(ch)
    }

    fn skip_whitespace(&mut self) {
        while let Some(ch) = self.peek() {
            if ch.is_whitespace() {
                self.next();
            } else {
                break;
            }
        }
    }

    fn parse(&mut self) -> Option<JsonVal> {
        self.skip_whitespace();
        match self.peek() {
            Some('{') => {
                self.next();
                let obj = self.parse_object()?;
                Some(JsonVal::Object(obj))
            }
            Some('[') => {
                self.next();
                let arr = self.parse_array()?;
                Some(JsonVal::Array(arr))
            }
            Some('"') => {
                self.next();
                let s = self.parse_string()?;
                Some(JsonVal::String(s))
            }
            Some('t') => {
                self.next();
                if self.input[self.pos..].starts_with("rue") {
                    self.pos += 3;
                    Some(JsonVal::Bool(true))
                } else {
                    None
                }
            }
            Some('f') => {
                self.next();
                if self.input[self.pos..].starts_with("alse") {
                    self.pos += 4;
                    Some(JsonVal::Bool(false))
                } else {
                    None
                }
            }
            Some('n') => {
                self.next();
                if self.input[self.pos..].starts_with("ull") {
                    self.pos += 3;
                    Some(JsonVal::Null)
                } else {
                    None
                }
            }
            Some('0'..='9') | Some('-') | Some('.') => {
                self.next();
                let num = self.parse_number();
                Some(JsonVal::Number(num))
            }
            _ => None,
        }
    }

    fn parse_object(&mut self) -> Option<HashMap<String, JsonVal>> {
        let mut obj = HashMap::new();
        loop {
            self.skip_whitespace();
            if let Some('}') = self.peek() {
                self.next();
                break;
            }
            if let Some('"') = self.peek() {
                self.next();
                let key = self.parse_string()?;
                self.skip_whitespace();
                if let Some(':') = self.peek() {
                    self.next();
                }
                let val = self.parse()?;
                if let Some(val) = val {
                    obj.insert(key, val);
                }
            } else {
                return None;
            }
        }
        Some(obj)
    }

    fn parse_array(&mut self) -> Option<Vec<JsonVal>> {
        let mut arr = Vec::new();
        loop {
            self.skip_whitespace();
            if let Some(']') = self.peek() {
                self.next();
                break;
            }
            let val = self.parse()?;
            if let Some(val) = val {
                arr.push(val);
            }
        }
        Some(arr)
    }

    fn parse_string(&mut self) -> Option<String> {
        let mut s = String::new();
        loop {
            match self.next() {
                Some('"') => return Some(s),
                Some('\\') => {
                    self.next();
                    match self.peek() {
                        Some('\"') => { s.push('"'); self.next(); }
                        Some('\\') => { s.push('\\'); self.next(); }
                        Some('/') => { s.push('/'); self.next(); }
                        Some('b') => { s.push('\x08'); self.next(); }
                        Some('f') => { s.push('\x0c'); self.next(); }
                        Some('n') => { s.push('\n'); self.next(); }
                        Some('r') => { s.push('\r'); self.next(); }
                        Some('t') => { s.push('\t'); self.next(); }
                        Some('u') => {
                            self.next();
                            let hex = self.next().unwrap() as char;
                            let hex = self.next().unwrap() as char;
                            let hex = self.next().unwrap() as char;
                            let hex = self.next().unwrap() as char;
                            let code = u32::from_str_radix(&format!("{}{}{}{}", hex as u8, hex as u8, hex as u8, hex as u8), 16).unwrap();
                            if code >= 0xD800 && code <= 0xDBFF {
                                let high = code;
                                let low_code = u32::from_str_radix(&format!("{}{}{}{}", self.next().unwrap() as char, self.next().unwrap() as char, self.next().unwrap() as char, self.next().unwrap() as char), 16).unwrap();
                                if low_code >= 0xDC00 && low_code <= 0xDFFF {
                                    s.push((0x10000 + (high - 0xD800) * 0x400 + (low_code - 0xDC00)).into());
                                }
                            } else {
                                s.push(code.into());
                            }
                        }
                        _ => return None,
                    }
                }
                Some(ch) => {
                    s.push(ch);
                }
                None => return None,
            }
        }
    }

    fn parse_number(&mut self) -> i64 {
        let start = self.pos;
        if let Some('-') = self.peek() {
            self.next();
        }
        while let Some(ch) = self.peek() {
            if ch.is_ascii_digit() {
                self.next();
            } else {
                break;
            }
        }
        if let Some('.') = self.peek() {
            self.next();
            while let Some(ch) = self.peek() {
                if ch.is_ascii_digit() {
                    self.next();
                } else {
                    break;
                }
            }
        }
        // For this task, we expect integers.
        // We'll parse as f64 then round.
        let s = &self.input[start..self.pos];
        s.parse::<f64>().unwrap() as i64
    }
}

struct Serializer;

impl Serializer {
    fn serialize(val: &JsonVal) -> String {
        match val {
            JsonVal::Null => "null".to_string(),
            JsonVal::Bool(b) => b.to_string(),
            JsonVal::Number(n) => n.to_string(),
            JsonVal::String(s) => {
                let mut s = String::new();
                s.push('"');
                for ch in s.chars() {
                    match ch {
                        '"' => s.push_str("\\\""),
                        '\\' => s.push_str("\\\\"),
                        '\x08' => s.push_str("\\b"),
                        '\x0c' => s.push_str("\\f"),
                        '\n' => s.push_str("\\n"),
                        '\r' => s.push_str("\\r"),
                        '\t' => s.push_str("\\t"),
                        c if c < '\x20' => {
                            s.push_str(&format!("\\u{:04x}", c as u32));
                        }
                        '/' => s.push('/'),
                        _ => s.push(ch),
                    }
                }
                s.push('"');
                s
            }
            JsonVal::Array(arr) => {
                let mut s = "[".to_string();
                for (i, v) in arr.iter().enumerate() {
                    if i > 0 { s.push(','); }
                    s.push_str(&Serializer::serialize(v));
                }
                s.push(']');
                s
            }
            JsonVal::Object(obj) => {
                let mut s = "{".to_string();
                let mut first = true;
                for (k, v) in obj.iter() {
                    if !first { s.push(','); }
                    first = false;
                    s.push_str(&Serializer::serialize_string(k));
                    s.push(':');
                    s.push_str(&Serializer::serialize(v));
                }
                s.push('}');
                s
            }
        }
    }

    fn serialize_string(s: &str) -> String {
        let mut ss = String::new();
        ss.push('"');
        for ch in s.chars() {
            match ch {
                '"' => ss.push_str("\\\""),
                '\\' => ss.push_str("\\\\"),
                '\x08' => ss.push_str("\\b"),
                '\x0c' => ss.push_str("\\f"),
                '\n' => ss.push_str("\\n"),
                '\r' => ss.push_str("\\r"),
                '\t' => ss.push_str("\\t"),
                c if c < '\x20' => {
                    ss.push_str(&format!("\\u{:04x}", c as u32));
                }
                '/' => ss.push('/'),
                _ => ss.push(ch),
            }
        }
        ss.push('"');
        ss
    }
}

