fn parse_csv_v2(content: &str) -> Vec<(String, String, i64, String, i64)> {
    let mut items = Vec::new();
    let mut lines = Vec::new();
    let mut current_line = String::new();

    for ch in content.chars() {
        if ch == '\n' {
            lines.push(current_line.clone());
            current_line.clear();
        } else {
            current_line.push(ch);
        }
    }
    if !current_line.is_empty() {
        lines.push(current_line);
    }

    let mut header_parsed = false;
    for line in lines {
        let mut row: Vec<String> = Vec::new();
        let mut field = String::new();
        let mut in_quotes = false;
        let mut chars = line.chars().peekable();

        while let Some(ch) = chars.next() {
            if in_quotes {
                if ch == '"' {
                    if chars.peek() == Some(&'"') {
                        chars.next();
                        field.push('"');
                    } else {
                        in_quotes = false;
                    }
                } else {
                    field.push(ch);
                }
            } else {
                if ch == '"' {
                    in_quotes = true;
                } else if ch == ',' {
                    row.push(field);
                    field.clear();
                } else if ch == '\r' {
                    continue;
                } else {
                    field.push(ch);
                }
            }
        }
        row.push(field);

        if !header_parsed {
            header_parsed = true;
            continue;
        }

        if row.len() >= 5 {
            let sku = row[0].clone();
            let name = row[1].clone();
            let price_cents: i64 = row[2].parse().unwrap_or(0);
            let currency = row[3].clone();
            let stock: i64 = row[4].parse().unwrap_or(0);
            items.push((sku, name, price_cents, currency, stock));
        }
    }

    items
}

