public class Main {
    public static void main(String[] args) {
        if (args.length < 1) {
            return;
        }
        String dirPath = args[0];
        Path dir = Paths.get(dirPath);

        try {
            List<Path> files = Files.list(dir)
                    .filter(p -> p.toString().endsWith(".wav"))
                    .sorted(Comparator.comparing(p -> p.getFileName().toString()))
                    .toList();

            for (int i = 0; i < files.size(); i++) {
                if (i > 0) {
                    System.out.println();
                }
                processFile(files.get(i));
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static void processFile(Path path) {
        String fileName = path.getFileName().toString();

        try {
            byte[] data = Files.readAllBytes(path);
            WavInfo wav = parseWav(data);
            if (wav == null) {
                System.out.println(fileName + ": unsupported");
                return;
            }

            // Check support conditions
            if (wav.effectiveFormat != 1 || wav.bitsPerSample != 16) {
                System.out.println(fileName + ": unsupported");
                return;
            }

            // Decode DTMF
            DTMFResult result = decodeDtmf(wav);

            System.out.println(fileName + ": " + wav.sampleRate + " Hz, " + wav.channels + " ch, " + result.blockCount + " blocks");

            StringBuilder sb = new StringBuilder();
            for (DTMFEvent event : result.events) {
                sb.append(event.digit).append(" ").append(event.startMs).append(" ").append(event.endMs).append("\n");
            }
            System.out.print(sb.toString());

            StringBuilder digits = new StringBuilder();
            for (char d : result.allDigits) {
                digits.append(d);
            }
            System.out.println("digits: " + digits.toString());

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static WavInfo parseWav(byte[] data) {
        if (data.length < 12) return null;

        // RIFF
        if (data.length < 12 || new String(data, 0, 4).equals("RIFF") != true) return null;
        if (new String(data, 8, 4).equals("WAVE") != true) return null;

        int dataOffset = 12;
        WavInfo fmtInfo = null;

        while (dataOffset < data.length) {
            if (data.length - dataOffset < 8) break;

            String id = new String(data, dataOffset, 4);
            if (id.length() < 4) break;

            int size = ByteBuffer.wrap(data, dataOffset + 4, 4).order(ByteOrder.LITTLE_ENDIAN).getInt();
            dataOffset += 8;

            if (size < 0) break;

            // Check for odd size
            if (dataOffset + size > data.length) break;

            // Read body
            if (size % 2 != 0) {
                dataOffset += size + 1;
            } else {
                dataOffset += size;
            }

            if (id.equals("fmt ")) {
                if (size < 16) return null;
                // Parse fmt body
                short formatTag = ByteBuffer.wrap(data, dataOffset - size - 8, 2).order(ByteOrder.LITTLE_ENDIAN).getShort();
                short channels = ByteBuffer.wrap(data, dataOffset - size - 6, 2).order(ByteOrder.LITTLE_ENDIAN).getShort();
                int sampleRate = ByteBuffer.wrap(data, dataOffset - size - 4, 4).order(ByteOrder.LITTLE_ENDIAN).getInt();
                int byteRate = ByteBuffer.wrap(data, dataOffset - size, 4).order(ByteOrder.LITTLE_ENDIAN).getInt();
                short blockAlign = ByteBuffer.wrap(data, dataOffset - size + 8, 2).order(ByteOrder.LITTLE_ENDIAN).getShort();
                short bitsPerSample = ByteBuffer.wrap(data, dataOffset - size + 10, 2).order(ByteOrder.LITTLE_ENDIAN).getShort();

                // Effective format
                short effectiveFormat = formatTag;
                if (formatTag == 0xFFFE) {
                    if (size >= 24) {
                        effectiveFormat = ByteBuffer.wrap(data, dataOffset - size - 8 + 24, 2).order(ByteOrder.LITTLE_ENDIAN).getShort();
                    } else {
                        effectiveFormat = formatTag; // Fallback
                    }
                }

                fmtInfo = new WavInfo(channels, sampleRate, byteRate, blockAlign, bitsPerSample, effectiveFormat);
            } else if (id.equals("data")) {
                if (fmtInfo == null) return null;
                return new WavInfo(channels, sampleRate, byteRate, blockAlign, bitsPerSample, effectiveFormat, dataOffset - size - 8, size);
            }
        }

        if (fmtInfo == null) return null;
        return new WavInfo(channels, sampleRate, byteRate, blockAlign, bitsPerSample, effectiveFormat, 0, 0);
    }

