            String id = new String(data, dataOffset, 4);
            if (id.length() < 4) break;

            int size = ByteBuffer.wrap(data, dataOffset + 4, 4).order(ByteOrder.LITTLE_ENDIAN).getInt();
            dataOffset += 8;

            if (size < 0) break;

            // Check for odd size
            if (dataOffset + size > data.length) break;

            // Read body
            if (size % 2 != 0) {
                dataOffset += size + 1;
            } else {
                dataOffset += size;
            }

            if (id.equals("fmt ")) {
                if (size < 16) return null;
                // Parse fmt body
                short formatTag = ByteBuffer.wrap(data, dataOffset - size - 8, 2).order(ByteOrder.LITTLE_ENDIAN).getShort();
                short channels = ByteBuffer.wrap(data, dataOffset - size - 6, 2).order(ByteOrder.LITTLE_ENDIAN).getShort();
                int sampleRate = ByteBuffer.wrap(data, dataOffset - size - 4, 4).order(ByteOrder.LITTLE_ENDIAN).getInt();
                int byteRate = ByteBuffer.wrap(data, dataOffset - size, 4).order(ByteOrder.LITTLE_ENDIAN).getInt();
                short blockAlign = ByteBuffer.wrap(data, dataOffset - size + 8, 2).order(ByteOrder.LITTLE_ENDIAN).getShort();
                short bitsPerSample = ByteBuffer.wrap(data, dataOffset - size + 10, 2).order(ByteOrder.LITTLE_ENDIAN).getShort();

                // Effective format
                short effectiveFormat = formatTag;
                if (formatTag == 0xFFFE) {
                    if (size >= 24) {
                        effectiveFormat = ByteBuffer.wrap(data, dataOffset - size - 8 + 24, 2).order(ByteOrder.LITTLE_ENDIAN).getShort();
                    } else {
                        effectiveFormat = formatTag; // Fallback
                    }
                }

                fmtInfo = new WavInfo(channels, sampleRate, byteRate, blockAlign, bitsPerSample, effectiveFormat);
            } else if (id.equals("data")) {
                if (fmtInfo == null) return null;
                return new WavInfo(channels, sampleRate, byteRate, blockAlign, bitsPerSample, effectiveFormat, dataOffset - size - 8, size);
            }
        }

        if (fmtInfo == null) return null;
        return new WavInfo(channels, sampleRate, byteRate, blockAlign, bitsPerSample, effectiveFormat, 0, 0);
    }

