import sys
import os
import struct
import math

def parse_wav(filepath):
    try:
        with open(filepath, 'rb') as f:
            data = f.read()
    except Exception:
        return None, None, None

    if len(data) < 12:
        return None, None, None

    # RIFF header
    if data[0:4] != b'RIFF':
        return None, None, None
    if data[8:12] != b'WAVE':
        return None, None, None

    # Find fmt and data chunks
    fmt_body = None
    data_body = None

    pos = 12
    while pos < len(data):
        if pos + 8 > len(data):
            break
        chunk_id = data[pos:pos+4]
        chunk_size = struct.unpack('<I', data[pos+4:pos+8])[0]

        if chunk_id == b'fmt ':
            fmt_body = data[pos+8:pos+8+chunk_size]
        elif chunk_id == b'data':
            data_body = data[pos+8:pos+8+chunk_size]
            break

        if chunk_size % 2 == 1:
            pos += 8 + chunk_size + 1
        else:
            pos += 8 + chunk_size

    if fmt_body is None or data_body is None:
        return None, None, None

    # Parse fmt body
    if len(fmt_body) < 16:
        return None, None, None

    tag = struct.unpack('<H', fmt_body[0:2])[0]
    channels = struct.unpack('<H', fmt_body[2:4])[0]
    rate = struct.unpack('<I', fmt_body[4:8])[0]
    bps = struct.unpack('<H', fmt_body[14:16])[0]

    effective_format = tag
    if tag == 0xFFFE:
        if len(fmt_body) >= 26:
            effective_format = struct.unpack('<H', fmt_body[24:26])[0]
        else:
            return None, None, None

    # Check support
    if effective_format != 1 or bps != 16 or channels not in (1, 2) or rate not in (8000, 16000):
        return None, None, None

    # Parse data body
    num_samples = len(data_body) // 2
    num_frames = num_samples // channels

    # Extract left channel samples
    left_samples = []
    for i in range(num_frames):
        idx = i * channels
        if idx + 1 < len(data_body):
            sample_bytes = data_body[idx:idx+2]
            val = struct.unpack('<h', sample_bytes)[0]
            left_samples.append(val)
        else:
            return None, None, None

    return rate, channels, left_samples

def goertzel(block, f, rate):
    N = len(block)
    c = 2 * math.cos(2 * math.pi * f / rate)
    s1 = 0.0
    s2 = 0.0
    for x in block:
        s = x + c * s1 - s2
        s2 = s1
        s1 = s
    P = s1*s1 + s2*s2 - c*s1*s2
    return P

def decode_dtmf(samples, rate):
    N = rate // 50
    num_frames = len(samples) // N

    low_freqs = [697, 770, 852, 941]
    high_freqs = [1209, 1336, 1477, 1633]

    keypad_map = {
        (697, 1209): '1', (697, 1336): '2', (697, 1477): '3', (697, 1633): 'A',
        (770, 1209): '4', (770, 1336): '5', (770, 1477): '6', (770, 1633): 'B',
        (852, 1209): '7', (852, 1336): '8', (852, 1477): '9', (852, 1633): 'C',
        (941, 1209): '*', (941, 1336): '0', (941, 1477): '#', (941, 1633): 'D'
    }

    labels = []
    for i in range(num_frames):
        block = samples[i*N : (i+1)*N]
        E = sum(x*x for x in block)

        if E < 1000000 * N:
            labels.append('none')
            continue

        powers = []
        for f in low_freqs:
            P = goertzel(block, f, rate)
            r = 2 * P / (N * E)
            powers.append(r)

        for f in high_freqs:
            P = goertzel(block, f, rate)
            r = 2 * P / (N * E)
            powers.append(r)

        max_r_low = max(powers[:4])
        max_r_high = max(powers[4:])

        fl = low_freqs[powers[:4].index(max_r_low)]
        fh = high_freqs[powers[4:].index(max_r_high)]

        r_low = max_r_low
        r_high = max_r_high

        if r_low >= 0.1 and r_high >= 0.1 and (r_low + r_high) >= 0.6:
            labels.append(keypad_map[(fl, fh)])
        else:
            labels.append('none')

    # Bridging
    bridged_labels = []
    for i in range(len(labels)):
        if labels[i] != 'none':
            bridged_labels.append(labels[i])
        else:
            if i > 0 and i < len(labels) - 1:
                left = labels[i-1]
                right = labels[i+1]
                if left != 'none' and right != 'none' and left == right:
                    bridged_labels.append(left)
                else:
                    bridged_labels.append('none')
            else:
                bridged_labels.append('none')

    # Events
    events = []
    current_digit = None
    run_start = -1
    run_length = 0

    for i, label in enumerate(bridged_labels):
        if label != 'none':
            if label != current_digit:
                if current_digit is not None and run_length >= 2:
                    events.append((current_digit, 20 * run_start, 20 * (run_start + run_length)))
                current_digit = label
                run_start = i
                run_length = 1
            else:
                run_length += 1
        else:
            if current_digit is not None and run_length >= 2:
                events.append((current_digit, 20 * run_start, 20 * (run_start + run_length)))
            current_digit = None
            run_start = -1
            run_length = 0

    if current_digit is not None and run_length >= 2:
        events.append((current_digit, 20 * run_start, 20 * (run_start + run_length)))

    return num_frames, events

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    directory = sys.argv[1]

    files = []
    try:
        for f in os.listdir(directory):
            if f.endswith('.wav'):
                files.append(f)
    except Exception:
        sys.exit(1)

    files.sort(key=lambda x: x.encode('utf-8'))

    first = True
    for name in files:
        filepath = os.path.join(directory, name)

        if not first:
            print()
        first = False

        rate, channels, samples = parse_wav(filepath)

        if rate is None:
            print(f"{name}: unsupported")
            continue

        num_frames, events = decode_dtmf(samples, rate)

        print(f"{name}: {rate} Hz, {channels} ch, {num_frames} blocks")

        for digit, start, end in events:
            print(f"{digit} {start} {end}")

        digits_str = "".join(d for d, _, _ in events)
        print(f"digits: {digits_str}")

if __name__ == "__main__":
    main()
